      V2_GIT_LEDGER_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_INTENT_HANDLE_SCHEMA,
    schema_version: 1,
    intent_record_oid: sha(intentRecordOid,
      "automatic artifact binding intent record OID"),
