function automaticRecoveryArtifactBindingTransport(authorityValue) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(authorityValue);
  return deepFreeze({
    operation: "loadV2ProviderPreScopeArtifacts",
    requests: authority.candidates.map((candidate) => ({
      owner: authority.scope.repository.owner,
      repo: authority.scope.repository.name,
      pullNumber: authority.scope.pull_request.number,
      headSha: authority.scope.head_oid,
      selector: structuredClone(candidate.selector),
      expectedActor: structuredClone(authority.expected_actor),
      expectedApp: structuredClone(authority.expected_app),
    })),
    expected_count: authority.candidates.length,
    candidate_set_digest:
      automaticRecoveryArtifactBindingCandidateSetDigest(authority),
    retry_policy: "safe-idempotent",
  });
}

function validateAutomaticRecoveryArtifactBindingTransport(value) {
  assertObject(value, "automatic recovery artifact binding transport");
  exactKeys(value, [
    "operation", "requests", "expected_count", "candidate_set_digest",
    "retry_policy",
  ], "automatic recovery artifact binding transport");
  if (
    value.operation !== "loadV2ProviderPreScopeArtifacts" ||
    value.retry_policy !== "safe-idempotent"
  ) {
    throw new Error("automatic artifact binding transport is not one safe exact GET batch");
  }
  const count = integerBetween(
    value.expected_count,
    1,
    MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATES,
    "automatic recovery artifact binding transport expected_count");
  if (!Array.isArray(value.requests) || value.requests.length !== count) {
    throw new Error("automatic artifact binding transport request count is not exact");
  }
  value.requests.forEach((request, index) => {
    const label = `automatic recovery artifact binding transport requests[${index}]`;
    assertObject(request, label);
    exactKeys(request, [
      "owner", "repo", "pullNumber", "headSha", "selector",
      "expectedActor", "expectedApp",
    ], label);
    boundedString(request.owner, `${label}.owner`, 128);
    boundedString(request.repo, `${label}.repo`, 128);
    positiveInteger(request.pullNumber, `${label}.pullNumber`);
    sha(request.headSha, `${label}.headSha`);
    normalizeCarrierSelector(request.selector, `${label}.selector`);
    validateExternalActor(request.expectedActor, `${label}.expectedActor`);
    validateExternalApp(request.expectedApp, `${label}.expectedApp`);
    validateCodexProvider(
      request.expectedActor,
      request.expectedApp,
      `${label}.provider`,
    );
  });
  digest(value.candidate_set_digest,
    "automatic recovery artifact binding transport candidate_set_digest");
  return value;
}

function validateAutomaticReviewRequestTransport(value, expected = null) {
  assertObject(value, "automatic review request transport");
  exactKeys(value, [
    "method", "path", "body", "json", "expected_status", "retry_limit",
    "record_attempt_before_effect", "network_uncertainty_policy",
    "generation_id", "reservation_digest", "attempt_digest",
  ], "automatic review request transport");
  assertObject(value.json, "automatic review request transport json");
  exactKeys(value.json, ["body"], "automatic review request transport json");
  if (
    value.method !== "POST" || value.body !== "@codex review" ||
    value.json.body !== value.body || value.expected_status !== 201 ||
    value.retry_limit !== 0 || value.record_attempt_before_effect !== true ||
    value.network_uncertainty_policy !== "do-not-retry-or-reclaim" ||
    !GENERATION_ID.test(value.generation_id)
  ) {
    throw new Error("automatic review request transport is outside its retry-zero profile");
  }
  digest(value.reservation_digest,
    "automatic review request transport reservation_digest");
  digest(value.attempt_digest,
    "automatic review request transport attempt_digest");
  boundedString(value.path, "automatic review request transport path", 2048);
  if (expected !== null) {
    const repository = normalizeRepository(expected.repository);
    const reservation = validateV2GitLedgerRunnerReservation(
      expected.reservation,
    );
    const attempt = validateV2GitLedgerRequestAttempt(expected.attempt, {
      reservation,
    });
    const expectedPath =
      `/repos/${encodeURIComponent(repository.owner)}/` +
      `${encodeURIComponent(repository.name)}/issues/` +
      `${reservation.pull_request.number}/comments`;
    if (
      value.path !== expectedPath ||
      value.generation_id !== reservation.generation_id ||
      value.reservation_digest !== reservation.reservation_digest ||
      value.attempt_digest !== attempt.attempt_digest
    ) {
      throw new Error("automatic review request transport differs from its authority");
    }
  }
  return value;
}

function validateReservationStatusTransport(value) {
  assertObject(value, "reservation status transport");
  exactKeys(value, [
    "method", "target_sha", "context", "state", "description",
    "description_digest",
  ], "reservation status transport");
  if (
    value.method !== "POST" || value.state !== "pending" ||
    value.context === "codex/github-review-gate" ||
    !/^codex\/github-review-gate-reservation\/[1-3]$/u
      .test(value.context)
  ) {
    throw new Error("reservation status transport is outside its audit-only profile");
  }
  sha(value.target_sha, "reservation status transport target_sha");
  digest(value.description, "reservation status transport description");
  if (value.description_digest !== value.description) {
    throw new Error("reservation status transport description binding is invalid");
  }
  return value;
}

function automaticEffectGeneration(index, scope) {
  return {
    generation_id: `automatic:${index}`,
    kind: "automatic",
    index,
    review_epoch_digest: reviewEpochDigest(scope),
  };
}

