function validateAutomaticRecoveryArtifactBindingCandidate(value, {
  observed_at: observedAt,
  request_bound_at: requestBoundAt,
  candidate_count: candidateCount,
  candidate_index: candidateIndex,
} = {}) {
  assertObject(value, "automatic recovery artifact binding candidate");
  exactKeys(value, [
    "index", "count", "selector", "artifact_node_id", "artifact_url",
    "artifact_type", "artifact_created_at", "evidence_response_server_time",
    "evidence_raw_body_sha256", "candidate_digest",
  ], "automatic recovery artifact binding candidate");
  const index = nonnegativeInteger(value.index,
    "automatic recovery artifact binding candidate index");
  const count = integerBetween(
    value.count,
    1,
    MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATES,
    "automatic recovery artifact binding candidate count");
  const selector = normalizeCarrierSelector(
    value.selector,
    "automatic recovery artifact binding candidate selector",
  );
  boundedString(value.artifact_node_id,
    "automatic recovery artifact binding candidate artifact_node_id", 256);
  githubUrl(value.artifact_url,
    "automatic recovery artifact binding candidate artifact_url");
  if (value.artifact_type !== selector.kind) {
    throw new Error("automatic recovery artifact candidate type differs from selector");
  }
  const createdAt = timestamp(value.artifact_created_at,
    "automatic recovery artifact binding candidate artifact_created_at");
  const evidenceObservedAt = timestamp(value.evidence_response_server_time,
    "automatic recovery artifact binding candidate evidence_response_server_time");
  digest(value.evidence_raw_body_sha256,
    "automatic recovery artifact binding candidate evidence_raw_body_sha256");
  digest(value.candidate_digest,
    "automatic recovery artifact binding candidate candidate_digest");
  const { candidate_digest: candidateDigest, ...withoutDigest } = value;
  if (
    candidateDigest !== runnerDigestCanonical(
      "codex-review-gate-v2-automatic-recovery-artifact-binding-candidate",
      withoutDigest,
    ) ||
    (candidateCount !== undefined && count !== candidateCount) ||
    (candidateIndex !== undefined && index !== candidateIndex) ||
    (observedAt !== undefined &&
      Date.parse(evidenceObservedAt) > Date.parse(observedAt)) ||
    (requestBoundAt !== undefined &&
      Date.parse(createdAt) <= Date.parse(requestBoundAt))
  ) {
    throw new Error("automatic recovery artifact binding candidate is not exact");
  }
  return value;
}

function validateAutomaticRecoveryArtifactBindingCandidateScope(value) {
  assertObject(value, "automatic recovery artifact binding candidate scope");
  exactKeys(value, [
    "repository", "pull_request", "base_oid", "head_oid", "merge_base_oid",
  ], "automatic recovery artifact binding candidate scope");
  assertObject(value.repository,
    "automatic recovery artifact binding candidate repository");
  exactKeys(value.repository, ["owner", "name", "node_id"],
    "automatic recovery artifact binding candidate repository");
  boundedString(value.repository.owner,
    "automatic recovery artifact binding candidate repository.owner", 128);
  boundedString(value.repository.name,
    "automatic recovery artifact binding candidate repository.name", 128);
  boundedString(value.repository.node_id,
    "automatic recovery artifact binding candidate repository.node_id", 256);
  assertObject(value.pull_request,
    "automatic recovery artifact binding candidate pull_request");
  exactKeys(value.pull_request, ["number", "node_id"],
    "automatic recovery artifact binding candidate pull_request");
  positiveInteger(value.pull_request.number,
    "automatic recovery artifact binding candidate pull_request.number");
  boundedString(value.pull_request.node_id,
    "automatic recovery artifact binding candidate pull_request.node_id", 256);
  sha(value.base_oid,
    "automatic recovery artifact binding candidate scope.base_oid");
  sha(value.head_oid,
    "automatic recovery artifact binding candidate scope.head_oid");
  sha(value.merge_base_oid,
    "automatic recovery artifact binding candidate scope.merge_base_oid");
  return value;
}

function automaticRecoveryArtifactBindingCandidateProfile(value, {
  item = false,
} = {}) {
  const label = item
    ? "automatic recovery artifact binding candidate item"
    : "automatic recovery artifact binding candidate authority";
  const expectedSchema = item
    ? "codex-review-gate-git-ledger-automatic-recovery-artifact-binding-candidate-v2"
    : "codex-review-gate-runner-automatic-recovery-artifact-binding-candidate-authority-v2";
  if (value.schema !== expectedSchema) {
    throw new Error(`${label} is unsupported`);
  }
  if (value.schema_version === 1) {
    exactKeys(
      value,
      item
        ? LEGACY_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATE_ITEM_AUTHORITY_KEYS
        : LEGACY_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATE_AUTHORITY_KEYS,
      label,
    );
    if (value.decision !== "findings") {
      throw new Error(`${label} legacy profile is findings-only`);
    }
    return {
      legacy: true,
      candidate_version: 1,
      purpose: "finding-recovery",
      decision: "findings",
      minimum_generation: 1,
      maximum_generation: 2,
      exact_candidate_count: null,
    };
  }
  exactKeys(
    value,
    item
      ? AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATE_ITEM_AUTHORITY_KEYS
      : AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATE_AUTHORITY_KEYS,
    label,
  );
  if (value.schema_version !== 2 || value.candidate_version !== 1) {
    throw new Error(`${label} version is unsupported`);
  }
  if (value.purpose === "finding-recovery" && value.decision === "findings") {
    return {
      legacy: false,
      candidate_version: value.candidate_version,
      purpose: value.purpose,
      decision: value.decision,
      minimum_generation: 1,
      maximum_generation: 2,
      exact_candidate_count: null,
    };
  }
  if (
    value.purpose === "terminal-clean-completion" &&
    value.decision === "pending"
  ) {
    return {
      legacy: false,
      candidate_version: value.candidate_version,
      purpose: value.purpose,
      decision: value.decision,
      minimum_generation: 1,
      maximum_generation: 3,
      exact_candidate_count: 1,
    };
  }
  throw new Error(`${label} purpose and decision are inconsistent`);
}

function validateAutomaticRecoveryArtifactBindingCandidateAuthority(value) {
  assertObject(value, "automatic recovery artifact binding candidate authority");
  const profile = automaticRecoveryArtifactBindingCandidateProfile(value);
  digest(value.snapshot_fingerprint,
    "automatic recovery artifact binding candidate snapshot_fingerprint");
  if (!RUNNER_EPOCH_ID.test(value.review_epoch_id)) {
    throw new Error("automatic recovery artifact binding candidate review epoch is invalid");
  }
  const observedAt = timestamp(value.observed_at,
    "automatic recovery artifact binding candidate observed_at");
  const generationIndex = integerBetween(
    value.generation_index,
    profile.minimum_generation,
    profile.maximum_generation,
    "automatic recovery artifact binding candidate generation_index");
  if (value.generation_id !== `automatic:${generationIndex}`) {
    throw new Error("automatic recovery artifact binding candidate generation is invalid");
  }
  decimal(value.request_id,
    "automatic recovery artifact binding candidate request_id");
  boundedString(value.request_node_id,
    "automatic recovery artifact binding candidate request_node_id", 256);
  const requestBoundAt = timestamp(value.request_bound_at,
    "automatic recovery artifact binding candidate request_bound_at");
  sha(value.request_binding_record_oid,
    "automatic recovery artifact binding candidate request_binding_record_oid");
  digest(value.request_binding_receipt_digest,
    "automatic recovery artifact binding candidate request_binding_receipt_digest");
  validateExternalActor(value.expected_actor,
    "automatic recovery artifact binding candidate expected_actor");
  validateExternalApp(value.expected_app,
    "automatic recovery artifact binding candidate expected_app");
  validateCodexProvider(value.expected_actor, value.expected_app,
    "automatic recovery artifact binding candidate provider");
  validateAutomaticRecoveryArtifactBindingCandidateScope(value.scope);
  if (!Array.isArray(value.candidates) ||
      value.candidates.length < 1 ||
      value.candidates.length >
        MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATES ||
      profile.exact_candidate_count !== null &&
        value.candidates.length !== profile.exact_candidate_count) {
    throw ledgerError(
      "automatic-artifact-binding-candidate-count",
      "automatic recovery artifact binding candidate inventory is unbounded",
    );
  }
  const selectors = new Set();
  value.candidates.forEach((candidate, index) => {
    validateAutomaticRecoveryArtifactBindingCandidate(candidate, {
      observed_at: observedAt,
      request_bound_at: requestBoundAt,
      candidate_count: value.candidates.length,
      candidate_index: index,
    });
    requireExactArtifactUrl(
      candidate.artifact_url,
      value.scope.repository,
      value.scope.pull_request,
      candidate.selector,
    );
    const key = `${candidate.selector.kind}:${candidate.selector.id}`;
    if (selectors.has(key)) {
      throw new Error("automatic recovery artifact binding candidate selector repeats");
    }
    selectors.add(key);
  });
  digest(value.authority_digest,
    "automatic recovery artifact binding candidate authority_digest");
  const { authority_digest: authorityDigest, ...withoutDigest } = value;
  if (authorityDigest !== runnerDigestCanonical(
    "codex-review-gate-v2-automatic-recovery-artifact-binding-candidate-authority",
    withoutDigest,
  )) {
    throw new Error("automatic recovery artifact binding candidate authority digest is invalid");
  }
  if (Buffer.byteLength(canonicalJson(value), "utf8") >
      MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_ACTION_BYTES) {
    throw ledgerError(
      "automatic-artifact-binding-candidate-size",
      "automatic artifact binding candidate authority exceeds its hard byte cap",
    );
  }
  return value;
}

function automaticRecoveryArtifactBindingCandidateItemAuthority(
  aggregateValue,
  candidateValue,
) {
  const aggregate =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(aggregateValue);
  const candidate = aggregate.candidates.find((item) =>
    item.candidate_digest === candidateValue.candidate_digest);
  if (candidate === undefined) {
    throw new Error("automatic recovery artifact candidate is outside its authority");
  }
  const profile = automaticRecoveryArtifactBindingCandidateProfile(aggregate);
  const withoutDigest = {
    schema:
      "codex-review-gate-git-ledger-automatic-recovery-artifact-binding-candidate-v2",
    schema_version: aggregate.schema_version,
    ...(profile.legacy
      ? {}
      : {
          candidate_version: profile.candidate_version,
          purpose: profile.purpose,
        }),
    decision: aggregate.decision,
    snapshot_fingerprint: aggregate.snapshot_fingerprint,
    review_epoch_id: aggregate.review_epoch_id,
    observed_at: aggregate.observed_at,
    generation_id: aggregate.generation_id,
    generation_index: aggregate.generation_index,
    request_id: aggregate.request_id,
    request_node_id: aggregate.request_node_id,
    request_bound_at: aggregate.request_bound_at,
    request_binding_record_oid: aggregate.request_binding_record_oid,
    request_binding_receipt_digest:
      aggregate.request_binding_receipt_digest,
    expected_actor: structuredClone(aggregate.expected_actor),
    expected_app: structuredClone(aggregate.expected_app),
    scope: structuredClone(aggregate.scope),
    candidate: structuredClone(candidate),
  };
  return deepFreeze({
    ...withoutDigest,
    authority_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-automatic-recovery-artifact-binding-candidate-authority",
      withoutDigest,
    ),
  });
}

function validateAutomaticRecoveryArtifactBindingCandidateItemAuthority(value) {
  assertObject(value,
    "automatic recovery artifact binding candidate item authority");
  const profile = automaticRecoveryArtifactBindingCandidateProfile(value, {
    item: true,
  });
  digest(value.snapshot_fingerprint,
    "automatic recovery artifact binding candidate item snapshot_fingerprint");
  if (!RUNNER_EPOCH_ID.test(value.review_epoch_id)) {
    throw new Error("automatic recovery artifact binding candidate item epoch is invalid");
  }
  const observedAt = timestamp(value.observed_at,
    "automatic recovery artifact binding candidate item observed_at");
  const generationIndex = integerBetween(
    value.generation_index,
    profile.minimum_generation,
    profile.maximum_generation,
    "automatic recovery artifact binding candidate item generation_index");
  if (value.generation_id !== `automatic:${generationIndex}`) {
    throw new Error("automatic recovery artifact binding candidate item generation is invalid");
  }
  decimal(value.request_id,
    "automatic recovery artifact binding candidate item request_id");
  boundedString(value.request_node_id,
    "automatic recovery artifact binding candidate item request_node_id", 256);
  const requestBoundAt = timestamp(value.request_bound_at,
    "automatic recovery artifact binding candidate item request_bound_at");
  sha(value.request_binding_record_oid,
    "automatic recovery artifact binding candidate item request_binding_record_oid");
  digest(value.request_binding_receipt_digest,
    "automatic recovery artifact binding candidate item request_binding_receipt_digest");
  validateExternalActor(value.expected_actor,
    "automatic recovery artifact binding candidate item expected_actor");
  validateExternalApp(value.expected_app,
    "automatic recovery artifact binding candidate item expected_app");
  validateCodexProvider(value.expected_actor, value.expected_app,
    "automatic recovery artifact binding candidate item provider");
  validateAutomaticRecoveryArtifactBindingCandidateScope(value.scope);
  validateAutomaticRecoveryArtifactBindingCandidate(value.candidate, {
    observed_at: observedAt,
    request_bound_at: requestBoundAt,
    ...(profile.exact_candidate_count === null
      ? {}
      : { candidate_count: profile.exact_candidate_count }),
  });
  requireExactArtifactUrl(
    value.candidate.artifact_url,
    value.scope.repository,
    value.scope.pull_request,
    value.candidate.selector,
  );
  digest(value.authority_digest,
    "automatic recovery artifact binding candidate item authority_digest");
  const { authority_digest: authorityDigest, ...withoutDigest } = value;
  if (authorityDigest !== digestCanonical(
    "codex-review-gate-v2-git-ledger-automatic-recovery-artifact-binding-candidate-authority",
    withoutDigest,
  )) {
    throw new Error("automatic recovery artifact binding candidate item digest is invalid");
  }
  return value;
}

function automaticRecoveryArtifactBindingCandidateSemantic(value) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateItemAuthority(value);
  const profile = automaticRecoveryArtifactBindingCandidateProfile(authority, {
    item: true,
  });
  const candidate = authority.candidate;
  return {
    candidate_version: profile.candidate_version,
    purpose: profile.purpose,
    decision: profile.decision,
    review_epoch_id: authority.review_epoch_id,
    generation_id: authority.generation_id,
    request_id: authority.request_id,
    request_node_id: authority.request_node_id,
    request_bound_at: authority.request_bound_at,
    request_binding_record_oid: authority.request_binding_record_oid,
    request_binding_receipt_digest: authority.request_binding_receipt_digest,
    expected_actor: structuredClone(authority.expected_actor),
    expected_app: structuredClone(authority.expected_app),
    scope: structuredClone(authority.scope),
    candidate: {
      index: candidate.index,
      count: candidate.count,
      selector: structuredClone(candidate.selector),
      artifact_node_id: candidate.artifact_node_id,
      artifact_url: candidate.artifact_url,
      artifact_type: candidate.artifact_type,
      artifact_created_at: candidate.artifact_created_at,
      evidence_raw_body_sha256: candidate.evidence_raw_body_sha256,
    },
  };
}

function automaticRecoveryArtifactBindingCandidateAggregateSemantic(value, {
  preserve_legacy_digest: preserveLegacyDigest = false,
} = {}) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(value);
  const profile = automaticRecoveryArtifactBindingCandidateProfile(authority);
  const semantic = {
    candidate_version: profile.candidate_version,
    purpose: profile.purpose,
    decision: profile.decision,
    review_epoch_id: authority.review_epoch_id,
    generation_id: authority.generation_id,
    request_id: authority.request_id,
    request_node_id: authority.request_node_id,
    request_bound_at: authority.request_bound_at,
    request_binding_record_oid: authority.request_binding_record_oid,
    request_binding_receipt_digest:
      authority.request_binding_receipt_digest,
    expected_actor: structuredClone(authority.expected_actor),
    expected_app: structuredClone(authority.expected_app),
    scope: structuredClone(authority.scope),
    candidates: authority.candidates.map((candidate) => ({
      selector: structuredClone(candidate.selector),
      artifact_node_id: candidate.artifact_node_id,
      artifact_url: candidate.artifact_url,
      artifact_type: candidate.artifact_type,
      artifact_created_at: candidate.artifact_created_at,
      evidence_raw_body_sha256: candidate.evidence_raw_body_sha256,
    })),
  };
  if (profile.legacy && preserveLegacyDigest) {
    delete semantic.candidate_version;
    delete semantic.purpose;
    delete semantic.decision;
  }
  return semantic;
}

function automaticRecoveryArtifactBindingCandidateSemanticContext(value) {
  const { candidates: _candidates, ...context } = value;
  return context;
}

function automaticRecoveryArtifactBindingCandidateSemanticContextsEqual(
  left,
  right,
) {
  return canonicalJson(
    automaticRecoveryArtifactBindingCandidateSemanticContext(left),
  ) === canonicalJson(
    automaticRecoveryArtifactBindingCandidateSemanticContext(right),
  );
}

function automaticRecoveryArtifactBindingCandidateSemanticMatchesAt(
  current,
  frozen,
  offset,
) {
  return Number.isInteger(offset) && offset >= 0 &&
    current.candidates.length >= offset + frozen.candidates.length &&
    canonicalJson(current.candidates.slice(
      offset,
      offset + frozen.candidates.length,
    )) === canonicalJson(frozen.candidates);
}

function automaticRecoveryArtifactBindingCandidateSemanticsOverlap(
  left,
  right,
) {
  const leftSelectors = new Set(left.candidates.map((candidate) =>
    canonicalJson(candidate.selector)));
  return right.candidates.some((candidate) =>
    leftSelectors.has(canonicalJson(candidate.selector)));
}

function automaticRecoveryArtifactBindingCandidateSuffixAuthority(
  value,
  offset,
) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(value);
  if (!Number.isInteger(offset) || offset < 0 ||
      offset >= authority.candidates.length) {
    throw new Error("automatic recovery artifact candidate suffix is empty or invalid");
  }
  const sourceCandidates = authority.candidates.slice(offset);
  const candidates = sourceCandidates.map((candidate, index) => {
    const withoutDigest = {
      index,
      count: sourceCandidates.length,
      selector: structuredClone(candidate.selector),
      artifact_node_id: candidate.artifact_node_id,
      artifact_url: candidate.artifact_url,
      artifact_type: candidate.artifact_type,
      artifact_created_at: candidate.artifact_created_at,
      evidence_response_server_time:
        candidate.evidence_response_server_time,
      evidence_raw_body_sha256: candidate.evidence_raw_body_sha256,
    };
    return {
      ...withoutDigest,
      candidate_digest: runnerDigestCanonical(
        "codex-review-gate-v2-automatic-recovery-artifact-binding-candidate",
        withoutDigest,
      ),
    };
  });
  const { authority_digest: _authorityDigest, ...sourceWithoutDigest } =
    authority;
  const withoutDigest = {
    ...structuredClone(sourceWithoutDigest),
    candidates,
  };
  return validateAutomaticRecoveryArtifactBindingCandidateAuthority({
    ...withoutDigest,
    authority_digest: runnerDigestCanonical(
      "codex-review-gate-v2-automatic-recovery-artifact-binding-candidate-authority",
      withoutDigest,
    ),
  });
}

function automaticRecoveryArtifactBindingCandidateSetDigest(value) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(value);
  return digestCanonical(
    "codex-review-gate-v2-automatic-recovery-artifact-binding-candidate-set",
    automaticRecoveryArtifactBindingCandidateAggregateSemantic(authority, {
      preserve_legacy_digest: authority.schema_version === 1,
    }),
  );
}

function validateAutomaticRequestRecoveryAuthority(value, {
  boundary = null,
} = {}) {
  assertObject(value, "automatic request recovery authority");
  exactKeys(value, AUTOMATIC_RECOVERY_AUTHORITY_KEYS,
    "automatic request recovery authority");
  if (
    value.schema !== "codex-review-gate-automatic-request-recovery-authority-v2" ||
    value.schema_version !== 1 || value.decision !== "findings" ||
    value.same_review_epoch !== true
  ) {
    throw new Error("automatic request recovery authority is outside its closed profile");
  }
  digest(value.snapshot_fingerprint,
    "automatic request recovery snapshot_fingerprint");
  boundedString(value.review_epoch_id,
    "automatic request recovery review_epoch_id", 96);
  const priorIndex = integerBetween(value.prior_generation_index, 1, 2,
    "automatic request recovery prior_generation_index");
  const nextIndex = integerBetween(value.next_generation_index, 2, 3,
    "automatic request recovery next_generation_index");
  if (
    value.prior_generation_id !== `automatic:${priorIndex}` ||
    value.next_generation_id !== `automatic:${nextIndex}` ||
    nextIndex !== priorIndex + 1
  ) {
    throw new Error("automatic request recovery generations are not immediate");
  }
  decimal(value.prior_request_id,
    "automatic request recovery prior_request_id");
  sha(value.prior_request_binding_record_oid,
    "automatic request recovery prior_request_binding_record_oid");
  digest(value.prior_request_binding_receipt_digest,
    "automatic request recovery prior_request_binding_receipt_digest");
  assertObject(value.scope, "automatic request recovery scope");
  exactKeys(value.scope, [
    "repository_node_id", "pull_request_node_id", "pull_request_number",
    "base_oid", "head_oid", "merge_base_oid",
  ], "automatic request recovery scope");
  boundedString(value.scope.repository_node_id,
    "automatic request recovery scope.repository_node_id", 256);
  boundedString(value.scope.pull_request_node_id,
    "automatic request recovery scope.pull_request_node_id", 256);
  positiveInteger(value.scope.pull_request_number,
    "automatic request recovery scope.pull_request_number");
  sha(value.scope.base_oid, "automatic request recovery scope.base_oid");
  sha(value.scope.head_oid, "automatic request recovery scope.head_oid");
  sha(value.scope.merge_base_oid,
    "automatic request recovery scope.merge_base_oid");
  digest(value.scope_digest, "automatic request recovery scope_digest");
  if (
    value.scope_digest !== digestCanonical(
      "codex-review-gate-v2-automatic-recovery-scope",
      value.scope,
    )
  ) {
    throw new Error("automatic request recovery scope digest is invalid");
  }
  const findingIds = normalizeUniqueStringArray(
    value.finding_ids,
    "automatic request recovery finding_ids",
  );
  const closureIds = normalizeUniqueStringArray(
    value.closure_ids,
    "automatic request recovery closure_ids",
  );
  if (
    findingIds.length === 0 || findingIds.length !== closureIds.length ||
    !Array.isArray(value.closure_records) ||
    value.closure_records.length !== findingIds.length
  ) {
    throw new Error("automatic request recovery closure inventory is incomplete");
  }
  let latestFinding = null;
  let latestClosure = null;
  value.closure_records.forEach((record, index) => {
    assertObject(record, `automatic request recovery closure_records[${index}]`);
    exactKeys(record, [
      "finding_id", "finding_kind", "finding_artifact_id",
      "finding_server_time", "closure_id", "closure_server_time",
      "closure_authority_digest",
    ], `automatic request recovery closure_records[${index}]`);
    if (
      record.finding_id !== findingIds[index] ||
      record.closure_id !== closureIds[index] ||
      !new Set(["inline", "top-level"]).has(record.finding_kind)
    ) {
      throw new Error("automatic request recovery closure ordering is invalid");
    }
    boundedString(record.finding_artifact_id,
      `automatic request recovery closure_records[${index}].finding_artifact_id`,
      256);
    const finding = timestamp(record.finding_server_time,
      `automatic request recovery closure_records[${index}].finding_server_time`);
    const closure = timestamp(record.closure_server_time,
      `automatic request recovery closure_records[${index}].closure_server_time`);
    digest(record.closure_authority_digest,
      `automatic request recovery closure_records[${index}].closure_authority_digest`);
    if (Date.parse(finding) >= Date.parse(closure)) {
      throw new Error("automatic request recovery closure does not follow its finding");
    }
    if (latestFinding === null || Date.parse(finding) > Date.parse(latestFinding)) {
      latestFinding = finding;
    }
    if (latestClosure === null || Date.parse(closure) > Date.parse(latestClosure)) {
      latestClosure = closure;
    }
  });
  const findingObservedAt = timestamp(value.finding_observed_at,
    "automatic request recovery finding_observed_at");
  const closureObservedAt = timestamp(value.closure_observed_at,
    "automatic request recovery closure_observed_at");
  const finalSnapshotServerTime = timestamp(value.final_snapshot_server_time,
    "automatic request recovery final_snapshot_server_time");
  if (
    findingObservedAt !== latestFinding || closureObservedAt !== latestClosure ||
    Date.parse(findingObservedAt) >= Date.parse(closureObservedAt) ||
    Date.parse(closureObservedAt) > Date.parse(finalSnapshotServerTime) ||
    (boundary !== null &&
      Date.parse(finalSnapshotServerTime) > Date.parse(timestamp(
        boundary,
        "automatic request recovery record boundary",
      )))
  ) {
    throw new Error("automatic request recovery authority times are invalid");
  }
  for (const key of [
    "pagination_sha256", "final_reread_sha256", "evidence_snapshot_digest",
    "reducer_input_digest", "reducer_report_digest", "authority_digest",
  ]) {
    digest(value[key], `automatic request recovery ${key}`);
  }
  const { authority_digest: authorityDigest, ...withoutDigest } = value;
  if (
    authorityDigest !== digestCanonical(
      "codex-review-gate-v2-automatic-request-recovery-authority",
      withoutDigest,
    )
  ) {
    throw new Error("automatic request recovery authority digest is invalid");
  }
  return value;
}

function automaticRequestRecoveryTransitionDigest(authorityValue) {
  const authority = validateAutomaticRequestRecoveryAuthority(authorityValue);
  return digestCanonical(
    "codex-review-gate-v2-automatic-request-recovery-transition",
    {
      review_epoch_id: authority.review_epoch_id,
      prior_generation_id: authority.prior_generation_id,
      next_generation_id: authority.next_generation_id,
      prior_request_id: authority.prior_request_id,
      prior_request_binding_record_oid:
        authority.prior_request_binding_record_oid,
      prior_request_binding_receipt_digest:
        authority.prior_request_binding_receipt_digest,
      scope_digest: authority.scope_digest,
    },
  );
}

function validateAutomaticRecoveryCompletionExtension({
  intent_authority: intentAuthorityValue,
  completion_authority: completionAuthorityValue,
}) {
  const intentAuthority = validateAutomaticRequestRecoveryAuthority(
    intentAuthorityValue,
  );
  const completionAuthority = validateAutomaticRequestRecoveryAuthority(
    completionAuthorityValue,
  );
  if (
    automaticRequestRecoveryTransitionDigest(intentAuthority) !==
      automaticRequestRecoveryTransitionDigest(completionAuthority)
  ) {
    throw ledgerError(
      "automatic-recovery-completion-drift",
      "automatic recovery completion changes its scope, request, or generation authority",
    );
  }
  const completionFindings = new Set(completionAuthority.finding_ids);
  const completionClosures = new Set(completionAuthority.closure_ids);
  const completionRecords = new Set(
    completionAuthority.closure_records.map((record) => canonicalJson(
      automaticRecoveryClosureSemantic(record),
    )),
  );
  if (
    intentAuthority.finding_ids.some((id) => !completionFindings.has(id)) ||
    intentAuthority.closure_ids.some((id) => !completionClosures.has(id)) ||
    intentAuthority.closure_records.some((record) =>
      !completionRecords.has(canonicalJson(
        automaticRecoveryClosureSemantic(record),
      ))) ||
    Date.parse(completionAuthority.finding_observed_at) <
      Date.parse(intentAuthority.finding_observed_at) ||
    Date.parse(completionAuthority.closure_observed_at) <
      Date.parse(intentAuthority.closure_observed_at) ||
    Date.parse(completionAuthority.final_snapshot_server_time) <
      Date.parse(intentAuthority.final_snapshot_server_time)
  ) {
    throw ledgerError(
      "automatic-recovery-completion-proof-regressed",
      "automatic recovery completion removes or rewrites durable finding closure authority",
    );
  }
  return { intent_authority: intentAuthority, completion_authority: completionAuthority };
}

function automaticRecoveryClosureSemantic(record) {
  return {
    finding_id: record.finding_id,
    finding_kind: record.finding_kind,
    finding_artifact_id: record.finding_artifact_id,
    finding_server_time: record.finding_server_time,
    closure_id: record.closure_id,
    closure_server_time: record.closure_server_time,
  };
}

function normalizeInitialSourceAuthority(value) {
  assertObject(value, "initial source authority");
  exactKeys(value, [
    "tip_commit_sha", "same_job_source_inventory_digest",
    "same_job_scoped_authority_digest",
    "fully_reachable_record_manifest_digest",
    "capability_attestation_commit_sha", "capability_input_digest",
    "controller_release_digest", "post_ref_receipt",
  ], "initial source authority");
  sha(value.tip_commit_sha, "initial source tip_commit_sha");
  for (const key of [
    "same_job_source_inventory_digest", "same_job_scoped_authority_digest",
    "fully_reachable_record_manifest_digest", "capability_input_digest",
    "controller_release_digest",
  ]) {
    digest(value[key], `initial source ${key}`);
  }
  sha(value.capability_attestation_commit_sha,
    "initial source capability_attestation_commit_sha");
  validateRefReceipt(value.post_ref_receipt);
  return value;
}

function normalizeInitialLeaseAuthority(value) {
  assertObject(value, "initial lease authority");
  exactKeys(value, [
    "lease_id", "owner", "acquire_commit_sha", "acquired_at", "expires_at",
    "evaluated_scope_receipt_digest",
  ], "initial lease authority");
  boundedString(value.lease_id, "initial lease_id", 256);
  const owner = normalizeLeaseOwner(value.owner);
  sha(value.acquire_commit_sha, "initial lease acquire_commit_sha");
  const acquired = timestamp(value.acquired_at, "initial lease acquired_at");
  const expires = timestamp(value.expires_at, "initial lease expires_at");
  if (Date.parse(expires) <= Date.parse(acquired)) {
    throw new Error("initial lease expiry is not after acquire");
  }
  digest(value.evaluated_scope_receipt_digest,
    "initial lease evaluated_scope_receipt_digest");
  return { ...value, owner };
}

function normalizeInitialEvaluatedScopeAuthority(value) {
  assertObject(value, "initial evaluated scope authority");
  exactKeys(value, [
    "relation", "record_evaluated_scope_receipt_digest",
    "lease_evaluated_scope_receipt_digest",
    "discovery_continuity_receipt",
    "provider_pre_scope_receipt_digest",
  ], "initial evaluated scope authority");
  if (!new Set([
    "pull-request-event", "provider-selector", "scheduled-pull-request",
    "manual-pull-request",
  ]).has(value.relation)) {
    throw new Error("initial evaluated scope relation is unsupported");
  }
  digest(value.record_evaluated_scope_receipt_digest,
    "initial record evaluated scope digest");
  digest(value.lease_evaluated_scope_receipt_digest,
    "initial lease evaluated scope digest");
  validateV2GitLedgerDiscoveryContinuityReceipt(
    value.discovery_continuity_receipt,
  );
  if (value.relation === "provider-selector") {
    digest(value.provider_pre_scope_receipt_digest,
      "initial provider pre-scope digest");
  } else if (value.provider_pre_scope_receipt_digest !== null) {
    throw new Error("initial non-provider scope cites provider authority");
  }
  return value;
}

function normalizeInitialWorkflowCommandAuthority(
  value,
  { established = false } = {},
) {
  assertObject(value, "initial workflow command authority");
  exactKeys(value, ["command", "command_digest"],
    "initial workflow command authority");
  const command = value.command;
  assertObject(command, "initial stored workflow command");
  exactKeys(command, [
    "schema", "schema_version", "command", "repository", "pull_request",
    "dispatch_binding", "selection_policy", "route", "invocation",
    "workflow_receipt", "receipt_policy",
  ], "initial stored workflow command");
  if (
    command.schema !== "codex-review-gate-workflow-command-v2" ||
    command.schema_version !== 1 || command.command !== "run"
  ) {
    throw new Error("initial stored workflow command schema is unsupported");
  }
  assertObject(command.repository, "initial command repository");
  exactKeys(command.repository, ["owner", "name"],
    "initial command repository");
  assertObject(command.pull_request, "initial command pull_request");
  exactKeys(command.pull_request, ["number"], "initial command pull_request");
  positiveInteger(command.pull_request.number,
    "initial command pull_request.number");
  const dispatchBinding = command.dispatch_binding === null
    ? null
    : normalizeCandidateDispatchBinding(
      command.dispatch_binding,
      "initial command dispatch binding",
    );
  assertObject(command.route, "initial command route");
  exactKeys(command.route, ["operation", "trigger", "observation_boundary"],
    "initial command route");
  const supportedBoundary = established
    ? new Set([
        "initial", "public-initial-wait-complete",
        "public-post-request-wait-complete", "public-no-start-wait-complete",
        "private-reconcile",
      ])
    : new Set(["initial"]);
  const supportedTriggers = established
    ? new Set(["initial", "provider-event", "schedule", "manual", "timer"])
    : new Set(["initial", "provider-event", "schedule", "manual"]);
  if (
    !supportedBoundary.has(command.route.observation_boundary) ||
    !new Set(["ordinary", "evaluate-only"]).has(command.route.operation) ||
    !supportedTriggers.has(command.route.trigger)
  ) {
    throw new Error("initial command route is unsupported");
  }
  if ((command.route.trigger === "schedule") !==
      (dispatchBinding !== null) ||
      dispatchBinding !== null &&
        candidateDispatchNumber(dispatchBinding.candidate) !==
          command.pull_request.number) {
    throw new Error("initial command dispatch binding differs from its route");
  }
  assertObject(command.invocation, "initial command invocation");
  exactKeys(command.invocation, [
    "event_name", "event_payload_sha256", "run_id", "run_attempt",
    "actor_id",
  ], "initial command invocation");
  boundedString(command.invocation.event_name,
    "initial command event_name", 128);
  digest(command.invocation.event_payload_sha256,
    "initial command event_payload_sha256");
  decimal(command.invocation.run_id, "initial command run_id");
  positiveInteger(command.invocation.run_attempt,
    "initial command run_attempt");
  decimal(command.invocation.actor_id, "initial command actor_id");
  assertObject(command.workflow_receipt, "initial command workflow_receipt");
  if (!new Set(["head", "test-merge-with-head-sentinel"])
    .has(command.workflow_receipt.status_target_mode)) {
    throw new Error("initial command status target mode is unsupported");
  }
  digest(value.command_digest, "initial workflow command_digest");
  if (
    value.command_digest !== digestCanonical(
      "codex-review-gate-v2-workflow-command",
      command,
    )
  ) {
    throw new Error("initial workflow command digest is invalid");
  }
  return value;
}

function normalizeInitialPreflightAuthority(value) {
  assertObject(value, "initial preflight authority");
  exactKeys(value, [
    "preflight_receipt_digest", "configuration_digest",
    "repository_visibility", "public_wait_supported",
    "public_wait_topology", "public_wait_endpoint_receipts",
    "public_wait_topology_digest",
    "public_wait_endpoint_inventory_digest",
  ], "initial preflight authority");
  digest(value.preflight_receipt_digest,
    "initial preflight receipt_digest");
  digest(value.configuration_digest,
    "initial preflight configuration_digest");
  const visibility = boundedString(value.repository_visibility,
    "initial preflight repository_visibility", 32);
  if (!new Set(["public", "private", "internal"]).has(visibility)) {
    throw new Error("initial preflight repository visibility is unsupported");
  }
  assertObject(value.public_wait_topology,
    "initial preflight public_wait_topology");
  exactKeys(value.public_wait_topology, [
    "required", "configuration_compatible", "live_canary_required",
    "environments",
  ], "initial preflight public_wait_topology");
  const topology = value.public_wait_topology;
  if (
    topology.configuration_compatible !== true ||
    !Array.isArray(topology.environments) ||
    typeof topology.required !== "boolean" ||
    typeof topology.live_canary_required !== "boolean"
  ) {
    throw new Error("initial preflight public wait topology is invalid");
  }
  for (const [index, environment] of topology.environments.entries()) {
    assertObject(environment, `stored public wait environment ${index}`);
    exactKeys(environment, [
      "stage", "name", "id", "wait_timer_rule_id", "wait_timer_minutes",
    ], `stored public wait environment ${index}`);
    if (environment.wait_timer_minutes !== 15) {
      throw new Error("stored public wait timer is not fifteen minutes");
    }
    decimal(environment.id, `stored public wait environment ${index}.id`);
    decimal(environment.wait_timer_rule_id,
      `stored public wait environment ${index}.wait_timer_rule_id`);
  }
  if (!Array.isArray(value.public_wait_endpoint_receipts)) {
    throw new TypeError("initial public wait endpoint receipts are not bounded");
  }
  value.public_wait_endpoint_receipts.forEach((receipt, index) =>
    normalizeInitialEndpointReceipt(
      receipt,
      `stored public wait endpoint ${index}`,
    ));
  const supported = visibility === "public";
  if (
    value.public_wait_supported !== supported ||
    topology.required !== supported ||
    topology.live_canary_required !== supported ||
    topology.environments.length !== (supported ? 3 : 0) ||
    value.public_wait_endpoint_receipts.length !== (supported ? 4 : 0)
  ) {
    throw new Error("initial public wait topology differs from visibility");
  }
  digest(value.public_wait_topology_digest,
    "initial public wait topology_digest");
  digest(value.public_wait_endpoint_inventory_digest,
    "initial public wait endpoint_inventory_digest");
  if (
    value.public_wait_topology_digest !== digestCanonical(
      "codex-review-gate-v2-initial-public-wait-topology",
      topology,
    ) ||
    value.public_wait_endpoint_inventory_digest !== digestCanonical(
      "codex-review-gate-v2-initial-public-wait-endpoint-inventory",
      value.public_wait_endpoint_receipts,
    )
  ) {
    throw new Error("initial public wait evidence digest is invalid");
  }
  return value;
}

export function validateV2GitLedgerRecord(value) {
  assertObject(value, "Git ledger record");
  exactKeys(value, [
    "schema",
    "schema_version",
    "record_type",
    "predecessor_commit_sha",
    "pull_request",
    "head_ref_oid",
    "base_ref_oid",
    "potential_merge_commit_oid",
    "kind",
    "effect_id",
    "idempotency_key",
    "server_observed_at",
    "payload",
    "payload_digest",
    "control_comment_binding",
    "lease",
    "record_digest",
  ], "Git ledger record");
  if (value.schema !== V2_GIT_LEDGER_RECORD_SCHEMA || value.schema_version !== 1) {
    throw new Error("Git ledger record has an unsupported schema");
  }
  if (!RECORD_TYPES.has(value.record_type)) {
    throw new Error("Git ledger record_type is not a production record");
  }
  sha(value.predecessor_commit_sha, "record.predecessor_commit_sha");
  const repositoryObservation = REPOSITORY_RECORD_TYPES.has(value.record_type);
  const pullRequest = repositoryObservation
    ? requireNull(value.pull_request, "candidate inventory pull_request")
    : normalizePullRequest(value.pull_request);
  const head = repositoryObservation
    ? requireNull(value.head_ref_oid, "candidate inventory head_ref_oid")
    : sha(value.head_ref_oid, "record.head_ref_oid");
  const base = repositoryObservation
    ? requireNull(value.base_ref_oid, "candidate inventory base_ref_oid")
    : sha(value.base_ref_oid, "record.base_ref_oid");
  const potential = repositoryObservation
    ? requireNull(
      value.potential_merge_commit_oid,
      "candidate inventory potential_merge_commit_oid",
    )
    : nullableSha(
      value.potential_merge_commit_oid,
      "record.potential_merge_commit_oid",
    );
  const kind = nullableBoundedString(value.kind, "record.kind", 128);
  const effectId = nullableBoundedString(value.effect_id, "record.effect_id", 256);
  const idempotencyKey = nullableBoundedString(
    value.idempotency_key,
    "record.idempotency_key",
    256,
  );
  const observedAt = timestamp(value.server_observed_at, "record.server_observed_at");
  validateCanonicalJsonValue(value.payload, "record.payload");
  const payloadDigest = digest(value.payload_digest, "record.payload_digest");
  if (payloadDigest !== digestV2GitLedgerPayload(value.payload)) {
    throw new Error("Git ledger record payload digest is invalid");
  }
  const control = normalizeControlCommentBinding(value.control_comment_binding);
  const lease = normalizeLeaseBinding(value.lease);
  validateRecordTypeFields({
    ...value,
    pull_request: pullRequest,
    head_ref_oid: head,
    base_ref_oid: base,
    potential_merge_commit_oid: potential,
    kind,
    effect_id: effectId,
    idempotency_key: idempotencyKey,
    server_observed_at: observedAt,
    control_comment_binding: control,
    lease,
  });
  digest(value.record_digest, "record.record_digest");
  const { record_digest: _recordDigest, ...withoutDigest } = value;
  const expectedDigest = digestCanonical(
    "codex-review-gate-v2-git-ledger-record",
    withoutDigest,
  );
  if (expectedDigest !== value.record_digest) {
    throw new Error("Git ledger record digest is invalid");
  }
  return deepFreeze(structuredClone(value));
}

export function validateV2GitLedgerEnvelope(value, expected = null) {
  assertObject(value, "Git ledger envelope");
  exactKeys(value, [
    "schema",
    "schema_version",
    "repository",
    "ledger_ref",
    "record_type",
    "sequence",
    "pull_request",
    "head_ref_oid",
    "base_ref_oid",
    "potential_merge_commit_oid",
    "kind",
    "effect_id",
    "idempotency_key",
    "predecessor_commit_sha",
    "server_observed_at",
    "payload",
    "payload_digest",
    "control_comment_binding",
    "lease",
    "source_workflow",
    "workflow_provenance",
    "workflow_provenance_jwt",
    "envelope_digest",
  ], "Git ledger envelope");
  if (
    value.schema !== V2_GIT_LEDGER_ENVELOPE_SCHEMA ||
    value.schema_version !== 1 || !ALL_RECORD_TYPES.has(value.record_type)
  ) {
    throw new Error("Git ledger envelope has an unsupported schema or record type");
  }
  const repository = normalizeRepository(value.repository);
  const ledgerRef = normalizeLedgerRef(value.ledger_ref);
  const sequence = nonnegativeInteger(value.sequence, "envelope.sequence");
  const predecessor = value.predecessor_commit_sha === null
    ? null
    : sha(value.predecessor_commit_sha, "envelope.predecessor_commit_sha");
  const source = normalizeSourceWorkflow(
    value.source_workflow,
    "envelope.source_workflow",
  );
  const provenance = validateV2GitLedgerProvenanceReceipt(
    value.workflow_provenance,
  );
  const compactJwt = compactOidcJwt(value.workflow_provenance_jwt);
  if (rawDigest(compactJwt) !== provenance.token_sha256) {
    throw new Error(
      "Git ledger workflow provenance JWT digest differs from its receipt",
    );
  }
  timestamp(value.server_observed_at, "envelope.server_observed_at");
  validateCanonicalJsonValue(value.payload, "envelope.payload");
  if (digestV2GitLedgerPayload(value.payload) !== value.payload_digest) {
    throw new Error("Git ledger envelope payload digest is invalid");
  }
  normalizeEnvelopeScopeFields(value);
  validateInternalEnvelopeFields(value);
  validateEnvelopeProvenanceBinding(value, provenance);
  digest(value.envelope_digest, "envelope.envelope_digest");
  const { envelope_digest: _digest, ...withoutDigest } = value;
  if (
    digestCanonical("codex-review-gate-v2-git-ledger-envelope", withoutDigest) !==
    value.envelope_digest
  ) {
    throw new Error("Git ledger envelope digest is invalid");
  }
  if (expected !== null && (
    canonicalJson(repository) !== canonicalJson(expected.repository) ||
    ledgerRef !== expected.ledger_ref ||
    canonicalJson(source) !== canonicalJson(expected.source_workflow) ||
    !provenanceMatchesExpected(provenance, expected)
  )) {
    throw new Error("Git ledger envelope does not bind its repository, ref, and provenance");
  }
  if (sequence === 0 && predecessor !== null) {
    throw new Error("Git ledger genesis cannot have a predecessor");
  }
  if (sequence > 0 && predecessor === null) {
    throw new Error("non-genesis Git ledger envelope requires a predecessor");
  }
  return value;
}

export function validateV2GitLedgerPublicEnvelope(value) {
  assertObject(value, "public Git ledger envelope");
  exactKeys(value, [
    "schema",
    "schema_version",
    "repository",
    "ledger_ref",
    "record_type",
    "sequence",
    "pull_request",
    "head_ref_oid",
    "base_ref_oid",
    "potential_merge_commit_oid",
    "kind",
    "effect_id",
    "idempotency_key",
    "predecessor_commit_sha",
    "server_observed_at",
    "payload",
    "payload_digest",
    "control_comment_binding",
    "lease",
    "source_workflow",
    "workflow_provenance",
    "envelope_digest",
    "public_envelope_digest",
  ], "public Git ledger envelope");
  if (
    value.schema !== V2_GIT_LEDGER_PUBLIC_ENVELOPE_SCHEMA ||
    value.schema_version !== 1 || !ALL_RECORD_TYPES.has(value.record_type)
  ) {
    throw new Error("public Git ledger envelope has an unsupported schema or record type");
  }
  normalizeRepository(value.repository);
  normalizeLedgerRef(value.ledger_ref);
  nonnegativeInteger(value.sequence, "public envelope.sequence");
  if (value.predecessor_commit_sha !== null) {
    sha(value.predecessor_commit_sha, "public envelope.predecessor_commit_sha");
  }
  timestamp(value.server_observed_at, "public envelope.server_observed_at");
  validateCanonicalJsonValue(value.payload, "public envelope.payload");
  if (digestV2GitLedgerPayload(value.payload) !== value.payload_digest) {
    throw new Error("public Git ledger envelope payload digest is invalid");
  }
  normalizeSourceWorkflow(value.source_workflow, "public envelope.source_workflow");
  validateV2GitLedgerProvenanceReceipt(value.workflow_provenance);
  normalizeEnvelopeScopeFields(value);
  validateInternalEnvelopeFields(value);
  validateEnvelopeProvenanceBinding(value, value.workflow_provenance);
  digest(value.envelope_digest, "public envelope.envelope_digest");
  digest(value.public_envelope_digest, "public envelope.public_envelope_digest");
  const { public_envelope_digest: _digest, ...withoutDigest } = value;
  if (
    digestCanonical(
      "codex-review-gate-v2-git-ledger-public-envelope",
      withoutDigest,
    ) !== value.public_envelope_digest
  ) {
    throw new Error("public Git ledger envelope digest is invalid");
  }
  return value;
}

function validateProjectionEnvelope(value) {
  if (value?.schema === V2_GIT_LEDGER_PUBLIC_ENVELOPE_SCHEMA) {
    return validateV2GitLedgerPublicEnvelope(value);
  }
  return validateV2GitLedgerEnvelope(value);
}

function recordFromProjectionEnvelope(value) {
  const envelope = validateProjectionEnvelope(value);
  return createV2GitLedgerRecord({
    record_type: envelope.record_type,
    predecessor_commit_sha: envelope.predecessor_commit_sha,
    pull_request: envelope.pull_request,
    head_ref_oid: envelope.head_ref_oid,
    base_ref_oid: envelope.base_ref_oid,
    potential_merge_commit_oid: envelope.potential_merge_commit_oid,
    kind: envelope.kind,
    effect_id: envelope.effect_id,
    idempotency_key: envelope.idempotency_key,
    server_observed_at: envelope.server_observed_at,
    payload: envelope.payload,
    control_comment_binding: envelope.control_comment_binding,
    lease: envelope.lease,
  });
}

function redactEnvelope(value) {
  if (value.schema === V2_GIT_LEDGER_PUBLIC_ENVELOPE_SCHEMA) {
    validateV2GitLedgerPublicEnvelope(value);
    return structuredClone(value);
  }
  validateV2GitLedgerEnvelope(value);
  const {
    schema: _schema,
    workflow_provenance_jwt: _compactJwt,
    ...publicFields
  } = value;
  const withoutDigest = {
    schema: V2_GIT_LEDGER_PUBLIC_ENVELOPE_SCHEMA,
    ...structuredClone(publicFields),
  };
  const redacted = {
    ...withoutDigest,
    public_envelope_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-public-envelope",
      withoutDigest,
    ),
  };
  validateV2GitLedgerPublicEnvelope(redacted);
  return redacted;
}

function redactRecordEntry(entry) {
  const redacted = {
    commit_sha: entry.commit_sha,
    parents: structuredClone(entry.parents),
    tree_sha: entry.tree_sha,
    blob_sha: entry.blob_sha,
    envelope: redactEnvelope(entry.envelope),
    evidence: structuredClone(entry.evidence),
  };
  if (entry.candidate_inventory_attachment_evidence !== undefined) {
    safeReflectApply(
      safeWeakMapSet,
      REDACTED_CANDIDATE_INVENTORY_ATTACHMENT_EVIDENCE,
      [redacted, entry.candidate_inventory_attachment_evidence],
    );
  }
  return redacted;
}

function candidateInventoryAttachmentEvidence(entry) {
  return entry?.candidate_inventory_attachment_evidence ??
    safeReflectApply(
      safeWeakMapGet,
      REDACTED_CANDIDATE_INVENTORY_ATTACHMENT_EVIDENCE,
      [entry],
    ) ?? null;
}

function transferCandidateInventoryAttachmentEvidence(source, target) {
  if (!Array.isArray(source) || !Array.isArray(target) ||
      source.length !== target.length) {
    throw new TypeError("candidate inventory evidence transfer is unbounded");
  }
  for (let index = 0; index < source.length; index += 1) {
    const evidence = candidateInventoryAttachmentEvidence(source[index]);
    if (evidence === null) continue;
    if (
      source[index].commit_sha !== target[index].commit_sha ||
      source[index].envelope.envelope_digest !==
        target[index].envelope.envelope_digest
    ) {
      throw ledgerError(
        "candidate-inventory-attachment-binding",
        "redacted candidate evidence changed its durable record identity",
      );
    }
    safeReflectApply(
      safeWeakMapSet,
      REDACTED_CANDIDATE_INVENTORY_ATTACHMENT_EVIDENCE,
      [target[index], evidence],
    );
  }
}

function validateEnvelopeProvenanceBinding(envelope, provenance) {
  let operation;
  if (envelope.record_type === "genesis") {
    operation = "bootstrap-genesis";
  } else if (envelope.record_type === "capability-canary") {
    operation = `bootstrap-race-${envelope.payload.contender}`;
  } else if (envelope.record_type === "capability-attestation") {
    operation = "bootstrap-race";
  } else {
    operation = envelope.record_type;
  }
  const expectedScope = RECORD_TYPES.has(envelope.record_type)
    ? envelopeScope(envelope)
    : null;
  const expectedIdentity = RECORD_TYPES.has(envelope.record_type)
    ? productionRecordIdentity(envelope)
    : null;
  const binding = provenance.operation_binding;
  if (
    binding.operation !== operation ||
    canonicalJson(binding.repository) !== canonicalJson(envelope.repository) ||
    binding.ledger_ref !== envelope.ledger_ref ||
    binding.predecessor_commit_sha !== envelope.predecessor_commit_sha ||
    binding.github_server_time !== envelope.server_observed_at ||
    canonicalJson(binding.source_workflow) !==
      canonicalJson(envelope.source_workflow) ||
    canonicalJson(binding.effect_scope) !== canonicalJson(expectedScope) ||
    canonicalJson(binding.record_identity) !== canonicalJson(expectedIdentity)
  ) {
    throw new Error(
      "Git ledger envelope does not bind its exact workflow provenance operation",
    );
  }
  if (!RECORD_TYPES.has(envelope.record_type)) return;
  validateTriggerIdentityAgainstClaims(
    binding.evaluated_scope_receipt,
    provenance.claims,
  );
  if (envelope.record_type === "candidate-inventory-observation") {
    validateCandidateEvaluatedScopeBinding(
      envelope,
      binding.evaluated_scope_receipt,
    );
  } else if (envelope.record_type === "candidate-dispatch-observation") {
    validateCandidateDispatchEvaluatedScopeBinding(
      envelope,
      binding.evaluated_scope_receipt,
    );
  }
  validateOidcEffectScopeRelation(provenance.claims, expectedScope);
  const owner = new Set([
    "lease-acquire",
    "candidate-inventory-observation",
    "candidate-dispatch-observation",
  ]).has(envelope.record_type)
    ? envelope.payload.owner
    : envelope.lease.owner;
  if (
    provenance.claims.run_id !== owner.run_id ||
    provenance.claims.run_attempt !== String(owner.run_attempt)
  ) {
    throw new Error(
      "Git ledger envelope lease owner differs from OIDC run identity",
    );
  }
}

function sealRecord(value) {
  const base = {
    schema: V2_GIT_LEDGER_RECORD_SCHEMA,
    schema_version: 1,
    ...structuredClone(value),
    payload_digest: digestV2GitLedgerPayload(value.payload),
  };
  const sealed = {
    ...base,
    record_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-record",
      base,
    ),
  };
  validateV2GitLedgerRecord(sealed);
  return deepFreeze(sealed);
}

function sealEnvelope(value) {
  const base = {
    schema: V2_GIT_LEDGER_ENVELOPE_SCHEMA,
    schema_version: 1,
    ...structuredClone(value),
    payload_digest: digestV2GitLedgerPayload(value.payload),
  };
  const sealed = {
    ...base,
    envelope_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-envelope",
      base,
    ),
  };
  validateV2GitLedgerEnvelope(sealed);
  return deepFreeze(sealed);
}

async function loadStableChain({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  repo,
  verifyWorkflowProvenance,
  provenanceBudget,
  requestBudget,
  assertOperationCurrent = () => {},
  allowBootstrapCheckpoint = false,
  capability = null,
}) {
  assertOperationCurrent();
  const preRef = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const readBoundary = preRef.server_time;
  const reverse = [];
  const visited = new Set();
  let cursor = preRef.target_commit_sha;
  for (let count = 0; count < MAX_V2_GIT_LEDGER_COMMITS; count += 1) {
    if (visited.has(cursor)) {
      throw ledgerError("commit-cycle", "Git ledger commit graph contains a cycle");
    }
    visited.add(cursor);
    assertOperationCurrent();
    const record = await fetchCommitEnvelope({
      fetchImpl,
      authorization,
      base,
      repoPath,
      commitSha: cursor,
      repo,
      ref,
      requestBudget,
      assertOperationCurrent,
      allowCheckpointRoot: allowBootstrapCheckpoint,
    });
    assertOperationCurrent();
    if (record.checkpoint_root === true) {
      if (!allowBootstrapCheckpoint || reverse.length === 0) {
        throw ledgerError(
          "CHECKPOINT_SUFFIX_REQUIRED",
          "bootstrap checkpoint root requires one complete bounded suffix",
        );
      }
      return loadStableBootstrapCheckpointChain({
        fetchImpl,
        authorization,
        base,
        repoPath,
        ref,
        refSuffix,
        repo,
        verifyWorkflowProvenance,
        provenanceBudget,
        requestBudget,
        preRef,
        readBoundary,
        reverseSuffixRecords: reverse,
        checkpointRoot: record,
        capability,
        assertOperationCurrent,
      });
    }
    reverse.push(record);
    if (record.parents.length === 0) break;
    cursor = record.parents[0];
    if (count === MAX_V2_GIT_LEDGER_COMMITS - 1) {
      throw ledgerError("commit-cap", "Git ledger exceeds the bounded commit cap");
    }
  }
  const records = await hydrateCurrentCandidateInventoryAttachments({
    records: reverse.reverse(),
    fetchImpl,
    authorization,
    base,
    repoPath,
    repository: repo,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  validateReachableChain(records, readBoundary);
  assertOperationCurrent();
  const provenanceReverification = await reverifyReachableWorkflowProvenance({
    records,
    repository: repo,
    ledgerRef: ref,
    verifyWorkflowProvenance,
    provenanceBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const postRef = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertStableRefBoundary(preRef, postRef, "Git ledger");
  const state = projectChainState(records, readBoundary);
  return deepFreeze({
    tip_commit_sha: preRef.target_commit_sha,
    genesis_commit_sha: records[0].commit_sha,
    records,
    pre_ref: preRef,
    post_ref: postRef,
    observed_at: readBoundary,
    provenance_reverification: provenanceReverification,
    ...state,
  });
}

function assertStableRefBoundary(preRef, postRef, label) {
  if (preRef.target_commit_sha !== postRef.target_commit_sha) {
    throw ledgerError(
      "unstable-ref",
      `${label} ref changed across the two-pass stable read`,
    );
  }
  if (Date.parse(postRef.server_time) < Date.parse(preRef.server_time)) {
    throw ledgerError(
      "unstable-ref-time",
      `${label} post-ref server time regressed across the stable read`,
    );
  }
}

function checkpointProvenanceEvidence(recordOid, envelope, liveReceipt) {
  const withoutDigest = {
    record_oid: recordOid,
    stored_receipt_digest: envelope.workflow_provenance.receipt_digest,
    live_receipt_digest: liveReceipt.receipt_digest,
    token_sha256: liveReceipt.token_sha256,
    key_id: liveReceipt.key_id,
    verified_at_server_time: liveReceipt.verified_at_server_time,
    discovery: structuredClone(liveReceipt.discovery),
    jwks: structuredClone(liveReceipt.jwks),
  };
  return deepFreeze({
    ...withoutDigest,
    evidence_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-provenance-reverification",
      withoutDigest,
    ),
  });
}

function matureCheckpointProvenanceReverificationDigest(evidence) {
  if (!Array.isArray(evidence) || evidence.length === 0) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_PROVENANCE_INVENTORY",
      "mature checkpoint source provenance inventory is empty",
    );
  }
  return digestCanonical(
    "codex-review-gate-v2-mature-checkpoint-source-provenance-inventory",
    evidence.map((entry, index) => {
      assertObject(
        entry,
        `mature checkpoint source provenance evidence ${index}`,
      );
      sha(
        entry.record_oid,
        `mature checkpoint source provenance evidence ${index}.record_oid`,
      );
      for (const field of [
        "stored_receipt_digest", "token_sha256",
      ]) {
        digest(
          entry[field],
          `mature checkpoint source provenance evidence ${index}.${field}`,
        );
      }
      boundedString(
        entry.key_id,
        `mature checkpoint source provenance evidence ${index}.key_id`,
        512,
      );
      return {
        record_oid: entry.record_oid,
        stored_receipt_digest: entry.stored_receipt_digest,
        token_sha256: entry.token_sha256,
        key_id: entry.key_id,
      };
    }),
  );
}

async function loadMatureCheckpointSourceSeed({
  fetchImpl,
  authorization,
  base,
  repoPath,
  repository,
  ledgerRef,
  checkpointState,
  sourceSeedTreeSha,
  verifyWorkflowProvenance,
  provenanceBudget,
  requestBudget,
  assertOperationCurrent,
}) {
  assertOperationCurrent();
  const sourceTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: sourceSeedTreeSha,
    maximumEntries: 2,
    requestBudget,
    assertOperationCurrent,
  });
  const manifestEntry = sourceTreeEntries.find((entry) =>
    entry.path === V2_GIT_LEDGER_CHECKPOINT_SOURCE_SEED_MANIFEST_PATH) ?? null;
  const chunksEntry = sourceTreeEntries.find((entry) =>
    entry.path === V2_GIT_LEDGER_CHECKPOINT_SOURCE_SEED_CHUNKS_PATH) ?? null;
  if (
    sourceTreeEntries.length !== 2 ||
    manifestEntry?.mode !== "100644" || manifestEntry.type !== "blob" ||
    chunksEntry?.mode !== "040000" || chunksEntry.type !== "tree" ||
    sourceSeedTreeSha !== checkpointState.source.query_seed_tree_sha
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_TREE",
      "mature checkpoint source seed tree has an unsupported shape",
    );
  }
  assertOperationCurrent();
  const manifestBytes = await fetchExactGitBlobBytes({
    fetchImpl,
    authorization,
    base,
    repoPath,
    objectOid: manifestEntry.sha,
    maximumBytes: MAX_V2_GIT_LEDGER_BLOB_BYTES,
    requestBudget,
    assertOperationCurrent,
  });
  const manifest = validateMatureCheckpointSourceManifest(
    parseCanonicalCheckpointJson(
      manifestBytes,
      "mature checkpoint source manifest",
    ),
  );
  if (
    canonicalJson(manifest) !==
      canonicalJson(checkpointState.source.query_seed_manifest) ||
    chunksEntry.sha !== manifest.chunk_tree_sha
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_BINDING",
      "mature checkpoint source manifest differs from its state or tree",
    );
  }
  assertOperationCurrent();
  const chunkTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: chunksEntry.sha,
    maximumEntries: manifest.chunk_count,
    requestBudget,
    assertOperationCurrent,
  });
  const expectedChunkEntries = manifest.chunks.map((chunk) => ({
    path: chunk.path,
    mode: "100644",
    type: "blob",
    sha: chunk.blob_sha,
  }));
  if (
    canonicalJson(chunkTreeEntries) !== canonicalJson(expectedChunkEntries) ||
    canonicalGitTreeSha(expectedChunkEntries) !== manifest.chunk_tree_sha
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_CHUNK_TREE",
      "mature checkpoint source chunk tree differs from its manifest",
    );
  }
  const encodedParts = [];
  for (const [index, chunk] of manifest.chunks.entries()) {
    assertOperationCurrent();
    const bytes = await fetchExactGitBlobBytes({
      fetchImpl,
      authorization,
      base,
      repoPath,
      objectOid: chunk.blob_sha,
      maximumBytes: MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES,
      requestBudget,
      assertOperationCurrent,
    });
    if (
      bytes.byteLength !== chunk.byte_length ||
      rawDigest(bytes) !== chunk.sha256 ||
      chunk.path !== matureCheckpointSeedChunkPath(index)
    ) {
      throw ledgerError(
        "CHECKPOINT_SOURCE_CHUNK_IDENTITY",
        "mature checkpoint source chunk changed identity",
      );
    }
    encodedParts.push(bytes);
  }
  const encoded = Buffer.concat(encodedParts);
  if (
    encoded.byteLength !== manifest.encoded_byte_length ||
    rawDigest(encoded) !== manifest.encoded_sha256
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_ENCODED_IDENTITY",
      "mature checkpoint encoded source changed identity",
    );
  }
  let decoded;
  try {
    decoded = inflateRawSync(encoded, {
      maxOutputLength: manifest.decoded_byte_length + 1,
    });
  } catch (error) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_INFLATE",
      "mature checkpoint source cannot be boundedly decompressed",
      error,
    );
  }
  if (
    decoded.byteLength !== manifest.decoded_byte_length ||
    rawDigest(decoded) !== manifest.decoded_sha256
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_DECODED_IDENTITY",
      "mature checkpoint decoded source changed identity",
    );
  }
  const seed = validateMatureCheckpointSourceSeed(
    parseCanonicalCheckpointJson(decoded, "mature checkpoint source seed"),
    manifest,
    repository,
    ledgerRef,
  );
  if (
    seed.source_genesis_commit_sha !==
      checkpointState.source.genesis_commit_sha ||
    seed.source_observed_at !== checkpointState.source.observed_at
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_BINDING",
      "mature checkpoint source seed differs from its state boundary",
    );
  }
  assertOperationCurrent();
  const provenanceReverification =
    await reverifyReachableWorkflowProvenance({
      records: seed.records,
      repository,
      ledgerRef,
      verifyWorkflowProvenance,
      provenanceBudget,
      assertOperationCurrent,
    });
  assertOperationCurrent();
  if (provenanceReverification.length !== seed.records.length) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_PROVENANCE_INVENTORY",
      "mature checkpoint source provenance inventory is incomplete",
    );
  }
  if (
    matureCheckpointProvenanceReverificationDigest(
      provenanceReverification,
    ) !== checkpointState.source.provenance_reverification_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_PROVENANCE_INVENTORY",
      "mature checkpoint source provenance inventory differs from state",
    );
  }
  const projected = projectChainState(seed.records, seed.source_observed_at);
  const projectedCapability = projected.latest_capability;
  const sourceAttestation = seed.records.find((entry) =>
    entry.commit_sha === checkpointState.source
      .capability_attestation_commit_sha);
  const activation = checkpointState.source.capability_activation;
  if (
    projected.projection.projection_digest !==
      checkpointState.source.source_projection_digest ||
    bootstrapCheckpointAuthorityDigest(projected.authority_projection) !==
      checkpointState.source.authority_projection_digest ||
    projected.authority_projection.candidate_inventory.authority_digest !==
      checkpointState.source.candidate_inventory_authority_digest ||
    projected.authority_projection.candidate_dispatch.authority_digest !==
      checkpointState.source.candidate_dispatch_authority_digest ||
    projectedCapability?.attestation_commit_sha !==
      checkpointState.source.capability_attestation_commit_sha ||
    projectedCapability.capability_input_digest !==
      activation.capability_input_digest ||
    projectedCapability.capability_stable_digest !==
      activation.capability_stable_digest ||
    projectedCapability.protection_receipt_digest !==
      activation.protection_receipt_digest ||
    canonicalJson(projectedCapability.controller_release) !==
      canonicalJson(activation.controller_release) ||
    sourceAttestation?.envelope.record_type !== "capability-attestation" ||
    sourceAttestation.envelope.workflow_provenance.receipt_digest !==
      activation.oidc_attestation_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_REPLAY_MISMATCH",
      "mature checkpoint source replay differs from its comparison digests",
    );
  }
  return {
    seed,
    records: seed.records,
    projected,
    provenance_reverification: provenanceReverification,
  };
}

async function loadStableMatureCheckpointChain({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  repo,
  verifyWorkflowProvenance,
  provenanceBudget,
  requestBudget,
  preRef,
  readBoundary,
  suffixRecords: initialSuffixRecords,
  checkpointRoot,
  carrierValue,
  capability,
  assertOperationCurrent,
}) {
  assertOperationCurrent();
  const stateTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: checkpointRoot.checkpoint_state_tree_sha,
    maximumEntries: 2,
    requestBudget,
    assertOperationCurrent,
  });
  const stateBlobEntry = stateTreeEntries.find((entry) =>
    entry.path === V2_GIT_LEDGER_CHECKPOINT_STATE_BLOB_PATH) ?? null;
  const sourceSeedTreeEntry = stateTreeEntries.find((entry) =>
    entry.path === V2_GIT_LEDGER_CHECKPOINT_SOURCE_SEED_PATH) ?? null;
  if (
    stateTreeEntries.length !== 2 ||
    stateBlobEntry?.mode !== "100644" || stateBlobEntry.type !== "blob" ||
    sourceSeedTreeEntry?.mode !== "040000" ||
      sourceSeedTreeEntry.type !== "tree"
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_TREE_MISMATCH",
      "mature checkpoint state tree lacks its state and source seed",
    );
  }
  assertOperationCurrent();
  const stateBytes = await fetchExactGitBlobBytes({
    fetchImpl,
    authorization,
    base,
    repoPath,
    objectOid: stateBlobEntry.sha,
    maximumBytes: MAX_V2_GIT_LEDGER_BLOB_BYTES,
    requestBudget,
    assertOperationCurrent,
  });
  const checkpointState = validateMatureCheckpointState(
    parseCanonicalCheckpointJson(stateBytes, "mature checkpoint state"),
  );
  validateCheckpointCapabilityAgainstFactory(checkpointState, capability);
  if (
    canonicalJson(checkpointState.repository) !== canonicalJson(repo) ||
    checkpointState.ledger_ref !== ref ||
    checkpointState.source.tip_commit_sha !== checkpointRoot.parents[0] ||
    checkpointState.source.query_seed_tree_sha !== sourceSeedTreeEntry.sha ||
    checkpointState.next_unit.semantic_record_count >
      initialSuffixRecords.length
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_BINDING",
      "mature checkpoint state differs from its root or suffix",
    );
  }
  const carrier = validateCheckpointCarrier(carrierValue, {
    repository: repo,
    ledgerRef: ref,
    sourceTipCommitSha: checkpointRoot.parents[0],
    checkpointState,
    stateTreeSha: checkpointRoot.checkpoint_state_tree_sha,
    capability,
  });
  validateExactCheckpointCommitValue(checkpointRoot.commit, {
    commitSha: checkpointRoot.commit_sha,
    expectedTreeSha: checkpointRoot.tree_sha,
    expectedParentSha: checkpointRoot.parents[0],
    expectedServerTime: carrier.server_observed_at,
  });
  const source = await loadMatureCheckpointSourceSeed({
    fetchImpl,
    authorization,
    base,
    repoPath,
    repository: repo,
    ledgerRef: ref,
    checkpointState,
    sourceSeedTreeSha: sourceSeedTreeEntry.sha,
    verifyWorkflowProvenance,
    provenanceBudget,
    requestBudget,
    assertOperationCurrent,
  });
  const boundaryTime = Date.parse(readBoundary);
  if (
    source.seed.source_observed_at !== checkpointState.source.observed_at ||
    Date.parse(checkpointState.source.observed_at) >
      Date.parse(carrier.server_observed_at) ||
    Date.parse(carrier.server_observed_at) > boundaryTime
  ) {
    throw ledgerError(
      "CHECKPOINT_TIME_REGRESSION",
      "mature checkpoint source, carrier, and read boundary are not monotonic",
    );
  }
  let priorServerTime = carrier.server_observed_at;
  for (const entry of initialSuffixRecords) {
    if (
      Date.parse(entry.envelope.server_observed_at) <
        Date.parse(priorServerTime) ||
      Date.parse(entry.envelope.server_observed_at) > boundaryTime
    ) {
      throw ledgerError(
        "CHECKPOINT_TIME_REGRESSION",
        "mature checkpoint suffix time is outside its read boundary",
      );
    }
    priorServerTime = entry.envelope.server_observed_at;
  }
  const consumedJtis = new Set(source.records.map((entry) =>
    provenanceReplayIdentity(entry.envelope.workflow_provenance)));
  if (consumedJtis.size !== source.records.length) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_PROVENANCE_INVENTORY",
      "mature checkpoint source contains duplicate provenance identities",
    );
  }
  const liveProvenance = [...source.provenance_reverification];
  assertOperationCurrent();
  const checkpointLiveReceipt = await reverifyStoredWorkflowProvenance({
    verifyWorkflowProvenance,
    envelope: carrier,
    policy: capability.workflow_provenance_policy,
    provenanceBudget,
  });
  assertUnusedProvenanceJti(consumedJtis, checkpointLiveReceipt);
  liveProvenance.push(checkpointProvenanceEvidence(
    checkpointRoot.commit_sha,
    carrier,
    checkpointLiveReceipt,
  ));
  const transactionSuffixCount =
    checkpointState.next_unit.semantic_record_count;
  const transactionSuffixRecords =
    await hydrateCurrentCandidateInventoryAttachments({
      records: initialSuffixRecords.slice(0, transactionSuffixCount),
      fetchImpl,
      authorization,
      base,
      repoPath,
      repository: repo,
      requestBudget,
      assertOperationCurrent,
    });
  let suffixRecords = transactionSuffixRecords;
  if (initialSuffixRecords.length > transactionSuffixCount) {
    const laterSuffix = initialSuffixRecords.slice(transactionSuffixCount);
    const laterAttachedInventoryRecord = laterSuffix.some((entry) =>
      entry.candidate_inventory_attachment_tree_sha !== null);
    if (laterAttachedInventoryRecord) {
      const latestHydratedSuffix =
        await hydrateCurrentCandidateInventoryAttachments({
          records: initialSuffixRecords,
          fetchImpl,
          authorization,
          base,
          repoPath,
          repository: repo,
          requestBudget,
          assertOperationCurrent,
        });
      suffixRecords = [
        ...transactionSuffixRecords,
        ...latestHydratedSuffix.slice(transactionSuffixCount),
      ];
    } else {
      suffixRecords = [...transactionSuffixRecords, ...laterSuffix];
    }
  }
  for (const entry of suffixRecords) {
    validateV2GitLedgerEnvelope(entry.envelope, {
      repository: repo,
      ledger_ref: ref,
      source_workflow: sourceWorkflow(capability.controller_release),
      provenance_policy: provenanceExpected(capability),
    });
    assertOperationCurrent();
    const liveReceipt = await reverifyStoredWorkflowProvenance({
      verifyWorkflowProvenance,
      envelope: entry.envelope,
      policy: capability.workflow_provenance_policy,
      provenanceBudget,
    });
    assertUnusedProvenanceJti(consumedJtis, liveReceipt);
    liveProvenance.push(checkpointProvenanceEvidence(
      entry.commit_sha,
      entry.envelope,
      liveReceipt,
    ));
  }
  const transactionSuffix = suffixRecords.slice(0, transactionSuffixCount);
  const transactionRecords = [...source.records, ...transactionSuffix];
  const transactionState = projectChainState(
    transactionRecords,
    transactionSuffix.at(-1).envelope.server_observed_at,
  );
  const transactionCandidateAuthority =
    transactionState.authority_projection.candidate_inventory;
  const transactionDispatchAuthority =
    transactionState.authority_projection.candidate_dispatch;
  const activeReservation = transactionDispatchAuthority.active_reservation;
  const currentDispatchCycle = transactionDispatchAuthority.current_cycle;
  const transactionCommandAuthority = activeReservation === null
    ? currentDispatchCycle?.dispatch_command_authority ?? null
    : activeReservation.scan_command_authority;
  const transactionTriggerIdentity = activeReservation === null
    ? currentDispatchCycle?.trigger_identity ?? null
    : activeReservation.reservation.trigger_identity;
  let firstPlan;
  if (checkpointState.schema_version === 3) {
    const nextUnit = checkpointState.next_unit;
    const generationEntry = transactionSuffix[0];
    const dispatchEntry = transactionSuffix[1];
    const generation = transactionCandidateAuthority.completed_generation;
    const completedSource = candidateInventoryCompletedSource(
      transactionCandidateAuthority,
    );
    const attachmentEvidence = generationEntry
      ?.candidate_inventory_attachment_evidence ?? null;
    const endpointDigests = transactionSuffix.map((entry) => {
      const endpoint = entry.envelope.workflow_provenance.operation_binding
        .evaluated_scope_receipt?.scope_endpoint_receipt ?? null;
      return endpoint === null ? null : digestCanonical(
        "codex-review-gate-v2-checkpoint-repository-endpoint-receipt",
        endpoint,
      );
    });
    const candidateCount = generation?.candidate_count ?? null;
    const emptyDispatch = candidateCount === 0;
    const batchCount = candidateCount === null || candidateCount === 0
      ? 0
      : Math.ceil(candidateCount / MAX_V2_CANDIDATE_DISPATCH_ITEMS);
    const sourceBudget = candidateCount === null
      ? null
      : calculateCurrentOpenCheckpointCommitBudget({
          candidate_count: candidateCount,
          batch_count: batchCount,
          source_record_count: checkpointState.source.commit_count,
        });
    const freshBudget = candidateCount === null
      ? null
      : calculateCurrentOpenCheckpointCommitBudget({
          candidate_count: candidateCount,
          batch_count: batchCount,
          source_record_count: 1,
        });
    if (
      transactionSuffix.length !== 2 ||
      generationEntry?.envelope.record_type !==
        "candidate-inventory-observation" ||
      generationEntry.envelope.payload.schema_version !== 3 ||
      generationEntry.envelope.payload.phase !== "current-open-generation" ||
      dispatchEntry?.envelope.record_type !==
        "candidate-dispatch-observation" ||
      transactionCandidateAuthority.incomplete_cycle !== null ||
      transactionCandidateAuthority.atomic_cycle !== null ||
      transactionCandidateAuthority.completed_cycle !== null ||
      generation === null || completedSource === null ||
      completedSource.source_kind !== "current-open-v3" ||
      generation.generation_record_oid !== generationEntry.commit_sha ||
      generation.generation_id !== nextUnit.generation_id ||
      generation.source_authority_digest !==
        nextUnit.production_candidate_authority_digest ||
      generation.current_open_projection_digest !==
        nextUnit.current_open_projection_digest ||
      generation.candidate_count !== nextUnit.candidate_count ||
      generation.candidate_set_digest !== nextUnit.candidate_set_digest ||
      generation.source_semantic_digest !==
        nextUnit.source_current_open_semantic_digest ||
      generation.lifecycle_candidate_set_digest !==
        nextUnit.lifecycle_candidate_set_digest ||
      generation.attachment_manifest.manifest_digest !==
        nextUnit.attachment_manifest_digest ||
      attachmentEvidence?.production_candidate_authority.authority_digest !==
        nextUnit.production_candidate_authority_digest ||
      attachmentEvidence.current_open_projection_digest !==
        nextUnit.current_open_projection_digest ||
      generationEntry.envelope.payload.current_open_receipt_digest !==
        nextUnit.current_open_receipt_digest ||
      currentDispatchCycle === null ||
      currentDispatchCycle.generation_id !==
        completedSource.dispatch_generation_id ||
      emptyDispatch !== (
        activeReservation === null &&
        currentDispatchCycle.cycle_complete === true
      ) ||
      !emptyDispatch && (
        activeReservation === null || currentDispatchCycle.cycle_complete
      ) ||
      transactionCommandAuthority === null ||
      transactionTriggerIdentity === null ||
      endpointDigests.some((entry) =>
        entry !== nextUnit.repository_endpoint_receipt_digest) ||
      digestCanonical(
        "codex-review-gate-v2-checkpoint-stable-command-authority",
        candidateDispatchStableCommandAuthority(transactionCommandAuthority),
      ) !== nextUnit.stable_command_authority_digest ||
      digestCanonical(
        "codex-review-gate-v2-checkpoint-trigger-identity",
        normalizeCandidateDispatchTriggerIdentity(
          transactionTriggerIdentity,
        ),
      ) !== nextUnit.trigger_identity_digest ||
      sourceBudget === null || freshBudget === null ||
      sourceBudget.total_commit_budget_required !==
        nextUnit.total_commit_budget_required ||
      sourceBudget.remaining_ledger_commit_capacity_after_dispatch !==
        nextUnit.current_epoch_remaining_commit_capacity ||
      freshBudget.remaining_ledger_commit_capacity_after_dispatch !==
        nextUnit.fresh_epoch_remaining_commit_capacity ||
      sourceBudget.remaining_ledger_commit_capacity_after_dispatch >= 0 ||
      freshBudget.remaining_ledger_commit_capacity_after_dispatch < 0
    ) {
      throw ledgerError(
        "CHECKPOINT_SUFFIX_AUTHORITY",
        "mature current-open checkpoint does not reconstruct its admitted generation",
      );
    }
    firstPlan = activeReservation === null
      ? null
      : createCandidateDispatchPlan(activeReservation, {
          candidateDispatchAuthorityDigest:
            transactionDispatchAuthority.authority_digest,
        });
  } else {
    const candidateCount = transactionCandidateAuthority.completed_cycle
      ?.cycle_receipt.open_pull_requests.length ?? null;
    const emptyDispatch = candidateCount === 0;
    if (
      transactionCandidateAuthority.incomplete_cycle !== null ||
      transactionCandidateAuthority.atomic_cycle !== null ||
      transactionCandidateAuthority.completed_cycle?.cycle_id !==
        checkpointState.next_unit.cycle_id ||
      transactionCandidateAuthority.completed_cycle?.cycle_receipt
        .receipt_digest !==
        checkpointState.next_unit.stable_cycle_receipt_digest ||
      currentDispatchCycle === null || candidateCount === null ||
      emptyDispatch !== (
        activeReservation === null &&
        currentDispatchCycle.cycle_complete === true
      ) ||
      !emptyDispatch && (
        activeReservation === null || currentDispatchCycle.cycle_complete
      ) ||
      transactionCommandAuthority === null ||
      transactionTriggerIdentity === null ||
      digestCanonical(
        "codex-review-gate-v2-checkpoint-stable-command-authority",
        candidateDispatchStableCommandAuthority(
          transactionCommandAuthority,
        ),
      ) !== checkpointState.next_unit.stable_command_authority_digest ||
      digestCanonical(
        "codex-review-gate-v2-checkpoint-trigger-identity",
        normalizeCandidateDispatchTriggerIdentity(
          transactionTriggerIdentity,
        ),
      ) !== checkpointState.next_unit.trigger_identity_digest
    ) {
      throw ledgerError(
        "CHECKPOINT_SUFFIX_AUTHORITY",
        "mature checkpoint transaction prefix does not reconstruct its next unit",
      );
    }
    const classification = checkpointState.next_unit
      .classification_projection;
    const attemptEntries = transactionSuffix.filter((entry) =>
      entry.envelope.record_type === "candidate-inventory-observation" &&
      entry.envelope.payload.phase === "attempt");
    const attemptCount = attemptEntries.length;
    const driftCodes = attemptEntries.slice(0, -1).map((entry) =>
      entry.envelope.payload.outcome);
    const attemptEvidence = attemptEntries.map((entry) =>
      candidateInventoryAttachmentEvidence(entry));
    if (attemptEvidence.some((evidence) => evidence === null)) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_ATTACHMENT",
        "mature checkpoint transaction lacks one attempt attachment",
      );
    }
    const stableAttempt = attemptEvidence.at(-1);
    const budgetCycle = {
      shard_receipts: stableAttempt.shard_receipts,
      cycle_receipt:
        transactionCandidateAuthority.completed_cycle.cycle_receipt,
    };
    const budgetDriftAttempts = attemptEvidence.slice(0, -1).map(
      (evidence) => ({ shard_receipts: evidence.shard_receipts }),
    );
    const sourceBudget = candidateInventoryCycleCommitBudgetAtRecordCount({
      state: "persist-required",
      reachableRecordCount: checkpointState.source.commit_count,
      driftAttempts: budgetDriftAttempts,
      cycle: budgetCycle,
    });
    const freshBudget = candidateInventoryCycleCommitBudgetAtRecordCount({
      state: "persist-required",
      reachableRecordCount: 1,
      driftAttempts: budgetDriftAttempts,
      cycle: budgetCycle,
    });
    if (
      checkpointState.next_unit.semantic_record_count !== attemptCount + 3 ||
      classification.semantic_inventory_digest !==
        candidateInventoryCycleSemanticDigest(
          transactionCandidateAuthority.completed_cycle.cycle_receipt,
        ) ||
      classification.candidate_count !== candidateCount ||
      classification.drift_attempt_count !== attemptCount - 1 ||
      canonicalJson(classification.drift_codes) !== canonicalJson(driftCodes) ||
      classification.inventory_commit_budget_required !==
        sourceBudget.inventory_commit_budget_required ||
      classification.dispatch_commit_budget_required !==
        sourceBudget.dispatch_commit_budget_required ||
      classification.candidate_execution_commit_budget_required !==
        sourceBudget.candidate_execution_commit_budget_required ||
      classification.total_commit_budget_required !==
        sourceBudget.total_commit_budget_required ||
      classification.remaining_ledger_commit_capacity_after_dispatch !==
        sourceBudget.remaining_ledger_commit_capacity_after_dispatch ||
      checkpointState.next_unit.fresh_epoch_remaining_commit_capacity !==
        freshBudget.remaining_ledger_commit_capacity_after_dispatch
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_PROJECTION",
        "mature checkpoint classification differs from its transaction prefix",
      );
    }
    firstPlan = activeReservation === null
      ? null
      : createCandidateDispatchPlan(activeReservation);
  }
  const futureState = matureCheckpointFutureState({
    checkpointCommitSha: checkpointRoot.commit_sha,
    checkpointState,
    suffixRecords: transactionSuffix,
    projectedState: transactionState,
    firstDispatchPlan: firstPlan,
  });
  const queryRecords = [...source.records, ...suffixRecords];
  if (queryRecords.length > MAX_V2_GIT_LEDGER_SEMANTIC_RECORDS) {
    throw ledgerError(
      "CHECKPOINT_SEMANTIC_RECORD_CAP",
      "mature checkpoint semantic query exceeds its first-slice cap",
    );
  }
  const queryState = suffixRecords.length === transactionSuffixCount
    ? transactionState
    : projectChainState(
      queryRecords,
      suffixRecords.at(-1).envelope.server_observed_at,
    );
  assertOperationCurrent();
  const postRef = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent,
  });
  assertStableRefBoundary(preRef, postRef, "mature checkpoint ledger");
  return deepFreeze({
    tip_commit_sha: preRef.target_commit_sha,
    genesis_commit_sha: source.seed.source_genesis_commit_sha,
    records: queryRecords,
    epoch_records: suffixRecords,
    epoch_record_offset: 1,
    epoch_commit_count: 1 + suffixRecords.length,
    next_sequence: suffixRecords.at(-1).envelope.sequence + 1,
    logical_record_count:
      checkpointState.source.logical_record_count + 1 + suffixRecords.length,
    pre_ref: preRef,
    post_ref: postRef,
    observed_at: readBoundary,
    provenance_reverification: liveProvenance,
    consumed_provenance_identities: [...consumedJtis],
    checkpoint_epoch: {
      profile: MATURE_CHECKPOINT_PROFILE,
      epoch_id: checkpointState.epoch_id,
      epoch_root_commit_sha: checkpointRoot.commit_sha,
      source_tip_commit_sha: checkpointState.source.tip_commit_sha,
      source_record_count: checkpointState.source.commit_count,
      checkpoint_state_digest: checkpointState.checkpoint_state_digest,
      query_seed_digest: futureState.query_seed_digest,
      future_state_digest: futureState.future_state_digest,
      source_projection_digest: futureState.source_projection_digest,
      authority_projection_digest:
        futureState.authority_projection_digest,
      candidate_inventory_authority_digest:
        futureState.candidate_inventory_authority_digest,
      candidate_dispatch_authority_digest:
        futureState.candidate_dispatch_authority_digest,
      first_dispatch_plan_digest:
        futureState.first_dispatch_plan_digest,
      source_query_seed_tree_sha:
        checkpointState.source.query_seed_tree_sha,
      source_query_seed_manifest_digest:
        checkpointState.source.query_seed_manifest.manifest_digest,
      next_unit_admission_digest:
        checkpointState.next_unit.admission_digest,
    },
    ...queryState,
  });
}

async function loadStableBootstrapCheckpointChain({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  repo,
  verifyWorkflowProvenance,
  provenanceBudget,
  requestBudget,
  preRef,
  readBoundary,
  reverseSuffixRecords,
  checkpointRoot,
  capability,
  assertOperationCurrent,
}) {
  if (capability === null) {
    throw ledgerError(
      "capability-attestation-required",
      "checkpoint load requires this factory's exact capability authority",
    );
  }
  assertOperationCurrent();
  let suffixRecords = [...reverseSuffixRecords].reverse();
  const suffixCount = suffixRecords.length;
  if (
    suffixCount < 2 ||
    suffixCount > MAX_V2_GIT_LEDGER_COMMITS - 1 ||
    suffixRecords.at(-1).envelope.sequence !== suffixCount ||
    checkpointRoot.parents.length !== 1
  ) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_CAP",
      "protected ref does not end in one complete bounded checkpoint suffix",
    );
  }
  for (let index = 0; index < suffixRecords.length; index += 1) {
    const entry = suffixRecords[index];
    const expectedParent = index === 0
      ? checkpointRoot.commit_sha
      : suffixRecords[index - 1].commit_sha;
    if (
      entry.envelope.sequence !== index + 1 ||
      entry.parents.length !== 1 ||
      entry.parents[0] !== expectedParent ||
      entry.envelope.predecessor_commit_sha !== expectedParent
    ) {
      throw ledgerError(
        "CHECKPOINT_SUFFIX_SEQUENCE",
        "checkpoint suffix sequence or predecessor is not contiguous",
      );
    }
  }

  assertOperationCurrent();
  const carrierBytes = await fetchExactGitBlobBytes({
    fetchImpl,
    authorization,
    base,
    repoPath,
    objectOid: checkpointRoot.carrier_blob_sha,
    maximumBytes: MAX_V2_GIT_LEDGER_BLOB_BYTES,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const carrierValue = parseCanonicalCheckpointJson(
    carrierBytes,
    "checkpoint carrier",
  );
  if (carrierValue?.payload?.profile === MATURE_CHECKPOINT_PROFILE) {
    return loadStableMatureCheckpointChain({
      fetchImpl,
      authorization,
      base,
      repoPath,
      ref,
      refSuffix,
      repo,
      verifyWorkflowProvenance,
      provenanceBudget,
      requestBudget,
      preRef,
      readBoundary,
      suffixRecords,
      checkpointRoot,
      carrierValue,
      capability,
      assertOperationCurrent,
    });
  }
  if (
    suffixCount < 4 ||
    suffixCount > MAX_V2_CANDIDATE_SCAN_PASSES + 3
  ) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_CAP",
      "bootstrap checkpoint suffix exceeds its closed next-unit profile",
    );
  }
  const stateTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: checkpointRoot.checkpoint_state_tree_sha,
    maximumEntries: 2,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const stateBlobEntry = stateTreeEntries.find((entry) =>
    entry.path === V2_GIT_LEDGER_CHECKPOINT_STATE_BLOB_PATH) ?? null;
  const frontierTreeEntry = stateTreeEntries.find((entry) =>
    entry.path === V2_GIT_LEDGER_CHECKPOINT_FRONTIER_NODES_PATH) ?? null;
  if (
    stateTreeEntries.length !== 2 ||
    stateBlobEntry?.mode !== "100644" || stateBlobEntry.type !== "blob" ||
    frontierTreeEntry?.mode !== "040000" || frontierTreeEntry.type !== "tree"
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_TREE_MISMATCH",
      "checkpoint state tree lacks its exact state blob and frontier tree",
    );
  }
  const stateBytes = await fetchExactGitBlobBytes({
    fetchImpl,
    authorization,
    base,
    repoPath,
    objectOid: stateBlobEntry.sha,
    maximumBytes: MAX_V2_GIT_LEDGER_BLOB_BYTES,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const checkpointState = validateBootstrapCheckpointState(
    parseCanonicalCheckpointJson(stateBytes, "checkpoint state"),
  );
  const latestCapabilitySeed = validateCheckpointCapabilityAgainstFactory(
    checkpointState,
    capability,
  );
  if (
    canonicalJson(checkpointState.repository) !== canonicalJson(repo) ||
    checkpointState.ledger_ref !== ref ||
    checkpointState.source.tip_commit_sha !== checkpointRoot.parents[0] ||
    checkpointState.prefix_frontier.tree_sha !== frontierTreeEntry.sha ||
    checkpointState.next_unit.semantic_record_count !== suffixCount
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_BINDING",
      "checkpoint state differs from its protected ref root and suffix",
    );
  }
  const carrier = validateCheckpointCarrier(carrierValue, {
    repository: repo,
    ledgerRef: ref,
    sourceTipCommitSha: checkpointRoot.parents[0],
    checkpointState,
    stateTreeSha: checkpointRoot.checkpoint_state_tree_sha,
    capability,
  });
  validateExactCheckpointCommitValue(checkpointRoot.commit, {
    commitSha: checkpointRoot.commit_sha,
    expectedTreeSha: checkpointRoot.tree_sha,
    expectedParentSha: checkpointRoot.parents[0],
    expectedServerTime: carrier.server_observed_at,
  });

  const frontierTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: frontierTreeEntry.sha,
    maximumEntries: MAX_V2_PERSISTENT_FRONTIER_OPERATION_OBJECTS,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const frontier = await loadCheckpointPrefixFrontier({
    fetchImpl,
    authorization,
    base,
    repoPath,
    checkpointState,
    treeEntries: frontierTreeEntries,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const boundaryTime = Date.parse(readBoundary);
  if (
    Date.parse(frontier.tip_server_observed_at) >
      Date.parse(checkpointState.source.observed_at) ||
    Date.parse(checkpointState.source.observed_at) >
      Date.parse(carrier.server_observed_at) ||
    Date.parse(carrier.server_observed_at) > boundaryTime
  ) {
    throw ledgerError(
      "CHECKPOINT_TIME_REGRESSION",
      "checkpoint source, carrier, and read boundary are not monotonic",
    );
  }
  let priorServerTime = carrier.server_observed_at;
  for (const entry of suffixRecords) {
    if (
      Date.parse(entry.envelope.server_observed_at) <
        Date.parse(priorServerTime) ||
      Date.parse(entry.envelope.server_observed_at) > boundaryTime
    ) {
      throw ledgerError(
        "CHECKPOINT_TIME_REGRESSION",
        "checkpoint suffix time is outside its authenticated read boundary",
      );
    }
    priorServerTime = entry.envelope.server_observed_at;
  }

  const consumedJtis = new Set(frontier.provenance_identities);
  const liveProvenance = [];
  const checkpointLiveReceipt = await reverifyStoredWorkflowProvenance({
    verifyWorkflowProvenance,
    envelope: carrier,
    policy: capability.workflow_provenance_policy,
    provenanceBudget,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  assertUnusedProvenanceJti(consumedJtis, checkpointLiveReceipt);
  liveProvenance.push(checkpointProvenanceEvidence(
    checkpointRoot.commit_sha,
    carrier,
    checkpointLiveReceipt,
  ));

  suffixRecords = await hydrateCurrentCandidateInventoryAttachments({
    records: suffixRecords,
    fetchImpl,
    authorization,
    base,
    repoPath,
    repository: repo,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  for (const entry of suffixRecords) {
    validateV2GitLedgerEnvelope(entry.envelope, {
      repository: repo,
      ledger_ref: ref,
      source_workflow: sourceWorkflow(capability.controller_release),
      provenance_policy: provenanceExpected(capability),
    });
    const liveReceipt = await reverifyStoredWorkflowProvenance({
      verifyWorkflowProvenance,
      envelope: entry.envelope,
      policy: capability.workflow_provenance_policy,
      provenanceBudget,
    });
    assertOperationCurrent();
    assertHttpDeadlineOpen(requestBudget);
    assertUnusedProvenanceJti(consumedJtis, liveReceipt);
    liveProvenance.push(checkpointProvenanceEvidence(
      entry.commit_sha,
      entry.envelope,
      liveReceipt,
    ));
  }

  const suffixState = projectChainState(
    suffixRecords,
    suffixRecords.at(-1).envelope.server_observed_at,
    { epochRecordOffset: 1, latestCapabilitySeed },
  );
  const candidateAuthority =
    suffixState.authority_projection.candidate_inventory;
  const dispatchAuthority =
    suffixState.authority_projection.candidate_dispatch;
  const activeReservation = dispatchAuthority.active_reservation;
  if (
    candidateAuthority.incomplete_cycle !== null ||
    candidateAuthority.completed_cycle?.cycle_id !==
      checkpointState.next_unit.cycle_id ||
    candidateAuthority.completed_cycle?.cycle_receipt.receipt_digest !==
      checkpointState.next_unit.stable_cycle_receipt_digest ||
    activeReservation === null ||
    digestCanonical(
      "codex-review-gate-v2-checkpoint-stable-command-authority",
      candidateDispatchStableCommandAuthority(
        activeReservation.scan_command_authority,
      ),
    ) !== checkpointState.next_unit.stable_command_authority_digest ||
    digestCanonical(
      "codex-review-gate-v2-checkpoint-trigger-identity",
      normalizeCandidateDispatchTriggerIdentity(
        activeReservation.reservation.trigger_identity,
      ),
    ) !== checkpointState.next_unit.trigger_identity_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_AUTHORITY",
      "checkpoint suffix does not reconstruct its authenticated next unit",
    );
  }
  const classification = checkpointState.next_unit.classification_projection;
  const attemptCount = suffixRecords.filter((entry) =>
    entry.envelope.record_type === "candidate-inventory-observation" &&
    entry.envelope.payload.phase === "attempt").length;
  if (
    classification.semantic_inventory_digest !==
      candidateInventoryCycleSemanticDigest(
        candidateAuthority.completed_cycle.cycle_receipt,
      ) ||
    classification.candidate_count !==
      candidateAuthority.completed_cycle.cycle_receipt.open_pull_requests.length ||
    classification.drift_attempt_count !== attemptCount - 1
  ) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_PROJECTION",
      "checkpoint classification differs from its durable suffix evidence",
    );
  }
  const firstPlan = createCandidateDispatchPlan(activeReservation);
  if (
    firstPlan.schema_version !== 2 ||
    Buffer.byteLength(canonicalJson(firstPlan), "utf8") >
      candidateDispatchPlanByteCap(firstPlan)
  ) {
    throw ledgerError(
      "CHECKPOINT_DISPATCH_PLAN_UNREPRESENTABLE",
      "checkpoint suffix cannot reconstruct one bounded compact dispatch plan",
    );
  }

  const queryRecords = [
    ...checkpointState.source.query_records.map((entry) =>
      deepFreeze(structuredClone(entry))),
    ...suffixRecords,
  ];
  const queryState = {
    ...suffixState,
    projection: projectV2GitLedgerRecords(queryRecords),
    authority_projection: deriveV2GitLedgerAuthority(queryRecords),
  };
  const futureState = bootstrapCheckpointFutureState({
    checkpointCommitSha: checkpointRoot.commit_sha,
    checkpointState,
    suffixRecords,
    projectedState: queryState,
    firstDispatchPlan: firstPlan,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const postRef = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  assertStableRefBoundary(preRef, postRef, "checkpoint ledger");
  const provenanceReverification = [
    ...checkpointState.source.provenance_reverification.map((entry) =>
      deepFreeze(structuredClone(entry))),
    ...liveProvenance,
  ];
  return deepFreeze({
    tip_commit_sha: preRef.target_commit_sha,
    genesis_commit_sha: checkpointState.source.genesis_commit_sha,
    records: queryRecords,
    epoch_records: suffixRecords,
    epoch_record_offset: futureState.epoch_record_offset,
    epoch_commit_count: futureState.epoch_commit_count,
    next_sequence: futureState.next_sequence,
    logical_record_count: futureState.logical_record_count,
    pre_ref: preRef,
    post_ref: postRef,
    observed_at: readBoundary,
    provenance_reverification: provenanceReverification,
    consumed_provenance_identities: [...consumedJtis],
    checkpoint_epoch: {
      profile: CHECKPOINT_PROFILE,
      epoch_id: checkpointState.epoch_id,
      epoch_root_commit_sha: checkpointRoot.commit_sha,
      source_tip_commit_sha: checkpointState.source.tip_commit_sha,
      source_record_count: checkpointState.source.commit_count,
      checkpoint_state_digest: checkpointState.checkpoint_state_digest,
      query_seed_digest: futureState.query_seed_digest,
      future_state_digest: futureState.future_state_digest,
      source_projection_digest: futureState.source_projection_digest,
      authority_projection_digest:
        futureState.authority_projection_digest,
      candidate_inventory_authority_digest:
        futureState.candidate_inventory_authority_digest,
      candidate_dispatch_authority_digest:
        futureState.candidate_dispatch_authority_digest,
      first_dispatch_plan_digest:
        futureState.first_dispatch_plan_digest,
      prefix_frontier_tree_sha: checkpointState.prefix_frontier.tree_sha,
      prefix_frontier_entry_count: frontier.entry_count,
      prefix_frontier_node_count: frontier.node_count,
    },
    ...queryState,
  });
}

async function hydrateCurrentCandidateInventoryAttachments({
  records,
  fetchImpl,
  authorization,
  base,
  repoPath,
  repository,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  assertOperationCurrent();
  let generationIndex = -1;
  let startIndex = -1;
  for (let index = records.length - 1; index >= 0; index -= 1) {
    const envelope = records[index].envelope;
    if (
      envelope.record_type === "candidate-inventory-observation" &&
      envelope.payload.schema_version === 3 &&
      envelope.payload.phase === "current-open-generation"
    ) {
      generationIndex = index;
      break;
    }
    if (envelope.record_type === "candidate-inventory-observation" &&
        envelope.payload.schema_version === 2 &&
        envelope.payload.phase === "cycle-start") {
      startIndex = index;
      break;
    }
  }
  if (generationIndex >= 0) {
    const entry = records[generationIndex];
    const evidence = await fetchCurrentOpenGenerationAttachmentEvidence({
      fetchImpl,
      authorization,
      base,
      repoPath,
      attachmentTreeSha: entry.candidate_inventory_attachment_tree_sha,
      manifest: entry.envelope.payload.attachment_manifest,
      repository,
      requestBudget,
      assertOperationCurrent,
    });
    const hydrated = [...records];
    hydrated[generationIndex] = deepFreeze({
      ...entry,
      candidate_inventory_attachment_evidence: evidence,
    });
    return hydrated;
  }
  if (startIndex < 0) return records;
  const hydrated = [...records];
  for (let index = startIndex + 1; index < records.length; index += 1) {
    const entry = records[index];
    const payload = entry.envelope.payload;
    if (entry.envelope.record_type !== "candidate-inventory-observation") {
      continue;
    }
    if (payload.schema_version !== 2) {
      throw ledgerError(
        "candidate-inventory-atomic-lineage",
        "compact candidate inventory transaction contains a legacy phase",
      );
    }
    if (payload.phase === "cycle-complete") break;
    if (payload.phase !== "attempt") continue;
    assertOperationCurrent();
    const evidence = await fetchCandidateInventoryAttachmentEvidence({
      fetchImpl,
      authorization,
      base,
      repoPath,
      attachmentTreeSha: entry.candidate_inventory_attachment_tree_sha,
      manifest: payload.attachment_manifest,
      repository,
      requestBudget,
      assertOperationCurrent,
    });
    assertOperationCurrent();
    hydrated[index] = deepFreeze({
      ...entry,
      candidate_inventory_attachment_evidence: evidence,
    });
  }
  return hydrated;
}

async function fetchCurrentOpenGenerationAttachmentEvidence({
  fetchImpl,
  authorization,
  base,
  repoPath,
  attachmentTreeSha,
  manifest: manifestValue,
  repository,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  const manifest = validateCurrentOpenGenerationAttachmentManifest(
    manifestValue,
  );
  if (
    manifest.attachment_tree_sha !== attachmentTreeSha ||
    canonicalJson(manifest.repository) !==
      canonicalJson(candidateRepository(repository))
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-binding",
      "current-open generation attachment belongs to another source",
    );
  }
  assertOperationCurrent();
  const treeCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/trees/${attachmentTreeSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const tree = treeCapture.data;
  assertObject(tree, "current-open generation attachment tree");
  const expectedEntries = manifest.chunks.map((chunk) => ({
    path: chunk.path,
    mode: "100644",
    type: "blob",
    sha: chunk.blob_sha,
  }));
  const actualEntries = Array.isArray(tree.tree)
    ? tree.tree.map((entry, index) => {
      assertObject(entry,
        `current-open generation attachment tree entry ${index}`);
      return {
        path: entry.path,
        mode: entry.mode,
        type: entry.type,
        sha: entry.sha,
      };
    })
    : null;
  if (
    tree.sha !== attachmentTreeSha || tree.truncated === true ||
    actualEntries === null ||
    canonicalJson([...actualEntries].sort((left, right) =>
      left.path.localeCompare(right.path))) !==
      canonicalJson([...expectedEntries].sort((left, right) =>
        left.path.localeCompare(right.path))) ||
    canonicalGitTreeSha(expectedEntries) !== attachmentTreeSha
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-tree-identity",
      "current-open generation attachment tree changed identity",
    );
  }
  const encodedParts = [];
  for (const [index, chunk] of manifest.chunks.entries()) {
    assertOperationCurrent();
    const blobCapture = await request({
      fetchImpl,
      authorization,
      base,
      method: "GET",
      path: `${repoPath}/git/blobs/${chunk.blob_sha}`,
      expectedStatus: 200,
      requestBudget,
      assertOperationCurrent,
    });
    assertOperationCurrent();
    const blob = blobCapture.data;
    assertObject(blob, `current-open generation attachment blob ${index}`);
    if (blob.sha !== chunk.blob_sha || blob.encoding !== "base64" ||
        typeof blob.content !== "string") {
      throw ledgerError(
        "candidate-inventory-attachment-blob-identity",
        "current-open generation attachment blob is not canonical",
      );
    }
    const compactBase64 = blob.content.replace(/\n/gu, "");
    const bytes = Buffer.from(compactBase64, "base64");
    if (
      bytes.toString("base64") !== compactBase64 ||
      bytes.byteLength !== chunk.byte_length ||
      gitObjectSha("blob", bytes) !== chunk.blob_sha ||
      rawDigest(bytes) !== chunk.sha256
    ) {
      throw ledgerError(
        "candidate-inventory-attachment-blob-identity",
        "current-open generation attachment bytes changed",
      );
    }
    encodedParts.push(bytes);
  }
  const encoded = Buffer.concat(encodedParts);
  if (
    encoded.byteLength !== manifest.encoded_byte_length ||
    rawDigest(encoded) !== manifest.encoded_sha256
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-encoded-identity",
      "current-open generation encoded evidence changed",
    );
  }
  let decoded;
  try {
    decoded = inflateRawSync(encoded, {
      maxOutputLength: manifest.decoded_byte_length + 1,
    });
  } catch (error) {
    throw ledgerError(
      "candidate-inventory-attachment-inflate",
      "current-open generation evidence cannot be boundedly decompressed",
      error,
    );
  }
  if (
    decoded.byteLength !== manifest.decoded_byte_length ||
    rawDigest(decoded) !== manifest.decoded_sha256
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-decoded-identity",
      "current-open generation decoded evidence changed",
    );
  }
  let text;
  try {
    text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true })
      .decode(decoded);
  } catch (error) {
    throw ledgerError(
      "candidate-inventory-attachment-utf8",
      "current-open generation evidence is not UTF-8",
      error,
    );
  }
  let value;
  try {
    value = JSON.parse(text);
  } catch (error) {
    throw ledgerError(
      "candidate-inventory-attachment-json",
      "current-open generation evidence is not JSON",
      error,
    );
  }
  if (canonicalJson(value) !== text) {
    throw ledgerError(
      "candidate-inventory-attachment-json",
      "current-open generation evidence is not canonical JSON",
    );
  }
  const evidence = validateCurrentOpenGenerationEvidence(
    value,
    candidateRepository(repository),
  );
  if (
    evidence.evidence_digest !== manifest.evidence_digest ||
    evidence.current_open_projection_digest !==
      manifest.current_open_projection_digest ||
    evidence.production_candidate_authority.authority_digest !==
      manifest.production_candidate_authority_digest ||
    evidence.production_candidate_authority.candidate_count !==
      manifest.candidate_count ||
    evidence.production_candidate_authority.candidate_set_digest !==
      manifest.candidate_set_digest ||
    evidence.production_candidate_authority
      .source_current_open_semantic_digest !==
      manifest.source_current_open_semantic_digest ||
    evidence.lifecycle_candidate_set_digest !==
      manifest.lifecycle_candidate_set_digest ||
    canonicalJson(evidence.dispatch_batch_digests) !==
      canonicalJson(manifest.dispatch_batch_digests)
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-evidence",
      "current-open generation attachment changed its manifest authority",
    );
  }
  return evidence;
}

async function fetchCandidateInventoryAttachmentEvidence({
  fetchImpl,
  authorization,
  base,
  repoPath,
  attachmentTreeSha,
  manifest: manifestValue,
  repository,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  assertOperationCurrent();
  const manifest = validateCandidateInventoryAttachmentManifest(manifestValue);
  if (manifest.attachment_tree_sha !== attachmentTreeSha ||
      canonicalJson(manifest.repository) !==
        canonicalJson(candidateRepository(repository))) {
    throw ledgerError(
      "candidate-inventory-attachment-binding",
      "candidate inventory attachment tree belongs to another attempt",
    );
  }
  assertOperationCurrent();
  const treeCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/trees/${attachmentTreeSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const tree = treeCapture.data;
  assertObject(tree, "candidate inventory attachment tree");
  const expectedEntries = manifest.artifacts.flatMap((artifact) =>
    artifact.chunks.map((chunk) => ({
      path: chunk.path,
      mode: "100644",
      type: "blob",
      sha: chunk.blob_sha,
    })));
  const actualEntries = Array.isArray(tree.tree)
    ? tree.tree.map((entry, index) => {
      assertObject(entry, `candidate inventory attachment tree entry ${index}`);
      return {
        path: entry.path,
        mode: entry.mode,
        type: entry.type,
        sha: entry.sha,
      };
    })
    : null;
  if (
    tree.sha !== attachmentTreeSha || actualEntries === null ||
    tree.truncated === true ||
    canonicalJson([...actualEntries].sort((left, right) =>
      left.path.localeCompare(right.path))) !==
      canonicalJson([...expectedEntries].sort((left, right) =>
        left.path.localeCompare(right.path))) ||
    canonicalGitTreeSha(expectedEntries) !== attachmentTreeSha
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-tree-identity",
      "candidate inventory attachment tree shape or identity changed",
    );
  }
  const artifactValues = [];
  for (const [artifactIndex, artifact] of manifest.artifacts.entries()) {
    const encodedParts = [];
    for (const [chunkIndex, chunk] of artifact.chunks.entries()) {
      assertOperationCurrent();
      const blobCapture = await request({
        fetchImpl,
        authorization,
        base,
        method: "GET",
        path: `${repoPath}/git/blobs/${chunk.blob_sha}`,
        expectedStatus: 200,
        requestBudget,
        assertOperationCurrent,
      });
      assertOperationCurrent();
      const blob = blobCapture.data;
      assertObject(blob,
        `candidate inventory attachment blob ${artifactIndex}:${chunkIndex}`);
      if (blob.sha !== chunk.blob_sha || blob.encoding !== "base64" ||
          typeof blob.content !== "string") {
        throw ledgerError(
          "candidate-inventory-attachment-blob-identity",
          "candidate inventory attachment blob response is not canonical",
        );
      }
      const compactBase64 = blob.content.replace(/\n/gu, "");
      const bytes = Buffer.from(compactBase64, "base64");
      if (
        bytes.toString("base64") !== compactBase64 ||
        bytes.byteLength !== chunk.byte_length ||
        bytes.byteLength > MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES ||
        gitObjectSha("blob", bytes) !== chunk.blob_sha ||
        rawDigest(bytes) !== chunk.sha256
      ) {
        throw ledgerError(
          "candidate-inventory-attachment-blob-identity",
          "candidate inventory attachment blob bytes changed",
        );
      }
      encodedParts.push(bytes);
    }
    const encoded = Buffer.concat(encodedParts);
    if (encoded.byteLength !== artifact.encoded_byte_length ||
        rawDigest(encoded) !== artifact.encoded_sha256) {
      throw ledgerError(
        "candidate-inventory-attachment-encoded-identity",
        "candidate inventory encoded artifact changed",
      );
    }
    let decoded;
    try {
      decoded = inflateRawSync(encoded, {
        maxOutputLength: artifact.decoded_byte_length + 1,
      });
    } catch (error) {
      throw ledgerError(
        "candidate-inventory-attachment-inflate",
        "candidate inventory attachment cannot be boundedly decompressed",
        error,
      );
    }
    if (decoded.byteLength !== artifact.decoded_byte_length ||
        rawDigest(decoded) !== artifact.decoded_sha256) {
      throw ledgerError(
        "candidate-inventory-attachment-decoded-identity",
        "candidate inventory decoded artifact changed",
      );
    }
    let text;
    try {
      text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true })
        .decode(decoded);
    } catch (error) {
      throw ledgerError(
        "candidate-inventory-attachment-utf8",
        "candidate inventory decoded artifact is not UTF-8",
        error,
      );
    }
    let value;
    try {
      value = JSON.parse(text);
    } catch (error) {
      throw ledgerError(
        "candidate-inventory-attachment-json",
        "candidate inventory decoded artifact is not JSON",
        error,
      );
    }
    if (canonicalJson(value) !== text ||
        value.receipt_digest !== artifact.receipt_digest ||
        value.observed_at !== artifact.observed_at) {
      throw ledgerError(
        "candidate-inventory-attachment-json",
        "candidate inventory decoded artifact is not canonical evidence",
      );
    }
    artifactValues.push({
      role: artifact.role,
      shard_index: artifact.shard_index,
      value,
    });
  }
  const initialInventory = artifactValues[0].value;
  const finalInventoryIndex = artifactValues.findIndex(({ role }) =>
    role === "final-inventory");
  return deepFreeze({
    initial_inventory: initialInventory,
    shard_receipts: artifactValues.slice(1, finalInventoryIndex)
      .map(({ value }) => value),
    final_inventory: artifactValues[finalInventoryIndex].value,
    final_shard_receipts: artifactValues.slice(finalInventoryIndex + 1)
      .map(({ value }) => value),
  });
}

async function fetchCommitEnvelope({
  fetchImpl,
  authorization,
  base,
  repoPath,
  commitSha,
  repo,
  ref,
  requestBudget,
  assertOperationCurrent = () => {},
  allowCheckpointRoot = false,
}) {
  assertOperationCurrent();
  const commitCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/commits/${commitSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const commit = commitCapture.data;
  assertObject(commit, "Git ledger commit");
  if (sha(commit.sha, "Git ledger commit.sha") !== commitSha) {
    throw ledgerError("commit-identity", "Git ledger commit response changed its SHA");
  }
  if (!Array.isArray(commit.parents) || commit.parents.length > 1) {
    throw ledgerError("multi-parent", "Git ledger commits must have at most one parent");
  }
  const parents = commit.parents.map((parent) => {
    assertObject(parent, "Git ledger commit parent");
    return sha(parent.sha, "Git ledger commit parent.sha");
  });
  assertObject(commit.tree, "Git ledger commit tree");
  const treeSha = sha(commit.tree.sha, "Git ledger commit.tree.sha");
  assertOperationCurrent();
  const treeCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/trees/${treeSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const tree = treeCapture.data;
  assertObject(tree, "Git ledger tree");
  if (
    sha(tree.sha, "Git ledger tree.sha") !== treeSha ||
    !Array.isArray(tree.tree) ||
    !new Set([1, 2]).has(tree.tree.length)
  ) {
    throw ledgerError(
      "tree-shape",
      "Git ledger tree must contain one envelope and at most one attachment tree",
    );
  }
  const entry = tree.tree.find((item) => item?.path === V2_GIT_LEDGER_BLOB_PATH);
  assertObject(entry, "Git ledger tree entry");
  if (
    entry.path !== V2_GIT_LEDGER_BLOB_PATH || entry.mode !== "100644" ||
    entry.type !== "blob"
  ) {
    throw ledgerError("tree-shape", "Git ledger tree entry is not the canonical blob");
  }
  const attachmentEntry = tree.tree.find((item) =>
    item?.path === V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_PATH) ?? null;
  const checkpointStateEntry = tree.tree.find((item) =>
    item?.path === V2_GIT_LEDGER_CHECKPOINT_STATE_PATH) ?? null;
  if (
    allowCheckpointRoot && tree.tree.length === 2 &&
    attachmentEntry === null && checkpointStateEntry !== null &&
    checkpointStateEntry.mode === "040000" &&
    checkpointStateEntry.type === "tree"
  ) {
    const carrierBlobSha = sha(
      entry.sha,
      "checkpoint carrier blob SHA",
    );
    const checkpointStateTreeSha = sha(
      checkpointStateEntry.sha,
      "checkpoint state tree SHA",
    );
    const checkpointEntries = [{
      path: V2_GIT_LEDGER_BLOB_PATH,
      mode: "100644",
      type: "blob",
      sha: carrierBlobSha,
    }, {
      path: V2_GIT_LEDGER_CHECKPOINT_STATE_PATH,
      mode: "040000",
      type: "tree",
      sha: checkpointStateTreeSha,
    }];
    if (
      parents.length !== 1 ||
      canonicalGitTreeSha(checkpointEntries) !== treeSha
    ) {
      throw ledgerError(
        "CHECKPOINT_ROOT_TREE_MISMATCH",
        "checkpoint root commit does not bind one exact canonical state tree",
      );
    }
    return deepFreeze({
      checkpoint_root: true,
      commit_sha: commitSha,
      parents,
      tree_sha: treeSha,
      carrier_blob_sha: carrierBlobSha,
      checkpoint_state_tree_sha: checkpointStateTreeSha,
      commit: structuredClone(commit),
      evidence: {
        commit_raw_body_sha256: rawDigest(commitCapture.raw_body_bytes),
        tree_raw_body_sha256: rawDigest(treeCapture.raw_body_bytes),
        commit_server_time: commitCapture.server_time,
        tree_server_time: treeCapture.server_time,
      },
    });
  }
  if (
    tree.tree.length === 2 &&
    (attachmentEntry === null || attachmentEntry.mode !== "040000" ||
      attachmentEntry.type !== "tree")
  ) {
    throw ledgerError(
      "tree-shape",
      "Git ledger attachment entry is not the canonical child tree",
    );
  }
  const blobSha = sha(entry.sha, "Git ledger tree entry.sha");
  const canonicalEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }, ...(attachmentEntry === null ? [] : [{
    path: V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_PATH,
    mode: "040000",
    type: "tree",
    sha: sha(attachmentEntry.sha, "Git ledger attachment tree SHA"),
  }])];
  if (canonicalGitTreeSha(canonicalEntries) !== treeSha) {
    throw ledgerError(
      "tree-identity",
      "Git ledger tree bytes do not match their exact Git object identity",
    );
  }
  assertOperationCurrent();
  const blobCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/blobs/${blobSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const blob = blobCapture.data;
  assertObject(blob, "Git ledger blob");
  if (
    sha(blob.sha, "Git ledger blob.sha") !== blobSha ||
    blob.encoding !== "base64" || typeof blob.content !== "string"
  ) {
    throw ledgerError("blob-shape", "Git ledger blob is not canonical base64 content");
  }
  const bytes = Buffer.from(blob.content.replace(/\n/gu, ""), "base64");
  if (
    bytes.length === 0 || bytes.length > MAX_V2_GIT_LEDGER_BLOB_BYTES ||
    bytes.toString("base64") !== blob.content.replace(/\n/gu, "") ||
    gitObjectSha("blob", bytes) !== blobSha
  ) {
    throw ledgerError(
      "blob-identity",
      "Git ledger blob bytes do not match their exact Git object identity",
    );
  }
  let text;
  try {
    text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true })
      .decode(bytes);
  } catch {
    throw ledgerError(
      "invalid-blob-utf8",
      "Git ledger blob bytes are not canonical UTF-8",
    );
  }
  if (!text.endsWith("\n")) {
    throw ledgerError("noncanonical-blob", "Git ledger blob lacks one canonical newline");
  }
  let envelope;
  try {
    envelope = JSON.parse(text.slice(0, -1));
  } catch (error) {
    throw ledgerError("invalid-json", "Git ledger blob is not JSON", error);
  }
  if (`${canonicalJson(envelope)}\n` !== text) {
    throw ledgerError("noncanonical-blob", "Git ledger blob bytes are not canonical JSON");
  }
  validateV2GitLedgerEnvelope(envelope);
  const attachmentTreeSha = attachmentEntry === null
    ? null
    : sha(attachmentEntry.sha, "Git ledger attachment tree SHA");
  const compactAttempt =
    envelope.record_type === "candidate-inventory-observation" &&
    envelope.payload.schema_version === 2 &&
    envelope.payload.phase === "attempt";
  const currentOpenGeneration =
    envelope.record_type === "candidate-inventory-observation" &&
    envelope.payload.schema_version === 3 &&
    envelope.payload.phase === "current-open-generation";
  const attachedInventoryRecord = compactAttempt || currentOpenGeneration;
  if (
    attachedInventoryRecord !== (attachmentTreeSha !== null) ||
    compactAttempt &&
      envelope.payload.attachment_manifest.attachment_tree_sha !==
        attachmentTreeSha ||
    currentOpenGeneration &&
      envelope.payload.attachment_manifest.attachment_tree_sha !==
        attachmentTreeSha
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-binding",
      "Git ledger attachment tree differs from its compact attempt envelope",
    );
  }
  if (
    canonicalJson(envelope.repository) !== canonicalJson(repo) ||
    envelope.ledger_ref !== ref
  ) {
    throw ledgerError(
      "envelope-scope",
      "Git ledger envelope belongs to another repository or ref",
    );
  }
  const expectedMessage = commitMessage(envelope);
  if (commit.message !== expectedMessage) {
    throw ledgerError("commit-message", "Git ledger commit message is not canonical");
  }
  validateCommitIdentity({
    commit,
    commitSha,
    treeSha,
    parents,
    envelope,
  });
  return deepFreeze({
    commit_sha: commitSha,
    parents,
    tree_sha: treeSha,
    blob_sha: blobSha,
    candidate_inventory_attachment_tree_sha: attachmentTreeSha,
    envelope,
    evidence: {
      commit_raw_body_sha256: rawDigest(commitCapture.raw_body_bytes),
      tree_raw_body_sha256: rawDigest(treeCapture.raw_body_bytes),
      blob_raw_body_sha256: rawDigest(blobCapture.raw_body_bytes),
      commit_server_time: commitCapture.server_time,
      tree_server_time: treeCapture.server_time,
      blob_server_time: blobCapture.server_time,
    },
  });
}

function validateReachableChain(records, observedAt) {
  if (records.length === 0) {
    throw ledgerError("empty-chain", "Git ledger ref has no reachable commit");
  }
  const genesis = records[0];
  if (
    genesis.parents.length !== 0 || genesis.envelope.sequence !== 0 ||
    genesis.envelope.record_type !== "genesis" ||
    genesis.envelope.predecessor_commit_sha !== null
  ) {
    throw ledgerError("invalid-genesis", "Git ledger root is not one sealed genesis");
  }
  let priorTime = null;
  const provenanceIdentities = new Set();
  for (const [index, record] of records.entries()) {
    const envelope = record.envelope;
    if (envelope.sequence !== index) {
      throw ledgerError("sequence-gap", "Git ledger sequence is not contiguous from zero");
    }
    if (index > 0) {
      const parent = records[index - 1];
      if (
        record.parents.length !== 1 || record.parents[0] !== parent.commit_sha ||
        envelope.predecessor_commit_sha !== parent.commit_sha
      ) {
        throw ledgerError("predecessor-mismatch", "Git ledger predecessor is not its sole parent");
      }
    }
    const currentTime = Date.parse(envelope.server_observed_at);
    if (priorTime !== null && currentTime < priorTime) {
      throw ledgerError("time-regression", "Git ledger observation time regressed");
    }
    priorTime = currentTime;
    if (currentTime > Date.parse(observedAt)) {
      throw ledgerError("future-record", "Git ledger contains a record after the read boundary");
    }
    const replayIdentity = provenanceReplayIdentity(
      record.envelope.workflow_provenance,
    );
    if (provenanceIdentities.has(replayIdentity)) {
      throw ledgerError(
        "duplicate-provenance-identity",
        "Git ledger reuses one OIDC token identity across records",
      );
    }
    provenanceIdentities.add(replayIdentity);
  }
  validateCapabilityPairs(records);
}

function validateReachableAppendSuffix(loaded, records, observedAt) {
  if (!Array.isArray(records) || records.length === 0) {
    throw ledgerError(
      "empty-chain",
      "Git ledger append suffix has no reachable commit",
    );
  }
  const startSequence = loaded.next_sequence ?? loaded.records.length;
  let predecessorCommitSha = loaded.tip_commit_sha;
  let priorTime = Date.parse(
    loaded.records.at(-1).envelope.server_observed_at,
  );
  const boundaryTime = Date.parse(observedAt);
  const provenanceIdentities = new Set(loaded.records.map((entry) =>
    provenanceReplayIdentity(entry.envelope.workflow_provenance)));
  for (const [index, record] of records.entries()) {
    const envelope = record.envelope;
    if (
      envelope.sequence !== startSequence + index ||
      record.parents.length !== 1 ||
      record.parents[0] !== predecessorCommitSha ||
      envelope.predecessor_commit_sha !== predecessorCommitSha
    ) {
      throw ledgerError(
        "sequence-gap",
        "Git ledger append suffix is not one contiguous physical extension",
      );
    }
    const currentTime = Date.parse(envelope.server_observed_at);
    if (currentTime < priorTime) {
      throw ledgerError(
        "time-regression",
        "Git ledger append suffix observation time regressed",
      );
    }
    if (currentTime > boundaryTime) {
      throw ledgerError(
        "future-record",
        "Git ledger append suffix contains a record after its boundary",
      );
    }
    const replayIdentity = provenanceReplayIdentity(
      envelope.workflow_provenance,
    );
    if (provenanceIdentities.has(replayIdentity)) {
      throw ledgerError(
        "duplicate-provenance-identity",
        "Git ledger append suffix reuses one OIDC token identity",
      );
    }
    provenanceIdentities.add(replayIdentity);
    predecessorCommitSha = record.commit_sha;
    priorTime = currentTime;
  }
}

function assertUnusedProvenanceJti(consumed, provenance) {
  const replayIdentity = provenanceReplayIdentity(provenance);
  if (consumed.has(replayIdentity)) {
    throw ledgerError(
      "duplicate-provenance-identity",
      "OIDC token identity is already consumed by the Git ledger",
    );
  }
  consumed.add(replayIdentity);
}

function provenanceReplayIdentity(provenance) {
  const claims = normalizeOidcClaims(provenance.claims);
  return claims.jti === null
    ? `jwt:${provenance.token_sha256}`
    : `jti:${claims.jti}`;
}

function validateCapabilityPairs(records) {
  for (let index = 1; index < records.length; index += 1) {
    const record = records[index];
    if (record.envelope.record_type !== "capability-canary") continue;
    const next = records[index + 1];
    if (next === undefined) continue;
    if (next.envelope.record_type === "capability-canary") continue;
    if (next.envelope.record_type !== "capability-attestation") {
      throw ledgerError(
        "unattested-canary",
        "reachable capability canary is not immediately sealed by an attestation",
      );
    }
    const payload = next.envelope.payload;
    const canaryPayload = record.envelope.payload;
    if (
      payload.winner_commit_sha !== record.commit_sha ||
      payload.race_parent_commit_sha !== record.parents[0] ||
      payload.genesis_commit_sha !== records[0].commit_sha ||
      canaryPayload.race_parent_commit_sha !== record.parents[0] ||
      canaryPayload.genesis_commit_sha !== records[0].commit_sha ||
      payload.bootstrap_candidate_digest !==
        canaryPayload.bootstrap_candidate_digest ||
      payload.race_final_ref_reread.target_commit_sha !== record.commit_sha
    ) {
      throw ledgerError("attestation-binding", "capability attestation does not bind its race");
    }
    const writeObservation = validateWriteObservationReceipt(
      payload.write_observation_receipt,
    );
    const bootstrapCandidate = validateEmbeddedBootstrapCandidate(
      canaryPayload,
      record.envelope.repository,
      record.envelope.ledger_ref,
    );
    const attestedCapability = validateEmbeddedCapability(
      payload,
      next.envelope.repository,
      next.envelope.ledger_ref,
    );
    const expectedCapability = validateV2GitLedgerCapabilityReceipt(
      sealCapabilityFromBootstrap(bootstrapCandidate, writeObservation),
      {
        repository: record.envelope.repository,
        ledger_ref: record.envelope.ledger_ref,
      },
    );
    const writtenContender = writeObservation.contenders.find((item) =>
      item.label === canaryPayload.contender) ?? null;
    const raceResult = writeObservation.race_results.find((item) =>
      item.label === canaryPayload.contender) ?? null;
    const genesisObservation = writeObservation.genesis;
    if (
      stableCapabilityBindingDigest(attestedCapability) !==
        stableCapabilityBindingDigest(expectedCapability) ||
      writeObservation.bootstrap_candidate_digest !==
        bootstrapCandidate.input_digest ||
      writeObservation.race_parent_commit_sha !== record.parents[0] ||
      writeObservation.winner_commit_sha !== record.commit_sha ||
      canonicalJson(writeObservation.race_final_ref_reread) !==
        canonicalJson(payload.race_final_ref_reread) ||
      payload.race_final_ref_reread.ref !== next.envelope.ledger_ref ||
      payload.race_final_ref_reread.server_time !==
        next.envelope.server_observed_at ||
      payload.race_final_ref_reread.server_time !==
        next.envelope.workflow_provenance.operation_binding
          .github_server_time ||
      writeObservation.race_results.some((item) =>
        Date.parse(item.server_time) >
          Date.parse(writeObservation.race_final_ref_reread.server_time)) ||
      canonicalJson(writeObservation.race_results) !==
        canonicalJson(payload.contenders) ||
      writtenContender?.commit_sha !== record.commit_sha ||
      writtenContender.tree_sha !== record.tree_sha ||
      writtenContender.blob_sha !== record.blob_sha ||
      raceResult?.commit_sha !== record.commit_sha ||
      raceResult.outcome !== "winner" ||
      (genesisObservation !== null && (
        genesisObservation.commit_sha !== records[0].commit_sha ||
        genesisObservation.tree_sha !== records[0].tree_sha ||
        genesisObservation.blob_sha !== records[0].blob_sha
      ))
    ) {
      throw ledgerError(
        "capability-transition-mismatch",
        "capability attestation differs from its exact canary authority and race",
      );
    }
    const winners = payload.contenders.filter((item) => item.outcome === "winner");
    const losers = payload.contenders.filter((item) => item.outcome === "non-fast-forward");
    if (
      winners.length !== 1 || losers.length !== 1 ||
      winners[0].commit_sha !== record.commit_sha
    ) {
      throw ledgerError("attestation-race", "capability attestation race evidence is invalid");
    }
    const recovered = [];
    for (let prior = index - 1; prior >= 0; prior -= 1) {
      if (records[prior].envelope.record_type !== "capability-canary") break;
      recovered.unshift(records[prior].commit_sha);
    }
    if (canonicalJson(recovered) !==
        canonicalJson(payload.recovered_unattested_canary_commits)) {
      throw ledgerError(
        "attestation-recovery",
        "capability attestation does not bind every prior unattested canary",
      );
    }
  }
}

function collectTrailingCanaries(records) {
  const commits = [];
  for (let index = records.length - 1; index >= 0; index -= 1) {
    if (records[index].envelope.record_type !== "capability-canary") break;
    commits.unshift(records[index].commit_sha);
  }
  if (commits.length > 32) {
    throw ledgerError(
      "capability-recovery-cap",
      "too many consecutive unattested canaries require operator recovery",
    );
  }
  return commits;
}

function projectChainState(records, observedAt, {
  epochRecordOffset = 0,
  latestCapabilitySeed = null,
} = {}) {
  nonnegativeInteger(
    epochRecordOffset,
    "Git ledger projection epoch record offset",
  );
  const intentByEffect = new Map();
  const effectByIdempotency = new Map();
  const responseByEffect = new Set();
  const leaseIds = new Set();
  const controlCommentStates = new Map();
  let activeLease = null;
  let latestCapability = latestCapabilitySeed === null
    ? null
    : structuredClone(latestCapabilitySeed);
  const candidateInventoryState = {
    source_records: [],
    seen_cycle_ids: new Set(),
    completed: null,
    incomplete: null,
    atomic: null,
    generation: null,
  };
  const candidateDispatchState = {
    source_records: [],
    cycles: [],
  };
  const candidateDispatchAttemptIndex = createCandidateDispatchAttemptIndex();
  let candidateInventoryAuthorityCache = null;
  let candidateInventoryAuthorityRepositoryKey = null;
  let candidateDispatchAuthorityCache = null;
  let candidateDispatchAuthorityRepositoryKey = null;
  const currentCandidateInventoryAuthority = (repository) => {
    const repositoryKey = canonicalJson(repository);
    if (
      candidateInventoryAuthorityCache === null ||
      candidateInventoryAuthorityRepositoryKey !== repositoryKey
    ) {
      const authority = buildCandidateInventoryAuthority(
        repository,
        candidateInventoryState,
      );
      if (!Object.isFrozen(authority)) {
        throw new TypeError("candidate inventory authority cache requires a frozen value");
      }
      candidateInventoryAuthorityCache = authority;
      candidateInventoryAuthorityRepositoryKey = repositoryKey;
    }
    return candidateInventoryAuthorityCache;
  };
  const currentCandidateDispatchAuthority = (repository) => {
    const repositoryKey = canonicalJson(repository);
    if (
      candidateDispatchAuthorityCache === null ||
      candidateDispatchAuthorityRepositoryKey !== repositoryKey
    ) {
      const authority = buildCandidateDispatchAuthority(
        repository,
        candidateDispatchState,
      );
      if (!Object.isFrozen(authority)) {
        throw new TypeError("candidate dispatch authority cache requires a frozen value");
      }
      candidateDispatchAuthorityCache = authority;
      candidateDispatchAuthorityRepositoryKey = repositoryKey;
    }
    return candidateDispatchAuthorityCache;
  };
  const invalidateCandidateInventoryAuthority = () => {
    candidateInventoryAuthorityCache = null;
    candidateInventoryAuthorityRepositoryKey = null;
  };
  const invalidateCandidateDispatchAuthority = () => {
    candidateDispatchAuthorityCache = null;
    candidateDispatchAuthorityRepositoryKey = null;
  };
  for (const [recordIndex, record] of records.entries()) {
    const envelope = record.envelope;
    const effectScope = envelopeScope(envelope);
    let controlCommentState = null;
    if (effectScope !== null) {
      const headKey = canonicalJson({
        pull_request: effectScope.pull_request,
        head_ref_oid: effectScope.head_ref_oid,
      });
      const exactKey = canonicalJson({
        base_ref_oid: effectScope.base_ref_oid,
        potential_merge_commit_oid: effectScope.potential_merge_commit_oid,
      });
      controlCommentState = controlCommentStates.get(headKey) ?? null;
      if (controlCommentState?.exact_key !== exactKey) {
        controlCommentState = { exact_key: exactKey, binding: null };
        controlCommentStates.set(headKey, controlCommentState);
      }
    }
    if (
      (candidateInventoryState.incomplete !== null ||
        candidateInventoryState.atomic !== null) &&
      envelope.record_type !== "candidate-inventory-observation"
    ) {
      throw ledgerError(
        "candidate-inventory-write-window",
        "an incomplete candidate inventory rejects unrelated ledger writes",
      );
    }
    const dispatchBefore = currentCandidateDispatchAuthority(
      envelope.repository,
    );
    if (
      dispatchBefore.current_cycle !== null &&
      dispatchBefore.current_cycle.cycle_complete === false &&
      dispatchBefore.current_cycle.active_reservation === null &&
      envelope.record_type !== "candidate-dispatch-observation"
    ) {
      throw ledgerError(
        "candidate-dispatch-write-window",
        "an incomplete candidate dispatch rejects unrelated ledger writes",
      );
    }
    if (dispatchBefore.active_reservation !== null &&
        envelope.record_type === "capability-attestation") {
      throw ledgerError(
        "candidate-dispatch-write-window",
        "active candidate dispatch rejects a capability replacement",
      );
    }
    if (envelope.record_type === "capability-attestation") {
      latestCapability = {
        attestation_commit_sha: record.commit_sha,
        capability_input_digest: envelope.payload.capability_input_digest,
        capability_stable_digest: envelope.payload.capability_stable_digest,
        capability_receipt: envelope.payload.capability_receipt,
        protection_receipt_digest: envelope.payload.protection_receipt_digest,
        controller_release: envelope.payload.controller_release,
        payload: envelope.payload,
      };
      continue;
    }
    if (envelope.record_type === "candidate-inventory-observation") {
      const payload = validateV2GitLedgerCandidateInventoryPayload(
        envelope.payload,
        { repository: envelope.repository },
      );
      const authority = currentCandidateInventoryAuthority(
        envelope.repository,
      );
      const currentDispatch = candidateDispatchState.cycles.at(-1) ?? null;
      if (currentDispatch !== null &&
          currentDispatch.cycle_complete === false) {
        throw ledgerError(
          "candidate-dispatch-inventory-replacement",
          "candidate inventory cannot advance during an unfinished dispatch cycle",
        );
      }
      if (payload.prior_candidate_authority_digest !== authority.authority_digest) {
        throw ledgerError(
          "candidate-inventory-predecessor",
          "candidate inventory history does not bind prior repository authority",
        );
      }
      const row = candidateInventorySourceRecord(record);
      validateAndApplyCandidateInventoryTransition({
        payload,
        repository: envelope.repository,
        state: candidateInventoryState,
        recordOid: row.record_oid,
        recordServerTime: envelope.server_observed_at,
        attachmentEvidence:
          candidateInventoryAttachmentEvidence(record),
        apply: true,
      });
      candidateInventoryState.source_records.push(row);
      invalidateCandidateInventoryAuthority();
      continue;
    }
    if (envelope.record_type === "candidate-dispatch-observation") {
      const payload = validateV2GitLedgerCandidateDispatchPayload(
        envelope.payload,
        { repository: envelope.repository },
      );
      const authority = currentCandidateDispatchAuthority(
        envelope.repository,
      );
      if (payload.prior_candidate_dispatch_authority_digest !==
          authority.authority_digest) {
        throw ledgerError(
          "candidate-dispatch-predecessor",
          "candidate dispatch history does not bind prior dispatch authority",
        );
      }
      const expiryRecovery = activeLease !== null &&
        payload.phase === "candidate-ack" &&
        payload.candidate_ack.terminal_authority.kind ===
          "durable-prefix-recovery" &&
        payload.candidate_ack.terminal_authority.recovery.mode === "expired" &&
        payload.candidate_ack.terminal_authority.lease_release_record_oid ===
          null &&
        payload.candidate_ack.terminal_authority.lease_acquire_commit_sha ===
          activeLease.acquire_commit_sha &&
        payload.candidate_ack.terminal_authority.recovery.lease_expires_at ===
          activeLease.expires_at &&
        Date.parse(
          payload.candidate_ack.terminal_authority.recovery.post_ref_receipt
            .server_time,
        ) >= Date.parse(activeLease.expires_at);
      if (activeLease !== null && !expiryRecovery) {
        throw ledgerError(
          "candidate-dispatch-lease-release-required",
          "candidate dispatch records require no active PR lease",
        );
      }
      const row = candidateDispatchSourceRecord(record);
      validateAndApplyCandidateDispatchTransition({
        payload,
        repository: envelope.repository,
        candidateAuthority: currentCandidateInventoryAuthority(
          envelope.repository,
        ),
        state: candidateDispatchState,
        recordOid: row.record_oid,
        predecessorCommitSha: envelope.predecessor_commit_sha,
        recordServerTime: envelope.server_observed_at,
        // Physical checkpoint epochs restart their envelope sequence at one.
        // The semantic query may include a replay seed before this record, so
        // an array index is not a physical-capacity witness.
        reachableRecordCount: envelope.sequence,
        priorRecords: records.slice(0, recordIndex),
        apply: true,
      });
      candidateDispatchState.source_records.push(row);
      invalidateCandidateDispatchAuthority();
      if (expiryRecovery) activeLease = null;
      continue;
    }
    const evaluatedScopeReceipt =
      envelope.workflow_provenance?.operation_binding?.evaluated_scope_receipt ??
      null;
    if (evaluatedScopeReceipt?.relation === "scheduled-pull-request") {
      validateScheduledPullRequestInventoryBinding(
        currentCandidateInventoryAuthority(envelope.repository),
        currentCandidateDispatchAuthority(envelope.repository),
        envelopeScope(envelope),
        evaluatedScopeReceipt,
        envelope.repository,
      );
    }
    const candidateDispatchAttemptUpdate =
      validateCandidateDispatchAttemptWindow({
        prior_records: records.slice(0, recordIndex),
        record: envelope,
        evaluated_scope_receipt: evaluatedScopeReceipt,
        dispatch_authority: currentCandidateDispatchAuthority(
          envelope.repository,
        ),
        active_lease: activeLease,
        attempt_index: candidateDispatchAttemptIndex,
        reachable_record_count: envelope.sequence,
      });
    validateEvaluatedScopeLeaseLineage(
      envelope,
      evaluatedScopeReceipt,
      activeLease,
    );
    if (envelope.record_type === "lease-acquire") {
      const payload = envelope.payload;
      if (leaseIds.has(payload.lease_id)) {
        throw ledgerError("duplicate-lease", "Git ledger repeats a lease identity");
      }
      leaseIds.add(payload.lease_id);
      if (
        activeLease !== null &&
        Date.parse(payload.acquired_at) < Date.parse(activeLease.expires_at)
      ) {
        throw ledgerError("overlapping-lease", "Git ledger contains overlapping leases");
      }
      activeLease = {
        lease_id: payload.lease_id,
        owner: payload.owner,
        acquire_commit_sha: record.commit_sha,
        acquired_at: payload.acquired_at,
        expires_at: payload.expires_at,
        scope: envelopeScope(envelope),
        evaluated_scope_receipt: evaluatedScopeReceipt,
      };
      commitCandidateDispatchAttemptIndex(
        candidateDispatchAttemptIndex,
        candidateDispatchAttemptUpdate,
        record,
      );
      continue;
    }
    if (envelope.record_type === "lease-release") {
      if (
        activeLease === null ||
        envelope.payload.lease_id !== activeLease.lease_id ||
        envelope.payload.acquire_commit_sha !== activeLease.acquire_commit_sha ||
        canonicalJson(envelope.payload.owner) !== canonicalJson(activeLease.owner) ||
        Date.parse(envelope.payload.released_at) >= Date.parse(activeLease.expires_at)
      ) {
        throw ledgerError("invalid-lease-release", "Git ledger lease release is not authoritative");
      }
      requireSameScope(envelopeScope(envelope), activeLease.scope, "lease release");
      activeLease = null;
      commitCandidateDispatchAttemptIndex(
        candidateDispatchAttemptIndex,
        candidateDispatchAttemptUpdate,
        record,
      );
      continue;
    }
    if (
      envelope.record_type === "effect-intent" ||
      envelope.record_type === "effect-response"
    ) {
      if (envelope.kind === "artifact-binding") {
        validateArtifactBindingLineage(
          records.slice(0, recordIndex),
          envelope,
          envelope.repository,
        );
      } else if (envelope.kind === "artifact-binding-ready") {
        if (envelope.record_type === "effect-intent") {
          validateArtifactBindingReadyLineage(
            records.slice(0, recordIndex),
            envelope,
            envelope.repository,
          );
        } else {
          validateArtifactBindingReadyConfirmationLineage(
            records.slice(0, recordIndex),
            envelope,
            envelope.repository,
          );
        }
      } else if (envelope.kind === "request-binding") {
        validateRequestBindingLineage(
          records.slice(0, recordIndex),
          envelope,
          envelope.repository,
        );
      } else if (envelope.kind === "review-request") {
        validateReviewRequestLineage(
          records.slice(0, recordIndex),
          envelope,
        );
      } else if (envelope.kind === "automatic-request-reservation") {
        validateAutomaticReservationLineage(
          records.slice(0, recordIndex),
          envelope,
        );
      } else if (envelope.kind === "scheduler-observation") {
        validateSchedulerObservationLineage(
          records.slice(0, recordIndex),
          envelope,
        );
      } else if (envelope.kind === "effect-attempt") {
        validateEffectAttemptLineage(
          records.slice(0, recordIndex),
          envelope,
        );
      } else if (envelope.kind === "reservation-status-write") {
        validateReservationStatusLineage(
          records.slice(0, recordIndex),
          envelope,
        );
      } else if (envelope.kind === "status-write") {
        validateStatusWriteLineage(
          records.slice(0, recordIndex),
          envelope,
        );
      } else if (envelope.kind === "scheduler-state") {
        validateSchedulerStateLineage(
          records.slice(0, recordIndex),
          envelope,
          envelope.repository,
        );
      }
      if (
        activeLease === null ||
        Date.parse(envelope.server_observed_at) >= Date.parse(activeLease.expires_at)
      ) {
        throw ledgerError("lease-required", "effect record is outside an active lease");
      }
      validateEnvelopeLease(envelope, activeLease);
      requireSameScope(envelopeScope(envelope), activeLease.scope, "effect record");
      const currentControlComment = controlCommentState.binding;
      if (envelope.kind === "control-comment-create") {
        if (
          currentControlComment !== null ||
          (envelope.record_type === "effect-intent" &&
            envelope.control_comment_binding !== null)
        ) {
          throw ledgerError(
            "control-comment-binding",
            "control comment create history has an invalid prior binding",
          );
        }
      } else if (envelope.kind === "control-comment-update") {
        if (
          currentControlComment === null ||
          (envelope.record_type === "effect-intent" &&
            canonicalJson(envelope.control_comment_binding) !==
              canonicalJson(currentControlComment))
        ) {
          throw ledgerError(
            "control-comment-binding",
            "control comment update history does not bind the current comment",
          );
        }
      } else if (
        envelope.control_comment_binding !== null &&
        canonicalJson(envelope.control_comment_binding) !==
          canonicalJson(currentControlComment)
      ) {
        throw ledgerError(
          "control-comment-binding",
          "effect history cites a non-current controller comment",
        );
      }
      if (envelope.record_type === "effect-intent") {
        if (intentByEffect.has(envelope.effect_id)) {
          throw ledgerError("duplicate-effect", "Git ledger repeats an effect identity");
        }
        if (effectByIdempotency.has(envelope.idempotency_key)) {
          throw ledgerError("duplicate-idempotency", "Git ledger repeats an idempotency key");
        }
        intentByEffect.set(envelope.effect_id, record);
        effectByIdempotency.set(envelope.idempotency_key, record);
      } else {
        const intent = intentByEffect.get(envelope.effect_id);
        const durableIntentRecovery = new Set([
          "artifact-binding", "artifact-binding-ready", "scheduler-state",
        ]).has(envelope.kind);
        if (
          intent === undefined || responseByEffect.has(envelope.effect_id) ||
          intent.envelope.idempotency_key !== envelope.idempotency_key ||
          intent.envelope.kind !== envelope.kind ||
          envelope.payload.intent_commit_sha !== intent.commit_sha ||
          (!durableIntentRecovery &&
            envelope.payload.predecessor_commit_sha !== intent.commit_sha) ||
          canonicalJson(envelope.payload.action) !==
            canonicalJson(intent.envelope.payload.action) ||
          canonicalJson(envelope.payload.generation) !==
            canonicalJson(intent.envelope.payload.generation) ||
          envelope.payload.ordinal !== intent.envelope.payload.ordinal
        ) {
          throw ledgerError("invalid-effect-response", "effect response lacks one exact intent");
        }
        responseByEffect.add(envelope.effect_id);
        if (new Set(["control-comment-create", "control-comment-update"])
          .has(envelope.kind)) {
          controlCommentState.binding = structuredClone(
            envelope.control_comment_binding,
          );
        }
      }
    }
    commitCandidateDispatchAttemptIndex(
      candidateDispatchAttemptIndex,
      candidateDispatchAttemptUpdate,
      record,
    );
  }
  if (
    activeLease !== null &&
    Date.parse(observedAt) >= Date.parse(activeLease.expires_at)
  ) {
    activeLease = null;
  }
  const projection = projectV2GitLedgerRecords(records);
  const authorityProjection = deriveV2GitLedgerAuthority(records);
  return {
    active_lease: activeLease,
    latest_capability: latestCapability,
    effect_intent_count: intentByEffect.size,
    effect_response_count: responseByEffect.size,
    control_comment_binding: projection.control_comment_binding,
    projection,
    authority_projection: authorityProjection,
  };
}

function candidateDispatchAttemptBinding(receiptValue) {
  if (receiptValue === null || receiptValue === undefined) return null;
  const receipt = validateV2GitLedgerEvaluatedScopeReceipt(receiptValue);
  if (receipt.relation !== "scheduled-pull-request") return null;
  const inventory = receipt.inventory_receipt;
  const selectedCandidate = candidateDispatchIdentity(
    inventory.selected_candidate,
  );
  const common = {
    repository: structuredClone(receipt.repository),
    dispatch_generation_id: inventory.dispatch_generation_id,
    dispatch_cycle_id: inventory.dispatch_cycle_id,
    dispatch_reservation_record_oid:
      inventory.dispatch_reservation_record_oid,
    dispatch_reservation_digest: inventory.dispatch_reservation_digest,
    dispatch_digest: inventory.dispatch_digest,
    dispatch_batch_index: inventory.dispatch_batch_index,
    dispatch_batch_count: inventory.dispatch_batch_count,
    dispatch_candidate_index: inventory.dispatch_candidate_index,
    selected_candidate: structuredClone(selectedCandidate),
    trigger_event_name: receipt.trigger_event_name,
    trigger_ref: receipt.trigger_ref,
    trigger_sha: receipt.trigger_sha,
  };
  if (inventory.schema_version !== 2) return common;
  return {
    schema_version: 2,
    repository: common.repository,
    candidate_authority_digest: inventory.candidate_authority_digest,
    candidate_dispatch_authority_digest:
      inventory.candidate_dispatch_authority_digest,
    candidate_source: structuredClone(inventory.candidate_source),
    inventory_digest: inventory.inventory_digest,
    dispatch_generation_id: common.dispatch_generation_id,
    dispatch_cycle_id: common.dispatch_cycle_id,
    dispatch_reservation_record_oid:
      common.dispatch_reservation_record_oid,
    dispatch_reservation_digest: common.dispatch_reservation_digest,
    dispatch_digest: common.dispatch_digest,
    dispatch_batch_index: common.dispatch_batch_index,
    dispatch_batch_count: common.dispatch_batch_count,
    dispatch_candidate_index: common.dispatch_candidate_index,
    selected_candidate: common.selected_candidate,
    trigger_event_name: common.trigger_event_name,
    trigger_ref: common.trigger_ref,
    trigger_sha: common.trigger_sha,
  };
}

function candidateDispatchAttemptStage(value) {
  if (value.record_type === "lease-acquire") return 0;
  if (value.record_type === "lease-release") return 16;
  if (!new Set(["effect-intent", "effect-response"])
    .has(value.record_type)) return null;
  const responseOffset = value.record_type === "effect-response" ? 1 : 0;
  if (value.kind === "scheduler-observation") {
    return responseOffset === 0 ? 1 : null;
  }
  if (value.kind === "status-write") {
    const index = value.payload?.action?.status_write_index;
    return index === 0
      ? 2 + responseOffset
      : index === 1 ? 4 + responseOffset : null;
  }
  if (value.kind === "artifact-binding") {
    const queued = value.payload?.action
      ?.queued_after_artifact_binding_intent_record_oid !== null;
    return queued
      ? responseOffset === 0 ? 9 : 13
      : responseOffset === 0 ? 6 : 10;
  }
  if (value.kind === "artifact-binding-ready") {
    const queued = value.payload?.action
      ?.queued_after_artifact_binding_intent_record_oid !== null;
    return queued ? 11 + responseOffset : 7 + responseOffset;
  }
  if (value.kind === "scheduler-state") {
    return 6 + responseOffset;
  }
  if (value.kind === "automatic-request-reservation") {
    return responseOffset === 0 ? 8 : null;
  }
  if (value.kind === "reservation-status-write") return 9 + responseOffset;
  if (value.kind === "effect-attempt") {
    return responseOffset === 0 ? 11 : null;
  }
  if (value.kind === "review-request") return 12 + responseOffset;
  if (value.kind === "request-binding") return 14 + responseOffset;
  return null;
}

function candidateDispatchScheduledAcquireAttempts(records) {
  return records.flatMap((entry) => {
    if (entry.envelope.record_type !== "lease-acquire") return [];
    const receipt = entry.envelope.workflow_provenance?.operation_binding
      ?.evaluated_scope_receipt ?? null;
    const binding = candidateDispatchAttemptBinding(receipt);
    return binding === null ? [] : [{ entry, binding }];
  });
}

function createCandidateDispatchAttemptIndex() {
  return {
    attempts: [],
    by_binding: new Map(),
  };
}

function commitCandidateDispatchAttemptIndex(index, update, entry) {
  if (update === null) return;
  const stage = candidateDispatchAttemptStage(entry.envelope);
  if (stage !== update.stage) {
    throw new TypeError("candidate dispatch attempt index stage is inconsistent");
  }
  if (stage === 0) {
    if (
      entry.envelope.record_type !== "lease-acquire" ||
      index.by_binding.has(update.binding_key)
    ) {
      throw new TypeError("candidate dispatch attempt index start is inconsistent");
    }
    const attempt = {
      entry,
      binding: structuredClone(update.binding),
      binding_key: update.binding_key,
      lease_id: entry.envelope.payload.lease_id,
      acquire_commit_sha: entry.commit_sha,
      last_stage: 0,
      last_record_oid: entry.commit_sha,
    };
    index.attempts.push(attempt);
    index.by_binding.set(update.binding_key, attempt);
    return;
  }
  const attempt = index.by_binding.get(update.binding_key);
  if (
    attempt === undefined ||
    stage <= attempt.last_stage ||
    entry.envelope.record_type === "lease-acquire"
  ) {
    throw new TypeError("candidate dispatch attempt index advance is inconsistent");
  }
  attempt.last_stage = stage;
  attempt.last_record_oid = entry.commit_sha;
}

function validateCandidateDispatchAttemptWindow({
  prior_records: priorRecords,
  record,
  evaluated_scope_receipt: evaluatedScopeReceipt,
  dispatch_authority: dispatchAuthority,
  active_lease: activeLease,
  attempt_index: attemptIndex = null,
  reachable_record_count: reachableRecordCountValue,
}) {
  const reachableRecordCount = nonnegativeInteger(
    reachableRecordCountValue,
    "candidate dispatch attempt reachable record count",
  );
  const active = dispatchAuthority.active_reservation;
  if (active === null) return null;
  const binding = candidateDispatchAttemptBinding(evaluatedScopeReceipt);
  if (binding === null) {
    throw ledgerError(
      "candidate-dispatch-write-window",
      "an active candidate dispatch rejects unrelated production records",
    );
  }
  const reservation = active.reservation;
  const candidate = reservation.candidates[binding.dispatch_candidate_index];
  const candidateIdentity = candidate === undefined
    ? null
    : candidateDispatchAttemptIdentity(candidate);
  if (candidate === undefined) {
    throw ledgerError(
      "candidate-dispatch-write-window",
      "production record differs from the active dispatch candidate",
    );
  }
  validateScheduledDispatchReceiptAgainstReservation(
    evaluatedScopeReceipt,
    active,
    candidate,
    {
      allow_pre_scope: true,
      candidate_dispatch_authority_digest: dispatchAuthority.authority_digest,
    },
  );
  if (
    binding.dispatch_generation_id !== reservation.generation_id ||
    binding.dispatch_cycle_id !== reservation.cycle_id ||
    binding.dispatch_reservation_record_oid !== active.reservation_record_oid ||
    binding.dispatch_reservation_digest !== reservation.reservation_digest ||
    binding.dispatch_digest !== reservation.dispatch_digest ||
    binding.dispatch_batch_index !== reservation.batch_index ||
    binding.dispatch_batch_count !== reservation.batch_count ||
    (binding.schema_version === 2) !== (candidate.schema_version === 2) ||
    binding.schema_version === 2 && (
      binding.candidate_authority_digest !==
        reservation.candidate_inventory_authority_digest ||
      binding.candidate_dispatch_authority_digest !==
        dispatchAuthority.authority_digest ||
      canonicalJson(binding.candidate_source) !==
        canonicalJson(reservation.candidate_source) ||
      binding.inventory_digest !== reservation.inventory_digest
    ) ||
    canonicalJson(binding.selected_candidate) !==
      canonicalJson(candidateIdentity) ||
    active.acknowledgements.some((ack) =>
      ack.candidate_index === binding.dispatch_candidate_index)
  ) {
    throw ledgerError(
      "candidate-dispatch-write-window",
      "production record differs from the active dispatch candidate",
    );
  }
  const stage = candidateDispatchAttemptStage(record);
  if (stage === null) {
    throw ledgerError(
      "candidate-dispatch-write-window",
      "active candidate dispatch record is outside the bounded protocol",
    );
  }
  const bindingKey = canonicalJson(binding);
  const attempts = (attemptIndex === null
    ? candidateDispatchScheduledAcquireAttempts(priorRecords)
    : attemptIndex.attempts).filter(({ binding: prior }) =>
    prior.dispatch_reservation_digest === reservation.reservation_digest);
  const sameAttempt = attemptIndex === null
    ? attempts.filter(({ binding: prior }) =>
      canonicalJson(prior) === bindingKey)
    : [attemptIndex.by_binding.get(bindingKey)].filter((item) =>
      item !== undefined &&
      item.binding.dispatch_reservation_digest ===
        reservation.reservation_digest);
  if (stage === 0) {
    if (sameAttempt.length !== 0) {
      throw ledgerError(
        "candidate-dispatch-attempt-replayed",
        "a dispatch candidate cannot acquire a second production lease",
      );
    }
    const acknowledged = new Set(active.acknowledgements.map(
      ({ candidate_index: index }) => index,
    ));
    if (attempts.some(({ binding: prior }) =>
      !acknowledged.has(prior.dispatch_candidate_index))) {
      throw ledgerError(
        "candidate-dispatch-attempt-unfinished",
        "the prior dispatch candidate must reach one durable acknowledgement",
      );
    }
    const budget = calculateActiveCandidateDispatchCommitBudget(
      dispatchAuthority.current_cycle,
      reachableRecordCount,
    );
    if (budget.remaining_ledger_commit_capacity_after_dispatch < 0) {
      throw ledgerError(
        "candidate-dispatch-commit-capacity",
        "ledger cannot persist the remaining scheduled candidate protocol",
      );
    }
    return { binding, binding_key: bindingKey, stage };
  }
  if (sameAttempt.length !== 1 || activeLease === null ||
      activeLease.acquire_commit_sha !== sameAttempt[0].entry.commit_sha ||
      activeLease.lease_id !== sameAttempt[0].entry.envelope.payload.lease_id ||
      canonicalJson(candidateDispatchAttemptBinding(
        activeLease.evaluated_scope_receipt,
      )) !== canonicalJson(binding)) {
    throw ledgerError(
      "candidate-dispatch-attempt-authority",
      "candidate production record lacks its unique active scheduled attempt",
    );
  }
  if (attemptIndex !== null) {
    const previousStage = sameAttempt[0].last_stage;
    if (
      stage <= previousStage ||
      stage === 1 && previousStage !== 0 ||
      stage > 1 && stage < 16 && previousStage < 1
    ) {
      throw ledgerError(
        "candidate-dispatch-attempt-order",
        "candidate production attempt is not one closed ordered prefix",
      );
    }
  } else {
    const acquireIndex = priorRecords.indexOf(sameAttempt[0].entry);
    const attemptRecords = priorRecords.slice(acquireIndex).map((entry) => ({
      value: entry.envelope,
      binding: candidateDispatchAttemptBinding(
        entry.envelope.workflow_provenance?.operation_binding
          ?.evaluated_scope_receipt ?? null,
      ),
    }));
    attemptRecords.push({ value: record, binding });
    let previousStage = -1;
    for (const item of attemptRecords) {
      const itemStage = candidateDispatchAttemptStage(item.value);
      if (
        itemStage === null || itemStage <= previousStage ||
        canonicalJson(item.binding) !== bindingKey ||
        itemStage === 1 && previousStage !== 0 ||
        itemStage > 1 && itemStage < 16 && previousStage < 1
      ) {
        throw ledgerError(
          "candidate-dispatch-attempt-order",
          "candidate production attempt is not one closed ordered prefix",
        );
      }
      previousStage = itemStage;
    }
  }
  return { binding, binding_key: bindingKey, stage };
}

function validateProductionTransition(
  loaded,
  record,
  repository,
  evaluatedScopeReceipt,
) {
  if (
    (loaded.authority_projection.candidate_inventory.incomplete_cycle !== null ||
      loaded.authority_projection.candidate_inventory.atomic_cycle !== null) &&
    record.record_type !== "candidate-inventory-observation"
  ) {
    throw ledgerError(
      "candidate-inventory-write-window",
      "an active candidate inventory transition rejects unrelated ledger writes",
    );
  }
  const currentDispatch = loaded.authority_projection.candidate_dispatch
    .current_cycle;
  if (
    currentDispatch !== null &&
    currentDispatch.cycle_complete === false &&
    currentDispatch.active_reservation === null &&
    record.record_type !== "candidate-dispatch-observation"
  ) {
    throw ledgerError(
      "candidate-dispatch-write-window",
      "an incomplete candidate dispatch rejects unrelated ledger writes",
    );
  }
  if (record.record_type === "candidate-inventory-observation") {
    const dispatch = loaded.authority_projection.candidate_dispatch;
    if (
      (record.payload.phase === "cycle-start" ||
       record.payload.phase === "current-open-generation") &&
      dispatch.current_cycle !== null &&
      dispatch.current_cycle.cycle_complete === false
    ) {
      throw ledgerError(
        "candidate-dispatch-inventory-replacement",
        "a new candidate inventory cannot start before dispatch completes",
      );
    }
    validateCandidateInventoryTransition(
      loaded.records,
      record,
      repository,
      {
        currentAuthority:
          loaded.authority_projection.candidate_inventory,
      },
    );
    return;
  }
  if (record.record_type === "candidate-dispatch-observation") {
    if (loaded.active_lease !== null &&
        record.payload.phase !== "candidate-ack") {
      throw ledgerError(
        "candidate-dispatch-active-pr-lease",
        "repository dispatch control cannot advance during an active PR lease",
      );
    }
    if (record.payload.phase === "candidate-ack" &&
        loaded.active_lease !== null) {
      throw ledgerError(
        "candidate-dispatch-lease-release-required",
        "candidate dispatch ack requires a durably released PR lease",
      );
    }
    validateCandidateDispatchTransition(
      loaded.records,
      record,
      repository,
      { reachableRecordCount: loaded.commit_count },
    );
    return;
  }
  validateCandidateDispatchAttemptWindow({
    prior_records: loaded.records,
    record,
    evaluated_scope_receipt: evaluatedScopeReceipt,
    dispatch_authority: loaded.authority_projection.candidate_dispatch,
    active_lease: loaded.active_lease,
    reachable_record_count: loaded.commit_count,
  });
  const currentControlComment = currentScopeControlCommentBinding(
    loaded.records,
    recordScope(record),
  );
  if (record.record_type === "lease-acquire") {
    if (loaded.active_lease !== null) {
      throw ledgerError("lease-active", "another unexpired controller lease is active");
    }
    if (loaded.records.some((entry) =>
      entry.envelope.record_type === "lease-acquire" &&
      entry.envelope.payload.lease_id === record.payload.lease_id)) {
      throw ledgerError("duplicate-lease", "lease identity is already consumed");
    }
    if (
      record.control_comment_binding !== null &&
      canonicalJson(record.control_comment_binding) !==
        canonicalJson(currentControlComment)
    ) {
      throw ledgerError(
        "control-comment-binding",
        "lease acquire cites a non-current controller comment binding",
      );
    }
    return;
  }
  if (loaded.active_lease === null) {
    throw ledgerError("lease-required", "production record requires an active controller lease");
  }
  validateRecordLease(record, loaded.active_lease);
  requireSameScope(recordScope(record), loaded.active_lease.scope, "production record");
  if (record.record_type === "lease-release") {
    if (Date.parse(record.server_observed_at) >= Date.parse(loaded.active_lease.expires_at)) {
      throw ledgerError("lease-expired", "an expired lease cannot be released or reused");
    }
    return;
  }
  if (Date.parse(record.server_observed_at) >= Date.parse(loaded.active_lease.expires_at)) {
    throw ledgerError("lease-expired", "effect record is at or after lease expiry");
  }
  if (record.kind === "control-comment-create") {
    if (currentControlComment !== null) {
      throw ledgerError(
        "control-comment-exists",
        "control-comment-create cannot replace an authorized controller comment",
      );
    }
  } else if (record.kind === "control-comment-update") {
    if (
      currentControlComment === null ||
      (record.record_type === "effect-intent" &&
        canonicalJson(record.control_comment_binding) !==
          canonicalJson(currentControlComment))
    ) {
      throw ledgerError(
        "control-comment-binding",
        "control-comment-update intent does not bind the current controller comment",
      );
    }
  } else if (
    record.control_comment_binding !== null &&
    canonicalJson(record.control_comment_binding) !==
      canonicalJson(currentControlComment)
  ) {
    throw ledgerError(
      "control-comment-binding",
      "effect record cites a non-current controller comment binding",
    );
  }
  if (record.record_type === "effect-intent") {
    if (record.kind === "artifact-binding") {
      validateArtifactBindingLineage(loaded.records, record, repository);
    } else if (record.kind === "artifact-binding-ready") {
      validateArtifactBindingReadyLineage(loaded.records, record, repository);
    } else if (record.kind === "request-binding") {
      validateRequestBindingLineage(loaded.records, record, repository);
    } else if (record.kind === "review-request") {
      validateReviewRequestLineage(loaded.records, record);
    } else if (record.kind === "automatic-request-reservation") {
      validateAutomaticReservationLineage(loaded.records, record);
    } else if (record.kind === "scheduler-observation") {
      validateSchedulerObservationLineage(loaded.records, record);
    } else if (record.kind === "effect-attempt") {
      validateEffectAttemptLineage(loaded.records, record);
    } else if (record.kind === "reservation-status-write") {
      validateReservationStatusLineage(loaded.records, record);
    } else if (record.kind === "status-write") {
      validateStatusWriteLineage(loaded.records, record);
    } else if (record.kind === "scheduler-state") {
      validateSchedulerStateLineage(loaded.records, record, repository);
    }
    for (const entry of loaded.records) {
      if (entry.envelope.record_type !== "effect-intent") continue;
      if (entry.envelope.effect_id === record.effect_id) {
        throw ledgerError("duplicate-effect", "effect identity is already consumed");
      }
      if (entry.envelope.idempotency_key === record.idempotency_key) {
        throw ledgerError("duplicate-idempotency", "idempotency key is already consumed");
      }
    }
  } else {
    if (record.kind === "artifact-binding") {
      validateArtifactBindingLineage(loaded.records, record, repository);
    } else if (record.kind === "artifact-binding-ready") {
      validateArtifactBindingReadyConfirmationLineage(
        loaded.records,
        record,
        repository,
      );
    } else if (record.kind === "request-binding") {
      validateRequestBindingLineage(loaded.records, record, repository);
    } else if (record.kind === "review-request") {
      validateReviewRequestLineage(loaded.records, record);
    } else if (record.kind === "status-write") {
      validateStatusWriteLineage(loaded.records, record);
    } else if (record.kind === "scheduler-state") {
      validateSchedulerStateLineage(loaded.records, record, repository);
    }
    const intent = loaded.records.find((entry) =>
      entry.envelope.record_type === "effect-intent" &&
      entry.envelope.effect_id === record.effect_id);
    const response = loaded.records.find((entry) =>
      entry.envelope.record_type === "effect-response" &&
      entry.envelope.effect_id === record.effect_id);
    const durableIntentRecovery = new Set([
      "artifact-binding", "artifact-binding-ready", "scheduler-state",
    ]).has(record.kind);
    if (
      intent === undefined || response !== undefined ||
      intent.envelope.idempotency_key !== record.idempotency_key ||
      intent.envelope.kind !== record.kind ||
      record.payload.intent_commit_sha !== intent.commit_sha ||
      (!durableIntentRecovery &&
        record.payload.predecessor_commit_sha !== intent.commit_sha) ||
      canonicalJson(record.payload.action) !==
        canonicalJson(intent.envelope.payload.action) ||
      canonicalJson(record.payload.generation) !==
        canonicalJson(intent.envelope.payload.generation) ||
      record.payload.ordinal !== intent.envelope.payload.ordinal
    ) {
      throw ledgerError("invalid-effect-response", "response does not bind one unbound intent");
    }
  }
}

function leaseReleaseIndexes(records, acquireCommitSha) {
  if (acquireCommitSha === null) return [];
  return records.flatMap((entry, index) =>
    entry.envelope.record_type === "lease-release" &&
      entry.envelope.payload.acquire_commit_sha === acquireCommitSha
      ? [index]
      : []);
}

function validateArtifactBindingReadyLineage(
  priorRecords,
  value,
  repositoryValue,
) {
  const repository = normalizeRepository(repositoryValue);
  const action = value.payload.action;
  const boundary = validateAutomaticRecoveryArtifactReachabilityBoundary(
    action.intent_reachability_boundary,
  );
  const intentIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === action.artifact_binding_intent_record_oid);
  const schedulerIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === action.scheduler_observation_record_oid);
  const acquireIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === boundary.lease_acquire_commit_sha);
  const boundaryIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === boundary.boundary_tip_record_oid);
  const intent = priorRecords[intentIndex]?.envelope;
  const scheduler = priorRecords[schedulerIndex]?.envelope;
  const acquire = priorRecords[acquireIndex]?.envelope;
  const boundaryTip = priorRecords[boundaryIndex]?.envelope;
  if (
    intent?.record_type === "effect-intent" &&
    intent.kind === "artifact-binding"
  ) {
    validateArtifactBindingLineage(
      priorRecords.slice(0, intentIndex),
      intent,
      repository,
    );
  }
  const candidateAuthority = intent?.kind === "artifact-binding"
    ? validateAutomaticRecoveryArtifactBindingCandidateAuthority(
        intent.payload.action.candidate_authority,
      )
    : null;
  const schedulerObservation =
    scheduler?.record_type === "effect-intent" &&
      scheduler.kind === "scheduler-observation"
      ? validateV2GitLedgerSchedulerObservation(scheduler.payload.action)
      : null;
  const controlled =
    schedulerObservation?.prior_scheduling.epoch.controlled_request ?? null;
  const automatic =
    schedulerObservation?.prior_scheduling.epoch.automatic_request ?? null;
  const readyScope = recordScope(value);
  const currentEntries = schedulerIndex < 0 || boundaryIndex < schedulerIndex
    ? []
    : priorRecords.slice(schedulerIndex, boundaryIndex + 1);
  const readyEvaluated = value.workflow_provenance?.operation_binding
    ?.evaluated_scope_receipt ?? null;
  const intentAcquireOid = intent?.lease?.acquire_commit_sha ?? null;
  const intentReleaseIndexes = intentAcquireOid === null ||
      intentAcquireOid === boundary.lease_acquire_commit_sha
    ? []
    : leaseReleaseIndexes(priorRecords, intentAcquireOid);
  const queueParentOid = intent?.kind === "artifact-binding"
    ? intent.payload.action
      .queued_after_artifact_binding_intent_record_oid
    : null;
  const queueParentResponses = queueParentOid === null
    ? []
    : priorRecords.filter((entry) =>
        entry.envelope.record_type === "effect-response" &&
        entry.envelope.kind === "artifact-binding" &&
        entry.envelope.payload.intent_commit_sha === queueParentOid);
  const identityMismatch = candidateAuthority === null || intentIndex < 0 ||
    value.effect_id !== `${intent.effect_id}:ready` ||
    value.idempotency_key !== `${intent.idempotency_key}:ready` ||
    action.artifact_binding_intent_payload_digest !== intent.payload_digest ||
    action.candidate_set_digest !==
      automaticRecoveryArtifactBindingCandidateSetDigest(candidateAuthority) ||
    action.candidate_authority_digest !== candidateAuthority.authority_digest ||
    action.queued_after_artifact_binding_intent_record_oid !==
      intent.payload.action
        .queued_after_artifact_binding_intent_record_oid ||
    (queueParentOid !== null && queueParentResponses.length !== 1) ||
    action.generation_id !== candidateAuthority.generation_id ||
    canonicalJson(value.payload.generation) !==
      canonicalJson(intent.payload.generation);
  const boundaryMismatches = [
    schedulerIndex < 0 && "scheduler-missing",
    acquireIndex < 0 && "acquire-missing",
    schedulerIndex <= acquireIndex && "scheduler-order",
    boundaryIndex < schedulerIndex && "boundary-order",
    intentIndex > boundaryIndex && "intent-order",
    value.predecessor_commit_sha !== boundary.boundary_tip_record_oid &&
      "predecessor",
    boundary.intent_record_oid !==
      action.artifact_binding_intent_record_oid && "intent-reference",
    boundary.scheduler_observation_record_oid !==
      action.scheduler_observation_record_oid && "scheduler-reference",
    boundary.ref_receipt.target_commit_sha !==
      boundary.boundary_tip_record_oid && "ref-target",
    boundaryTip === undefined && "tip-missing",
    boundaryTip !== undefined &&
      boundary.ref_receipt.ref !== boundaryTip.ledger_ref && "ref-name",
    boundary.ref_receipt.server_time !== value.server_observed_at &&
      "ready-time",
    boundaryTip !== undefined &&
      Date.parse(boundary.ref_receipt.server_time) <
        Date.parse(boundaryTip.server_observed_at) && "tip-time",
    intentAcquireOid !== null &&
      intentAcquireOid !== boundary.lease_acquire_commit_sha &&
      (intentReleaseIndexes.length !== 1 ||
        intentReleaseIndexes[0] <= intentIndex ||
        intentReleaseIndexes[0] >= acquireIndex) && "intent-lease-release",
  ].filter(Boolean);
  const boundaryMismatch = boundaryMismatches.length !== 0;
  const schedulerMismatch = acquire?.record_type !== "lease-acquire" ||
    value.lease?.acquire_commit_sha !== boundary.lease_acquire_commit_sha ||
    scheduler?.lease?.acquire_commit_sha !==
      boundary.lease_acquire_commit_sha ||
    canonicalJson(envelopeScope(acquire)) !== canonicalJson(readyScope) ||
    canonicalJson(envelopeScope(scheduler)) !== canonicalJson(readyScope) ||
    schedulerObservation === null ||
    schedulerObservation.scheduler_evaluation.decision !==
      candidateAuthority?.decision ||
    schedulerObservation.scheduler_evaluation.epoch_id !==
      candidateAuthority.review_epoch_id ||
    schedulerObservation.evaluated_scope_receipt_digest !==
      action.full_scope_receipt_digest ||
    readyEvaluated !== null &&
      readyEvaluated.receipt_digest !== action.full_scope_receipt_digest ||
    currentEntries.some((entry) =>
      canonicalJson(envelopeScope(entry.envelope)) !==
        canonicalJson(readyScope) ||
      entry.envelope.lease?.acquire_commit_sha !==
        boundary.lease_acquire_commit_sha);
  const requestMismatch =
    controlled === null ||
    controlled.request_id !== candidateAuthority.request_id ||
    controlled.bound_at !== candidateAuthority.request_bound_at ||
    controlled.binding_record_oid !==
      candidateAuthority.request_binding_record_oid ||
    controlled.binding_receipt_digest !==
      candidateAuthority.request_binding_receipt_digest ||
    automatic === null ||
    automatic.generation_index !== candidateAuthority.generation_index ||
    candidateAuthority.scope.repository.owner !== repository.owner ||
    candidateAuthority.scope.repository.name !== repository.name ||
    candidateAuthority.scope.repository.node_id !== repository.node_id ||
    candidateAuthority.scope.pull_request.number !== readyScope.pull_request.number ||
    candidateAuthority.scope.pull_request.node_id !== readyScope.pull_request.node_id ||
    candidateAuthority.scope.base_oid !== readyScope.base_ref_oid ||
    candidateAuthority.scope.head_oid !== readyScope.head_ref_oid;
  const mismatch = [
    identityMismatch && "identity",
    boundaryMismatch && "boundary",
    schedulerMismatch && "scheduler",
    requestMismatch && "request",
  ].filter(Boolean);
  if (mismatch.length !== 0) {
    throw ledgerError(
      "automatic-artifact-binding-ready-lineage",
      `artifact binding ready marker lacks one exact reachable ${mismatch.join("/")} authority${boundaryMismatches.length === 0 ? "" : ` (${boundaryMismatches.join(",")})`}`,
    );
  }
}

function validateArtifactBindingReadyConfirmationLineage(
  priorRecords,
  value,
  repositoryValue,
) {
  normalizeRepository(repositoryValue);
  const receipt = value.payload.receipt;
  const boundary =
    validateAutomaticRecoveryArtifactReadyReachabilityBoundary(
      receipt.ready_reachability_boundary,
    );
  const readyIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === receipt.ready_record_oid);
  const ready = priorRecords[readyIndex]?.envelope;
  if (
    ready?.record_type === "effect-intent" &&
    ready.kind === "artifact-binding-ready"
  ) {
    validateArtifactBindingReadyLineage(
      priorRecords.slice(0, readyIndex),
      ready,
      repositoryValue,
    );
  }
  const intentIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === boundary.artifact_binding_intent_record_oid);
  const boundaryIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === boundary.boundary_tip_record_oid);
  const schedulerIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha ===
      boundary.continuation_scheduler_observation_record_oid);
  const currentAcquireIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === boundary.continuation_lease_acquire_commit_sha);
  const oldAcquireOid = ready?.lease?.acquire_commit_sha ?? null;
  const oldReleaseIndexes = boundary.cross_run
    ? leaseReleaseIndexes(priorRecords, oldAcquireOid)
    : [];
  const scheduler = priorRecords[schedulerIndex]?.envelope;
  const schedulerAction =
    scheduler?.record_type === "effect-intent" &&
      scheduler.kind === "scheduler-observation"
      ? validateV2GitLedgerSchedulerObservation(scheduler.payload.action)
      : null;
  const intent = priorRecords[intentIndex]?.envelope;
  const candidateAuthority = intent?.record_type === "effect-intent" &&
      intent.kind === "artifact-binding"
    ? validateAutomaticRecoveryArtifactBindingCandidateAuthority(
        intent.payload.action.candidate_authority,
      )
    : null;
  const scope = recordScope(value);
  const currentEntries = schedulerIndex < 0 || boundaryIndex < schedulerIndex
    ? []
    : priorRecords.slice(schedulerIndex, boundaryIndex + 1);
  const evaluated = value.workflow_provenance?.operation_binding
    ?.evaluated_scope_receipt ?? null;
  const mismatch =
    readyIndex < 0 || intentIndex < 0 || intentIndex >= readyIndex ||
    boundaryIndex < readyIndex || schedulerIndex < 0 ||
    currentAcquireIndex < 0 || currentAcquireIndex >= schedulerIndex ||
    receipt.ready_record_payload_digest !== ready?.payload_digest ||
    boundary.ready_record_oid !== receipt.ready_record_oid ||
    boundary.ready_record_payload_digest !==
      receipt.ready_record_payload_digest ||
    boundary.artifact_binding_intent_record_oid !==
      ready?.payload.action.artifact_binding_intent_record_oid ||
    boundary.ref_receipt.target_commit_sha !==
      boundary.boundary_tip_record_oid ||
    boundary.ref_receipt.ref !==
      priorRecords[boundaryIndex]?.envelope.ledger_ref ||
    value.predecessor_commit_sha !== boundary.boundary_tip_record_oid ||
    boundary.ref_receipt.server_time !== value.server_observed_at ||
    Date.parse(boundary.ref_receipt.server_time) <
      Date.parse(priorRecords[boundaryIndex]?.envelope.server_observed_at) ||
    value.lease?.acquire_commit_sha !==
      boundary.continuation_lease_acquire_commit_sha ||
    scheduler?.lease?.acquire_commit_sha !==
      boundary.continuation_lease_acquire_commit_sha ||
    schedulerAction === null ||
    schedulerAction.scheduler_evaluation.decision !==
      candidateAuthority?.decision ||
    schedulerAction.evaluated_scope_receipt_digest !==
      boundary.continuation_full_scope_receipt_digest ||
    evaluated !== null && evaluated.receipt_digest !==
      boundary.continuation_full_scope_receipt_digest ||
    canonicalJson(envelopeScope(scheduler)) !== canonicalJson(scope) ||
    currentEntries.some((entry) =>
      canonicalJson(envelopeScope(entry.envelope)) !== canonicalJson(scope) ||
      entry.envelope.lease?.acquire_commit_sha !==
        boundary.continuation_lease_acquire_commit_sha) ||
    (!boundary.cross_run && (
      oldAcquireOid !== boundary.continuation_lease_acquire_commit_sha ||
      ready.payload.action.scheduler_observation_record_oid !==
        boundary.continuation_scheduler_observation_record_oid ||
      boundary.boundary_tip_record_oid !== receipt.ready_record_oid
    )) ||
    (boundary.cross_run && (
      oldAcquireOid === boundary.continuation_lease_acquire_commit_sha ||
      oldReleaseIndexes.length !== 1 ||
      oldReleaseIndexes[0] <= readyIndex ||
      oldReleaseIndexes[0] >= currentAcquireIndex
    ));
  if (mismatch) {
    throw ledgerError(
      "automatic-artifact-binding-ready-confirmation-lineage",
      "artifact binding ready confirmation lacks one exact durable continuation boundary",
    );
  }
}

function validateArtifactBindingLineage(priorRecords, value, repositoryValue) {
  const repository = normalizeRepository(repositoryValue);
  const action = value.payload.action;
  const candidateAuthority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(
      action.candidate_authority,
    );
  const candidateProfile = automaticRecoveryArtifactBindingCandidateProfile(
    candidateAuthority,
  );
  if (candidateProfile.purpose !== "finding-recovery") {
    throw ledgerError(
      "terminal-clean-artifact-binding-disabled",
      "terminal clean carriers are parser-compatible audit bytes without durable binding authority",
    );
  }
  if (value.record_type === "effect-intent") {
    validateAutomaticRecoveryArtifactBindingQueueLineage(
      priorRecords,
      value,
      candidateAuthority,
    );
  }
  const bindingEntry = priorRecords.find((entry) =>
    entry.commit_sha === action.request_binding_record_oid);
  const binding = bindingEntry?.envelope;
  if (
    binding?.record_type !== "effect-response" ||
    binding.kind !== "request-binding"
  ) {
    throw ledgerError(
      "artifact-request-binding-required",
      "artifact binding requires one prior reachable request-binding response",
    );
  }
  validateRequestBindingLineage(
    priorRecords.slice(0, priorRecords.indexOf(bindingEntry)),
    binding,
    repository,
  );
  const currentScope = value.record_type?.startsWith("effect-")
    ? recordScope(value)
    : envelopeScope(value);
  const requestScope = envelopeScope(binding);
  const exactRequestScope = canonicalJson(currentScope) ===
    canonicalJson(requestScope);
  const sameHeadRequestRetarget =
    candidateProfile.purpose === "finding-recovery" &&
    canonicalJson(currentScope.pull_request) ===
      canonicalJson(requestScope.pull_request) &&
    currentScope.head_ref_oid === requestScope.head_ref_oid &&
    candidateAuthority.scope.repository.owner === repository.owner &&
    candidateAuthority.scope.repository.name === repository.name &&
    candidateAuthority.scope.repository.node_id === repository.node_id &&
    canonicalJson(candidateAuthority.scope.pull_request) ===
      canonicalJson(currentScope.pull_request) &&
    candidateAuthority.scope.base_oid === currentScope.base_ref_oid &&
    candidateAuthority.scope.head_oid === currentScope.head_ref_oid;
  if (!exactRequestScope && !sameHeadRequestRetarget) {
    throw ledgerError(
      "artifact-request-lineage-mismatch",
      "artifact binding request lineage is outside its exact PR and head authority",
    );
  }
  const bindingPayload = binding.payload;
  const observationEntry = priorRecords.find((entry) =>
    entry.commit_sha === action.scheduler_observation_record_oid);
  const observation = observationEntry === undefined
    ? null
    : validateV2GitLedgerSchedulerObservation(
        observationEntry.envelope.payload.action,
      );
  const controlled = observation?.prior_scheduling.epoch.controlled_request ?? null;
  const automatic = observation?.prior_scheduling.epoch.automatic_request ?? null;
  if (
    bindingPayload.generation.generation_id !==
      value.payload.generation.generation_id ||
    bindingPayload.generation.kind !== value.payload.generation.kind ||
    bindingPayload.generation.index !== value.payload.generation.index ||
    bindingPayload.action.generation_id !== action.generation_id ||
    bindingPayload.action.request_id !== action.request_id ||
    bindingPayload.receipt.request_id !== action.request_id ||
    bindingPayload.receipt.request_node_id !== action.request_node_id ||
    bindingPayload.receipt.controlled !== true ||
    digestCanonical(
      "codex-review-gate-v2-request-binding-receipt",
      bindingPayload.receipt,
    ) !== candidateAuthority.request_binding_receipt_digest ||
    observationEntry?.envelope.record_type !== "effect-intent" ||
    observationEntry.envelope.kind !== "scheduler-observation" ||
    priorRecords.indexOf(observationEntry) < priorRecords.indexOf(bindingEntry) ||
    observation.scheduler_evaluation.decision !== candidateAuthority.decision ||
    observation.scheduler_evaluation.snapshot_fingerprint !==
      candidateAuthority.snapshot_fingerprint ||
    observation.scheduler_evaluation.epoch_id !==
      candidateAuthority.review_epoch_id ||
    observation.scheduler_evaluation.observed_at !==
      candidateAuthority.observed_at ||
    observation.evaluated_scope_receipt_digest !==
      action.full_scope_receipt_digest ||
    controlled === null ||
    controlled.request_id !== candidateAuthority.request_id ||
    controlled.bound_at !== candidateAuthority.request_bound_at ||
    controlled.binding_record_oid !==
      candidateAuthority.request_binding_record_oid ||
    controlled.binding_receipt_digest !==
      candidateAuthority.request_binding_receipt_digest ||
    automatic === null ||
    automatic.generation_index !== candidateAuthority.generation_index ||
    candidateAuthority.scope.repository.owner !== repository.owner ||
    candidateAuthority.scope.repository.name !== repository.name ||
    candidateAuthority.scope.repository.node_id !== repository.node_id ||
    candidateAuthority.scope.pull_request.number !== value.pull_request.number ||
    candidateAuthority.scope.pull_request.node_id !== value.pull_request.node_id ||
    candidateAuthority.scope.base_oid !== value.base_ref_oid ||
    candidateAuthority.scope.head_oid !== value.head_ref_oid
  ) {
    throw ledgerError(
      "artifact-request-lineage-mismatch",
      "artifact binding differs from its prior controlled request authority",
    );
  }
  if (value.record_type !== "effect-response") return;
  const receipt = value.payload.receipt;
  validateAutomaticRecoveryArtifactReachabilityLineage({
    prior_records: priorRecords,
    response: value,
    candidate_authority: candidateAuthority,
    repository,
  });
  receipt.bindings.forEach((artifactBinding) => {
    requireExactArtifactUrl(
      artifactBinding.artifact_url,
      repository,
      value.pull_request,
      artifactBinding.artifact_selector,
    );
    if (
      Date.parse(artifactBinding.artifact_created_at) <=
        Date.parse(bindingPayload.receipt.created_at) ||
      Date.parse(artifactBinding.server_time) <
        Date.parse(artifactBinding.artifact_created_at)
    ) {
      throw ledgerError(
        "artifact-time-order",
        "artifact binding does not strictly follow its request authority",
      );
    }
  });
}

function validateAutomaticRecoveryArtifactBindingQueueLineage(
  priorRecords,
  value,
  candidateAuthority,
) {
  const action = value.payload.action;
  const incarnationRecords = currentScopeIncarnationRecords(
    priorRecords,
    recordOrEnvelopeScope(value),
  );
  const queueParentOid =
    action.queued_after_artifact_binding_intent_record_oid;
  const priorIntents = incarnationRecords.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "artifact-binding" &&
    sameExactScope(entry.envelope, recordOrEnvelopeScope(value)) &&
    entry.envelope.payload.generation.generation_id ===
      candidateAuthority.generation_id &&
    entry.envelope.payload.action.request_binding_record_oid ===
      candidateAuthority.request_binding_record_oid);
  if (queueParentOid === null) {
    if (priorIntents.length !== 0) {
      throw ledgerError(
        "automatic-artifact-binding-queue-lineage",
        "a later artifact binding transaction must identify its unique durable queue parent",
      );
    }
    return;
  }
  const parentEntry = priorIntents.find((entry) =>
    entry.commit_sha === queueParentOid);
  const parent = parentEntry?.envelope;
  const readyEntries = incarnationRecords.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "artifact-binding-ready" &&
    entry.envelope.payload.action.artifact_binding_intent_record_oid ===
      queueParentOid);
  const ready = readyEntries[0];
  const confirmations = ready === undefined
    ? []
    : incarnationRecords.filter((entry) =>
        entry.envelope.record_type === "effect-response" &&
        entry.envelope.kind === "artifact-binding-ready" &&
        entry.envelope.payload.intent_commit_sha === ready.commit_sha);
  const parentAuthority = parent?.record_type === "effect-intent" &&
      parent.kind === "artifact-binding"
    ? validateAutomaticRecoveryArtifactBindingCandidateAuthority(
        parent.payload.action.candidate_authority,
      )
    : null;
  const parentSemantic = parentAuthority === null
    ? null
    : automaticRecoveryArtifactBindingCandidateAggregateSemantic(
        parentAuthority,
      );
  const currentSemantic =
    automaticRecoveryArtifactBindingCandidateAggregateSemantic(
      candidateAuthority,
    );
  const combinedCandidates = parentSemantic === null
    ? []
    : [...parentSemantic.candidates, ...currentSemantic.candidates];
  const selectors = new Set(combinedCandidates.map((candidate) =>
    canonicalJson(candidate.selector)));
  const sortedCandidates = [...combinedCandidates].sort((left, right) =>
    Date.parse(left.artifact_created_at) -
        Date.parse(right.artifact_created_at) ||
      (BigInt(left.selector.id) < BigInt(right.selector.id)
        ? -1
        : BigInt(left.selector.id) > BigInt(right.selector.id) ? 1 : 0));
  if (
    priorIntents.length !== 1 || parentEntry === undefined ||
    parent.payload.action
      .queued_after_artifact_binding_intent_record_oid !== null ||
    readyEntries.length !== 1 || confirmations.length !== 1 ||
    parentSemantic === null ||
    !automaticRecoveryArtifactBindingCandidateSemanticContextsEqual(
      parentSemantic,
      currentSemantic,
    ) ||
    selectors.size !== combinedCandidates.length ||
    canonicalJson(sortedCandidates) !== canonicalJson(combinedCandidates)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-queue-lineage",
      "artifact binding queue lacks one exact ordered disjoint suffix after its durable parent confirmation",
    );
  }
}

function validateAutomaticRecoveryArtifactReachabilityLineage({
  prior_records: priorRecords,
  response,
  candidate_authority: candidateAuthorityValue,
  repository,
}) {
  const candidateAuthority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(
      candidateAuthorityValue,
    );
  const receipt = response.payload.receipt;
  const confirmationIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha ===
      receipt.artifact_binding_ready_confirmation_record_oid);
  const confirmationEntry = priorRecords[confirmationIndex];
  const confirmation = confirmationEntry?.envelope;
  if (
    confirmation?.record_type === "effect-response" &&
    confirmation.kind === "artifact-binding-ready"
  ) {
    validateArtifactBindingReadyConfirmationLineage(
      priorRecords.slice(0, confirmationIndex),
      confirmation,
      repository,
    );
  }
  const boundary =
    confirmation?.record_type === "effect-response" &&
      confirmation.kind === "artifact-binding-ready"
    ? validateAutomaticRecoveryArtifactReadyReachabilityBoundary(
        confirmation.payload.receipt.ready_reachability_boundary,
      )
    : null;
  const intentIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === response.payload.intent_commit_sha);
  const intent = priorRecords[intentIndex]?.envelope;
  const continuationSchedulerIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha ===
      receipt.continuation_scheduler_observation_record_oid);
  const continuationScheduler =
    priorRecords[continuationSchedulerIndex]?.envelope;
  const continuationObservation =
    continuationScheduler?.record_type === "effect-intent" &&
      continuationScheduler.kind === "scheduler-observation"
      ? validateV2GitLedgerSchedulerObservation(
          continuationScheduler.payload.action,
        )
      : null;
  const controlled = continuationObservation?.prior_scheduling.epoch
    .controlled_request ?? null;
  const automatic = continuationObservation?.prior_scheduling.epoch
    .automatic_request ?? null;
  const continuationEvaluated = response.workflow_provenance
    ?.operation_binding?.evaluated_scope_receipt ?? null;
  const oldAcquireOid = intent?.lease?.acquire_commit_sha ?? null;
  const confirmationAcquireOid =
    confirmation?.lease?.acquire_commit_sha ?? null;
  const currentAcquireOid = receipt.continuation_lease_acquire_commit_sha;
  const currentAcquireIndex = priorRecords.findIndex((entry) =>
    entry.commit_sha === currentAcquireOid);
  const oldReleaseIndexes = oldAcquireOid === currentAcquireOid
    ? []
    : leaseReleaseIndexes(priorRecords, oldAcquireOid);
  const confirmationReleaseIndexes = confirmationAcquireOid === currentAcquireOid
    ? []
    : leaseReleaseIndexes(priorRecords, confirmationAcquireOid);
  if (
    confirmationIndex < 0 || boundary === null || intentIndex < 0 ||
    intentIndex >= confirmationIndex ||
    receipt.artifact_binding_ready_confirmation_payload_digest !==
      confirmation.payload_digest ||
    confirmation.payload.action.artifact_binding_intent_record_oid !==
      response.payload.intent_commit_sha ||
    confirmation.payload.action.candidate_set_digest !==
      response.payload.action.candidate_set_digest ||
    confirmation.payload.action.candidate_authority_digest !==
      candidateAuthority.authority_digest ||
    boundary.continuation_lease_acquire_commit_sha !==
      confirmationAcquireOid ||
    intent?.record_type !== "effect-intent" ||
    intent.kind !== "artifact-binding" ||
    intent.effect_id !== response.effect_id ||
    canonicalJson(intent.payload.action) !==
      canonicalJson(response.payload.action) ||
    continuationSchedulerIndex < 0 ||
    currentAcquireIndex < 0 ||
    currentAcquireIndex >= continuationSchedulerIndex ||
    continuationObservation === null ||
    continuationObservation.scheduler_evaluation.decision !==
      candidateAuthority.decision ||
    continuationObservation.scheduler_evaluation.epoch_id !==
      candidateAuthority.review_epoch_id ||
    continuationObservation.evaluated_scope_receipt_digest !==
      receipt.continuation_full_scope_receipt_digest ||
    continuationEvaluated !== null &&
      continuationEvaluated.receipt_digest !==
        receipt.continuation_full_scope_receipt_digest ||
    response.lease?.acquire_commit_sha !== currentAcquireOid ||
    continuationScheduler.lease?.acquire_commit_sha !== currentAcquireOid ||
    canonicalJson(envelopeScope(continuationScheduler)) !==
      canonicalJson(recordScope(response)) ||
    controlled === null || controlled.request_id !== candidateAuthority.request_id ||
    controlled.binding_record_oid !==
      candidateAuthority.request_binding_record_oid ||
    automatic === null ||
    automatic.generation_index !== candidateAuthority.generation_index ||
    (oldAcquireOid !== currentAcquireOid && (
      oldReleaseIndexes.length !== 1 ||
      oldReleaseIndexes[0] <= intentIndex ||
      oldReleaseIndexes[0] >= currentAcquireIndex
    )) ||
    (confirmationAcquireOid !== currentAcquireOid && (
      confirmationReleaseIndexes.length !== 1 ||
      confirmationReleaseIndexes[0] <= confirmationIndex ||
      confirmationReleaseIndexes[0] >= currentAcquireIndex
    )) ||
    receipt.bindings.some((binding) =>
      Date.parse(binding.server_time) <=
        Date.parse(boundary.ref_receipt.server_time))
  ) {
    throw ledgerError(
      "automatic-artifact-binding-reachability-lineage",
      "artifact binding response lacks one immutable ready marker before its exact point reads",
    );
  }
}

function validateReviewRequestLineage(priorRecords, value) {
  const reservations = priorRecords.filter((entry) => {
    const envelope = entry.envelope;
    return envelope.record_type === "effect-intent" &&
      envelope.kind === "automatic-request-reservation" &&
      sameHeadScope(envelope, recordOrEnvelopeScope(value)) &&
      sameAutomaticGenerationIdentity(
        envelope.payload.generation,
        value.payload.generation,
      );
  });
  if (reservations.length !== 1) {
    throw ledgerError(
      "review-request-reservation-required",
      "review request requires one prior automatic reservation for its generation",
    );
  }
  const action = value.payload.action;
  const reservation = reservations[0];
  const attempts = priorRecords.filter((entry) => {
    const envelope = entry.envelope;
    return entry.commit_sha === action.attempt_record_oid &&
      envelope.record_type === "effect-intent" &&
      envelope.kind === "effect-attempt";
  });
  if (
    attempts.length !== 1 ||
    reservation.commit_sha !== action.reservation_record_oid ||
    attempts[0].envelope.payload.action.reservation_record_oid !==
      reservation.commit_sha ||
    attempts[0].envelope.payload.action.scheduler_observation_record_oid !==
      action.scheduler_observation_record_oid ||
    attempts[0].envelope.payload.action.scheduler_action_key !==
      action.scheduler_action_key ||
    reservation.envelope.payload.action.post_scheduler_action_key !==
      action.scheduler_action_key
  ) {
    throw ledgerError(
      "review-request-attempt-required",
      "review request lacks one durable retry-zero attempt and reservation lineage",
    );
  }
  if (value.record_type === "effect-response") {
    const intent = priorRecords.find((entry) =>
      entry.commit_sha === value.payload.intent_commit_sha);
    const receipt = value.payload.receipt;
    const preScopeObservedAt =
      receipt.request_scope_receipt.pre_scope.observed_at;
    const postScopeObservedAt =
      receipt.request_scope_receipt.post_scope.observed_at;
    const exactLegacyCollapsedBoundary = new Set([
      preScopeObservedAt,
      receipt.created_at,
      receipt.post_server_time,
      receipt.refetch_server_time,
      postScopeObservedAt,
    ]).size === 1;
    const currentTimeLineage = intent !== undefined &&
      Date.parse(preScopeObservedAt) <=
        Date.parse(intent.envelope.server_observed_at) &&
      Date.parse(intent.envelope.server_observed_at) <=
        Date.parse(receipt.created_at);
    if (
      intent?.envelope.record_type !== "effect-intent" ||
      intent.envelope.kind !== "review-request" ||
      !currentTimeLineage && !exactLegacyCollapsedBoundary
    ) {
      throw ledgerError(
        "review-request-time-lineage",
        "review request scope, intent, and created times are not causal",
      );
    }
  }
}

function validateAutomaticReservationLineage(priorRecords, value) {
  const action = value.payload.action;
  const repository = value.repository ?? priorRecords[0]?.envelope.repository;
  if (repository === undefined) {
    throw ledgerError(
      "automatic-reservation-repository-authority-missing",
      "automatic reservation lacks its reachable repository authority",
    );
  }
  const observation = priorRecords.find((entry) =>
    entry.commit_sha === action.scheduler_observation_record_oid);
  if (
    observation?.envelope.record_type !== "effect-intent" ||
    observation.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "scheduler-observation-required",
      "automatic reservation requires one prior scheduler observation",
    );
  }
  const observed = observation.envelope.payload.action;
  validateRequiredStatusBindingsForObservation(
    priorRecords,
    observation.commit_sha,
  );
  const persist = observed.scheduler_plan.actions.find((item) =>
    item.kind === "persist_auto_request_intent" &&
    item.idempotency_key === action.scheduler_action_key);
  const post = observed.scheduler_plan.actions.find((item) =>
    item.kind === "post_review_request" &&
    item.idempotency_key === action.post_scheduler_action_key);
  if (
    persist === undefined || post === undefined ||
    persist.intent_id !== action.reservation.scheduler_intent_id ||
    post.intent_id !== persist.intent_id ||
    post.depends_on_idempotency_key !== persist.idempotency_key ||
    Date.parse(action.reservation.created_at) <
      Date.parse(observed.snapshot_server_time) ||
    action.reservation.status_ledger_binding.automatic_request_count !==
      countAutomaticReservations(priorRecords, recordOrEnvelopeScope(value))
  ) {
    throw ledgerError(
      "automatic-reservation-scheduler-mismatch",
      "automatic reservation differs from its exact scheduler action authority",
    );
  }
  if (
    action.reservation.status_ledger_binding.ledger_digest !==
      runnerHeadLedgerDigestFromRecords(
        priorRecords,
        recordOrEnvelopeScope(value),
        repository,
        action.reservation.status_ledger_binding.observed_at,
      )
  ) {
    throw ledgerError(
      "automatic-reservation-ledger-mismatch",
      "automatic reservation head-ledger preimage differs from reachable authority",
    );
  }
}

function validateRequiredStatusBindingsForObservation(
  priorRecords,
  observationRecordOid,
) {
  const observation = priorRecords.find((entry) =>
    entry.commit_sha === observationRecordOid);
  if (
    observation?.envelope.record_type !== "effect-intent" ||
    observation.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "scheduler-observation-required",
      "automatic reservation requires one protected scheduler observation",
    );
  }
  const statusPlan = observation.envelope.payload.action.status_plan;
  if (statusPlan.writes.length < 1 || statusPlan.writes.length > 2) {
    throw ledgerError(
      "automatic-request-status-transaction-required",
      "automatic request requires one closed one-or-two-write status transaction",
    );
  }
  const progress = statusWriteTransactionProgress(
    priorRecords,
    observationRecordOid,
    statusPlan.writes.length,
  );
  if (
    progress.unbound_intent !== null ||
    progress.next_index !== statusPlan.writes.length
  ) {
    throw ledgerError(
      "automatic-request-required-status-unbound",
      "automatic request requires every exact semantic status response binding",
    );
  }
}

function validateAutomaticRecoveryArtifactBindingStatusLineage(
  priorRecords,
  observationRecordOid,
  candidateAuthorityValue,
) {
  const candidateAuthority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(
      candidateAuthorityValue,
    );
  const profile = automaticRecoveryArtifactBindingCandidateProfile(
    candidateAuthority,
  );
  if (profile.purpose === "finding-recovery") {
    validateRequiredStatusBindingsForObservation(
      priorRecords,
      observationRecordOid,
    );
    return;
  }
  const observation = priorRecords.find((entry) =>
    entry.commit_sha === observationRecordOid);
  if (
    observation?.envelope.record_type !== "effect-intent" ||
    observation.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "scheduler-observation-required",
      "terminal clean artifact binding requires one protected scheduler observation",
    );
  }
  const statusPlan = observation.envelope.payload.action.status_plan;
  const suppressedWrites = statusPlan.suppressed_writes ?? [];
  if (
    statusPlan.decision !== "pending" ||
    statusPlan.terminal_cutover !== false ||
    [...statusPlan.writes, ...suppressedWrites].some((write) =>
      write.role !== "head-sentinel" || write.state !== "pending")
  ) {
    throw ledgerError(
      "automatic-artifact-binding-terminal-status-forbidden",
      "terminal clean artifact binding must preserve one non-terminal pending result",
    );
  }
  if (statusPlan.writes.length > 0) {
    validateRequiredStatusBindingsForObservation(
      priorRecords,
      observationRecordOid,
    );
  }
}

function validateAutomaticRecoveryAgainstObservation({
  authority: authorityValue,
  observation_entry: observationEntry,
  scope,
  repository,
  full_scope_receipt_digest: fullScopeReceiptDigest,
}) {
  const authority = validateAutomaticRequestRecoveryAuthority(authorityValue);
  if (
    observationEntry?.envelope.record_type !== "effect-intent" ||
    observationEntry.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "automatic-recovery-scheduler-observation-required",
      "automatic recovery requires one protected scheduler observation",
    );
  }
  const observation = validateV2GitLedgerSchedulerObservation(
    observationEntry.envelope.payload.action,
  );
  const controlled = observation.prior_scheduling.epoch.controlled_request;
  const automatic = observation.prior_scheduling.epoch.automatic_request;
  if (
    observation.scheduler_evaluation.decision !== "findings" ||
    observation.scheduler_evaluation.snapshot_fingerprint !==
      authority.snapshot_fingerprint ||
    observation.scheduler_evaluation.epoch_id !== authority.review_epoch_id ||
    observation.prior_scheduling.epoch.id !== authority.review_epoch_id ||
    observation.snapshot_server_time !== authority.final_snapshot_server_time ||
    observation.evaluated_scope_receipt_digest !== fullScopeReceiptDigest ||
    controlled === null ||
    controlled.request_id !== authority.prior_request_id ||
    controlled.binding_record_oid !==
      authority.prior_request_binding_record_oid ||
    controlled.binding_receipt_digest !==
      authority.prior_request_binding_receipt_digest ||
    automatic.generation_index !== authority.prior_generation_index ||
    authority.scope.repository_node_id !== repository.node_id ||
    authority.scope.pull_request_number !== scope.pull_request.number ||
    authority.scope.pull_request_node_id !== scope.pull_request.node_id ||
    authority.scope.base_oid !== scope.base_ref_oid ||
    authority.scope.head_oid !== scope.head_ref_oid
  ) {
    throw ledgerError(
      "automatic-recovery-observation-mismatch",
      "automatic recovery differs from its exact scheduler, request, and scope authority",
    );
  }
  return authority;
}

function automaticRecoveryArtifactBindingAction({
  authority: authorityValue,
  queued_after_artifact_binding_intent_record_oid:
    queuedAfterArtifactBindingIntentRecordOid = null,
  scheduler_observation_record_oid: schedulerObservationRecordOid,
  full_scope_receipt_digest: fullScopeReceiptDigest,
}) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(authorityValue);
  return deepFreeze({
    method: "GET",
    expected_status: 200,
    retry_policy: "safe-idempotent",
    generation_id: authority.generation_id,
    request_binding_record_oid: authority.request_binding_record_oid,
    request_id: authority.request_id,
    request_node_id: authority.request_node_id,
    queued_after_artifact_binding_intent_record_oid:
      queuedAfterArtifactBindingIntentRecordOid === null
        ? null
        : sha(
            queuedAfterArtifactBindingIntentRecordOid,
            "automatic artifact binding queue parent intent OID",
          ),
    scheduler_observation_record_oid: sha(
      schedulerObservationRecordOid,
      "automatic artifact binding scheduler observation record OID",
    ),
    full_scope_receipt_digest: digest(
      fullScopeReceiptDigest,
      "automatic artifact binding full scope receipt digest",
    ),
    candidate_set_digest:
      automaticRecoveryArtifactBindingCandidateSetDigest(authority),
    candidate_authority: structuredClone(authority),
  });
}

function automaticRecoveryArtifactBindingReadyAction({
  intent_record: intentRecordValue,
  intent_record_oid: intentRecordOid,
  scheduler_observation_record_oid: schedulerObservationRecordOid,
  full_scope_receipt_digest: fullScopeReceiptDigest,
  intent_reachability_boundary: reachabilityBoundaryValue,
}) {
  const intentRecord = validateV2GitLedgerRecord(intentRecordValue);
  if (
    intentRecord.record_type !== "effect-intent" ||
    intentRecord.kind !== "artifact-binding"
  ) {
    throw new TypeError(
      "artifact binding ready action requires one aggregate artifact intent",
    );
  }
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(
      intentRecord.payload.action.candidate_authority,
    );
  const reachabilityBoundary =
    validateAutomaticRecoveryArtifactReachabilityBoundary(
      reachabilityBoundaryValue,
    );
  const action = {
    artifact_binding_intent_record_oid: sha(
      intentRecordOid,
      "automatic artifact binding ready intent record OID",
    ),
    artifact_binding_intent_payload_digest: intentRecord.payload_digest,
    scheduler_observation_record_oid: sha(
      schedulerObservationRecordOid,
      "automatic artifact binding ready scheduler observation OID",
    ),
    full_scope_receipt_digest: digest(
      fullScopeReceiptDigest,
      "automatic artifact binding ready full scope receipt digest",
    ),
    generation_id: authority.generation_id,
    candidate_set_digest:
      automaticRecoveryArtifactBindingCandidateSetDigest(authority),
    candidate_authority_digest: authority.authority_digest,
    queued_after_artifact_binding_intent_record_oid:
      intentRecord.payload.action
        .queued_after_artifact_binding_intent_record_oid,
    intent_reachability_boundary: structuredClone(reachabilityBoundary),
  };
  return deepFreeze(action);
}

function validateAutomaticRecoveryArtifactReachabilityBoundary(value) {
  assertObject(value, "automatic artifact binding reachability boundary");
  exactKeys(value, [
    "schema", "schema_version", "intent_record_oid",
    "scheduler_observation_record_oid", "lease_acquire_commit_sha",
    "boundary_tip_record_oid", "ref_receipt", "boundary_digest",
  ], "automatic artifact binding reachability boundary");
  if (
    value.schema !==
      V2_GIT_LEDGER_AUTOMATIC_RECOVERY_ARTIFACT_REACHABILITY_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error(
      "automatic artifact binding reachability boundary schema is unsupported",
    );
  }
  sha(value.intent_record_oid,
    "automatic artifact binding reachability intent record OID");
  sha(value.scheduler_observation_record_oid,
    "automatic artifact binding reachability scheduler observation OID");
  sha(value.lease_acquire_commit_sha,
    "automatic artifact binding reachability lease acquire OID");
  sha(value.boundary_tip_record_oid,
    "automatic artifact binding reachability tip OID");
  validateRefReceipt(value.ref_receipt);
  if (value.ref_receipt.target_commit_sha !== value.boundary_tip_record_oid) {
    throw new Error(
      "automatic artifact binding reachability ref differs from its tip",
    );
  }
  digest(value.boundary_digest,
    "automatic artifact binding reachability boundary digest");
  const { boundary_digest: boundaryDigest, ...withoutDigest } = value;
  if (boundaryDigest !== digestCanonical(
    "codex-review-gate-v2-automatic-recovery-artifact-reachability",
    withoutDigest,
  )) {
    throw new Error(
      "automatic artifact binding reachability boundary digest is invalid",
    );
  }
  return deepFreeze(structuredClone(value));
}

function createAutomaticRecoveryArtifactReachabilityBoundary({
  loaded,
  intent_record_oid: intentRecordOid,
  scheduler_authority: schedulerAuthority,
  scope: scopeValue,
}) {
  const scope = normalizeEffectScope(scopeValue);
  const intentIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === intentRecordOid);
  const schedulerIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === schedulerAuthority.observation_record_oid);
  const boundaryIndex = loaded.records.length - 1;
  const boundaryTip = loaded.records[boundaryIndex];
  const activeLease = loaded.active_lease;
  const refReceiptValue = structuredClone(loaded.post_ref);
  const currentRecords = loaded.records.slice(
    schedulerIndex,
    boundaryIndex + 1,
  );
  const intent = loaded.records[intentIndex]?.envelope;
  const intentAcquireOid = intent?.lease?.acquire_commit_sha ?? null;
  const currentAcquireOid = schedulerAuthority.lease_authority
    .acquire_commit_sha;
  const currentAcquireIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === currentAcquireOid);
  const intentReleaseIndexes = intentAcquireOid === null ||
      intentAcquireOid === currentAcquireOid
    ? []
    : leaseReleaseIndexes(loaded.records, intentAcquireOid);
  if (
    scope === null || intentIndex < 0 || schedulerIndex < 0 ||
    currentAcquireIndex < 0 || currentAcquireIndex >= schedulerIndex ||
    boundaryTip === undefined ||
    loaded.post_ref.target_commit_sha !== boundaryTip.commit_sha ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      schedulerAuthority.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(scope) ||
    (intentAcquireOid !== null && intentAcquireOid !== currentAcquireOid && (
      intentReleaseIndexes.length !== 1 ||
      intentReleaseIndexes[0] <= intentIndex ||
      intentReleaseIndexes[0] >= currentAcquireIndex
    )) ||
    currentRecords.some((entry) => {
      const envelope = entry.envelope;
      return canonicalJson(envelopeScope(envelope)) !== canonicalJson(scope) ||
        envelope.lease?.acquire_commit_sha !==
          activeLease.acquire_commit_sha;
    })
  ) {
    throw ledgerError(
      "automatic-artifact-binding-reachability-mismatch",
      "artifact binding intent is not reachable under the current scheduler lease",
    );
  }
  const withoutDigest = {
    schema: V2_GIT_LEDGER_AUTOMATIC_RECOVERY_ARTIFACT_REACHABILITY_SCHEMA,
    schema_version: 1,
    intent_record_oid: intentRecordOid,
    scheduler_observation_record_oid:
      schedulerAuthority.observation_record_oid,
    lease_acquire_commit_sha: currentAcquireOid,
    boundary_tip_record_oid: boundaryTip.commit_sha,
    ref_receipt: refReceipt(refReceiptValue),
  };
  return validateAutomaticRecoveryArtifactReachabilityBoundary({
    ...withoutDigest,
    boundary_digest: digestCanonical(
      "codex-review-gate-v2-automatic-recovery-artifact-reachability",
      withoutDigest,
    ),
  });
}

function validateAutomaticRecoveryArtifactReadyReachabilityBoundary(value) {
  assertObject(value,
    "automatic artifact binding ready reachability boundary");
  exactKeys(value, [
    "schema", "schema_version", "ready_record_oid",
    "ready_record_payload_digest", "artifact_binding_intent_record_oid",
    "continuation_scheduler_observation_record_oid",
    "continuation_full_scope_receipt_digest",
    "continuation_lease_acquire_commit_sha", "boundary_tip_record_oid",
    "ref_receipt", "cross_run", "boundary_digest",
  ], "automatic artifact binding ready reachability boundary");
  if (
    value.schema !==
      V2_GIT_LEDGER_AUTOMATIC_RECOVERY_ARTIFACT_READY_REACHABILITY_SCHEMA ||
    value.schema_version !== 1 || typeof value.cross_run !== "boolean"
  ) {
    throw new Error(
      "automatic artifact binding ready reachability boundary is unsupported",
    );
  }
  for (const [key, label] of [
    ["ready_record_oid", "ready record OID"],
    ["artifact_binding_intent_record_oid", "artifact intent record OID"],
    ["continuation_scheduler_observation_record_oid",
      "continuation scheduler observation OID"],
    ["continuation_lease_acquire_commit_sha",
      "continuation lease acquire OID"],
    ["boundary_tip_record_oid", "boundary tip OID"],
  ]) {
    sha(value[key], `automatic artifact binding ${label}`);
  }
  digest(value.ready_record_payload_digest,
    "automatic artifact binding ready payload digest");
  digest(value.continuation_full_scope_receipt_digest,
    "automatic artifact binding continuation full scope digest");
  validateRefReceipt(value.ref_receipt);
  if (value.ref_receipt.target_commit_sha !== value.boundary_tip_record_oid) {
    throw new Error(
      "automatic artifact binding ready ref differs from its boundary tip",
    );
  }
  digest(value.boundary_digest,
    "automatic artifact binding ready boundary digest");
  const { boundary_digest: boundaryDigest, ...withoutDigest } = value;
  if (boundaryDigest !== digestCanonical(
    "codex-review-gate-v2-automatic-recovery-artifact-ready-reachability",
    withoutDigest,
  )) {
    throw new Error(
      "automatic artifact binding ready reachability digest is invalid",
    );
  }
  return deepFreeze(structuredClone(value));
}

function createAutomaticRecoveryArtifactReadyReachabilityBoundary({
  loaded,
  ready_record: readyRecordValue,
  ready_record_oid: readyRecordOid,
  scheduler_authority: schedulerAuthority,
  evaluated_scope_receipt: evaluatedScopeReceipt,
  scope: scopeValue,
}) {
  const readyRecord = validateV2GitLedgerRecord(readyRecordValue);
  const scope = normalizeEffectScope(scopeValue);
  const readyIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === readyRecordOid);
  const intentOid = readyRecord.payload.action
    .artifact_binding_intent_record_oid;
  const intentIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === intentOid);
  const schedulerIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === schedulerAuthority.observation_record_oid);
  const currentAcquireOid = schedulerAuthority.lease_authority
    .acquire_commit_sha;
  const currentAcquireIndex = loaded.records.findIndex((entry) =>
    entry.commit_sha === currentAcquireOid);
  const boundaryIndex = loaded.records.length - 1;
  const boundaryTip = loaded.records[boundaryIndex];
  const activeLease = loaded.active_lease;
  const readyAcquireOid = readyRecord.lease?.acquire_commit_sha ?? null;
  const sameRun = readyAcquireOid === currentAcquireOid &&
    readyRecord.payload.action.scheduler_observation_record_oid ===
      schedulerAuthority.observation_record_oid;
  const priorReleaseIndexes = sameRun
    ? []
    : leaseReleaseIndexes(loaded.records, readyAcquireOid);
  const currentRecords = schedulerIndex < 0
    ? []
    : loaded.records.slice(schedulerIndex, boundaryIndex + 1);
  if (
    scope === null || readyRecord.record_type !== "effect-intent" ||
    readyRecord.kind !== "artifact-binding-ready" || readyIndex < 0 ||
    intentIndex < 0 || intentIndex >= readyIndex || schedulerIndex < 0 ||
    currentAcquireIndex < 0 || currentAcquireIndex >= schedulerIndex ||
    boundaryTip === undefined ||
    loaded.post_ref.target_commit_sha !== boundaryTip.commit_sha ||
    activeLease === null ||
    activeLease.acquire_commit_sha !== currentAcquireOid ||
    canonicalJson(activeLease.scope) !== canonicalJson(scope) ||
    canonicalJson(evaluatedScopeReceipt.scope) !== canonicalJson(scope) ||
    (sameRun && boundaryTip.commit_sha !== readyRecordOid) ||
    (!sameRun && (
      priorReleaseIndexes.length !== 1 ||
      priorReleaseIndexes[0] <= readyIndex ||
      priorReleaseIndexes[0] >= currentAcquireIndex
    )) ||
    currentRecords.some((entry) =>
      canonicalJson(envelopeScope(entry.envelope)) !== canonicalJson(scope) ||
      entry.envelope.lease?.acquire_commit_sha !== currentAcquireOid)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-ready-reachability-mismatch",
      "artifact binding ready marker is not reachable under its exact continuation lease",
    );
  }
  const withoutDigest = {
    schema:
      V2_GIT_LEDGER_AUTOMATIC_RECOVERY_ARTIFACT_READY_REACHABILITY_SCHEMA,
    schema_version: 1,
    ready_record_oid: readyRecordOid,
    ready_record_payload_digest: readyRecord.payload_digest,
    artifact_binding_intent_record_oid: intentOid,
    continuation_scheduler_observation_record_oid:
      schedulerAuthority.observation_record_oid,
    continuation_full_scope_receipt_digest:
      evaluatedScopeReceipt.receipt_digest,
    continuation_lease_acquire_commit_sha: currentAcquireOid,
    boundary_tip_record_oid: boundaryTip.commit_sha,
    ref_receipt: refReceipt(loaded.post_ref),
    cross_run: !sameRun,
  };
  return validateAutomaticRecoveryArtifactReadyReachabilityBoundary({
    ...withoutDigest,
    boundary_digest: digestCanonical(
      "codex-review-gate-v2-automatic-recovery-artifact-ready-reachability",
      withoutDigest,
    ),
  });
}

function automaticRecoveryArtifactBindingReadyReceipt({
  ready_record: readyRecordValue,
  ready_record_oid: readyRecordOid,
  ready_reachability_boundary: readyReachabilityBoundaryValue,
}) {
  const readyRecord = validateV2GitLedgerRecord(readyRecordValue);
  const boundary =
    validateAutomaticRecoveryArtifactReadyReachabilityBoundary(
      readyReachabilityBoundaryValue,
    );
  if (
    readyRecord.record_type !== "effect-intent" ||
    readyRecord.kind !== "artifact-binding-ready" ||
    boundary.ready_record_oid !== readyRecordOid ||
    boundary.ready_record_payload_digest !== readyRecord.payload_digest ||
    boundary.artifact_binding_intent_record_oid !==
      readyRecord.payload.action.artifact_binding_intent_record_oid
  ) {
    throw new Error(
      "artifact binding ready confirmation differs from its exact marker",
    );
  }
  return deepFreeze({
    ready_record_oid: readyRecordOid,
    ready_record_payload_digest: readyRecord.payload_digest,
    ready_reachability_boundary: structuredClone(boundary),
  });
}

function validateAutomaticRecoveryArtifactBindingCandidateAgainstObservation({
  authority: authorityValue,
  observation_record_oid: observationRecordOid,
  records,
  repository,
  scope,
  full_scope_receipt_digest: fullScopeReceiptDigest,
  provider_identity_policy: providerIdentityPolicyValue,
}) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(authorityValue);
  const observationEntry = records.find((entry) =>
    entry.commit_sha === observationRecordOid);
  if (
    observationEntry?.envelope.record_type !== "effect-intent" ||
    observationEntry.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "automatic-artifact-binding-scheduler-observation-required",
      "artifact binding candidate requires one protected scheduler observation",
    );
  }
  const observation = validateV2GitLedgerSchedulerObservation(
    observationEntry.envelope.payload.action,
  );
  const controlled = observation.prior_scheduling.epoch.controlled_request;
  const automatic = observation.prior_scheduling.epoch.automatic_request;
  const policy = normalizeProviderIdentityPolicy(providerIdentityPolicyValue);
  const repositoryScope = authority.scope.repository;
  const pullRequestScope = authority.scope.pull_request;
  if (
    observation.scheduler_evaluation.decision !== authority.decision ||
    observation.scheduler_evaluation.snapshot_fingerprint !==
      authority.snapshot_fingerprint ||
    observation.scheduler_evaluation.epoch_id !== authority.review_epoch_id ||
    observation.scheduler_evaluation.observed_at !== authority.observed_at ||
    observation.evaluated_scope_receipt_digest !== fullScopeReceiptDigest ||
    controlled === null ||
    controlled.request_id !== authority.request_id ||
    controlled.bound_at !== authority.request_bound_at ||
    controlled.binding_record_oid !== authority.request_binding_record_oid ||
    controlled.binding_receipt_digest !==
      authority.request_binding_receipt_digest ||
    automatic.generation_index !== authority.generation_index ||
    repositoryScope.owner !== repository.owner ||
    repositoryScope.name !== repository.name ||
    repositoryScope.node_id !== repository.node_id ||
    pullRequestScope.number !== scope.pull_request.number ||
    pullRequestScope.node_id !== scope.pull_request.node_id ||
    authority.scope.base_oid !== scope.base_ref_oid ||
    authority.scope.head_oid !== scope.head_ref_oid ||
    canonicalJson(authority.expected_actor) !== canonicalJson(policy.actor) ||
    canonicalJson(authority.expected_app) !== canonicalJson(policy.app)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-candidate-observation-mismatch",
      "artifact binding candidate differs from scheduler, request, scope, or provider authority",
    );
  }
  const binding = records.find((entry) =>
    entry.commit_sha === authority.request_binding_record_oid);
  if (
    binding?.envelope.record_type !== "effect-response" ||
    binding.envelope.kind !== "request-binding" ||
    binding.envelope.payload.receipt.request_id !== authority.request_id ||
    binding.envelope.payload.receipt.request_node_id !==
      authority.request_node_id ||
    digestCanonical(
      "codex-review-gate-v2-request-binding-receipt",
      binding.envelope.payload.receipt,
    ) !== authority.request_binding_receipt_digest ||
    records.indexOf(binding) >= records.indexOf(observationEntry)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-request-authority-mismatch",
      "artifact binding candidate lacks its prior controlled request binding",
    );
  }
  return authority;
}

function validateAutomaticRecoveryArtifactPointRead(
  artifactHandle,
  authorityValue,
  candidateIndex,
  { reachability_boundary: reachabilityBoundaryValue = null } = {},
) {
  const authority =
    validateAutomaticRecoveryArtifactBindingCandidateAuthority(authorityValue);
  const reachabilityBoundary = reachabilityBoundaryValue === null
    ? null
    : validateAutomaticRecoveryArtifactReadyReachabilityBoundary(
        reachabilityBoundaryValue,
      );
  const candidate = authority.candidates[candidateIndex];
  if (candidate === undefined) {
    throw ledgerError(
      "automatic-artifact-binding-point-read-index",
      "exact artifact point read index is outside its aggregate authority",
    );
  }
  const artifact = artifactHandle.artifact;
  const createdAt = candidate.selector.kind === "pull_request_review"
    ? artifact.submitted_at
    : artifact.created_at;
  if (
    reachabilityBoundary !== null &&
    Date.parse(artifactHandle.response_server_time) <=
      Date.parse(reachabilityBoundary.ref_receipt.server_time)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-point-read-too-early",
      "exact artifact point read must strictly follow the durable ready boundary",
    );
  }
  if (
    canonicalJson(artifactHandle.selector) !==
      canonicalJson(candidate.selector) ||
    artifact.id !== candidate.selector.id ||
    artifact.node_id !== candidate.artifact_node_id ||
    artifact.html_url !== candidate.artifact_url ||
    createdAt !== candidate.artifact_created_at ||
    canonicalJson(artifact.author) !==
      canonicalJson(authority.expected_actor) ||
    canonicalJson(artifact.app) !== canonicalJson(authority.expected_app) ||
    artifactHandle.raw_body_sha256 !==
      candidate.evidence_raw_body_sha256 ||
    Date.parse(artifactHandle.response_server_time) <
      Date.parse(candidate.evidence_response_server_time)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-point-read-mismatch",
      "exact artifact point read differs from the opaque runner candidate",
    );
  }
  return artifactHandle;
}

function automaticRecoveryArtifactBindingReceipt({
  action,
  provider_artifact_handles: artifactHandles,
  ready_confirmation_record: readyConfirmationRecordValue,
  ready_confirmation_record_oid: readyConfirmationRecordOid,
  continuation_scheduler_observation_record_oid:
    continuationSchedulerObservationRecordOid,
  continuation_full_scope_receipt_digest: continuationFullScopeReceiptDigest,
  continuation_lease_acquire_commit_sha: continuationLeaseAcquireCommitSha,
}) {
  const authority = validateAutomaticRecoveryArtifactBindingCandidateAuthority(
    action.candidate_authority,
  );
  const readyConfirmationRecord = validateV2GitLedgerRecord(
    readyConfirmationRecordValue,
  );
  if (
    readyConfirmationRecord.record_type !== "effect-response" ||
    readyConfirmationRecord.kind !== "artifact-binding-ready" ||
    readyConfirmationRecord.payload.action.artifact_binding_intent_record_oid !==
      readyConfirmationRecord.payload.receipt.ready_reachability_boundary
        .artifact_binding_intent_record_oid ||
    readyConfirmationRecord.payload.action.candidate_set_digest !==
      action.candidate_set_digest ||
    readyConfirmationRecord.payload.action.candidate_authority_digest !==
      authority.authority_digest ||
    readyConfirmationRecord.payload.action.generation_id !==
      action.generation_id
  ) {
    throw new Error(
      "aggregate artifact binding response lacks its ready confirmation",
    );
  }
  const reachabilityBoundary =
    validateAutomaticRecoveryArtifactReadyReachabilityBoundary(
      readyConfirmationRecord.payload.receipt.ready_reachability_boundary,
    );
  if (!Array.isArray(artifactHandles) ||
      artifactHandles.length !== authority.candidates.length) {
    throw new Error("aggregate artifact binding point-read count differs from its intent");
  }
  const bindings = artifactHandles.map((artifactHandle, index) => {
    const candidate = authority.candidates[index];
    validateAutomaticRecoveryArtifactPointRead(
      artifactHandle,
      authority,
      index,
      { reachability_boundary: reachabilityBoundary },
    );
    const withoutDigest = {
      index,
      count: authority.candidates.length,
      generation_id: action.generation_id,
      request_binding_record_oid: action.request_binding_record_oid,
      request_id: action.request_id,
      request_node_id: action.request_node_id,
      artifact_selector: structuredClone(candidate.selector),
      artifact_node_id: artifactHandle.artifact.node_id,
      artifact_url: artifactHandle.artifact.html_url,
      artifact_type: candidate.artifact_type,
      artifact_created_at: candidate.artifact_created_at,
      server_time: artifactHandle.response_server_time,
      raw_body_sha256: artifactHandle.raw_body_sha256,
      actor: structuredClone(artifactHandle.artifact.author),
      app: structuredClone(artifactHandle.artifact.app),
    };
    return {
      ...withoutDigest,
      receipt_digest: digestCanonical(
        "codex-review-gate-v2-artifact-binding-receipt",
        withoutDigest,
      ),
    };
  });
  const receipt = {
    http_status: 200,
    candidate_set_digest: action.candidate_set_digest,
    artifact_binding_ready_confirmation_record_oid: sha(
      readyConfirmationRecordOid,
      "automatic artifact binding ready confirmation record OID",
    ),
    artifact_binding_ready_confirmation_payload_digest:
      readyConfirmationRecord.payload_digest,
    continuation_scheduler_observation_record_oid: sha(
      continuationSchedulerObservationRecordOid,
      "automatic artifact binding continuation scheduler observation OID",
    ),
    continuation_full_scope_receipt_digest: digest(
      continuationFullScopeReceiptDigest,
      "automatic artifact binding continuation full scope receipt digest",
    ),
    continuation_lease_acquire_commit_sha: sha(
      continuationLeaseAcquireCommitSha,
      "automatic artifact binding continuation lease acquire OID",
    ),
    binding_count: bindings.length,
    bindings,
    bindings_digest: digestCanonical(
      "codex-review-gate-v2-aggregate-artifact-binding-receipts",
      bindings,
    ),
  };
  if (Buffer.byteLength(canonicalJson(receipt), "utf8") >
      MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_RECEIPT_BYTES) {
    throw ledgerError(
      "automatic-artifact-binding-receipt-size",
      "aggregate artifact binding receipt exceeds its hard byte cap",
    );
  }
  return deepFreeze(receipt);
}

function validateAutomaticRecoveryArtifactBindingReceiptItem(value, {
  action,
  authority,
  index,
}) {
  const label = `artifact-binding receipt.bindings[${index}]`;
  assertObject(value, label);
  exactKeys(value, [
    "index", "count", "generation_id", "request_binding_record_oid",
    "request_id", "request_node_id", "artifact_selector",
    "artifact_node_id", "artifact_url", "artifact_type",
    "artifact_created_at", "server_time", "raw_body_sha256", "actor", "app",
    "receipt_digest",
  ], label);
  const candidate = authority.candidates[index];
  if (
    candidate === undefined ||
    value.index !== index ||
    value.count !== authority.candidates.length ||
    value.generation_id !== action.generation_id ||
    value.request_binding_record_oid !== action.request_binding_record_oid ||
    value.request_id !== action.request_id ||
    value.request_node_id !== action.request_node_id ||
    canonicalJson(value.artifact_selector) !==
      canonicalJson(candidate.selector) ||
    value.artifact_node_id !== candidate.artifact_node_id ||
    value.artifact_url !== candidate.artifact_url ||
    value.artifact_type !== candidate.artifact_type ||
    value.artifact_created_at !== candidate.artifact_created_at ||
    value.raw_body_sha256 !== candidate.evidence_raw_body_sha256 ||
    Date.parse(value.server_time) <
      Date.parse(candidate.evidence_response_server_time) ||
    canonicalJson(value.actor) !== canonicalJson(authority.expected_actor) ||
    canonicalJson(value.app) !== canonicalJson(authority.expected_app)
  ) {
    throw new Error(`${label} differs from its exact candidate authority`);
  }
  nonnegativeInteger(value.index, `${label}.index`);
  integerBetween(
    value.count,
    1,
    MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATES,
    `${label}.count`,
  );
  sha(value.request_binding_record_oid, `${label}.request_binding_record_oid`);
  decimal(value.request_id, `${label}.request_id`);
  boundedString(value.request_node_id, `${label}.request_node_id`, 256);
  normalizeCarrierSelector(value.artifact_selector,
    `${label}.artifact_selector`);
  boundedString(value.artifact_node_id, `${label}.artifact_node_id`, 256);
  requireExactArtifactUrl(
    value.artifact_url,
    authority.scope.repository,
    authority.scope.pull_request,
    value.artifact_selector,
  );
  timestamp(value.artifact_created_at, `${label}.artifact_created_at`);
  timestamp(value.server_time, `${label}.server_time`);
  digest(value.raw_body_sha256, `${label}.raw_body_sha256`);
  validateExternalActor(value.actor, `${label}.actor`);
  validateExternalApp(value.app, `${label}.app`);
  validateCodexProvider(value.actor, value.app, `${label}.provider`);
  digest(value.receipt_digest, `${label}.receipt_digest`);
  const { receipt_digest: receiptDigest, ...withoutDigest } = value;
  if (receiptDigest !== digestCanonical(
    "codex-review-gate-v2-artifact-binding-receipt",
    withoutDigest,
  )) {
    throw new Error(`${label} digest is invalid`);
  }
  return value;
}

function automaticRecoveryArtifactBindingResponseResult(entry) {
  if (
    entry?.envelope.record_type !== "effect-response" ||
    entry.envelope.kind !== "artifact-binding"
  ) {
    throw ledgerError(
      "automatic-artifact-binding-response-missing",
      "artifact binding response result lacks one reachable response",
    );
  }
  const receipt = entry.envelope.payload.receipt;
  return deepFreeze({
    schema:
      "codex-review-gate-git-ledger-automatic-recovery-artifact-binding-response-v2",
    schema_version: 1,
    response_append_receipt: recoveredAppendReceipt(
      entry,
      "automatic-recovery-artifact-binding-response",
    ),
    bindings: receipt.bindings.map((binding) => ({
      generation_id: binding.generation_id,
      request_id: binding.request_id,
      artifact_selector: structuredClone(binding.artifact_selector),
      record_oid: entry.commit_sha,
      receipt_digest: binding.receipt_digest,
    })),
  });
}

function validateAutomaticRecoveryArtifactBindingEnvelopeSize(record, phase) {
  const actionBytes = Buffer.byteLength(
    canonicalJson(record.payload.action),
    "utf8",
  );
  if (actionBytes >
      MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_ACTION_BYTES) {
    throw ledgerError(
      "automatic-artifact-binding-action-size",
      `aggregate artifact binding ${phase} action exceeds its hard byte cap`,
    );
  }
  if (record.record_type === "effect-response") {
    const receiptBytes = Buffer.byteLength(
      canonicalJson(record.payload.receipt),
      "utf8",
    );
    if (receiptBytes >
        MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_RECEIPT_BYTES) {
      throw ledgerError(
        "automatic-artifact-binding-receipt-size",
        "aggregate artifact binding response receipt exceeds its hard byte cap",
      );
    }
  }
  if (Buffer.byteLength(`${canonicalJson(record)}\n`, "utf8") >
      MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError(
      "automatic-artifact-binding-record-size",
      `aggregate artifact binding ${phase} record exceeds the Git ledger blob cap`,
    );
  }
}

function validateCurrentAutomaticRecoveryArtifactBindingIntent({
  loaded,
  private_intent: privateIntent,
}) {
  validateCurrentSchedulerAppendAuthority({
    loaded,
    scheduler_append: privateIntent.scheduler_append,
    scheduler_authority: privateIntent.scheduler_authority,
    evaluated_scope_receipt: privateIntent.evaluated_scope_receipt,
  });
  const intent = loaded.records.find((entry) =>
    entry.commit_sha === privateIntent.intent_append_receipt.commit_sha);
  const ready = loaded.records.find((entry) =>
    entry.commit_sha === privateIntent.ready_append_receipt.commit_sha);
  const readyConfirmation = loaded.records.find((entry) =>
    entry.commit_sha ===
      privateIntent.ready_confirmation_append_receipt.commit_sha);
  const currentIncarnation = new Set(currentScopeIncarnationRecords(
    loaded.records,
    privateIntent.scope,
  ));
  const activeLease = loaded.active_lease;
  if (
    !currentIncarnation.has(intent) ||
    !currentIncarnation.has(ready) ||
    !currentIncarnation.has(readyConfirmation) ||
    intent?.envelope.record_type !== "effect-intent" ||
    intent.envelope.kind !== "artifact-binding" ||
    canonicalJson(intent.envelope.payload.action) !==
      canonicalJson(privateIntent.intent_record.payload.action) ||
    ready?.envelope.record_type !== "effect-intent" ||
    ready.envelope.kind !== "artifact-binding-ready" ||
    canonicalJson(ready.envelope.payload.action) !==
      canonicalJson(privateIntent.ready_record.payload.action) ||
    ready.envelope.payload.action.artifact_binding_intent_record_oid !==
      privateIntent.intent_append_receipt.commit_sha ||
    readyConfirmation?.envelope.record_type !== "effect-response" ||
    readyConfirmation.envelope.kind !== "artifact-binding-ready" ||
    canonicalJson(readyConfirmation.envelope.payload) !==
      canonicalJson(privateIntent.ready_confirmation_record.payload) ||
    readyConfirmation.envelope.payload.intent_commit_sha !==
      privateIntent.ready_append_receipt.commit_sha ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      privateIntent.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(privateIntent.scope)
  ) {
    throw ledgerError(
      "stale-automatic-artifact-binding-intent-authority",
      "artifact binding response requires one reachable intent and active lease",
    );
  }
  validateFullDiscoveryScopeLineage(
    activeLease.evaluated_scope_receipt,
    privateIntent.evaluated_scope_receipt,
    activeLease,
  );
}

function validateAutomaticRecoveryFindingBindings(
  priorRecords,
  authorityValue,
) {
  const authority = validateAutomaticRequestRecoveryAuthority(authorityValue);
  for (const closure of authority.closure_records) {
    const bindings = priorRecords.flatMap((entry) => {
      const envelope = entry.envelope;
      if (
        envelope.record_type !== "effect-response" ||
        envelope.kind !== "artifact-binding"
      ) {
        return [];
      }
      const receipt = envelope.payload.receipt;
      if (envelope.payload.generation.generation_id !==
          authority.prior_generation_id ||
          envelope.payload.action.request_binding_record_oid !==
            authority.prior_request_binding_record_oid) {
        return [];
      }
      return receipt.bindings.filter((binding) =>
        binding.request_binding_record_oid ===
          authority.prior_request_binding_record_oid &&
        binding.request_id === authority.prior_request_id &&
        binding.artifact_selector.id === closure.finding_artifact_id &&
        binding.artifact_created_at === closure.finding_server_time);
    });
    if (bindings.length !== 1) {
      throw ledgerError(
        "automatic-recovery-finding-binding-mismatch",
        "automatic recovery finding lacks one exact reachable provider artifact binding",
      );
    }
  }
}

function validateAutomaticRecoveryArtifactBindingQueueComplete(
  priorRecords,
  authorityValue,
  scope,
) {
  const authority = validateAutomaticRequestRecoveryAuthority(authorityValue);
  const incarnationRecords = currentScopeIncarnationRecords(
    priorRecords,
    scope,
  );
  const incomplete = incarnationRecords.some((entry) => {
    const envelope = entry.envelope;
    return envelope.record_type === "effect-intent" &&
      envelope.kind === "artifact-binding" &&
      envelope.payload.generation.generation_id ===
        authority.prior_generation_id &&
      envelope.payload.action.request_binding_record_oid ===
        authority.prior_request_binding_record_oid &&
      !incarnationRecords.some((candidate) =>
        candidate.envelope.record_type === "effect-response" &&
        candidate.envelope.kind === "artifact-binding" &&
        candidate.envelope.effect_id === envelope.effect_id);
  });
  if (incomplete) {
    throw ledgerError(
      "automatic-recovery-artifact-binding-incomplete",
      "automatic recovery cannot advance while one durable artifact candidate queue remains incomplete",
    );
  }
}

function validateSchedulerStateLineage(priorRecords, value, repositoryValue) {
  const repository = normalizeRepository(repositoryValue);
  const action = value.payload.action;
  const scope = recordOrEnvelopeScope(value);
  const intentAuthority = validateAutomaticRequestRecoveryAuthority(
    action.recovery_authority,
    { boundary: value.server_observed_at },
  );
  const observation = priorRecords.find((entry) =>
    entry.commit_sha === action.scheduler_observation_record_oid);
  validateAutomaticRecoveryAgainstObservation({
    authority: intentAuthority,
    observation_entry: observation,
    scope,
    repository,
    full_scope_receipt_digest: action.full_scope_receipt_digest,
  });
  validateAutomaticRecoveryArtifactBindingQueueComplete(
    priorRecords,
    intentAuthority,
    scope,
  );
  validateAutomaticRecoveryFindingBindings(
    priorRecords.slice(0, priorRecords.indexOf(observation)),
    intentAuthority,
  );
  validateRequiredStatusBindingsForObservation(
    priorRecords,
    action.scheduler_observation_record_oid,
  );
  const binding = priorRecords.find((entry) =>
    entry.commit_sha === action.prior_request_binding_record_oid);
  if (
    binding?.envelope.record_type !== "effect-response" ||
    binding.envelope.kind !== "request-binding" ||
    binding.envelope.payload.receipt.request_id !==
      intentAuthority.prior_request_id ||
    digestCanonical(
      "codex-review-gate-v2-request-binding-receipt",
      binding.envelope.payload.receipt,
    ) !== intentAuthority.prior_request_binding_receipt_digest
  ) {
    throw ledgerError(
      "automatic-recovery-request-binding-mismatch",
      "automatic recovery lacks its exact reachable controlled request binding",
    );
  }
  const reservations = automaticReservationRecords(priorRecords, scope);
  const priorReservations = reservations.filter((entry) =>
    entry.envelope.payload.generation.generation_id ===
      intentAuthority.prior_generation_id);
  const nextReservations = reservations.filter((entry) =>
    entry.envelope.payload.generation.generation_id ===
      intentAuthority.next_generation_id);
  if (priorReservations.length !== 1 || nextReservations.length !== 0) {
    throw ledgerError(
      "automatic-recovery-reservation-lineage-mismatch",
      "automatic recovery requires one prior generation and no next reservation",
    );
  }
  const sameTransitionIntents = priorRecords.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "scheduler-state" &&
    entry.envelope.payload.action.recovery_transition_digest ===
      action.recovery_transition_digest);
  if (value.record_type === "effect-intent") {
    if (sameTransitionIntents.length !== 0) {
      throw ledgerError(
        "automatic-recovery-transition-replayed",
        "automatic recovery transition already has a durable intent",
      );
    }
    const completedForNextGeneration = priorRecords.some((entry) =>
      entry.envelope.record_type === "effect-response" &&
      entry.envelope.kind === "scheduler-state" &&
      entry.envelope.payload.receipt.next_generation_id ===
        intentAuthority.next_generation_id &&
      sameHeadScope(entry.envelope, scope));
    if (completedForNextGeneration) {
      throw ledgerError(
        "automatic-recovery-generation-replayed",
        "automatic recovery already made the next generation available",
      );
    }
    return;
  }
  const receipt = value.payload.receipt;
  const completionAuthority = validateAutomaticRequestRecoveryAuthority(
    receipt.completion_recovery_authority,
    { boundary: value.server_observed_at },
  );
  validateAutomaticRecoveryCompletionExtension({
    intent_authority: intentAuthority,
    completion_authority: completionAuthority,
  });
  const completionObservation = priorRecords.find((entry) =>
    entry.commit_sha ===
      receipt.completion_scheduler_observation_record_oid);
  validateAutomaticRecoveryAgainstObservation({
    authority: completionAuthority,
    observation_entry: completionObservation,
    scope,
    repository,
    full_scope_receipt_digest:
      receipt.completion_full_scope_receipt_digest,
  });
  validateAutomaticRecoveryFindingBindings(
    priorRecords.slice(0, priorRecords.indexOf(completionObservation)),
    completionAuthority,
  );
  validateRequiredStatusBindingsForObservation(
    priorRecords,
    receipt.completion_scheduler_observation_record_oid,
  );
  if (
    automaticRequestRecoveryTransitionDigest(completionAuthority) !==
      action.recovery_transition_digest
  ) {
    throw ledgerError(
      "automatic-recovery-completion-drift",
      "automatic recovery completion changes the durable transition authority",
    );
  }
}

function validateSchedulerObservationLineage(priorRecords, value) {
  const action = value.payload.action;
  const scope = recordOrEnvelopeScope(value);
  const repository = value.repository ?? priorRecords[0]?.envelope.repository;
  if (repository === undefined) {
    throw ledgerError(
      "scheduler-repository-authority-missing",
      "scheduler observation lacks its reachable repository authority",
    );
  }
  if (
    action.prior_authority_digest !==
      runnerPriorAuthorityDigest(priorRecords, scope)
  ) {
    throw ledgerError(
      "scheduler-prior-authority-mismatch",
      "scheduler observation does not bind the exact reachable predecessor authority",
    );
  }
  const claims = value.workflow_provenance?.claims;
  const leaseOwner = value.lease?.owner;
  if (
    leaseOwner === undefined ||
    action.prior_scheduling.run_identity.run_id !== leaseOwner.run_id ||
    action.prior_scheduling.run_identity.run_attempt !==
      leaseOwner.run_attempt ||
    action.scheduler_evaluation.run_id !== leaseOwner.run_id ||
    action.scheduler_evaluation.run_attempt !== leaseOwner.run_attempt
  ) {
    throw ledgerError(
      "scheduler-run-identity-mismatch",
      "scheduler observation run identity differs from its protected lease owner",
    );
  }
  if (
    claims !== undefined &&
    (action.prior_scheduling.run_identity.run_id !== claims.run_id ||
      action.prior_scheduling.run_identity.run_attempt !==
        Number(claims.run_attempt) ||
      action.scheduler_evaluation.run_id !== claims.run_id ||
      action.scheduler_evaluation.run_attempt !== Number(claims.run_attempt))
  ) {
    throw ledgerError(
      "scheduler-run-identity-mismatch",
      "scheduler observation run identity differs from its signed OIDC claims",
    );
  }
  const priorHead = deriveRunnerHeadLedger(
    priorRecords,
    scope,
    repository,
    action.prior_head_ledger.observed_at,
  );
  if (canonicalJson(priorHead) !== canonicalJson(action.prior_head_ledger)) {
    throw ledgerError(
      "scheduler-head-ledger-mismatch",
      "scheduler observation head ledger differs from reachable intent authority",
    );
  }
  const observations = schedulerObservationRecords(priorRecords, scope);
  const headObservations = headSchedulerObservationRecords(priorRecords, scope);
  if (action.prior_scheduling.wait_completions.length !== 0) {
    throw ledgerError(
      "public-wait-completion-producer-unavailable",
      "scheduler observation cannot introduce public wait completion authority without a trusted producer",
    );
  }
  if (observations.some((entry) =>
    entry.envelope.payload.action.scheduler_evaluation.snapshot_id ===
      action.scheduler_evaluation.snapshot_id)) {
    throw ledgerError(
      "scheduler-snapshot-replay",
      "scheduler observation repeats one protected snapshot identity",
    );
  }
  if (headObservations.length === 0) {
    if (action.initial_runner_state_authority === null) {
      throw ledgerError(
        "initial-runner-authority-required",
        "first scheduler observation lacks its protected initial authority",
      );
    }
    validateInitialRunnerStateHistoricalAuthority({
      prior_records: priorRecords,
      record_or_envelope: value,
      repository,
      authority: action.initial_runner_state_authority,
    });
    if (
      action.prior_scheduling.complete_snapshots.length !== 0 ||
      action.prior_scheduling.applied_action_keys.length !== 0 ||
      action.prior_scheduling.wait_completions.length !== 0 ||
      action.prior_scheduling.status.exact_sha_context_count !== 0 ||
      action.prior_scheduling.status.latest_idempotency_key !== null ||
      action.prior_scheduling.status.head_sentinel_receipt !== null ||
      action.prior_scheduling.epoch.controlled_request !== null ||
      action.prior_scheduling.epoch.automatic_request.state !== "available" ||
      action.prior_scheduling.epoch.id !== runnerEpochId(
        repository.node_id,
        value.pull_request.node_id,
        value.head_ref_oid,
      )
    ) {
      throw ledgerError(
        "scheduler-genesis-state-mismatch",
        "first scheduler observation does not start from an empty review epoch",
      );
    }
  } else {
    if (action.initial_runner_state_authority !== null) {
      throw ledgerError(
        "initial-runner-authority-replayed",
        "later scheduler observation repeats initial authority",
      );
    }
    const expected = deriveRunnerScheduling(
      priorRecords,
      scope,
      repository,
      action.prior_scheduling,
    );
    if (canonicalJson(expected) !== canonicalJson(action.prior_scheduling)) {
      throw ledgerError(
        "scheduler-prior-state-mismatch",
        "scheduler observation prior state differs from reachable authority",
      );
    }
  }
  validateNoStartHistory([
    ...observations.map((entry) => entry.envelope.payload.action.scheduler_evaluation),
    action.scheduler_evaluation,
  ]);
}

function validateInitialRunnerStateHistoricalAuthority({
  prior_records: priorRecords,
  record_or_envelope: value,
  repository,
  authority: authorityValue,
}) {
  const authority = validateV2GitLedgerInitialRunnerStateAuthority(
    authorityValue,
  );
  const scope = recordOrEnvelopeScope(value);
  const action = value.payload.action;
  const source = authority.source_authority;
  const lease = authority.lease_authority;
  const evaluated = authority.evaluated_scope_authority;
  const command = authority.workflow_command_authority.command;
  const preflight = authority.preflight_authority;
  const tip = priorRecords.at(-1);
  if (
    canonicalJson(authority.scope) !== canonicalJson(scope) ||
    tip?.commit_sha !== source.tip_commit_sha ||
    value.predecessor_commit_sha !== source.tip_commit_sha ||
    action.prior_authority_digest !== authority.prior_authority_digest ||
    canonicalJson(action.prior_scheduling) !==
      canonicalJson(authority.scheduling) ||
    canonicalJson(action.prior_head_ledger) !==
      canonicalJson(authority.head_ledger) ||
    canonicalJson(value.lease?.owner) !== canonicalJson(lease.owner)
  ) {
    throw ledgerError(
      "initial-runner-authority-lineage-mismatch",
      "initial runner authority differs from its scheduler predecessor",
    );
  }
  if (
    runnerPriorAuthorityDigest(priorRecords, scope) !==
      authority.prior_authority_digest ||
    hasPriorRunnerEffects(priorRecords, scope)
  ) {
    throw ledgerError(
      "initial-runner-prior-history-mismatch",
      "initial runner authority does not bind a predecessor without prior runner effects",
    );
  }
  if (
    source.fully_reachable_record_manifest_digest !==
      fullyReachableRecordManifestDigest(priorRecords)
  ) {
    throw ledgerError(
      "initial-runner-source-manifest-mismatch",
      "initial runner manifest differs from reachable history",
    );
  }
  const acquire = priorRecords.find((entry) =>
    entry.commit_sha === lease.acquire_commit_sha);
  const acquireEvaluated = acquire?.envelope.workflow_provenance
    ?.operation_binding?.evaluated_scope_receipt;
  if (
    acquire?.envelope.record_type !== "lease-acquire" ||
    acquire.envelope.payload.lease_id !== lease.lease_id ||
    acquire.envelope.payload.acquired_at !== lease.acquired_at ||
    acquire.envelope.payload.expires_at !== lease.expires_at ||
    canonicalJson(acquire.envelope.payload.owner) !== canonicalJson(lease.owner) ||
    acquireEvaluated?.receipt_digest !==
      lease.evaluated_scope_receipt_digest ||
    acquireEvaluated?.receipt_digest !==
      evaluated.lease_evaluated_scope_receipt_digest
  ) {
    throw ledgerError(
      "initial-runner-lease-authority-mismatch",
      "initial runner lease differs from its reachable acquire",
    );
  }
  const recordEvaluated = value.workflow_provenance?.operation_binding
    ?.evaluated_scope_receipt ?? null;
  if (
    recordEvaluated !== null &&
    (
      recordEvaluated.receipt_digest !==
        evaluated.record_evaluated_scope_receipt_digest ||
      canonicalJson(recordEvaluated.scope) !== canonicalJson(scope) ||
      recordEvaluated.relation !== evaluated.relation
    )
  ) {
    throw ledgerError(
      "initial-runner-evaluated-scope-mismatch",
      "initial runner record differs from its stored evaluated scope",
    );
  }
  if (evaluated.relation === "provider-selector") {
    if (
      acquireEvaluated.provider_artifact_receipt.phase !== "pre-scope" ||
      evaluated.provider_pre_scope_receipt_digest !==
        acquireEvaluated.receipt_digest ||
      recordEvaluated !== null &&
        recordEvaluated.provider_artifact_receipt.pre_scope_receipt_digest !==
          acquireEvaluated.receipt_digest
    ) {
      throw ledgerError(
        "initial-runner-provider-lineage-mismatch",
        "initial runner provider authority reverses pre/full discovery lineage",
      );
    }
  }
  if (recordEvaluated !== null) {
    validateFullDiscoveryScopeLineage(acquireEvaluated, recordEvaluated, lease);
    if (
      canonicalJson(evaluated.discovery_continuity_receipt) !==
        canonicalJson(recordEvaluated.discovery_continuity_receipt)
    ) {
      throw ledgerError(
        "initial-runner-continuity-mismatch",
        "initial runner action omits its full discovery continuity receipt",
      );
    }
  }
  validateInitialCommandScope(command, repository, recordEvaluated ?? acquireEvaluated);
  if (
    command.invocation.run_id !== lease.owner.run_id ||
    command.invocation.run_attempt !== lease.owner.run_attempt ||
    command.invocation.actor_id !== lease.owner.actor_id ||
    authority.scheduling.public_wait_supported !==
      preflight.public_wait_supported ||
    authority.scheduling.epoch.started_at !== lease.acquired_at
  ) {
    throw ledgerError(
      "initial-runner-command-authority-mismatch",
      "initial runner command/preflight projection differs from its lease",
    );
  }
  const claims = value.workflow_provenance?.claims;
  if (
    claims !== undefined &&
    (
      claims.run_id !== command.invocation.run_id ||
      Number(claims.run_attempt) !== command.invocation.run_attempt ||
      claims.event_name !== command.invocation.event_name
    )
  ) {
    throw ledgerError(
      "initial-runner-command-oidc-mismatch",
      "initial runner command differs from reverified record OIDC claims",
    );
  }
  const attestation = priorRecords.find((entry) =>
    entry.commit_sha === source.capability_attestation_commit_sha);
  const embeddedCapability = attestation?.envelope.payload.capability_receipt;
  if (
    attestation?.envelope.record_type !== "capability-attestation" ||
    attestation.envelope.payload.capability_input_digest !==
      source.capability_input_digest ||
    embeddedCapability === undefined ||
    digestCanonical(
      "codex-review-gate-v2-controller-release",
      embeddedCapability.controller_release,
    ) !== source.controller_release_digest
  ) {
    throw ledgerError(
      "initial-runner-capability-authority-mismatch",
      "initial runner authority differs from its reachable capability epoch",
    );
  }
}

function fullyReachableRecordManifestDigest(records) {
  const manifest = records.map((entry) => ({
    record_oid: entry.commit_sha,
    parent_oid: entry.parents[0] ?? null,
    tree_oid: entry.tree_sha,
    envelope_digest: entry.envelope.envelope_digest,
    record_type: entry.envelope.record_type,
    kind: entry.envelope.kind,
    effect_id: entry.envelope.effect_id,
    idempotency_key: entry.envelope.idempotency_key,
    payload_digest: entry.envelope.payload_digest,
    workflow_provenance_receipt_digest:
      entry.envelope.workflow_provenance.receipt_digest,
    workflow_provenance_jti:
      provenanceReplayIdentity(entry.envelope.workflow_provenance),
    server_observed_at: entry.envelope.server_observed_at,
  }));
  return digestCanonical(
    "codex-review-gate-v2-fully-reachable-record-manifest",
    manifest,
  );
}

function runnerPriorAuthorityDigest(records, scope) {
  const rows = records.map((entry) => ({
    record_oid: entry.commit_sha,
    parent_oids: structuredClone(entry.parents),
    tree_oid: entry.tree_sha,
    blob_oid: entry.blob_sha,
    envelope_digest: entry.envelope.envelope_digest,
  }));
  return digestCanonical(
    "codex-review-gate-v2-runner-prior-authority",
    { scope, records: rows },
  );
}

function schedulerObservationRecords(records, scope) {
  return currentScopeIncarnationRecords(records, scope).filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "scheduler-observation");
}

function headSchedulerObservationRecords(records, scope) {
  return records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "scheduler-observation" &&
    sameHeadScope(entry.envelope, scope));
}

function hasPriorRunnerEffects(records, scope) {
  return records.some((entry) =>
    new Set(["effect-intent", "effect-response"])
      .has(entry.envelope.record_type) &&
    sameHeadScope(entry.envelope, scope) &&
    !new Set(["control-comment-create", "control-comment-update"])
      .has(entry.envelope.kind));
}

function currentScopeIncarnationRecords(records, scope) {
  let lastForeignScopeIndex = -1;
  for (const [index, entry] of records.entries()) {
    if (
      sameHeadScope(entry.envelope, scope) &&
      !sameExactScope(entry.envelope, scope)
    ) {
      lastForeignScopeIndex = index;
    }
  }
  return records.slice(lastForeignScopeIndex + 1).filter((entry) =>
    sameExactScope(entry.envelope, scope));
}

function currentScopeIncarnationAnchorRecordOid(records, scope) {
  let anchorRecordOid = null;
  for (const entry of records) {
    if (
      sameHeadScope(entry.envelope, scope) &&
      !sameExactScope(entry.envelope, scope)
    ) {
      anchorRecordOid = entry.commit_sha;
    }
  }
  return anchorRecordOid;
}

function automaticRecoveryArtifactBindingEffectIdentity({
  candidate_set_digest: candidateSetDigestValue,
  incarnation_anchor_record_oid: incarnationAnchorRecordOidValue,
}) {
  const candidateSetDigest = digest(
    candidateSetDigestValue,
    "automatic artifact binding candidate set digest",
  );
  if (incarnationAnchorRecordOidValue === null) {
    return candidateSetDigest.slice("sha256:".length);
  }
  const incarnationAnchorRecordOid = sha(
    incarnationAnchorRecordOidValue,
    "automatic artifact binding incarnation anchor record OID",
  );
  return digestCanonical(
    "codex-review-gate-v2-automatic-artifact-binding-incarnation-identity",
    {
      candidate_set_digest: candidateSetDigest,
      incarnation_anchor_record_oid: incarnationAnchorRecordOid,
    },
  ).slice("sha256:".length);
}

function currentScopeControlCommentBinding(records, scope) {
  let binding = null;
  for (const entry of currentScopeIncarnationRecords(records, scope)) {
    const envelope = entry.envelope;
    if (
      envelope.record_type === "effect-response" &&
      new Set(["control-comment-create", "control-comment-update"])
        .has(envelope.kind)
    ) {
      binding = structuredClone(envelope.control_comment_binding);
    }
  }
  return binding;
}

function deriveRunnerScheduling(records, scope, repository, currentInput) {
  const observations = schedulerObservationRecords(records, scope);
  const headObservations = headSchedulerObservationRecords(records, scope);
  if (headObservations.length === 0) {
    throw ledgerError(
      "scheduler-observation-required",
      "runner scheduling cannot be derived without a protected observation",
    );
  }
  const first = headObservations[0].envelope.payload.action.prior_scheduling;
  const completeSnapshots = [];
  const snapshotIds = new Set();
  for (const observation of observations) {
    const snapshot = observation.envelope.payload.action.scheduler_evaluation;
    if (snapshot.complete === true && !snapshotIds.has(snapshot.snapshot_id)) {
      completeSnapshots.push(structuredClone(snapshot));
      snapshotIds.add(snapshot.snapshot_id);
    }
  }
  const automaticRequest = deriveRunnerAutomaticRequest(records, scope);
  const controlledRequest = deriveRunnerControlledRequest(records, scope);
  const head = deriveRunnerHeadLedger(
    records,
    scope,
    repository,
    currentInput.status.head_sentinel_receipt?.observed_at ??
      records.at(-1).envelope.server_observed_at,
  );
  const status = deriveRunnerSchedulingStatus(records, scope);
  for (const observation of observations) {
    if (
      observation.envelope.payload.action.prior_scheduling
        .wait_completions.length !== 0
    ) {
      throw ledgerError(
        "public-wait-completion-producer-unavailable",
        "runner scheduling history contains public wait completion authority without a trusted producer",
      );
    }
  }
  return {
    trigger: currentInput.trigger,
    public_wait_supported: first.public_wait_supported,
    status_target_mode: first.status_target_mode,
    run_identity: structuredClone(currentInput.run_identity),
    epoch: {
      id: first.epoch.id,
      started_at: first.epoch.started_at,
      controlled_request: controlledRequest,
      automatic_request: automaticRequest,
    },
    complete_snapshots: completeSnapshots,
    status: {
      exact_sha_context_count: head.exact_sha_context_count,
      latest_idempotency_key: head.latest_status_idempotency_key,
      head_sentinel_receipt: status.head_sentinel_receipt,
    },
    applied_action_keys: deriveAppliedSchedulerActionKeys(records, scope),
    no_start_candidate: observations.length === 0
      ? null
      : structuredClone(currentInput.no_start_candidate),
    // Pre-activation production has no trusted completion producer. Derivation
    // is therefore closed over reachable observations and cannot echo caller
    // input into durable authority.
    wait_completions: [],
  };
}

function deriveRunnerAutomaticRequest(records, scope) {
  const reservations = automaticReservationRecords(records, scope);
  const recoveryTransitions = records.filter((entry) =>
    entry.envelope.record_type === "effect-response" &&
    entry.envelope.kind === "scheduler-state" &&
    sameHeadScope(entry.envelope, scope));
  if (reservations.length === 0) {
    if (recoveryTransitions.length !== 0) {
      throw ledgerError(
        "automatic-recovery-prior-generation-required",
        "automatic recovery cannot precede its first controlled generation",
      );
    }
    return {
      state: "available",
      generation_index: 1,
      recovery_authority: null,
      intent_id: null,
      intent_persisted_at: null,
      effect_attempted_at: null,
    };
  }
  const reservation = reservations.at(-1);
  const reservationValue = reservation.envelope.payload.action.reservation;
  const latestRecovery = recoveryTransitions.at(-1) ?? null;
  if (latestRecovery !== null) {
    const recovery = validateAutomaticRequestRecoveryAuthority(
      latestRecovery.envelope.payload.receipt.completion_recovery_authority,
    );
    if (recovery.next_generation_index > reservationValue.generation_index) {
      if (
        recovery.prior_generation_index !== reservationValue.generation_index ||
        recovery.next_generation_index !== reservationValue.generation_index + 1
      ) {
        throw ledgerError(
          "automatic-recovery-generation-gap",
          "automatic recovery does not advance the latest generation exactly once",
        );
      }
      return {
        state: "available",
        generation_index: recovery.next_generation_index,
        recovery_authority: {
          prior_generation_id: recovery.prior_generation_id,
          finding_ids: structuredClone(recovery.finding_ids),
          closure_ids: structuredClone(recovery.closure_ids),
          closure_observed_at: recovery.closure_observed_at,
        },
        intent_id: null,
        intent_persisted_at: null,
        effect_attempted_at: null,
      };
    }
  }
  const attempt = records.find((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "effect-attempt" &&
    entry.envelope.payload.action.reservation_record_oid ===
      reservation.commit_sha);
  return {
    state: attempt === undefined ? "intent-persisted" : "effect-attempted",
    generation_index: reservationValue.generation_index,
    recovery_authority: structuredClone(
      reservationValue.recovery_authority,
    ),
    intent_id: reservationValue.scheduler_intent_id,
    intent_persisted_at: reservation.envelope.server_observed_at,
    effect_attempted_at: attempt === undefined
      ? null
      : attempt.envelope.server_observed_at,
  };
}

function deriveRunnerControlledRequest(records, scope) {
  const bindings = records.filter((entry) =>
    entry.envelope.record_type === "effect-response" &&
    entry.envelope.kind === "request-binding" &&
    sameHeadScope(entry.envelope, scope));
  if (bindings.length === 0) return null;
  const binding = bindings.at(-1);
  return {
    request_id: binding.envelope.payload.receipt.request_id,
    bound_at: binding.envelope.payload.receipt.created_at,
    binding_record_oid: binding.commit_sha,
    binding_receipt_digest: digestCanonical(
      "codex-review-gate-v2-request-binding-receipt",
      binding.envelope.payload.receipt,
    ),
  };
}

function validateNoStartHistory(snapshots) {
  const earliest = new Map();
  for (const snapshot of snapshots) {
    const candidate = snapshot.no_start_candidate;
    if (candidate === null) continue;
    const key = canonicalJson({
      artifact_id: candidate.artifact_id,
      artifact_digest: candidate.artifact_digest,
      scope_fingerprint: candidate.scope_fingerprint,
      lifecycle_fingerprint: candidate.lifecycle_fingerprint,
    });
    const prior = earliest.get(key);
    if (prior !== undefined && prior !== candidate.first_seen_at) {
      throw ledgerError(
        "no-start-first-seen-drift",
        "no-start candidate resets its durable first-seen authority",
      );
    }
    earliest.set(key, candidate.first_seen_at);
  }
}

function automaticReservationRecords(records, scope) {
  return records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "automatic-request-reservation" &&
    sameHeadScope(entry.envelope, scope));
}

function recoveredAppendReceipt(entry, label) {
  return deepFreeze({
    commit_sha: entry.commit_sha,
    receipt_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-recovered-private-append",
      {
        label,
        commit_sha: entry.commit_sha,
        envelope_digest: entry.envelope.envelope_digest,
      },
    ),
  });
}

function automaticRecoveryTransitionResult({
  loaded,
  scope,
  current_recovery_authority: currentRecoveryAuthorityValue,
  transition_digest: transitionDigest,
}) {
  const currentRecoveryAuthority = validateAutomaticRequestRecoveryAuthority(
    currentRecoveryAuthorityValue,
  );
  const intent = loaded.records.find((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "scheduler-state" &&
    entry.envelope.payload.action.recovery_transition_digest ===
      transitionDigest);
  const response = intent === undefined ? undefined : loaded.records.find(
    (entry) =>
      entry.envelope.record_type === "effect-response" &&
      entry.envelope.kind === "scheduler-state" &&
      entry.envelope.effect_id === intent.envelope.effect_id,
  );
  if (
    intent === undefined || response === undefined
  ) {
    throw ledgerError(
      "automatic-recovery-transition-reread-mismatch",
      "automatic recovery transition is absent from the exact stable reread",
    );
  }
  const intentRecoveryAuthority = validateAutomaticRequestRecoveryAuthority(
    intent.envelope.payload.action.recovery_authority,
  );
  const completionRecoveryAuthority = validateAutomaticRequestRecoveryAuthority(
    response.envelope.payload.receipt.completion_recovery_authority,
  );
  validateAutomaticRecoveryCompletionExtension({
    intent_authority: intentRecoveryAuthority,
    completion_authority: completionRecoveryAuthority,
  });
  validateAutomaticRecoveryCompletionExtension({
    intent_authority: completionRecoveryAuthority,
    completion_authority: currentRecoveryAuthority,
  });
  if (
    response.envelope.payload.receipt.intent_recovery_authority_digest !==
      intentRecoveryAuthority.authority_digest ||
    response.envelope.payload.receipt.completion_recovery_authority_digest !==
      completionRecoveryAuthority.authority_digest
  ) {
    throw ledgerError(
      "automatic-recovery-transition-reread-mismatch",
      "automatic recovery response does not bind both durable proof authorities",
    );
  }
  const runnerState = deriveV2GitLedgerRunnerState(
    loaded.records,
    scope,
    loaded.post_ref.server_time,
  );
  const automaticRequest = runnerState.scheduling.epoch.automatic_request;
  if (
    automaticRequest.state !== "available" ||
    automaticRequest.generation_index !==
      completionRecoveryAuthority.next_generation_index ||
    canonicalJson(automaticRequest.recovery_authority) !== canonicalJson({
      prior_generation_id: completionRecoveryAuthority.prior_generation_id,
      finding_ids: completionRecoveryAuthority.finding_ids,
      closure_ids: completionRecoveryAuthority.closure_ids,
      closure_observed_at: completionRecoveryAuthority.closure_observed_at,
    })
  ) {
    throw ledgerError(
      "automatic-recovery-transition-reread-mismatch",
      "automatic recovery is absent from the exact stable runner authority reread",
    );
  }
  return deepFreeze({
    schema:
      "codex-review-gate-git-ledger-automatic-request-recovery-transition-v2",
    schema_version: 1,
    prior_generation_id: completionRecoveryAuthority.prior_generation_id,
    next_generation_id: completionRecoveryAuthority.next_generation_id,
    recovery_transition_digest: transitionDigest,
    intent_recovery_authority_digest:
      intentRecoveryAuthority.authority_digest,
    completion_recovery_authority_digest:
      completionRecoveryAuthority.authority_digest,
    intent_record_receipt: recoveredAppendReceipt(
      intent,
      "automatic-request-recovery-transition-intent",
    ),
    response_record_receipt: recoveredAppendReceipt(
      response,
      "automatic-request-recovery-transition-response",
    ),
    runner_state_digest: runnerState.runner_state_digest,
  });
}

function recoverAutomaticRequestAttemptAuthority({
  records,
  scope,
  scheduler_append: schedulerAppend,
  scheduler_authority: schedulerAuthority,
  evaluated_scope_receipt: evaluatedScopeReceipt,
}) {
  const observation = validateV2GitLedgerSchedulerObservation(
    schedulerAppend.record.payload.action,
  );
  const persistActions = observation.scheduler_plan.actions.filter(
    (action) => action.kind === "persist_auto_request_intent",
  );
  const postActions = observation.scheduler_plan.actions.filter(
    (action) => action.kind === "post_review_request",
  );
  if (
    observation.prior_scheduling.epoch.automatic_request.state !==
      "intent-persisted" ||
    persistActions.length !== 0 ||
    postActions.length !== 1
  ) {
    throw ledgerError(
      "automatic-recovery-scheduler-state-required",
      "automatic request recovery requires one post-only intent-persisted scheduler observation",
    );
  }
  const postAction = postActions[0];
  const reservations = automaticReservationRecords(records, scope).filter(
    (entry) => {
      const action = entry.envelope.payload.action;
      return action.post_scheduler_action_key === postAction.idempotency_key &&
        action.scheduler_action_key ===
          postAction.depends_on_idempotency_key &&
        action.reservation.scheduler_intent_id === postAction.intent_id;
    },
  );
  if (reservations.length !== 1) {
    throw ledgerError(
      "automatic-recovery-reservation-required",
      "automatic request recovery requires one exact reachable reservation",
    );
  }
  const reservationEntry = reservations[0];
  const reservationAction = reservationEntry.envelope.payload.action;
  const reservationStatusIntents = records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "reservation-status-write" &&
    entry.envelope.payload.action.reservation_record_oid ===
      reservationEntry.commit_sha);
  if (reservationStatusIntents.length !== 1) {
    throw ledgerError(
      "automatic-recovery-reservation-status-required",
      "automatic request recovery requires one exact reservation status intent",
    );
  }
  const statusIntentEntry = reservationStatusIntents[0];
  const statusResponses = records.filter((entry) =>
    entry.envelope.record_type === "effect-response" &&
    entry.envelope.kind === "reservation-status-write" &&
    entry.envelope.effect_id === statusIntentEntry.envelope.effect_id);
  const attempts = records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "effect-attempt" &&
    entry.envelope.payload.action.reservation_record_oid ===
      reservationEntry.commit_sha);
  const reviewRequests = records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "review-request" &&
    entry.envelope.payload.action.reservation_record_oid ===
      reservationEntry.commit_sha);
  if (
    statusResponses.length !== 1 ||
    attempts.length !== 0 ||
    reviewRequests.length !== 0
  ) {
    throw ledgerError(
      "automatic-recovery-attempt-unavailable",
      "automatic request recovery requires one bound status and no prior request attempt",
    );
  }
  const statusResponseEntry = statusResponses[0];
  const reservationAppendReceipt = recoveredAppendReceipt(
    reservationEntry,
    "automatic-request-reservation",
  );
  const statusIntentAppendReceipt = recoveredAppendReceipt(
    statusIntentEntry,
    "reservation-status-write-intent",
  );
  const statusResponseAppendReceipt = recoveredAppendReceipt(
    statusResponseEntry,
    "reservation-status-write-response",
  );
  const automaticReservationHandle = sealAutomaticReservationHandle({
    reservation_record_oid: reservationEntry.commit_sha,
    append_receipt_digest: reservationAppendReceipt.receipt_digest,
    reservation_digest: reservationAction.reservation.reservation_digest,
  });
  const privateReservation = deepFreeze({
    scheduler_append: schedulerAppend,
    evaluated_scope_receipt: evaluatedScopeReceipt,
    lease_authority: schedulerAuthority.lease_authority,
    scope: schedulerAuthority.scope,
    reservation_record: reservationEntry.envelope,
    reservation_append_receipt: reservationAppendReceipt,
    reservation: structuredClone(reservationAction.reservation),
    // A same-head base/potential retarget preserves the consumed reservation
    // as origin history, but every new effect must bind the current exact
    // review incarnation. The stable automatic generation identity links the
    // continuation back to that origin without copying its stale epoch digest.
    generation: automaticEffectGeneration(
      reservationAction.reservation.generation_index,
      schedulerAuthority.scope,
    ),
  });
  const privateStatusIntent = deepFreeze({
    automatic_reservation_handle: automaticReservationHandle,
    evaluated_scope_receipt: evaluatedScopeReceipt,
    lease_authority: schedulerAuthority.lease_authority,
    scope: schedulerAuthority.scope,
    intent_record: statusIntentEntry.envelope,
    intent_append_receipt: statusIntentAppendReceipt,
    transport: null,
  });
  const reservationStatusResponseAppend = deepFreeze({
    schema:
      "codex-review-gate-git-ledger-recovered-reservation-status-response-v2",
    schema_version: 1,
    reservation_record_oid: reservationEntry.commit_sha,
    response_record_oid: statusResponseEntry.commit_sha,
    recovery_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-recovered-reservation-status-response",
      {
        scheduler_observation_record_oid:
          schedulerAuthority.observation_record_oid,
        reservation_record_oid: reservationEntry.commit_sha,
        status_intent_record_oid: statusIntentEntry.commit_sha,
        status_response_record_oid: statusResponseEntry.commit_sha,
      },
    ),
  });
  const privateResponse = deepFreeze({
    automatic_reservation_handle: automaticReservationHandle,
    private_intent: privateStatusIntent,
    response_record: statusResponseEntry.envelope,
    response_append_receipt: statusResponseAppendReceipt,
  });
  return {
    automatic_reservation_handle: automaticReservationHandle,
    private_reservation: privateReservation,
    reservation_status_response_append: reservationStatusResponseAppend,
    private_response: privateResponse,
  };
}

function countAutomaticReservations(records, scope) {
  const reservations = automaticReservationRecords(records, scope);
  if (reservations.length > 3) {
    throw ledgerError(
      "automatic-reservation-cap",
      "reachable automatic reservation intents exceed the head budget",
    );
  }
  return reservations.length;
}

function sameHeadScope(value, scope) {
  return canonicalJson(value.pull_request) === canonicalJson(scope.pull_request) &&
    value.head_ref_oid === scope.head_ref_oid;
}

function sameExactScope(value, scope) {
  return sameHeadScope(value, scope) &&
    value.base_ref_oid === scope.base_ref_oid &&
    value.potential_merge_commit_oid === scope.potential_merge_commit_oid;
}

function sameAutomaticGenerationIdentity(left, right) {
  return left?.kind === "automatic" && right?.kind === "automatic" &&
    left.generation_id === right.generation_id &&
    left.index === right.index;
}

function deriveRunnerHeadLedger(records, scope, repository, observedAtValue) {
  const observedAt = timestamp(observedAtValue, "runner head ledger boundary");
  const automaticRequestCount = countAutomaticReservations(records, scope);
  const statusIntents = requiredStatusIntentRecords(records, scope);
  if (statusIntents.length > 1000) {
    throw ledgerError(
      "status-intent-cap",
      "reachable required status intents exceed the exact SHA context cap",
    );
  }
  const boundAttemptIds = [];
  const bound = new Set();
  for (const entry of records) {
    const envelope = entry.envelope;
    if (
      envelope.record_type !== "effect-response" ||
      envelope.kind !== "request-binding" ||
      !sameHeadScope(envelope, scope)
    ) continue;
    const attemptEntry = records.find((candidate) =>
      candidate.commit_sha === envelope.payload.action.attempt_record_oid);
    const attemptId = attemptEntry?.envelope.payload.action.attempt.attempt_id;
    if (!RUNNER_ATTEMPT_ID.test(attemptId ?? "") || bound.has(attemptId)) {
      throw ledgerError(
        "bound-attempt-conflict",
        "request binding repeats or lacks one protected pre-effect attempt",
      );
    }
    bound.add(attemptId);
    boundAttemptIds.push(attemptId);
  }
  const latestStatus = statusIntents.at(-1)?.envelope.payload.action ?? null;
  return {
    schema: V2_GIT_LEDGER_HEAD_LEDGER_SCHEMA,
    schema_version: 1,
    repository_node_id: repository.node_id,
    pull_request_node_id: scope.pull_request.node_id,
    head_ref_oid: scope.head_ref_oid,
    automatic_request_count: automaticRequestCount,
    exact_sha_context_count: statusIntents.length,
    latest_status_idempotency_key:
      latestStatus?.scheduler_action_key ?? null,
    bound_attempt_ids: boundAttemptIds,
    observed_at: observedAt,
  };
}

function runnerHeadLedgerDigestFromRecords(
  records,
  scope,
  repository,
  observedAt,
) {
  return runnerDigestCanonical(
    "codex-review-gate-v2-head-ledger",
    deriveRunnerHeadLedger(records, scope, repository, observedAt),
  );
}

function requiredStatusIntentRecords(records, scope) {
  return currentScopeIncarnationRecords(records, scope).filter((entry) => {
    const envelope = entry.envelope;
    return envelope.record_type === "effect-intent" &&
      envelope.kind === "status-write" &&
      envelope.payload.action.context === "codex/github-review-gate" &&
      sameExactScope(envelope, scope);
  });
}

function deriveRunnerSchedulingStatus(records, scope) {
  const intents = requiredStatusIntentRecords(records, scope);
  const currentRecords = currentScopeIncarnationRecords(records, scope);
  let headSentinelReceipt = null;
  for (const entry of currentRecords) {
    const envelope = entry.envelope;
    if (
      envelope.record_type !== "effect-response" ||
      envelope.kind !== "status-write" ||
      envelope.payload.action.role !== "head-sentinel" ||
      envelope.payload.action.context !== "codex/github-review-gate" ||
      !sameExactScope(envelope, scope)
    ) continue;
    if (envelope.payload.receipt.state === "success") {
      throw ledgerError(
        "sentinel-success-forbidden",
        "reachable head sentinel response cannot carry success",
      );
    }
    headSentinelReceipt = {
      sha: envelope.payload.receipt.target_sha,
      context: envelope.payload.receipt.context,
      state: envelope.payload.receipt.state,
      status_id: envelope.payload.receipt.status_id,
      observed_at: envelope.payload.receipt.created_at,
    };
  }
  return {
    exact_sha_context_count: intents.length,
    latest_idempotency_key:
      intents.at(-1)?.envelope.payload.action.scheduler_action_key ?? null,
    head_sentinel_receipt: headSentinelReceipt,
  };
}

function deriveAppliedSchedulerActionKeys(records, scope) {
  const keys = [];
  const identities = new Map();
  const statusIndexes = new Map();
  const add = (key, identity, statusIndex = null, statusCount = null) => {
    const prior = identities.get(key);
    if (prior === undefined) {
      identities.set(key, identity);
      keys.push(key);
    } else if (prior !== identity) {
      throw ledgerError(
        "scheduler-action-key-conflict",
        "one scheduler action key identifies competing protected intents",
      );
    }
    if (statusIndex !== null) {
      const state = statusIndexes.get(key) ?? {
        count: statusCount,
        indexes: new Set(),
      };
      if (state.count !== statusCount || state.indexes.has(statusIndex)) {
        throw ledgerError(
          "status-plan-index-conflict",
          "status scheduler authority repeats or conflicts on a planned slot",
        );
      }
      state.indexes.add(statusIndex);
      statusIndexes.set(key, state);
    }
  };
  const currentRecords = new Set(currentScopeIncarnationRecords(records, scope));
  for (const entry of records) {
    const envelope = entry.envelope;
    if (envelope.record_type !== "effect-intent" ||
        !sameHeadScope(envelope, scope)) continue;
    const action = envelope.payload.action;
    if (envelope.kind === "automatic-request-reservation") {
      add(action.scheduler_action_key,
        `reservation:${entry.commit_sha}`);
    } else if (envelope.kind === "effect-attempt") {
      add(action.scheduler_action_key, `attempt:${entry.commit_sha}`);
    } else if (
      envelope.kind === "status-write" &&
      currentRecords.has(entry)
    ) {
      add(
        action.scheduler_action_key,
        `status:${action.scheduler_observation_record_oid}:` +
          `${action.status_plan_digest}`,
        action.status_write_index,
        action.status_write_count,
      );
    }
  }
  for (const [key, state] of statusIndexes) {
    if (state.indexes.size !== state.count) {
      // Partial status publication remains consumed and authoritative. Missing
      // siblings are not refunded, so the scheduler key is still applied.
      void key;
    }
  }
  return keys;
}

function validateEffectAttemptLineage(priorRecords, value) {
  const action = value.payload.action;
  const reservation = priorRecords.find((entry) =>
    entry.commit_sha === action.reservation_record_oid);
  const observation = priorRecords.find((entry) =>
    entry.commit_sha === action.scheduler_observation_record_oid);
  const reservationAction = reservation?.envelope.payload.action;
  const reservationValue = reservationAction?.reservation;
  const observationAction =
    observation?.envelope.record_type === "effect-intent" &&
      observation.envelope.kind === "scheduler-observation"
      ? validateV2GitLedgerSchedulerObservation(
          observation.envelope.payload.action,
        )
      : null;
  const postAction = observationAction?.scheduler_plan.actions.find((entry) =>
    entry.kind === "post_review_request" &&
    entry.idempotency_key === action.scheduler_action_key);
  if (
    reservation?.envelope.record_type !== "effect-intent" ||
    reservation.envelope.kind !== "automatic-request-reservation" ||
    observationAction === null ||
    !sameHeadScope(reservation.envelope, recordOrEnvelopeScope(value)) ||
    !sameExactScope(observation.envelope, recordOrEnvelopeScope(value)) ||
    reservationAction.post_scheduler_action_key !==
      action.scheduler_action_key ||
    postAction === undefined ||
    postAction.depends_on_idempotency_key !==
      reservationAction.scheduler_action_key ||
    postAction.intent_id !== reservationValue.scheduler_intent_id ||
    postAction.generation_id !== reservationValue.generation_id ||
    postAction.generation_index !== reservationValue.generation_index ||
    canonicalJson(postAction.recovery_authority) !==
      canonicalJson(reservationValue.recovery_authority)
  ) {
    throw ledgerError(
      "effect-attempt-reservation-required",
      "effect attempt lacks its exact scheduler observation and reservation",
    );
  }
  validateV2GitLedgerRequestAttempt(action.attempt, {
    reservation: reservation.envelope.payload.action.reservation,
  });
  if (!sameAutomaticGenerationIdentity(
    value.payload.generation,
    reservation.envelope.payload.generation,
  )) {
    throw ledgerError(
      "effect-attempt-generation-mismatch",
      "effect attempt differs from its consumed reservation generation",
    );
  }
  const reservationStatusResponses = priorRecords.filter((entry) => {
    const envelope = entry.envelope;
    return envelope.record_type === "effect-response" &&
      envelope.kind === "reservation-status-write" &&
      envelope.payload.action.reservation_record_oid === reservation.commit_sha &&
      sameAutomaticGenerationIdentity(
        envelope.payload.generation,
        value.payload.generation,
      );
  });
  if (reservationStatusResponses.length !== 1) {
    throw ledgerError(
      "reservation-status-binding-required",
      "effect attempt is forbidden before one exact reservation status binding",
    );
  }
  if (
    Date.parse(action.attempt.recorded_at) <
      Date.parse(
        reservationStatusResponses[0].envelope.payload.receipt
          .refetch_server_time,
      )
  ) {
    throw ledgerError(
      "effect-attempt-before-reservation-status",
      "effect attempt precedes its exact reservation status refetch binding",
    );
  }
}

function validateReservationStatusLineage(priorRecords, value) {
  const action = value.payload.action;
  const reservation = priorRecords.find((entry) =>
    entry.commit_sha === action.reservation_record_oid);
  if (
    reservation?.envelope.record_type !== "effect-intent" ||
    reservation.envelope.kind !== "automatic-request-reservation" ||
    canonicalJson(reservation.envelope.payload.generation) !==
      canonicalJson(value.payload.generation) ||
    action.description_digest !==
      reservation.envelope.payload.action.reservation_digest ||
    action.generation_id !==
      reservation.envelope.payload.generation.generation_id ||
    action.ordinal !== reservation.envelope.payload.ordinal
  ) {
    throw ledgerError(
      "reservation-status-lineage",
      "reservation status does not bind one exact consumed reservation",
    );
  }
}

function validateStatusWriteLineage(priorRecords, value) {
  const action = value.payload.action;
  const observation = priorRecords.find((entry) =>
    entry.commit_sha === action.scheduler_observation_record_oid);
  if (
    observation?.envelope.record_type !== "effect-intent" ||
    observation.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "status-scheduler-observation-required",
      "status write lacks its exact scheduler observation",
    );
  }
  const observed = observation.envelope.payload.action;
  const publish = observed.scheduler_plan.actions.find((item) =>
    item.kind === "publish_status" &&
    item.idempotency_key === action.scheduler_action_key);
  const writes = observed.status_plan.writes;
  const planned = writes[action.status_write_index];
  if (
    publish === undefined ||
    action.scheduler_plan_digest !== observed.scheduler_plan_digest ||
    action.status_plan_digest !== observed.status_plan_digest ||
    action.status_write_count !== writes.length ||
    planned === undefined || action.mode !== observed.status_plan.mode ||
    planned.role !== action.role || planned.sha !== action.target_sha ||
    planned.context !== action.context || planned.state !== action.state ||
    value.idempotency_key !== planned.idempotency_key
  ) {
    throw ledgerError(
      "status-plan-mismatch",
      "status write differs from its exact scheduler and runner status plan",
    );
  }
  if (value.record_type === "effect-intent") {
    const progress = statusWriteTransactionProgress(
      priorRecords,
      action.scheduler_observation_record_oid,
      writes.length,
    );
    if (
      progress.unbound_intent !== null ||
      progress.next_index !== action.status_write_index
    ) {
      throw ledgerError(
        "status-plan-sequence-mismatch",
        "status writes must follow the canonical response-bound plan order",
      );
    }
  }
}

function statusWriteTransactionProgress(
  records,
  observationRecordOid,
  writeCount,
) {
  const transactionObservation = records.find((entry) =>
    entry.commit_sha === observationRecordOid);
  if (
    transactionObservation?.envelope.record_type !== "effect-intent" ||
    transactionObservation.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "status-scheduler-observation-required",
      "status transaction lacks its protected scheduler observation",
    );
  }
  const transactionIdentity = statusWriteTransactionIdentity(
    transactionObservation.envelope.payload.action,
    recordOrEnvelopeScope(transactionObservation.envelope),
  );
  const intents = records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "status-write" &&
    statusWriteIntentTransactionIdentity(records, entry) ===
      transactionIdentity);
  const byIndex = new Map();
  for (const intent of intents) {
    const action = intent.envelope.payload.action;
    if (
      action.status_write_count !== writeCount ||
      byIndex.has(action.status_write_index)
    ) {
      throw ledgerError(
        "status-plan-index-conflict",
        "status transaction repeats or changes one protected plan slot",
      );
    }
    byIndex.set(action.status_write_index, intent);
  }
  for (let index = 0; index < writeCount; index += 1) {
    const intent = byIndex.get(index);
    if (intent === undefined) {
      if (byIndex.size !== index) {
        throw ledgerError(
          "status-plan-sequence-mismatch",
          "status transaction contains a skipped protected plan slot",
        );
      }
      return { next_index: index, unbound_intent: null };
    }
    const responses = records.filter((entry) =>
      entry.envelope.record_type === "effect-response" &&
      entry.envelope.kind === "status-write" &&
      entry.envelope.effect_id === intent.envelope.effect_id);
    if (responses.length > 1) {
      throw ledgerError(
        "status-write-response-conflict",
        "status transaction contains competing responses for one slot",
      );
    }
    if (responses.length === 0) {
      if (byIndex.size !== index + 1) {
        throw ledgerError(
          "status-plan-sequence-mismatch",
          "status transaction advances beyond one unbound intent",
        );
      }
      return { next_index: index, unbound_intent: intent };
    }
  }
  if (byIndex.size !== writeCount) {
    throw ledgerError(
      "status-plan-index-conflict",
      "status transaction exceeds its protected plan slots",
    );
  }
  return { next_index: writeCount, unbound_intent: null };
}

function statusWriteIntentTransactionIdentity(records, intentEntry) {
  const observationOid = intentEntry.envelope.payload.action
    .scheduler_observation_record_oid;
  const observation = records.find((entry) =>
    entry.commit_sha === observationOid);
  if (
    observation?.envelope.record_type !== "effect-intent" ||
    observation.envelope.kind !== "scheduler-observation"
  ) {
    throw ledgerError(
      "status-scheduler-observation-required",
      "status intent lacks its protected scheduler observation",
    );
  }
  return statusWriteTransactionIdentity(
    observation.envelope.payload.action,
    recordOrEnvelopeScope(observation.envelope),
  );
}

function statusWriteTransactionIdentity(observationAction, scope) {
  const observation = validateV2GitLedgerSchedulerObservation(
    observationAction,
  );
  const controlledRequest = observation.prior_scheduling.epoch
    .controlled_request;
  return digestCanonical(
    "codex-review-gate-v2-git-ledger-status-transaction",
    {
      scope: structuredClone(scope),
      epoch_id: observation.scheduler_evaluation.epoch_id,
      controlled_request: controlledRequest === null
        ? null
        : {
            request_id: controlledRequest.request_id,
            binding_record_oid: controlledRequest.binding_record_oid,
          },
      status_plan: {
        mode: observation.status_plan.mode,
        decision: observation.status_plan.decision,
        writes: observation.status_plan.writes.map((write) => ({
          role: write.role,
          sha: write.sha,
          context: write.context,
          state: write.state,
          reason: write.reason,
        })),
        terminal_cutover: observation.status_plan.terminal_cutover,
        freshness_assurance: observation.status_plan.freshness_assurance,
      },
    },
  );
}

function validateCurrentSchedulerAppendForStatus({
  loaded,
  scheduler_append: schedulerAppend,
  scheduler_authority: schedulerAuthority,
  evaluated_scope_receipt: evaluatedScopeReceipt,
  status_write_index: statusWriteIndex,
}) {
  validateCurrentSchedulerAppendAuthority({
    loaded,
    scheduler_append: schedulerAppend,
    scheduler_authority: schedulerAuthority,
    evaluated_scope_receipt: evaluatedScopeReceipt,
  });
  const observation = validateV2GitLedgerSchedulerObservation(
    schedulerAppend.record.payload.action,
  );
  const progress = statusWriteTransactionProgress(
    loaded.records,
    schedulerAuthority.observation_record_oid,
    observation.status_plan.writes.length,
  );
  if (progress.unbound_intent !== null) {
    throw ledgerError(
      "status-write-intent-ambiguous-consumed",
      "a durable status intent has no exact response and cannot be retried",
    );
  }
  if (progress.next_index !== statusWriteIndex) {
    throw ledgerError(
      "status-plan-sequence-mismatch",
      "status write index is not the next canonical protected plan slot",
    );
  }
}

function validateCurrentSchedulerAppendAuthority({
  loaded,
  scheduler_append: schedulerAppend,
  scheduler_authority: schedulerAuthority,
  evaluated_scope_receipt: evaluatedScopeReceipt,
}) {
  const observationRecordOid = schedulerAuthority.observation_record_oid;
  const observation = loaded.records.find((entry) =>
    entry.commit_sha === observationRecordOid);
  const scope = schedulerAuthority.scope;
  const observations = schedulerObservationRecords(loaded.records, scope);
  const activeLease = loaded.active_lease;
  if (
    observation?.envelope.record_type !== "effect-intent" ||
    observation.envelope.kind !== "scheduler-observation" ||
    observations.at(-1)?.commit_sha !== observationRecordOid ||
    schedulerAppend.append_receipt.commit_sha !== observationRecordOid ||
    schedulerAppend.append_receipt.payload_digest !==
      observation.envelope.payload_digest ||
    schedulerAppend.record.effect_id !== observation.envelope.effect_id ||
    schedulerAppend.record.idempotency_key !==
      observation.envelope.idempotency_key ||
    canonicalJson(schedulerAppend.record.payload.action) !==
      canonicalJson(observation.envelope.payload.action) ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      schedulerAuthority.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(scope)
  ) {
    throw ledgerError(
      "stale-scheduler-status-authority",
      "status intent requires the current reachable scheduler observation and lease",
    );
  }
  validateFullDiscoveryScopeLineage(
    activeLease.evaluated_scope_receipt,
    evaluatedScopeReceipt,
    activeLease,
  );
}

function validateCurrentStatusIntentForResponse({
  loaded,
  private_intent: privateIntent,
}) {
  const intentOid = privateIntent.intent_append_receipt.commit_sha;
  const intent = loaded.records.find((entry) => entry.commit_sha === intentOid);
  const activeLease = loaded.active_lease;
  if (
    intent?.envelope.record_type !== "effect-intent" ||
    intent.envelope.kind !== "status-write" ||
    canonicalJson(intent.envelope.payload.action) !==
      canonicalJson(privateIntent.intent_record.payload.action) ||
    loaded.records.some((entry) =>
      entry.envelope.record_type === "effect-response" &&
      entry.envelope.effect_id === privateIntent.intent_record.effect_id) ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      privateIntent.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(privateIntent.scope)
  ) {
    throw ledgerError(
      "stale-status-intent-authority",
      "status response requires one current reachable unbound intent and lease",
    );
  }
  validateFullDiscoveryScopeLineage(
    activeLease.evaluated_scope_receipt,
    privateIntent.evaluated_scope_receipt,
    activeLease,
  );
}

function validateCurrentAutomaticReservation({
  loaded,
  private_reservation: privateReservation,
  require_status_absent: requireStatusAbsent,
}) {
  const reservationOid =
    privateReservation.reservation_append_receipt.commit_sha;
  const reservation = loaded.records.find((entry) =>
    entry.commit_sha === reservationOid);
  const activeLease = loaded.active_lease;
  const statusIntents = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "reservation-status-write" &&
    entry.envelope.payload.action.reservation_record_oid === reservationOid);
  if (
    reservation?.envelope.record_type !== "effect-intent" ||
    reservation.envelope.kind !== "automatic-request-reservation" ||
    canonicalJson(reservation.envelope.payload.action) !==
      canonicalJson(privateReservation.reservation_record.payload.action) ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      privateReservation.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(privateReservation.scope) ||
    (requireStatusAbsent && statusIntents.length !== 0)
  ) {
    throw ledgerError(
      "stale-automatic-reservation-authority",
      "reservation status requires one current reachable reservation and lease",
    );
  }
  validateFullDiscoveryScopeLineage(
    activeLease.evaluated_scope_receipt,
    privateReservation.evaluated_scope_receipt,
    activeLease,
  );
}

function validateCurrentReservationStatusIntent({
  loaded,
  private_intent: privateIntent,
}) {
  const intentOid = privateIntent.intent_append_receipt.commit_sha;
  const intent = loaded.records.find((entry) => entry.commit_sha === intentOid);
  const activeLease = loaded.active_lease;
  if (
    intent?.envelope.record_type !== "effect-intent" ||
    intent.envelope.kind !== "reservation-status-write" ||
    canonicalJson(intent.envelope.payload.action) !==
      canonicalJson(privateIntent.intent_record.payload.action) ||
    loaded.records.some((entry) =>
      entry.envelope.record_type === "effect-response" &&
      entry.envelope.effect_id === privateIntent.intent_record.effect_id) ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      privateIntent.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(privateIntent.scope)
  ) {
    throw ledgerError(
      "stale-reservation-status-intent-authority",
      "reservation status response requires one reachable unbound intent and lease",
    );
  }
  validateFullDiscoveryScopeLineage(
    activeLease.evaluated_scope_receipt,
    privateIntent.evaluated_scope_receipt,
    activeLease,
  );
}

function validateCurrentAutomaticReservationForAttempt({
  loaded,
  private_reservation: privateReservation,
  private_response: privateResponse,
}) {
  validateCurrentAutomaticReservation({
    loaded,
    private_reservation: privateReservation,
    require_status_absent: false,
  });
  const reservationOid =
    privateReservation.reservation_append_receipt.commit_sha;
  const responseOid = privateResponse.response_append_receipt.commit_sha;
  const response = loaded.records.find((entry) =>
    entry.commit_sha === responseOid);
  const statusIntent = privateResponse.private_intent;
  const attempts = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "effect-attempt" &&
    entry.envelope.payload.action.reservation_record_oid === reservationOid);
  const reviewRequests = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "review-request" &&
    entry.envelope.payload.action.reservation_record_oid === reservationOid);
  const runnerState = deriveV2GitLedgerRunnerState(
    loaded.records,
    privateReservation.scope,
    loaded.post_ref.server_time,
  );
  const authoritativeReservation = runnerState.reservations.find((item) =>
    item.record_oid === reservationOid);
  if (
    response?.envelope.record_type !== "effect-response" ||
    response.envelope.kind !== "reservation-status-write" ||
    response.envelope.payload.intent_commit_sha !==
      statusIntent.intent_append_receipt.commit_sha ||
    canonicalJson(response.envelope.payload.action) !==
      canonicalJson(statusIntent.intent_record.payload.action) ||
    canonicalJson(response.envelope.payload.receipt) !==
      canonicalJson(privateResponse.response_record.payload.receipt) ||
    authoritativeReservation?.reservation_status_response_record_oid !==
      responseOid ||
    authoritativeReservation.reservation_status_bound !== true ||
    attempts.length !== 0 || reviewRequests.length !== 0
  ) {
    throw ledgerError(
      "stale-automatic-request-attempt-authority",
      "automatic request attempt requires one bound reservation status and no prior attempt",
    );
  }
}

function validateCurrentAutomaticReviewRequestAttempt({
  loaded,
  private_reservation: privateReservation,
  private_response: privateResponse,
  attempt_record: attemptRecord,
  attempt_append_receipt: attemptAppendReceipt,
}) {
  validateCurrentAutomaticReservation({
    loaded,
    private_reservation: privateReservation,
    require_status_absent: false,
  });
  const reservationOid =
    privateReservation.reservation_append_receipt.commit_sha;
  const attempt = loaded.records.find((entry) =>
    entry.commit_sha === attemptAppendReceipt.commit_sha);
  const response = loaded.records.find((entry) =>
    entry.commit_sha === privateResponse.response_append_receipt.commit_sha);
  const reviewRequests = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "review-request" &&
    entry.envelope.payload.action.reservation_record_oid === reservationOid);
  if (
    loaded.tip_commit_sha !== attemptAppendReceipt.commit_sha ||
    attempt?.envelope.record_type !== "effect-intent" ||
    attempt.envelope.kind !== "effect-attempt"
  ) {
    throw ledgerError(
      "automatic-review-request-attempt-reread-mismatch",
      "retry-zero request attempt is absent from exact stable authority",
    );
  }
  const storedAction = attempt.envelope.payload.action;
  const preparedAction = attemptRecord.payload.action;
  if (
    storedAction.scheduler_observation_record_oid !==
      preparedAction.scheduler_observation_record_oid ||
    storedAction.reservation_record_oid !==
      preparedAction.reservation_record_oid ||
    storedAction.scheduler_action_key !== preparedAction.scheduler_action_key ||
    Date.parse(storedAction.attempt.recorded_at) <
      Date.parse(preparedAction.attempt.recorded_at)
  ) {
    throw ledgerError(
      "automatic-review-request-attempt-action-mismatch",
      "retry-zero request attempt differs from its exact prepared action",
    );
  }
  validateV2GitLedgerRequestAttempt(storedAction.attempt, {
    reservation: privateReservation.reservation,
  });
  if (
    response?.envelope.record_type !== "effect-response" ||
    response.envelope.kind !== "reservation-status-write"
  ) {
    throw ledgerError(
      "automatic-review-request-status-response-missing",
      "retry-zero request attempt lost its reservation status authority",
    );
  }
  if (reviewRequests.length !== 0) {
    throw ledgerError(
      "automatic-review-request-intent-already-present",
      "retry-zero request attempt already has one reachable review intent",
    );
  }
  return deepFreeze(structuredClone(storedAction.attempt));
}

async function automaticReviewRequestControllerAuthority({
  preflight_handle: preflightHandle,
  repository,
  lease_owner: leaseOwnerValue,
}) {
  if (preflightHandle === null) {
    throw ledgerError(
      "automatic-review-request-preflight-required",
      "automatic review request binding requires one branded live preflight",
    );
  }
  const module = await import("./workflow-preflight.mjs");
  if (typeof module.assertV2WorkflowPreflightHandle !== "function") {
    throw ledgerError(
      "automatic-review-request-preflight-unavailable",
      "automatic review request binding cannot validate its controller principal",
    );
  }
  const preflight = module.assertV2WorkflowPreflightHandle(preflightHandle);
  const leaseOwner = normalizeLeaseOwner(leaseOwnerValue);
  const app = structuredClone(preflight.identity_evidence?.app_catalog);
  validateExternalApp(app, "automatic review request controller App catalog");
  if (
    preflight.repository.owner !== repository.owner ||
    preflight.repository.name !== repository.name ||
    preflight.repository.id !== repository.id ||
    preflight.repository.node_id !== repository.node_id ||
    preflight.repository.owner_id !== repository.owner_id ||
    preflight.identity_evidence.triggering_actor_id_claim !==
      leaseOwner.actor_id ||
    app.id !== "15368" || app.slug !== "github-actions"
  ) {
    throw ledgerError(
      "automatic-review-request-controller-authority-mismatch",
      "automatic review request controller principal differs from preflight, OIDC lease, or App catalog",
    );
  }
  return deepFreeze({ actor_id: leaseOwner.actor_id, app });
}

function automaticReviewRequestScopeDigest(value) {
  return runnerDigestCanonical("codex-review-gate-v2-scope", {
    repository_node_id: value.repository.node_id,
    pull_request_node_id: value.pull_request.node_id,
    pull_request_number: value.pull_request.number,
    lifecycle: {
      state: value.pull_request.state,
      merged: value.pull_request.merged,
      merged_at: value.pull_request.merged_at,
      is_draft: value.pull_request.is_draft,
    },
    scope: value.scope,
  });
}

function validateCurrentAutomaticReviewRequestBinding({
  loaded,
  private_intent: privateIntent,
  progress,
}) {
  const intentOid = privateIntent.intent_append_receipt.commit_sha;
  const reviewIntent = loaded.records.find((entry) =>
    entry.commit_sha === intentOid);
  const reviewResponses = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-response" &&
    entry.envelope.kind === "review-request" &&
    entry.envelope.effect_id === privateIntent.intent_record.effect_id);
  const bindingIntents = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-intent" &&
    entry.envelope.kind === "request-binding" &&
    entry.envelope.payload.action.attempt_record_oid ===
      privateIntent.attempt_append_receipt.commit_sha);
  const bindingResponses = loaded.records.filter((entry) =>
    entry.envelope.record_type === "effect-response" &&
    entry.envelope.kind === "request-binding" &&
    entry.envelope.payload.action.attempt_record_oid ===
      privateIntent.attempt_append_receipt.commit_sha);
  const activeLease = loaded.active_lease;
  if (
    reviewIntent?.envelope.record_type !== "effect-intent" ||
    reviewIntent.envelope.kind !== "review-request" ||
    canonicalJson(reviewIntent.envelope.payload.action) !==
      canonicalJson(privateIntent.intent_record.payload.action) ||
    activeLease === null ||
    activeLease.acquire_commit_sha !==
      privateIntent.lease_authority.acquire_commit_sha ||
    canonicalJson(activeLease.scope) !== canonicalJson(privateIntent.scope) ||
    reviewResponses.length > 1 || bindingIntents.length > 1 ||
    bindingResponses.length > 1
  ) {
    throw ledgerError(
      "stale-automatic-review-request-binding-authority",
      "automatic review request binding lost its exact intent, lease, or unique lineage",
    );
  }
  validateFullDiscoveryScopeLineage(
    activeLease.evaluated_scope_receipt,
    privateIntent.evaluated_scope_receipt,
    activeLease,
  );
  if (progress.review_response_append_receipt === null) {
    if (
      loaded.tip_commit_sha !== intentOid || reviewResponses.length !== 0 ||
      bindingIntents.length !== 0 || bindingResponses.length !== 0
    ) {
      throw ledgerError(
        "automatic-review-request-response-already-present",
        "automatic review request response authority is stale or already consumed",
      );
    }
    return;
  }
  const reviewResponse = reviewResponses[0];
  if (
    reviewResponse?.commit_sha !==
      progress.review_response_append_receipt.commit_sha ||
    canonicalJson(reviewResponse.envelope.payload.receipt) !==
      canonicalJson(progress.review_response_record.payload.receipt)
  ) {
    throw ledgerError(
      "automatic-review-request-response-reread-mismatch",
      "automatic review request response is absent from reachable authority",
    );
  }
  if (progress.request_binding_intent_append_receipt === null) {
    if (
      loaded.tip_commit_sha !== reviewResponse.commit_sha ||
      bindingIntents.length !== 0 || bindingResponses.length !== 0
    ) {
      throw ledgerError(
        "automatic-review-request-binding-intent-already-present",
        "automatic review request binding intent authority is stale or consumed",
      );
    }
    return;
  }
  const bindingIntent = bindingIntents[0];
  if (
    bindingIntent?.commit_sha !==
      progress.request_binding_intent_append_receipt.commit_sha ||
    canonicalJson(bindingIntent.envelope.payload.action) !==
      canonicalJson(progress.request_binding_intent_record.payload.action)
  ) {
    throw ledgerError(
      "automatic-review-request-binding-intent-reread-mismatch",
      "request binding intent is absent from reachable authority",
    );
  }
  if (progress.request_binding_response_append_receipt === null) {
    if (
      loaded.tip_commit_sha !== bindingIntent.commit_sha ||
      bindingResponses.length !== 0
    ) {
      throw ledgerError(
        "automatic-review-request-binding-response-already-present",
        "request binding response authority is stale or consumed",
      );
    }
    return;
  }
  const bindingResponse = bindingResponses[0];
  if (
    bindingResponse?.commit_sha !==
      progress.request_binding_response_append_receipt.commit_sha ||
    canonicalJson(bindingResponse.envelope.payload.receipt) !==
      canonicalJson(progress.request_binding_response_record.payload.receipt)
  ) {
    throw ledgerError(
      "automatic-review-request-binding-response-reread-mismatch",
      "request binding response is absent from reachable authority",
    );
  }
}

function validateRequestBindingLineage(priorRecords, value, repositoryValue) {
  const repository = normalizeRepository(repositoryValue);
  const action = value.payload.action;
  const requests = priorRecords.filter((entry) => {
    const envelope = entry.envelope;
    return envelope.record_type === "effect-response" &&
      envelope.kind === "review-request" &&
      canonicalJson(envelopeScope(envelope)) ===
        canonicalJson(recordOrEnvelopeScope(value)) &&
      canonicalJson(envelope.payload.generation) ===
        canonicalJson(value.payload.generation) &&
      envelope.payload.receipt.carrier_selector.id === action.request_id;
  });
  if (requests.length !== 1) {
    throw ledgerError(
      "request-binding-review-request-required",
      "request binding requires one prior exact review-request response",
    );
  }
  const reservation = priorRecords.find((entry) =>
    entry.commit_sha === action.reservation_record_oid);
  const attempt = priorRecords.find((entry) =>
    entry.commit_sha === action.attempt_record_oid);
  const requestAction = requests[0].envelope.payload.action;
  if (
    reservation?.envelope.record_type !== "effect-intent" ||
    reservation.envelope.kind !== "automatic-request-reservation" ||
    attempt?.envelope.record_type !== "effect-intent" ||
    attempt.envelope.kind !== "effect-attempt" ||
    requestAction.reservation_record_oid !== reservation.commit_sha ||
    requestAction.attempt_record_oid !== attempt.commit_sha ||
    !sameAutomaticGenerationIdentity(
      reservation.envelope.payload.generation,
      value.payload.generation,
    ) ||
    canonicalJson(attempt.envelope.payload.generation) !==
      canonicalJson(value.payload.generation)
  ) {
    throw ledgerError(
      "request-binding-attempt-lineage",
      "request binding lacks its exact reservation and pre-effect attempt",
    );
  }
  const selector = requests[0].envelope.payload.receipt.carrier_selector;
  requireExactArtifactUrl(
    value.record_type === "effect-response"
      ? value.payload.receipt.request_url
      : exactArtifactUrl(repository, value.pull_request, selector),
    repository,
    value.pull_request,
    selector,
  );
  if (value.record_type === "effect-response") {
    const requestReceipt = requests[0].envelope.payload.receipt;
    const bindingReceipt = value.payload.receipt;
    if (
      bindingReceipt.controlled !== true ||
      bindingReceipt.request_id !== requestReceipt.request_id ||
      bindingReceipt.request_node_id !== requestReceipt.request_node_id ||
      bindingReceipt.request_url !== requestReceipt.request_url ||
      bindingReceipt.body_sha256 !== requestReceipt.body_sha256 ||
      bindingReceipt.created_at !== requestReceipt.created_at ||
      bindingReceipt.updated_at !== requestReceipt.updated_at ||
      bindingReceipt.raw_body_sha256 !==
        requestReceipt.refetch_raw_body_sha256 ||
      canonicalJson(bindingReceipt.actor) !==
        canonicalJson(requestReceipt.actor)
    ) {
      throw ledgerError(
        "request-binding-receipt-mismatch",
        "request binding differs from its exact POST and refetch authority",
      );
    }
  }
}

function recordOrEnvelopeScope(value) {
  return {
    pull_request: value.pull_request,
    head_ref_oid: value.head_ref_oid,
    base_ref_oid: value.base_ref_oid,
    potential_merge_commit_oid: value.potential_merge_commit_oid,
  };
}

function requireExactArtifactUrl(value, repository, pullRequest, selectorValue) {
  const selector = normalizeCarrierSelector(selectorValue, "artifact URL selector");
  if (value !== exactArtifactUrl(repository, pullRequest, selector)) {
    throw ledgerError(
      "artifact-url-scope",
      "artifact URL does not bind the exact repository, pull request, type, and ID",
    );
  }
}

function exactArtifactUrl(repository, pullRequestValue, selector) {
  const pullRequest = normalizePullRequest(pullRequestValue);
  const prefix = `https://github.com/${repository.owner}/${repository.name}`;
  if (selector.kind === "issue_comment") {
    return `${prefix}/pull/${pullRequest.number}#issuecomment-${selector.id}`;
  }
  if (selector.kind === "pull_request_review") {
    return `${prefix}/pull/${pullRequest.number}#pullrequestreview-${selector.id}`;
  }
  return `${prefix}/pull/${pullRequest.number}#discussion_r${selector.id}`;
}

function exactProviderArtifactUrl(
  repository,
  pullRequestValue,
  selector,
) {
  const pullRequest = normalizePullRequest(pullRequestValue);
  const prefix = `https://github.com/${repository.owner}/${repository.name}`;
  if (selector.kind === "issue_comment") {
    return `${prefix}/pull/${pullRequest.number}#issuecomment-${selector.id}`;
  }
  if (selector.kind === "pull_request_review") {
    return `${prefix}/pull/${pullRequest.number}#pullrequestreview-${selector.id}`;
  }
  return `${prefix}/pull/${pullRequest.number}#discussion_r${selector.id}`;
}

function authoritativeRecordTime(record, authorityTime) {
  const authority = timestamp(authorityTime, "authoritative GitHub server time");
  if (Date.parse(record.server_observed_at) > Date.parse(authority)) {
    throw ledgerError(
      "caller-clock-ahead",
      "caller record time is after the authoritative GitHub ref observation",
    );
  }
  const normalized = structuredClone(record);
  normalized.server_observed_at = authority;
  if (normalized.record_type === "lease-acquire") {
    normalized.payload.acquired_at = authority;
    normalized.payload.expires_at = addSeconds(
      authority,
      normalized.payload.lease_ttl_seconds,
    );
  } else if (normalized.record_type === "lease-release") {
    normalized.payload.released_at = authority;
  } else if (
    normalized.record_type === "effect-intent" &&
    normalized.kind === "effect-attempt"
  ) {
    const attempt = normalized.payload.action.attempt;
    attempt.recorded_at = authority;
    const { attempt_digest: _attemptDigest, ...withoutDigest } = attempt;
    attempt.attempt_digest = runnerDigestCanonical(
      "codex-review-gate-v2-request-attempt",
      withoutDigest,
    );
  }
  return normalized;
}

function authoritativeArtifactBindingReadyRecordTime(record, authorityTime) {
  const authority = timestamp(
    authorityTime,
    "authoritative GitHub server time",
  );
  const normalized = structuredClone(record);
  const boundary = normalized.record_type === "effect-intent"
    ? normalized.payload.action.intent_reachability_boundary
    : normalized.payload.receipt.ready_reachability_boundary;
  const observedAt = timestamp(
    normalized.server_observed_at,
    "artifact binding ready stable ref time",
  );
  if (
    normalized.kind !== "artifact-binding-ready" ||
    !new Set(["effect-intent", "effect-response"])
      .has(normalized.record_type) ||
    boundary.ref_receipt.ref !== V2_GIT_LEDGER_REF ||
    boundary.ref_receipt.target_commit_sha !==
      normalized.predecessor_commit_sha ||
    boundary.ref_receipt.server_time !== observedAt ||
    Date.parse(observedAt) > Date.parse(authority)
  ) {
    throw ledgerError(
      "automatic-artifact-binding-ready-authoritative-time",
      "artifact binding ready record must exact-bind its admitted stable ref boundary",
    );
  }
  return normalized;
}

function requireLeaseWriteWindow(record, activeLease, authorityTime) {
  if (new Set([
    "lease-acquire",
    "candidate-inventory-observation",
    "candidate-dispatch-observation",
  ]).has(record.record_type)) return;
  if (activeLease === null) {
    throw ledgerError("lease-required", "production append lacks an active lease");
  }
  const remaining = Date.parse(activeLease.expires_at) -
    Date.parse(timestamp(authorityTime, "lease write-fence GitHub time"));
  const required = record.record_type === "lease-release"
    ? 1
    : V2_GIT_LEDGER_APPEND_SAFETY_WINDOW_MS;
  if (remaining < required) {
    throw ledgerError(
      "lease-write-window",
      "active lease cannot cover the bounded protected-ref append window",
    );
  }
}

function requireCurrentCapability(loaded, capability) {
  if (loaded.records.at(-1)?.envelope.record_type === "capability-canary") {
    throw ledgerError(
      "capability-recovery-required",
      "production access is blocked behind an unattested capability canary",
    );
  }
  const current = findCurrentCapability(loaded, capability);
  if (current === null) {
    throw ledgerError(
      "capability-attestation-required",
      "production Git ledger access requires a reachable current capability attestation",
    );
  }
  return current;
}

function requireCommitCapacity(currentCount, required, operation) {
  if (currentCount + required > MAX_V2_GIT_LEDGER_COMMITS) {
    throw ledgerError(
      "commit-capacity",
      `${operation} cannot fit within the bounded Git ledger commit cap`,
    );
  }
}

function rejectBootstrapCheckpointMutation(loaded, operation) {
  if (loaded.checkpoint?.profile === CHECKPOINT_PROFILE) {
    throw ledgerError(
      "CHECKPOINT_EPOCH_READ_ONLY",
      `${operation} is unavailable until checkpoint suffix writes are enabled`,
    );
  }
}

function findCurrentCapability(loaded, capability) {
  const latest = loaded.latest_capability;
  if (latest === null) return null;
  if (
    latest.capability_stable_digest !== stableCapabilityBindingDigest(capability) ||
    latest.protection_receipt_digest !==
      capability.protection.live_ruleset_receipt_digest ||
    canonicalJson(latest.controller_release) !==
      canonicalJson(capability.controller_release)
  ) {
    return null;
  }
  return deepFreeze({
    commit_sha: latest.attestation_commit_sha,
    ...structuredClone(latest),
  });
}

function capabilityBindingDigest(capability) {
  return digestCanonical("codex-review-gate-v2-git-ledger-capability-binding", {
    repository: capability.repository,
    repository_endpoint_receipt: capability.repository_endpoint_receipt,
    ledger_ref: capability.ledger_ref,
    permissions: capability.permissions,
    protection: capability.protection,
    ruleset_receipt: capability.ruleset_receipt,
    protection_receipt: capability.protection_receipt,
    controller_release: capability.controller_release,
    workflow_provenance_policy: capability.workflow_provenance_policy,
    provider_identity_policy: capability.provider_identity_policy,
  });
}

export function projectV2GitLedgerStableControllerReleaseAuthorization(value) {
  const release = normalizeControllerRelease(value);
  return deepFreeze({
    repository: structuredClone(release.repository),
    release_sha: release.release_sha,
    workflow_path: release.workflow_path,
    workflow_ref: release.workflow_ref,
    workflow_sha: release.workflow_sha,
    job_workflow_ref: release.job_workflow_ref,
    job_workflow_sha: release.job_workflow_sha,
    current: true,
  });
}

function projectStableSourceWorkflowAuthorization(value) {
  const source = normalizeSourceWorkflow(
    value,
    "stable capability source_workflow_pin",
  );
  return {
    repository: structuredClone(source.repository),
    workflow_path: source.workflow_path,
    workflow_ref: source.workflow_ref,
    workflow_sha: source.workflow_sha,
    job_workflow_ref: source.job_workflow_ref,
    job_workflow_sha: source.job_workflow_sha,
  };
}

function projectStableCapabilityPermissions(value) {
  assertObject(value, "stable capability permissions");
  const requested = value.contents_write_requested;
  const observed = value.contents_write_observed;
  if (
    (requested !== true && observed !== true) ||
    (requested !== undefined && observed !== undefined) ||
    value.metadata_read_observed !== true ||
    value.observed_only !== true
  ) {
    throw new Error("stable capability permissions are incomplete or ambiguous");
  }
  return {
    contents_write_authorized: true,
    metadata_read_authorized: true,
    observed_only: true,
  };
}

export function projectV2GitLedgerStableCapabilityAuthorization(value) {
  assertObject(value, "stable capability authorization");
  const repository = normalizeRepository(value.repository);
  const ledgerRef = normalizeLedgerRef(value.ledger_ref);
  validateProtectionPolicy(value.protection);
  const ruleset = normalizeLedgerRulesetReceipt(
    value.ruleset_receipt,
    repository,
    ledgerRef,
  );
  const protectionReceipt = normalizeLedgerProtectionReceipt(
    value.protection_receipt,
    ruleset,
  );
  const release = normalizeControllerRelease(value.controller_release);
  validateProtectionBindings(
    value.protection,
    ruleset,
    protectionReceipt,
    release,
  );
  const provenancePolicy = normalizeProvenancePolicy(
    value.workflow_provenance_policy,
  );
  const providerIdentityPolicy = normalizeProviderIdentityPolicy(
    value.provider_identity_policy,
  );
  if (provenancePolicy.repository_owner_id !== repository.owner_id) {
    throw new Error(
      "stable capability OIDC owner differs from the repository authority",
    );
  }
  return deepFreeze({
    repository,
    ledger_ref: ledgerRef,
    permissions: projectStableCapabilityPermissions(value.permissions),
    protection: {
      deletion_blocked: value.protection.deletion_blocked,
      non_fast_forward_blocked: value.protection.non_fast_forward_blocked,
      force_pushes_blocked: value.protection.force_pushes_blocked,
      live_ruleset_receipt_digest:
        value.protection.live_ruleset_receipt_digest,
      source_workflow_pin: projectStableSourceWorkflowAuthorization(
        value.protection.source_workflow_pin,
      ),
      accepted_records_restricted_by_oidc_source:
        value.protection.accepted_records_restricted_by_oidc_source,
    },
    ruleset_receipt: ruleset,
    protection_receipt: protectionReceipt,
    controller_release:
      projectV2GitLedgerStableControllerReleaseAuthorization(release),
    workflow_provenance_policy: provenancePolicy,
    provider_identity_policy: providerIdentityPolicy,
  });
}

export function digestV2GitLedgerStableCapabilityAuthorization(value) {
  return digestCanonical(
    "codex-review-gate-v2-git-ledger-stable-capability-binding",
    projectV2GitLedgerStableCapabilityAuthorization(value),
  );
}

function stableCapabilityBindingDigest(value) {
  return digestV2GitLedgerStableCapabilityAuthorization(value);
}

function findCurrentCapabilityForBootstrapCandidate(loaded, candidate) {
  const latest = loaded.latest_capability;
  if (
    latest === null ||
    latest.capability_stable_digest !== stableCapabilityBindingDigest(candidate)
  ) {
    return null;
  }
  const embedded = validateV2GitLedgerCapabilityReceipt(
    latest.capability_receipt,
    { repository: candidate.repository, ledger_ref: candidate.ledger_ref },
  );
  return deepFreeze({
    commit_sha: latest.attestation_commit_sha,
    capability_receipt: embedded,
    ...structuredClone(latest),
  });
}

function provenanceExpected(capability) {
  return {
    ...capability.workflow_provenance_policy,
    protection_receipt_digest:
      capability.protection.live_ruleset_receipt_digest,
  };
}

function sealLoadedLedger(
  loaded,
  capability,
  authority,
  observedAt,
  provenance,
) {
  const checkpointEpoch = loaded.checkpoint_epoch ?? null;
  const isBootstrapCheckpoint = checkpointEpoch !== null;
  const tip = loaded.records.at(-1);
  const publicRecords = loaded.records.map(redactRecordEntry);
  const recordManifest = loaded.records.map((entry) => ({
    record_oid: entry.commit_sha,
    parent_oid: entry.parents[0] ?? null,
    tree_oid: entry.tree_sha,
    envelope_digest: entry.envelope.envelope_digest,
    record_type: entry.envelope.record_type,
    kind: entry.envelope.kind,
    effect_id: entry.envelope.effect_id,
    idempotency_key: entry.envelope.idempotency_key,
    payload_digest: entry.envelope.payload_digest,
    workflow_provenance_receipt_digest:
      entry.envelope.workflow_provenance.receipt_digest,
    workflow_provenance_jti:
      provenanceReplayIdentity(entry.envelope.workflow_provenance),
    server_observed_at: entry.envelope.server_observed_at,
  }));
  const recordManifestDigest = digestCanonical(
    "codex-review-gate-v2-fully-reachable-record-manifest",
    recordManifest,
  );
  const attestation = loaded.records.find((entry) =>
    entry.commit_sha === authority.attestation_commit_sha);
  if (attestation?.envelope.record_type !== "capability-attestation") {
    throw ledgerError(
      "capability-attestation-unreachable",
      "current capability attestation is absent from the stable record manifest",
    );
  }
  const withoutDigest = {
    schema: "codex-review-gate-git-ledger-load-v2",
    schema_version: isBootstrapCheckpoint ? 2 : 1,
    repository: capability.repository,
    repository_endpoint_receipt: capability.repository_endpoint_receipt,
    ledger_ref: capability.ledger_ref,
    tip_commit_sha: loaded.tip_commit_sha,
    tip_tree_sha: tip.tree_sha,
    tip_tree_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-tip-tree",
      { tree_oid: tip.tree_sha, blob_oid: tip.blob_sha },
    ),
    genesis_commit_sha: loaded.genesis_commit_sha,
    commit_count: isBootstrapCheckpoint
      ? loaded.epoch_commit_count
      : loaded.records.length,
    ...(isBootstrapCheckpoint ? {
      record_scope: checkpointEpoch.profile === MATURE_CHECKPOINT_PROFILE
        ? "mature-checkpoint-query"
        : "bootstrap-checkpoint-query",
      epoch_root_commit_sha: checkpointEpoch.epoch_root_commit_sha,
      epoch_record_offset: loaded.epoch_record_offset,
      epoch_commit_count: loaded.epoch_commit_count,
      next_sequence: loaded.next_sequence,
      logical_record_count: loaded.logical_record_count,
      checkpoint: {
        ...structuredClone(checkpointEpoch),
        epoch_record_offset: loaded.epoch_record_offset,
        epoch_commit_count: loaded.epoch_commit_count,
        next_sequence: loaded.next_sequence,
        logical_record_count: loaded.logical_record_count,
      },
    } : {}),
    observed_at: observedAt,
    capability: {
      attestation_commit_sha: authority.attestation_commit_sha,
      capability_input_digest: authority.capability_input_digest,
      protection_receipt_digest: authority.protection_receipt_digest,
      controller_release: authority.controller_release,
      provider_identity_policy_catalog_digest:
        capability.provider_identity_policy.catalog_digest,
      provider_identity_policy:
        capability.provider_identity_policy,
    },
    ruleset_receipt: capability.ruleset_receipt,
    protection_receipt: capability.protection_receipt,
    capability_attestation: {
      record_oid: authority.attestation_commit_sha,
      oidc_attestation_digest:
        attestation.envelope.workflow_provenance.receipt_digest,
      workflow_provenance_policy_digest: digestCanonical(
        "codex-review-gate-v2-workflow-provenance-policy",
        capability.workflow_provenance_policy,
      ),
      controller_release_digest: digestCanonical(
        "codex-review-gate-v2-controller-release",
        capability.controller_release,
      ),
      provider_identity_policy_catalog_digest:
        capability.provider_identity_policy.catalog_digest,
    },
    source_authority: {
      source_workflow_pin: capability.protection.source_workflow_pin,
      accepted_records_restricted_by_oidc_source:
        capability.protection.accepted_records_restricted_by_oidc_source,
      live_ruleset_receipt_digest:
        capability.protection.live_ruleset_receipt_digest,
      workflow_provenance_receipt_digest: provenance.receipt_digest,
      workflow_provenance: provenance,
    },
    protection_receipt_digest:
      capability.protection.live_ruleset_receipt_digest,
    active_lease: loaded.active_lease,
    control_comment_binding: loaded.control_comment_binding,
    projection: loaded.projection,
    authority_projection: loaded.authority_projection,
    provenance_reverification: loaded.provenance_reverification,
    provenance_reverification_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-provenance-reverification-inventory",
      loaded.provenance_reverification,
    ),
    effect_intent_count: loaded.effect_intent_count,
    effect_response_count: loaded.effect_response_count,
    records: publicRecords,
    record_manifest: recordManifest,
    fully_reachable_record_manifest_digest: recordManifestDigest,
    pre_ref: refReceipt(loaded.pre_ref),
    post_ref: refReceipt(loaded.post_ref),
    two_pass_reads: {
      pre: {
        read_index: 1,
        ref_oid: loaded.pre_ref.target_commit_sha,
        server_time: loaded.pre_ref.server_time,
        raw_body_sha256: loaded.pre_ref.raw_body_sha256,
      },
      post: {
        read_index: 2,
        ref_oid: loaded.post_ref.target_commit_sha,
        server_time: loaded.post_ref.server_time,
        raw_body_sha256: loaded.post_ref.raw_body_sha256,
      },
      stable: true,
    },
    stable: true,
  };
  return deepFreeze({
    ...withoutDigest,
    inventory_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-inventory",
      withoutDigest,
    ),
  });
}

function candidateInventoryAttemptArtifacts(cycle) {
  return [
    {
      role: "initial-inventory",
      shard_index: null,
      value: cycle.initial_inventory,
    },
    ...cycle.shard_receipts.map((value, shardIndex) => ({
      role: "initial-shard",
      shard_index: shardIndex,
      value,
    })),
    {
      role: "final-inventory",
      shard_index: null,
      value: cycle.final_inventory,
    },
    ...cycle.final_shard_receipts.map((value, shardIndex) => ({
      role: "final-shard",
      shard_index: shardIndex,
      value,
    })),
  ];
}

function maximumCandidateInventoryTransportObservedAt(values, label) {
  let latest = null;
  for (const [index, rawValue] of values.entries()) {
    const value = timestamp(
      rawValue,
      `${label} transport observation ${index}`,
    );
    if (latest === null || Date.parse(value) > Date.parse(latest)) {
      latest = value;
    }
  }
  if (latest === null) {
    throw new Error(`${label} has no transport observation boundary`);
  }
  return latest;
}

function candidateInventoryArtifactTransportObservedAt(value, label) {
  const observations = [value.observed_at];
  if (Array.isArray(value.passes)) {
    for (const pass of value.passes) {
      observations.push(pass.observed_at);
      if (Array.isArray(pass.pages)) {
        observations.push(...pass.pages.map((page) => page.server_time));
      }
    }
  }
  if (Array.isArray(value.observations)) {
    observations.push(...value.observations.map((observation) =>
      observation.endpoint_receipt.server_time));
  }
  return maximumCandidateInventoryTransportObservedAt(observations, label);
}

function candidateInventoryAttemptTransportBoundaries(cycle, label) {
  return candidateInventoryAttemptArtifacts(cycle).map((artifact, index) =>
    candidateInventoryArtifactTransportObservedAt(
      artifact.value,
      `${label} artifact ${index}`,
    ));
}

function assertCandidateInventoryAttemptTransportOrder(
  cycle,
  priorObservedAt,
  {
    code = "candidate-inventory-time",
    message = "candidate inventory transport evidence regressed",
    label = "candidate inventory attempt",
  } = {},
) {
  let previous = priorObservedAt === null
    ? null
    : timestamp(priorObservedAt, `${label} predecessor boundary`);
  for (const boundary of candidateInventoryAttemptTransportBoundaries(
    cycle,
    label,
  )) {
    if (previous !== null && Date.parse(boundary) < Date.parse(previous)) {
      throw ledgerError(code, message);
    }
    previous = boundary;
  }
  return previous;
}

function candidateInventoryIncompleteTransportObservedAt(value, label) {
  return maximumCandidateInventoryTransportObservedAt([
    candidateInventoryArtifactTransportObservedAt(
      value.initial_inventory,
      `${label} initial inventory`,
    ),
    ...value.shard_receipts.map((receipt, index) =>
      candidateInventoryArtifactTransportObservedAt(
        receipt,
        `${label} shard ${index}`,
      )),
  ], label);
}

function candidateInventoryCompletedTransportObservedAt(value, label) {
  if (
    value.initial_inventory === null ||
    !Array.isArray(value.shard_receipts) ||
    value.final_inventory?.observed_at === undefined
  ) {
    return timestamp(value.cycle_receipt.observed_at, `${label} summary`);
  }
  return maximumCandidateInventoryTransportObservedAt([
    candidateInventoryIncompleteTransportObservedAt(value, label),
    candidateInventoryArtifactTransportObservedAt(
      value.final_inventory,
      `${label} final inventory`,
    ),
    candidateInventoryCycleReceiptTransportObservedAt(value.cycle_receipt),
  ], label);
}

function candidateInventoryDurableTransportObservedAt({
  incomplete,
  completed,
}, label) {
  if (incomplete !== null && incomplete !== undefined) {
    return candidateInventoryIncompleteTransportObservedAt(incomplete, label);
  }
  if (completed !== null && completed !== undefined) {
    return candidateInventoryCompletedTransportObservedAt(completed, label);
  }
  return null;
}

function candidateInventoryCycleReceiptTransportObservedAt(receiptValue) {
  const receipt = validateV2CandidateCycleReceipt(receiptValue);
  return maximumCandidateInventoryTransportObservedAt([
    receipt.final_inventory_observed_at,
    receipt.observed_at,
    ...receipt.final_shard_receipts.map((shard, index) =>
      candidateInventoryArtifactTransportObservedAt(
        shard,
        `candidate inventory cycle final shard ${index}`,
      )),
  ], "candidate inventory cycle receipt");
}

function candidateInventoryCycleTransportObservedAt(cycle) {
  const observations = candidateInventoryAttemptTransportBoundaries(
    cycle,
    "candidate inventory cycle",
  );
  if (cycle.cycle_receipt !== null && cycle.cycle_receipt !== undefined) {
    observations.push(
      candidateInventoryCycleReceiptTransportObservedAt(cycle.cycle_receipt),
    );
  }
  return maximumCandidateInventoryTransportObservedAt(
    observations,
    "candidate inventory cycle",
  );
}

function currentOpenLifecycleCandidates({
  authority,
}) {
  return authority.candidates.map((candidate) => {
    return {
      identity: structuredClone(candidate.identity),
      identity_digest: candidate.identity_digest,
      lifecycle_seed: structuredClone(candidate.lifecycle_seed),
      lifecycle_seed_digest: candidate.lifecycle_seed_digest,
      // This is a stable candidate identity, not an observed-absence epoch.
      // Source generations and lifecycle seeds independently bind each scan.
      lifecycle_generation_id: currentOpenLifecycleGenerationId(
        authority.repository,
        candidate.identity_digest,
      ),
    };
  });
}

function currentOpenLifecycleGenerationId(repository, identityDigest) {
  return `candidate-lifecycle:${digestCanonical(
    "codex-review-gate-v2-current-open-lifecycle-generation",
    {
      repository: Object.hasOwn(repository, "owner_id")
        ? candidateRepository(repository)
        : normalizeCandidateRepository(repository),
      identity_digest: identityDigest,
    },
  ).slice("sha256:".length)}`;
}

function currentOpenSourceGenerationId({
  repository,
  priorCandidateAuthorityDigest,
  evaluationCommandAuthority,
  currentOpenReceiptDigest,
  currentOpenProjectionDigest,
  productionCandidateAuthorityDigest,
  candidateSetDigest,
  sourceCurrentOpenSemanticDigest,
  observationWindow,
}) {
  return `candidate-source:${digestCanonical(
    "codex-review-gate-v2-current-open-source-generation",
    {
      repository: Object.hasOwn(repository, "owner_id")
        ? candidateRepository(repository)
        : normalizeCandidateRepository(repository),
      prior_candidate_authority_digest: priorCandidateAuthorityDigest,
      evaluation_command_authority:
        structuredClone(evaluationCommandAuthority),
      current_open_receipt_digest: currentOpenReceiptDigest,
      current_open_projection_digest: currentOpenProjectionDigest,
      production_candidate_authority_digest:
        productionCandidateAuthorityDigest,
      candidate_set_digest: candidateSetDigest,
      source_current_open_semantic_digest: sourceCurrentOpenSemanticDigest,
      observation_window: structuredClone(observationWindow),
    },
  ).slice("sha256:".length)}`;
}

function currentOpenDispatchBatchDigests(candidates) {
  const digests = [];
  for (
    let offset = 0, batchIndex = 0;
    offset < candidates.length;
    offset += MAX_V2_CANDIDATE_DISPATCH_ITEMS, batchIndex += 1
  ) {
    const batch = candidates.slice(
      offset,
      offset + MAX_V2_CANDIDATE_DISPATCH_ITEMS,
    );
    digests.push(currentOpenDispatchBatchDigest(batch, batchIndex, offset));
  }
  return digests;
}

function currentOpenProductionDigestCanonical(domain, value) {
  return rawDigest(`${domain}\n${canonicalJson(value)}\n`);
}

function currentOpenDispatchBatchDigest(candidates, batchIndex, offset) {
  return digestCanonical(
    "codex-review-gate-v2-current-open-dispatch-batch-binding",
    {
      batch_index: batchIndex,
      candidate_offset: offset,
      candidate_count: candidates.length,
      candidates: candidates.map((candidate) => ({
        identity: structuredClone(candidate.identity),
        identity_digest: candidate.identity_digest,
        lifecycle_seed: structuredClone(candidate.lifecycle_seed),
        lifecycle_seed_digest: candidate.lifecycle_seed_digest,
        lifecycle_generation_id: candidate.lifecycle_generation_id,
      })),
    },
  );
}

function prepareCurrentOpenGenerationPublication({
  authority: authorityValue,
  projection: projectionValue,
  priorCandidateAuthority,
  commandAuthority,
}) {
  const authority = validateV2CurrentOpenProductionCandidateAuthority(
    authorityValue,
    candidateRepository(priorCandidateAuthority.repository),
  );
  const projection =
    validateV2CurrentOpenCandidateInventoryGitLedgerProjection(
      projectionValue,
      authority.repository,
    );
  if (
    projection.receipt.receipt_digest === undefined ||
    projection.receipt.current_open_semantic_digest !==
      authority.source_current_open_semantic_digest ||
    projection.semantic_projection.length !== authority.candidate_count
  ) {
    throw ledgerError(
      "CURRENT_OPEN_PRODUCTION_AUTHORITY_MISMATCH",
      "current-open production authority differs from its exact live projection",
    );
  }
  const evaluationCommandAuthority =
    candidateDispatchEvaluationCommandAuthority(commandAuthority);
  const currentOpenProjectionDigest = digestCanonical(
    "codex-review-gate-v2-current-open-live-projection",
    projection,
  );
  assertCurrentOpenGenerationFollowsPredecessor({
    state: candidateInventoryStateFromAuthority(priorCandidateAuthority),
    observationWindow: projection.receipt.observation_window,
    observedAt: projection.receipt.observation_window.completed_at,
  });
  const generationId = currentOpenSourceGenerationId({
    repository: authority.repository,
    priorCandidateAuthorityDigest: priorCandidateAuthority.authority_digest,
    evaluationCommandAuthority,
    currentOpenReceiptDigest: projection.receipt.receipt_digest,
    currentOpenProjectionDigest,
    productionCandidateAuthorityDigest: authority.authority_digest,
    candidateSetDigest: authority.candidate_set_digest,
    sourceCurrentOpenSemanticDigest:
      authority.source_current_open_semantic_digest,
    observationWindow: projection.receipt.observation_window,
  });
  const lifecycleCandidates = currentOpenLifecycleCandidates({
    authority,
  });
  const lifecycleCandidateSetDigest = digestCanonical(
    "codex-review-gate-v2-current-open-lifecycle-candidate-set",
    lifecycleCandidates.map((candidate) => ({
      identity_digest: candidate.identity_digest,
      lifecycle_seed_digest: candidate.lifecycle_seed_digest,
      lifecycle_generation_id: candidate.lifecycle_generation_id,
    })),
  );
  const dispatchBatchDigests = currentOpenDispatchBatchDigests(
    lifecycleCandidates,
  );
  const evidenceWithoutDigest = {
    schema: V2_GIT_LEDGER_CURRENT_OPEN_GENERATION_EVIDENCE_SCHEMA,
    schema_version: 1,
    current_open_projection_digest: currentOpenProjectionDigest,
    production_candidate_authority: structuredClone(authority),
    lifecycle_candidates: lifecycleCandidates,
    lifecycle_candidate_set_digest: lifecycleCandidateSetDigest,
    dispatch_batch_digests: dispatchBatchDigests,
  };
  const evidence = deepFreeze({
    ...evidenceWithoutDigest,
    evidence_digest: digestCanonical(
      "codex-review-gate-v2-current-open-generation-evidence",
      evidenceWithoutDigest,
    ),
  });
  const decoded = Buffer.from(canonicalJson(evidence), "utf8");
  if (
    decoded.byteLength === 0 ||
    decoded.byteLength >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_DECODED_BYTES
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-capacity",
      "current-open generation evidence exceeds its decoded byte cap",
    );
  }
  const encoded = deflateRawSync(decoded, { level: 9 });
  if (
    encoded.byteLength === 0 ||
    encoded.byteLength >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ENCODED_BYTES
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-capacity",
      "current-open generation evidence exceeds its encoded byte cap",
    );
  }
  const chunks = [];
  for (
    let offset = 0, chunkIndex = 0;
    offset < encoded.byteLength;
    offset += MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES, chunkIndex += 1
  ) {
    const bytes = encoded.subarray(
      offset,
      Math.min(
        encoded.byteLength,
        offset + MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES,
      ),
    );
    chunks.push({
      path: `g-c${String(chunkIndex).padStart(4, "0")}.bin`,
      chunk_index: chunkIndex,
      byte_length: bytes.byteLength,
      blob_sha: gitObjectSha("blob", bytes),
      sha256: rawDigest(bytes),
      bytes: Buffer.from(bytes),
    });
  }
  if (
    chunks.length === 0 ||
    chunks.length > MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_CHUNKS
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-capacity",
      "current-open generation evidence exceeds its chunk cap",
    );
  }
  const treeEntries = chunks.map(({ path, blob_sha: blobSha }) => ({
    path,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }));
  const treeBytes = canonicalGitTreeBytes(treeEntries);
  const withoutDigest = {
    schema:
      V2_GIT_LEDGER_CURRENT_OPEN_GENERATION_ATTACHMENT_MANIFEST_SCHEMA,
    schema_version: 1,
    repository: structuredClone(authority.repository),
    generation_id: generationId,
    current_open_projection_digest: currentOpenProjectionDigest,
    candidate_count: authority.candidate_count,
    candidate_set_digest: authority.candidate_set_digest,
    source_current_open_semantic_digest:
      authority.source_current_open_semantic_digest,
    production_candidate_authority_digest: authority.authority_digest,
    lifecycle_candidate_set_digest: lifecycleCandidateSetDigest,
    dispatch_batch_digests: dispatchBatchDigests,
    evidence_digest: evidence.evidence_digest,
    decoded_byte_length: decoded.byteLength,
    decoded_sha256: rawDigest(decoded),
    encoding: "deflate-raw",
    encoded_byte_length: encoded.byteLength,
    encoded_sha256: rawDigest(encoded),
    chunk_count: chunks.length,
    chunks: chunks.map(({ bytes: _bytes, ...chunk }) => chunk),
    attachment_tree_sha: gitObjectSha("tree", treeBytes),
    attachment_tree_sha256: rawDigest(treeBytes),
  };
  const manifest = validateCurrentOpenGenerationAttachmentManifest({
    ...withoutDigest,
    manifest_digest: digestCanonical(
      "codex-review-gate-v2-current-open-generation-attachment-manifest",
      withoutDigest,
    ),
  });
  return {
    generation_id: generationId,
    evaluation_command_authority: evaluationCommandAuthority,
    current_open_receipt_digest: projection.receipt.receipt_digest,
    current_open_projection_digest: currentOpenProjectionDigest,
    production_candidate_authority: authority,
    observation_window: structuredClone(projection.receipt.observation_window),
    observed_at: projection.receipt.observation_window.completed_at,
    lifecycle_candidate_set_digest: lifecycleCandidateSetDigest,
    dispatch_batch_digests: dispatchBatchDigests,
    manifest,
    chunks,
    tree_entries: treeEntries,
    evidence,
  };
}

function currentOpenGenerationPayload({
  authority,
  owner,
  publication,
}) {
  return validateV2GitLedgerCandidateInventoryPayload({
    schema: V2_GIT_LEDGER_CANDIDATE_INVENTORY_RECORD_SCHEMA,
    schema_version: 3,
    phase: "current-open-generation",
    source_profile: CURRENT_OPEN_GENERATION_SOURCE_PROFILE,
    generation_id: publication.generation_id,
    owner: structuredClone(owner),
    prior_candidate_authority_digest: authority.authority_digest,
    evaluation_command_authority:
      structuredClone(publication.evaluation_command_authority),
    current_open_receipt_digest: publication.current_open_receipt_digest,
    current_open_projection_digest: publication.current_open_projection_digest,
    production_candidate_authority_digest:
      publication.production_candidate_authority.authority_digest,
    candidate_count:
      publication.production_candidate_authority.candidate_count,
    candidate_set_digest:
      publication.production_candidate_authority.candidate_set_digest,
    source_current_open_semantic_digest:
      publication.production_candidate_authority
        .source_current_open_semantic_digest,
    observation_window: structuredClone(publication.observation_window),
    observed_at: publication.observed_at,
    lifecycle_candidate_set_digest:
      publication.lifecycle_candidate_set_digest,
    dispatch_batch_digests:
      structuredClone(publication.dispatch_batch_digests),
    attachment_manifest: structuredClone(publication.manifest),
  }, { repository: authority.repository });
}

function validateCurrentOpenGenerationEvidence(value, repositoryValue) {
  assertObject(value, "current-open generation evidence");
  exactKeys(value, [
    "schema", "schema_version", "current_open_projection_digest",
    "production_candidate_authority",
    "lifecycle_candidates", "lifecycle_candidate_set_digest",
    "dispatch_batch_digests", "evidence_digest",
  ], "current-open generation evidence");
  if (
    value.schema !== V2_GIT_LEDGER_CURRENT_OPEN_GENERATION_EVIDENCE_SCHEMA ||
    value.schema_version !== 1 || !Array.isArray(value.lifecycle_candidates)
  ) {
    throw new Error("current-open generation evidence schema is invalid");
  }
  digest(
    value.current_open_projection_digest,
    "current-open generation evidence projection digest",
  );
  const authority = validateV2CurrentOpenProductionCandidateAuthority(
    value.production_candidate_authority,
    repositoryValue,
  );
  if (value.lifecycle_candidates.length !== authority.candidate_count) {
    throw new Error("current-open generation lifecycle count is invalid");
  }
  const lifecycleCandidates = value.lifecycle_candidates.map(
    (candidate, index) => {
      assertObject(candidate, `current-open lifecycle candidate ${index}`);
      exactKeys(candidate, [
        "identity", "identity_digest", "lifecycle_seed",
        "lifecycle_seed_digest", "lifecycle_generation_id",
      ], `current-open lifecycle candidate ${index}`);
      const source = authority.candidates[index];
      if (
        canonicalJson({
          identity: candidate.identity,
          identity_digest: candidate.identity_digest,
          lifecycle_seed: candidate.lifecycle_seed,
          lifecycle_seed_digest: candidate.lifecycle_seed_digest,
        }) !== canonicalJson(source) ||
        !CANDIDATE_LIFECYCLE_GENERATION_ID.test(
          candidate.lifecycle_generation_id,
        )
      ) {
        throw new Error("current-open lifecycle candidate binding is invalid");
      }
      if (candidate.lifecycle_generation_id !==
          currentOpenLifecycleGenerationId(
            authority.repository,
            candidate.identity_digest,
          )) {
        throw ledgerError(
          "candidate-inventory-lifecycle-generation",
          "current-open lifecycle id is not derived from immutable identity",
        );
      }
      return structuredClone(candidate);
    },
  );
  const lifecycleCandidateSetDigest = digestCanonical(
    "codex-review-gate-v2-current-open-lifecycle-candidate-set",
    lifecycleCandidates.map((candidate) => ({
      identity_digest: candidate.identity_digest,
      lifecycle_seed_digest: candidate.lifecycle_seed_digest,
      lifecycle_generation_id: candidate.lifecycle_generation_id,
    })),
  );
  if (value.lifecycle_candidate_set_digest !== lifecycleCandidateSetDigest) {
    throw new Error("current-open lifecycle candidate set digest is invalid");
  }
  const dispatchBatchDigests = currentOpenDispatchBatchDigests(
    lifecycleCandidates,
  );
  if (canonicalJson(value.dispatch_batch_digests) !==
      canonicalJson(dispatchBatchDigests)) {
    throw new Error("current-open lifecycle dispatch batches are invalid");
  }
  const { evidence_digest: _digest, ...withoutDigest } = value;
  if (value.evidence_digest !== digestCanonical(
    "codex-review-gate-v2-current-open-generation-evidence",
    withoutDigest,
  )) {
    throw new Error("current-open generation evidence digest is invalid");
  }
  return deepFreeze({
    ...structuredClone(value),
    production_candidate_authority: authority,
    lifecycle_candidates: lifecycleCandidates,
  });
}

function validateCurrentOpenGenerationAttachmentManifest(value) {
  assertObject(value, "current-open generation attachment manifest");
  exactKeys(value, [
    "schema", "schema_version", "repository", "generation_id",
    "current_open_projection_digest",
    "candidate_count", "candidate_set_digest",
    "source_current_open_semantic_digest",
    "production_candidate_authority_digest",
    "lifecycle_candidate_set_digest", "dispatch_batch_digests",
    "evidence_digest",
    "decoded_byte_length", "decoded_sha256", "encoding",
    "encoded_byte_length", "encoded_sha256", "chunk_count", "chunks",
    "attachment_tree_sha", "attachment_tree_sha256", "manifest_digest",
  ], "current-open generation attachment manifest");
  if (
    value.schema !==
      V2_GIT_LEDGER_CURRENT_OPEN_GENERATION_ATTACHMENT_MANIFEST_SCHEMA ||
    value.schema_version !== 1 ||
    !CANDIDATE_SOURCE_GENERATION_ID.test(value.generation_id) ||
    value.encoding !== "deflate-raw"
  ) {
    throw new Error("current-open generation attachment schema is invalid");
  }
  const repository = normalizeCandidateRepository(value.repository);
  const candidateCount = nonnegativeInteger(value.candidate_count,
    "current-open generation attachment candidate count");
  if (candidateCount > MAX_V2_CANDIDATE_DISPATCH_CYCLE_ITEMS) {
    throw ledgerError("CANDIDATE_OPEN_SET_CAP",
      "current-open generation attachment exceeds its candidate cap");
  }
  if (
    !Array.isArray(value.dispatch_batch_digests) ||
    value.dispatch_batch_digests.length !== Math.ceil(
      candidateCount / MAX_V2_CANDIDATE_DISPATCH_ITEMS,
    ) ||
    value.dispatch_batch_digests.length > MAX_V2_CANDIDATE_DISPATCH_BATCHES
  ) {
    throw new Error("current-open generation manifest dispatch batches are invalid");
  }
  value.dispatch_batch_digests.forEach((entry, index) =>
    digest(entry, `current-open generation manifest dispatch batch ${index}`));
  for (const field of [
    "current_open_projection_digest", "candidate_set_digest",
    "source_current_open_semantic_digest",
    "production_candidate_authority_digest", "lifecycle_candidate_set_digest",
    "evidence_digest", "decoded_sha256", "encoded_sha256",
    "attachment_tree_sha256", "manifest_digest",
  ]) digest(value[field], `current-open generation attachment ${field}`);
  const decodedByteLength = positiveInteger(value.decoded_byte_length,
    "current-open generation attachment decoded bytes");
  const encodedByteLength = positiveInteger(value.encoded_byte_length,
    "current-open generation attachment encoded bytes");
  const chunkCount = positiveInteger(value.chunk_count,
    "current-open generation attachment chunk count");
  if (
    decodedByteLength >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_DECODED_BYTES ||
    encodedByteLength >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ENCODED_BYTES ||
    chunkCount >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_CHUNKS ||
    !Array.isArray(value.chunks) || value.chunks.length !== chunkCount
  ) {
    throw new Error("current-open generation attachment bounds are invalid");
  }
  let totalBytes = 0;
  const chunks = value.chunks.map((chunk, index) => {
    assertObject(chunk, `current-open generation attachment chunk ${index}`);
    exactKeys(chunk, [
      "path", "chunk_index", "byte_length", "blob_sha", "sha256",
    ], `current-open generation attachment chunk ${index}`);
    const byteLength = positiveInteger(chunk.byte_length,
      `current-open generation attachment chunk ${index} bytes`);
    if (
      chunk.path !== `g-c${String(index).padStart(4, "0")}.bin` ||
      chunk.chunk_index !== index ||
      byteLength > MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES
    ) {
      throw new Error("current-open generation attachment chunks are invalid");
    }
    sha(chunk.blob_sha,
      `current-open generation attachment chunk ${index} blob sha`);
    digest(chunk.sha256,
      `current-open generation attachment chunk ${index} digest`);
    totalBytes += byteLength;
    return structuredClone(chunk);
  });
  if (totalBytes !== encodedByteLength) {
    throw new Error("current-open generation encoded length is invalid");
  }
  const treeEntries = chunks.map((chunk) => ({
    path: chunk.path,
    mode: "100644",
    type: "blob",
    sha: chunk.blob_sha,
  }));
  const treeBytes = canonicalGitTreeBytes(treeEntries);
  if (
    sha(value.attachment_tree_sha,
      "current-open generation attachment tree sha") !==
      gitObjectSha("tree", treeBytes) ||
    value.attachment_tree_sha256 !== rawDigest(treeBytes)
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-tree-identity",
      "current-open generation attachment tree identity is invalid",
    );
  }
  const { manifest_digest: _digest, ...withoutDigest } = value;
  if (value.manifest_digest !== digestCanonical(
    "codex-review-gate-v2-current-open-generation-attachment-manifest",
    withoutDigest,
  )) {
    throw new Error("current-open generation attachment manifest is invalid");
  }
  return deepFreeze({
    ...structuredClone(value),
    repository,
    candidate_count: candidateCount,
    chunks,
  });
}

function prepareCandidateInventoryAttemptAttachment({
  cycle,
  attemptIndex,
  attemptCount,
  outcome,
}) {
  const index = nonnegativeInteger(
    attemptIndex,
    "candidate inventory attachment attempt index",
  );
  const count = positiveInteger(
    attemptCount,
    "candidate inventory attachment attempt count",
  );
  if (index >= count || count > MAX_V2_CANDIDATE_SCAN_PASSES) {
    throw ledgerError(
      "candidate-inventory-attachment-attempt",
      "candidate inventory attachment attempt is outside its closed pass count",
    );
  }
  if (!new Set([
    "stable",
    "CANDIDATE_INVENTORY_DRIFT",
    "CANDIDATE_LIFECYCLE_DRIFT",
  ]).has(outcome)) {
    throw ledgerError(
      "candidate-inventory-attachment-outcome",
      "candidate inventory attachment outcome is unsupported",
    );
  }
  const artifacts = candidateInventoryAttemptArtifacts(cycle);
  if (
    artifacts.length >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ARTIFACTS ||
    cycle.shard_receipts.length >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_SHARDS ||
    cycle.final_shard_receipts.length >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_SHARDS
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-capacity",
      "candidate inventory attempt exceeds its bounded attachment domain",
    );
  }
  const chunks = [];
  const manifestArtifacts = [];
  let totalDecodedBytes = 0;
  let totalEncodedBytes = 0;
  for (const [artifactIndex, artifact] of artifacts.entries()) {
    const decoded = Buffer.from(canonicalJson(artifact.value), "utf8");
    const encoded = deflateRawSync(decoded, { level: 9 });
    totalDecodedBytes += decoded.byteLength;
    totalEncodedBytes += encoded.byteLength;
    const artifactChunks = [];
    for (
      let offset = 0, chunkIndex = 0;
      offset < encoded.byteLength;
      offset += MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES, chunkIndex += 1
    ) {
      const bytes = encoded.subarray(
        offset,
        Math.min(
          encoded.byteLength,
          offset + MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES,
        ),
      );
      const path = `a${String(artifactIndex).padStart(3, "0")}-c${
        String(chunkIndex).padStart(4, "0")}.bin`;
      const chunk = {
        path,
        chunk_index: chunkIndex,
        byte_length: bytes.byteLength,
        blob_sha: gitObjectSha("blob", bytes),
        sha256: rawDigest(bytes),
      };
      chunks.push({ ...chunk, bytes: Buffer.from(bytes) });
      artifactChunks.push(chunk);
    }
    manifestArtifacts.push({
      role: artifact.role,
      shard_index: artifact.shard_index,
      receipt_digest: digest(
        artifact.value.receipt_digest,
        `candidate inventory attachment ${artifact.role} receipt digest`,
      ),
      observed_at: timestamp(
        artifact.value.observed_at,
        `candidate inventory attachment ${artifact.role} observed_at`,
      ),
      decoded_byte_length: decoded.byteLength,
      decoded_sha256: rawDigest(decoded),
      encoding: "deflate-raw",
      encoded_byte_length: encoded.byteLength,
      encoded_sha256: rawDigest(encoded),
      chunk_count: artifactChunks.length,
      chunks: artifactChunks,
    });
  }
  if (
    chunks.length === 0 ||
    chunks.length >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_CHUNKS ||
    totalDecodedBytes >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_DECODED_BYTES ||
    totalEncodedBytes >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ENCODED_BYTES
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-capacity",
      "candidate inventory attempt attachment bytes exceed the closed profile",
    );
  }
  const treeEntries = chunks.map(({ path, blob_sha: blobSha }) => ({
    path,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }));
  const treeBytes = canonicalGitTreeBytes(treeEntries);
  const semanticArtifacts = manifestArtifacts.map((artifact) => ({
    role: artifact.role,
    shard_index: artifact.shard_index,
    receipt_digest: artifact.receipt_digest,
    observed_at: artifact.observed_at,
    decoded_byte_length: artifact.decoded_byte_length,
    decoded_sha256: artifact.decoded_sha256,
  }));
  const attemptEvidenceWithoutDigest = {
    repository: structuredClone(cycle.initial_inventory.repository),
    attempt_index: index,
    attempt_count: count,
    outcome,
    artifacts: semanticArtifacts,
  };
  const attemptEvidenceDigest = digestCanonical(
    "codex-review-gate-v2-candidate-inventory-attempt-evidence",
    attemptEvidenceWithoutDigest,
  );
  const withoutDigest = {
    schema: V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_MANIFEST_SCHEMA,
    schema_version: 1,
    repository: structuredClone(cycle.initial_inventory.repository),
    attempt_index: index,
    attempt_count: count,
    outcome,
    attempt_evidence_digest: attemptEvidenceDigest,
    artifact_count: manifestArtifacts.length,
    artifacts: manifestArtifacts,
    chunk_count: chunks.length,
    total_encoded_bytes: totalEncodedBytes,
    total_decoded_bytes: totalDecodedBytes,
    attachment_tree_sha: gitObjectSha("tree", treeBytes),
    attachment_tree_sha256: rawDigest(treeBytes),
  };
  const manifest = validateCandidateInventoryAttachmentManifest({
    ...withoutDigest,
    manifest_digest: digestCanonical(
      "codex-review-gate-v2-candidate-inventory-attachment-manifest",
      withoutDigest,
    ),
  });
  return {
    manifest,
    chunks,
    tree_entries: treeEntries,
    evidence: structuredClone(cycle),
  };
}

function validateCandidateInventoryAttachmentManifest(value) {
  assertObject(value, "candidate inventory attachment manifest");
  exactKeys(value, [
    "schema", "schema_version", "repository", "attempt_index",
    "attempt_count", "outcome", "attempt_evidence_digest",
    "artifact_count", "artifacts", "chunk_count", "total_encoded_bytes",
    "total_decoded_bytes", "attachment_tree_sha",
    "attachment_tree_sha256", "manifest_digest",
  ], "candidate inventory attachment manifest");
  if (
    value.schema !==
      V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_MANIFEST_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error("candidate inventory attachment manifest schema is unsupported");
  }
  const repository = normalizeCandidateRepository(value.repository);
  const attemptIndex = nonnegativeInteger(
    value.attempt_index,
    "candidate inventory attachment attempt_index",
  );
  const attemptCount = positiveInteger(
    value.attempt_count,
    "candidate inventory attachment attempt_count",
  );
  if (attemptIndex >= attemptCount || attemptCount > MAX_V2_CANDIDATE_SCAN_PASSES) {
    throw new Error("candidate inventory attachment attempt position is invalid");
  }
  if (!new Set([
    "stable",
    "CANDIDATE_INVENTORY_DRIFT",
    "CANDIDATE_LIFECYCLE_DRIFT",
  ]).has(value.outcome)) {
    throw new Error("candidate inventory attachment outcome is unsupported");
  }
  digest(value.attempt_evidence_digest,
    "candidate inventory attachment attempt_evidence_digest");
  const artifactCount = positiveInteger(
    value.artifact_count,
    "candidate inventory attachment artifact_count",
  );
  if (!Array.isArray(value.artifacts) ||
      artifactCount !== value.artifacts.length ||
      artifactCount >
        MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ARTIFACTS) {
    throw new Error("candidate inventory attachment artifacts are not bounded");
  }
  const paths = new Set();
  const semanticArtifacts = [];
  let initialShardIndex = 0;
  let finalShardIndex = 0;
  let finalInventorySeen = false;
  let chunkCount = 0;
  let totalEncodedBytes = 0;
  let totalDecodedBytes = 0;
  for (const [artifactIndex, artifact] of value.artifacts.entries()) {
    assertObject(artifact,
      `candidate inventory attachment artifact ${artifactIndex}`);
    exactKeys(artifact, [
      "role", "shard_index", "receipt_digest", "observed_at",
      "decoded_byte_length", "decoded_sha256", "encoding",
      "encoded_byte_length", "encoded_sha256", "chunk_count", "chunks",
    ], `candidate inventory attachment artifact ${artifactIndex}`);
    const validPosition = artifactIndex === 0
      ? artifact.role === "initial-inventory" && artifact.shard_index === null
      : !finalInventorySeen && artifact.role === "initial-shard" &&
          artifact.shard_index === initialShardIndex
        ? (initialShardIndex += 1, true)
        : !finalInventorySeen && artifact.role === "final-inventory" &&
            artifact.shard_index === null
          ? (finalInventorySeen = true, true)
          : finalInventorySeen && artifact.role === "final-shard" &&
              artifact.shard_index === finalShardIndex
            ? (finalShardIndex += 1, true)
            : false;
    if (!validPosition) {
      throw new Error("candidate inventory attachment artifact order is invalid");
    }
    digest(artifact.receipt_digest,
      `candidate inventory attachment artifact ${artifactIndex}.receipt_digest`);
    timestamp(artifact.observed_at,
      `candidate inventory attachment artifact ${artifactIndex}.observed_at`);
    const decodedBytes = positiveInteger(
      artifact.decoded_byte_length,
      `candidate inventory attachment artifact ${artifactIndex}.decoded_byte_length`,
    );
    const encodedBytes = positiveInteger(
      artifact.encoded_byte_length,
      `candidate inventory attachment artifact ${artifactIndex}.encoded_byte_length`,
    );
    digest(artifact.decoded_sha256,
      `candidate inventory attachment artifact ${artifactIndex}.decoded_sha256`);
    digest(artifact.encoded_sha256,
      `candidate inventory attachment artifact ${artifactIndex}.encoded_sha256`);
    if (artifact.encoding !== "deflate-raw" ||
        !Array.isArray(artifact.chunks) || artifact.chunks.length === 0 ||
        artifact.chunk_count !== artifact.chunks.length) {
      throw new Error("candidate inventory attachment chunks are invalid");
    }
    let artifactEncodedBytes = 0;
    for (const [chunkIndex, chunk] of artifact.chunks.entries()) {
      assertObject(chunk,
        `candidate inventory attachment chunk ${artifactIndex}:${chunkIndex}`);
      exactKeys(chunk, [
        "path", "chunk_index", "byte_length", "blob_sha", "sha256",
      ], `candidate inventory attachment chunk ${artifactIndex}:${chunkIndex}`);
      const expectedPath = `a${String(artifactIndex).padStart(3, "0")}-c${
        String(chunkIndex).padStart(4, "0")}.bin`;
      const byteLength = positiveInteger(
        chunk.byte_length,
        `candidate inventory attachment chunk ${artifactIndex}:${chunkIndex}.byte_length`,
      );
      if (
        chunk.path !== expectedPath || chunk.chunk_index !== chunkIndex ||
        paths.has(chunk.path) ||
        byteLength > MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES
      ) {
        throw new Error("candidate inventory attachment chunk order is invalid");
      }
      paths.add(chunk.path);
      sha(chunk.blob_sha,
        `candidate inventory attachment chunk ${artifactIndex}:${chunkIndex}.blob_sha`);
      digest(chunk.sha256,
        `candidate inventory attachment chunk ${artifactIndex}:${chunkIndex}.sha256`);
      artifactEncodedBytes += byteLength;
    }
    if (artifactEncodedBytes !== encodedBytes) {
      throw new Error("candidate inventory attachment encoded length is inconsistent");
    }
    semanticArtifacts.push({
      role: artifact.role,
      shard_index: artifact.shard_index,
      receipt_digest: artifact.receipt_digest,
      observed_at: artifact.observed_at,
      decoded_byte_length: decodedBytes,
      decoded_sha256: artifact.decoded_sha256,
    });
    chunkCount += artifact.chunks.length;
    totalEncodedBytes += encodedBytes;
    totalDecodedBytes += decodedBytes;
  }
  if (
    !finalInventorySeen ||
    initialShardIndex > MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_SHARDS ||
    finalShardIndex > MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_SHARDS ||
    chunkCount !== value.chunk_count ||
    totalEncodedBytes !== value.total_encoded_bytes ||
    totalDecodedBytes !== value.total_decoded_bytes ||
    chunkCount > MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_CHUNKS ||
    totalEncodedBytes >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ENCODED_BYTES ||
    totalDecodedBytes >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_DECODED_BYTES
  ) {
    throw new Error("candidate inventory attachment aggregate bounds are invalid");
  }
  if (value.attempt_evidence_digest !== digestCanonical(
    "codex-review-gate-v2-candidate-inventory-attempt-evidence",
    {
      repository: structuredClone(repository),
      attempt_index: attemptIndex,
      attempt_count: attemptCount,
      outcome: value.outcome,
      artifacts: semanticArtifacts,
    },
  )) {
    throw new Error("candidate inventory attachment evidence digest is invalid");
  }
  const treeEntries = value.artifacts.flatMap((artifact) =>
    artifact.chunks.map((chunk) => ({
      path: chunk.path,
      mode: "100644",
      type: "blob",
      sha: chunk.blob_sha,
    })));
  const treeBytes = canonicalGitTreeBytes(treeEntries);
  if (
    sha(value.attachment_tree_sha,
      "candidate inventory attachment_tree_sha") !==
      gitObjectSha("tree", treeBytes) ||
    digest(value.attachment_tree_sha256,
      "candidate inventory attachment_tree_sha256") !== rawDigest(treeBytes)
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-tree-identity",
      "candidate inventory attachment tree identity is invalid",
    );
  }
  const { manifest_digest: _manifestDigest, ...withoutDigest } = value;
  if (value.manifest_digest !== digestCanonical(
    "codex-review-gate-v2-candidate-inventory-attachment-manifest",
    withoutDigest,
  )) {
    throw new Error("candidate inventory attachment manifest digest is invalid");
  }
  return deepFreeze(structuredClone(value));
}

function checkpointBoundaryError(message) {
  return ledgerError("CHECKPOINT_SOURCE_BOUNDARY_UNSUPPORTED", message);
}

function validateBootstrapOnlyCheckpointBoundary(loaded) {
  if (loaded === null || typeof loaded !== "object") {
    throw checkpointBoundaryError(
      "checkpoint source must be one fully loaded bootstrap authority",
    );
  }
  const records = loaded.records;
  const inventory = loaded.authority_projection?.candidate_inventory;
  const dispatch = loaded.authority_projection?.candidate_dispatch;
  const expectedTypes = [
    "genesis",
    "capability-canary",
    "capability-attestation",
  ];
  if (
    !Array.isArray(records) || records.length !== 3 ||
    records.some((entry, index) =>
      entry?.envelope?.record_type !== expectedTypes[index] ||
      entry.envelope.sequence !== index ||
      canonicalJson(entry.parents) !== canonicalJson(
        index === 0 ? [] : [records[index - 1].commit_sha],
      )) ||
    loaded.tip_commit_sha !== records[2].commit_sha ||
    loaded.genesis_commit_sha !== records[0].commit_sha ||
    (loaded.commit_count ?? records.length) !== 3 ||
    loaded.active_lease !== null ||
    loaded.control_comment_binding !== null ||
    loaded.effect_intent_count !== 0 ||
    loaded.effect_response_count !== 0 ||
    inventory === null || inventory === undefined ||
    !Array.isArray(inventory.source_records) ||
    inventory.source_records.length !== 0 ||
    inventory.completed_cycle !== null ||
    inventory.incomplete_cycle !== null ||
    inventory.atomic_cycle !== null ||
    dispatch === null || dispatch === undefined ||
    !Array.isArray(dispatch.source_records) ||
    dispatch.source_records.length !== 0 ||
    !Array.isArray(dispatch.cycles) || dispatch.cycles.length !== 0 ||
    dispatch.current_cycle !== null ||
    dispatch.active_reservation !== null
  ) {
    throw checkpointBoundaryError(
      "checkpoint diagnostics currently support only the exact three-record bootstrap boundary",
    );
  }
  return loaded;
}

function validateMatureQuiescentCheckpointBoundary(loaded) {
  if (
    loaded === null || typeof loaded !== "object" ||
    loaded.checkpoint_epoch !== undefined || loaded.checkpoint !== undefined ||
    !Array.isArray(loaded.records) || loaded.records.length < 4 ||
    loaded.records.length > MAX_V2_GIT_LEDGER_COMMITS ||
    (loaded.commit_count ?? loaded.records.length) !== loaded.records.length
  ) {
    throw checkpointBoundaryError(
      "mature checkpoint source must be one ordinary stable physical epoch",
    );
  }
  const inventory = loaded.authority_projection?.candidate_inventory;
  const dispatch = loaded.authority_projection?.candidate_dispatch;
  const currentDispatch = dispatch?.current_cycle ?? null;
  if (
    loaded.active_lease !== null || inventory === null ||
    inventory === undefined || dispatch === null || dispatch === undefined ||
    inventory.incomplete_cycle !== null || inventory.atomic_cycle !== null ||
    dispatch.active_reservation !== null ||
    currentDispatch !== null && currentDispatch.cycle_complete !== true
  ) {
    throw checkpointBoundaryError(
      "mature checkpoint source contains an active inventory, dispatch, or lease transition",
    );
  }
  return loaded;
}

function checkpointRecordManifest(records) {
  return records.map((entry) => ({
    record_oid: entry.commit_sha,
    parent_oid: entry.parents[0] ?? null,
    tree_oid: entry.tree_sha,
    envelope_digest: entry.envelope.envelope_digest,
    record_type: entry.envelope.record_type,
    kind: entry.envelope.kind,
    effect_id: entry.envelope.effect_id,
    idempotency_key: entry.envelope.idempotency_key,
    payload_digest: entry.envelope.payload_digest,
    workflow_provenance_receipt_digest:
      entry.envelope.workflow_provenance.receipt_digest,
    workflow_provenance_jti:
      provenanceReplayIdentity(entry.envelope.workflow_provenance),
    server_observed_at: entry.envelope.server_observed_at,
  }));
}

function checkpointRollingAuditRoot(records) {
  let rolling = digestCanonical(
    "codex-review-gate-v2-checkpoint-audit-root-empty",
    { record_count: 0 },
  );
  for (const [ordinal, entry] of records.entries()) {
    rolling = digestCanonical(
      "codex-review-gate-v2-checkpoint-audit-root-step",
      {
        prior_root: rolling,
        ordinal,
        record_oid: entry.commit_sha,
        parent_oid: entry.parents[0] ?? null,
        envelope_digest: entry.envelope.envelope_digest,
        record_type: entry.envelope.record_type,
        server_observed_at: entry.envelope.server_observed_at,
      },
    );
  }
  return rolling;
}

function checkpointPrefixRecordFact(entry, ordinal) {
  return {
    ordinal,
    record_oid: entry.commit_sha,
    parent_oid: entry.parents[0] ?? null,
    tree_oid: entry.tree_sha,
    blob_oid: entry.blob_sha,
    record_type: entry.envelope.record_type,
    sequence: entry.envelope.sequence,
    envelope_digest: entry.envelope.envelope_digest,
    payload_digest: entry.envelope.payload_digest,
    server_observed_at: entry.envelope.server_observed_at,
    provenance_identity:
      provenanceReplayIdentity(entry.envelope.workflow_provenance),
    provenance_receipt_digest:
      entry.envelope.workflow_provenance.receipt_digest,
    provenance_token_sha256:
      entry.envelope.workflow_provenance.token_sha256,
  };
}

async function buildBootstrapCheckpointPrefixFrontier({ records, epochId }) {
  const nodeBytes = new Map();
  const frontier = createV2PersistentMerkleMap({
    domain: CHECKPOINT_PREFIX_FRONTIER_DOMAIN,
    epoch_id: epochId,
    readBlob: async (objectOid) => {
      const bytes = nodeBytes.get(objectOid);
      return bytes === undefined ? null : new Uint8Array(bytes);
    },
    writeBlob: async (bytes, { expected_object_oid: expectedObjectOid }) => {
      const snapshot = Buffer.from(bytes);
      if (gitObjectSha("blob", snapshot) !== expectedObjectOid) {
        throw ledgerError(
          "CHECKPOINT_FRONTIER_OBJECT_MISMATCH",
          "checkpoint frontier writer received bytes for another object",
        );
      }
      const prior = nodeBytes.get(expectedObjectOid);
      if (prior !== undefined && !prior.equals(snapshot)) {
        throw ledgerError(
          "CHECKPOINT_FRONTIER_OBJECT_MISMATCH",
          "checkpoint frontier object identity mapped to different bytes",
        );
      }
      nodeBytes.set(expectedObjectOid, snapshot);
      return expectedObjectOid;
    },
  });
  const updates = [];
  for (const [ordinal, entry] of records.entries()) {
    const fact = checkpointPrefixRecordFact(entry, ordinal);
    updates.push(
      {
        key: { kind: "ordinal", ordinal },
        value: fact,
      },
      {
        key: { kind: "record-oid", record_oid: entry.commit_sha },
        value: fact,
      },
      {
        key: {
          kind: "provenance-identity",
          identity: fact.provenance_identity,
        },
        value: {
          ordinal,
          record_oid: entry.commit_sha,
          provenance_receipt_digest: fact.provenance_receipt_digest,
          provenance_token_sha256: fact.provenance_token_sha256,
        },
      },
    );
  }
  const applied = await frontier.apply({
    root: frontier.emptyRoot(),
    updates,
    mode: "insert-only",
  });
  const created = applied.created_objects;
  if (
    applied.root.count !== updates.length ||
    created.length !== 2 * updates.length - 1 ||
    nodeBytes.size !== created.length
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_CLOSURE_MISMATCH",
      "checkpoint prefix frontier is not one closed Patricia tree",
    );
  }
  const treeEntries = created.map((descriptor) => {
    const bytes = nodeBytes.get(descriptor.object_oid);
    if (
      bytes === undefined || bytes.byteLength !== descriptor.object_bytes ||
      rawDigest(bytes) !== descriptor.object_sha256 ||
      bytes.byteLength > MAX_V2_PERSISTENT_FRONTIER_NODE_BYTES
    ) {
      throw ledgerError(
        "CHECKPOINT_FRONTIER_OBJECT_MISMATCH",
        "checkpoint frontier descriptor differs from its prepared bytes",
      );
    }
    return {
      path: `n-${descriptor.object_oid}.json`,
      mode: "100644",
      type: "blob",
      sha: descriptor.object_oid,
    };
  }).sort((left, right) => left.path.localeCompare(right.path));
  const rawBytes = [...nodeBytes.values()].reduce(
    (total, bytes) => total + bytes.byteLength,
    0,
  );
  if (
    created.length > MAX_V2_PERSISTENT_FRONTIER_OPERATION_OBJECTS ||
    rawBytes > MAX_V2_PERSISTENT_FRONTIER_OPERATION_BYTES
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_CAP",
      "checkpoint prefix frontier exceeds its object or raw byte cap",
    );
  }
  const treeSha = canonicalGitTreeSha(treeEntries);
  const manifest = deepFreeze({
    domain: CHECKPOINT_PREFIX_FRONTIER_DOMAIN,
    root: structuredClone(applied.root),
    tree_sha: treeSha,
    tree_entry_count: treeEntries.length,
    node_count: created.length,
    raw_node_bytes: rawBytes,
    oid_set_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-frontier-oids",
      treeEntries.map(({ sha: objectOid }) => objectOid).sort(),
    ),
  });
  return {
    frontier,
    root: applied.root,
    node_bytes: nodeBytes,
    tree_entries: treeEntries,
    manifest,
  };
}

function bootstrapCheckpointEmptyFrontiers(epochId) {
  const roots = {};
  for (const [name, domain] of Object.entries(
    CHECKPOINT_EMPTY_FRONTIER_DOMAINS,
  )) {
    const frontier = createV2PersistentMerkleMap({
      domain,
      epoch_id: epochId,
      readBlob: async () => null,
      writeBlob: async () => {
        throw ledgerError(
          "CHECKPOINT_EMPTY_FRONTIER_WRITE",
          "empty checkpoint frontier unexpectedly attempted a write",
        );
      },
    });
    roots[name] = frontier.emptyRoot();
  }
  return deepFreeze(roots);
}

function canonicalGitCommitBytes({ treeSha, parents, message, serverTime }) {
  const at = timestamp(serverTime, "Git commit timestamp");
  const lines = [
    `tree ${sha(treeSha, "Git commit tree SHA")}`,
    ...parents.map((parent) => `parent ${sha(parent, "Git commit parent SHA")}`),
    `author ${COMMIT_AUTHOR.name} <${COMMIT_AUTHOR.email}> ${gitTimestamp(at)}`,
    `committer ${COMMIT_AUTHOR.name} <${COMMIT_AUTHOR.email}> ${gitTimestamp(at)}`,
    "",
    boundedString(message, "Git commit message", 512),
  ];
  return Buffer.from(lines.join("\n"), "utf8");
}

function validateCandidateInventoryAttachmentBundle(envelope, bundle) {
  const currentOpenGeneration =
    envelope.record_type === "candidate-inventory-observation" &&
    envelope.payload.schema_version === 3 &&
    envelope.payload.phase === "current-open-generation";
  const compactAttempt =
    envelope.record_type === "candidate-inventory-observation" &&
    envelope.payload.schema_version === 2 &&
    envelope.payload.phase === "attempt";
  if (!currentOpenGeneration && !compactAttempt) {
    throw ledgerError(
      "candidate-inventory-attachment-binding",
      "candidate inventory attachment lacks one supported envelope",
    );
  }
  const manifest = currentOpenGeneration
    ? validateCurrentOpenGenerationAttachmentManifest(bundle.manifest)
    : validateCandidateInventoryAttachmentManifest(bundle.manifest);
  if (
    envelope.payload.attachment_manifest.manifest_digest !==
      manifest.manifest_digest
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-binding",
      "candidate inventory attachment differs from its envelope manifest",
    );
  }
  const expectedChunks = currentOpenGeneration
    ? manifest.chunks
    : manifest.artifacts.flatMap((artifact) => artifact.chunks);
  const expectedTreeEntries = expectedChunks.map((chunk) => ({
    path: chunk.path,
    mode: "100644",
    type: "blob",
    sha: chunk.blob_sha,
  }));
  if (
    !Array.isArray(bundle.chunks) ||
    !Array.isArray(bundle.tree_entries) ||
    bundle.chunks.length !== expectedChunks.length ||
    canonicalJson(bundle.tree_entries) !== canonicalJson(expectedTreeEntries)
  ) {
    throw ledgerError(
      "candidate-inventory-attachment-binding",
      "candidate inventory attachment chunks differ from their manifest",
    );
  }
  return { manifest, expectedChunks, expectedTreeEntries };
}

function planGitLedgerCommitObjects({
  envelope,
  parents,
  candidateInventoryAttachment = null,
}) {
  let attachmentTreeSha = null;
  const attachmentRequests = [];
  if (candidateInventoryAttachment !== null) {
    const { manifest, expectedChunks } =
      validateCandidateInventoryAttachmentBundle(
        envelope,
        candidateInventoryAttachment,
      );
    for (const [index, chunk] of
      candidateInventoryAttachment.chunks.entries()) {
      const expected = expectedChunks[index];
      const bytes = Buffer.from(chunk.bytes);
      if (
        expected === undefined || chunk.path !== expected.path ||
        bytes.byteLength !== expected.byte_length ||
        gitObjectSha("blob", bytes) !== expected.blob_sha ||
        rawDigest(bytes) !== expected.sha256
      ) {
        throw ledgerError(
          "candidate-inventory-attachment-binding",
          "candidate inventory attachment bytes differ from their manifest",
        );
      }
      attachmentRequests.push({
        kind: "blob",
        expected_sha: expected.blob_sha,
        body: { content: bytes.toString("base64"), encoding: "base64" },
      });
    }
    attachmentTreeSha = manifest.attachment_tree_sha;
    if (
      canonicalGitTreeSha(candidateInventoryAttachment.tree_entries) !==
        attachmentTreeSha
    ) {
      throw ledgerError(
        "candidate-inventory-attachment-tree-identity",
        "candidate inventory attachment tree changed identity",
      );
    }
    attachmentRequests.push({
      kind: "tree",
      expected_sha: attachmentTreeSha,
      body: {
        tree: structuredClone(candidateInventoryAttachment.tree_entries),
      },
    });
  }
  const envelopeBytes = Buffer.from(`${canonicalJson(envelope)}\n`, "utf8");
  if (envelopeBytes.byteLength > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError("blob-size", "Git ledger envelope exceeds its blob cap");
  }
  const blobSha = gitObjectSha("blob", envelopeBytes);
  const rootEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }, ...(attachmentTreeSha === null ? [] : [{
    path: V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_PATH,
    mode: "040000",
    type: "tree",
    sha: attachmentTreeSha,
  }])];
  const treeSha = canonicalGitTreeSha(rootEntries);
  const message = commitMessage(envelope);
  const commitBody = {
    message,
    tree: treeSha,
    parents: structuredClone(parents),
    author: { ...COMMIT_AUTHOR, date: envelope.server_observed_at },
    committer: { ...COMMIT_AUTHOR, date: envelope.server_observed_at },
  };
  const commitSha = gitObjectSha("commit", canonicalGitCommitBytes({
    treeSha,
    parents,
    message,
    serverTime: envelope.server_observed_at,
  }));
  return deepFreeze({
    blob_sha: blobSha,
    tree_sha: treeSha,
    commit_sha: commitSha,
    attachment_tree_sha: attachmentTreeSha,
    root_entries: rootEntries,
    requests: [
      ...attachmentRequests,
      {
        kind: "blob",
        expected_sha: blobSha,
        body: { content: envelopeBytes.toString("utf8"), encoding: "utf-8" },
      },
      {
        kind: "tree",
        expected_sha: treeSha,
        body: { tree: rootEntries },
      },
      { kind: "commit", expected_sha: commitSha, body: commitBody },
    ],
  });
}

function matureCheckpointCapabilityActivation(rawSource) {
  const sourceAttestation = rawSource.records.find((entry) =>
    entry.commit_sha === rawSource.latest_capability?.attestation_commit_sha);
  if (
    sourceAttestation?.envelope.record_type !== "capability-attestation" ||
    rawSource.latest_capability === null
  ) {
    throw checkpointBoundaryError(
      "checkpoint source lacks its exact current capability activation",
    );
  }
  return deepFreeze({
    attestation_commit_sha:
      rawSource.latest_capability.attestation_commit_sha,
    capability_input_digest:
      rawSource.latest_capability.capability_input_digest,
    capability_stable_digest:
      rawSource.latest_capability.capability_stable_digest,
    capability_receipt:
      structuredClone(rawSource.latest_capability.capability_receipt),
    protection_receipt_digest:
      rawSource.latest_capability.protection_receipt_digest,
    controller_release:
      structuredClone(rawSource.latest_capability.controller_release),
    oidc_attestation_digest:
      sourceAttestation.envelope.workflow_provenance.receipt_digest,
  });
}

function validateCheckpointCapabilityActivation({
  activation,
  source,
  repository,
  ledgerRef,
}) {
  assertObject(activation, "checkpoint source capability activation");
  exactKeys(activation, [
    "attestation_commit_sha", "capability_input_digest",
    "capability_stable_digest", "capability_receipt",
    "protection_receipt_digest", "controller_release",
    "oidc_attestation_digest",
  ], "checkpoint source capability activation");
  sha(
    activation.attestation_commit_sha,
    "checkpoint capability activation attestation",
  );
  for (const field of [
    "capability_input_digest", "capability_stable_digest",
    "protection_receipt_digest", "oidc_attestation_digest",
  ]) {
    digest(activation[field], `checkpoint capability activation ${field}`);
  }
  const embeddedCapability = validateV2GitLedgerCapabilityReceipt(
    activation.capability_receipt,
    { repository, ledger_ref: ledgerRef },
  );
  const embeddedRelease = normalizeControllerRelease(
    activation.controller_release,
  );
  if (
    activation.attestation_commit_sha !==
      source.capability_attestation_commit_sha ||
    activation.capability_stable_digest !==
      source.stable_capability_digest ||
    activation.capability_stable_digest !==
      digestV2GitLedgerStableCapabilityAuthorization(embeddedCapability) ||
    activation.capability_input_digest !==
      capabilityBindingDigest(embeddedCapability) ||
    activation.protection_receipt_digest !==
      embeddedCapability.protection.live_ruleset_receipt_digest ||
    canonicalJson(embeddedRelease) !==
      canonicalJson(embeddedCapability.controller_release)
  ) {
    throw ledgerError(
      "CHECKPOINT_CAPABILITY_ACTIVATION",
      "checkpoint capability activation differs from its authenticated source",
    );
  }
  return embeddedCapability;
}

function matureCheckpointSourceRecord(entry) {
  const attachmentEvidence = candidateInventoryAttachmentEvidence(entry);
  return {
    commit_sha: entry.commit_sha,
    parents: structuredClone(entry.parents),
    tree_sha: entry.tree_sha,
    blob_sha: entry.blob_sha,
    candidate_inventory_attachment_tree_sha:
      entry.candidate_inventory_attachment_tree_sha ?? null,
    envelope: structuredClone(entry.envelope),
    evidence: structuredClone(entry.evidence),
    candidate_inventory_attachment_evidence:
      attachmentEvidence === null ? null : structuredClone(attachmentEvidence),
  };
}

function validateMatureCheckpointSourceRecord(value, repository, ledgerRef,
  index) {
  const label = `mature checkpoint source record ${index}`;
  assertObject(value, label);
  exactKeys(value, [
    "commit_sha", "parents", "tree_sha", "blob_sha",
    "candidate_inventory_attachment_tree_sha", "envelope", "evidence",
    "candidate_inventory_attachment_evidence",
  ], label);
  sha(value.commit_sha, `${label}.commit_sha`);
  sha(value.tree_sha, `${label}.tree_sha`);
  sha(value.blob_sha, `${label}.blob_sha`);
  if (!Array.isArray(value.parents) || value.parents.length > 1) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_RECORD_PARENT",
      `${label} has an unsupported parent set`,
    );
  }
  value.parents.forEach((parent, parentIndex) =>
    sha(parent, `${label}.parents[${parentIndex}]`));
  validateV2GitLedgerEnvelope(value.envelope);
  if (
    canonicalJson(value.envelope.repository) !== canonicalJson(repository) ||
    value.envelope.ledger_ref !== ledgerRef
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_RECORD_SCOPE",
      `${label} belongs to another repository or ref`,
    );
  }
  assertObject(value.evidence, `${label}.evidence`);
  exactKeys(value.evidence, [
    "commit_raw_body_sha256", "tree_raw_body_sha256",
    "blob_raw_body_sha256", "commit_server_time", "tree_server_time",
    "blob_server_time",
  ], `${label}.evidence`);
  for (const field of [
    "commit_raw_body_sha256", "tree_raw_body_sha256",
    "blob_raw_body_sha256",
  ]) digest(value.evidence[field], `${label}.evidence.${field}`);
  for (const field of [
    "commit_server_time", "tree_server_time", "blob_server_time",
  ]) {
    if (timestamp(
      value.evidence[field],
      `${label}.evidence.${field}`,
    ) !== value.evidence[field]) {
      throw ledgerError(
        "CHECKPOINT_SOURCE_RECORD_TIME",
        `${label} evidence time is not canonical`,
      );
    }
  }
  const envelopeBytes = Buffer.from(
    `${canonicalJson(value.envelope)}\n`,
    "utf8",
  );
  if (gitObjectSha("blob", envelopeBytes) !== value.blob_sha) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_RECORD_BLOB",
      `${label} envelope bytes changed identity`,
    );
  }
  const compactAttempt =
    value.envelope.record_type === "candidate-inventory-observation" &&
    value.envelope.payload.schema_version === 2 &&
    value.envelope.payload.phase === "attempt";
  const currentOpenGeneration =
    value.envelope.record_type === "candidate-inventory-observation" &&
    value.envelope.payload.schema_version === 3 &&
    value.envelope.payload.phase === "current-open-generation";
  const attached = compactAttempt || currentOpenGeneration;
  const attachmentTreeSha = value.candidate_inventory_attachment_tree_sha;
  if (
    (attachmentTreeSha !== null) !== attached ||
    attached && (
      sha(attachmentTreeSha, `${label}.attachment_tree_sha`) !==
        value.envelope.payload.attachment_manifest.attachment_tree_sha
    ) ||
    !attached && value.candidate_inventory_attachment_evidence !== null
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_RECORD_ATTACHMENT",
      `${label} attachment differs from its envelope`,
    );
  }
  const rootEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: value.blob_sha,
  }, ...(attachmentTreeSha === null ? [] : [{
    path: V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_PATH,
    mode: "040000",
    type: "tree",
    sha: attachmentTreeSha,
  }])];
  if (canonicalGitTreeSha(rootEntries) !== value.tree_sha) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_RECORD_TREE",
      `${label} tree changed identity`,
    );
  }
  const expectedCommitSha = gitObjectSha("commit", canonicalGitCommitBytes({
    treeSha: value.tree_sha,
    parents: value.parents,
    message: commitMessage(value.envelope),
    serverTime: value.envelope.server_observed_at,
  }));
  if (expectedCommitSha !== value.commit_sha) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_RECORD_COMMIT",
      `${label} commit changed identity`,
    );
  }
  return deepFreeze({
    commit_sha: value.commit_sha,
    parents: structuredClone(value.parents),
    tree_sha: value.tree_sha,
    blob_sha: value.blob_sha,
    candidate_inventory_attachment_tree_sha: attachmentTreeSha,
    envelope: structuredClone(value.envelope),
    evidence: structuredClone(value.evidence),
    ...(value.candidate_inventory_attachment_evidence === null ? {} : {
      candidate_inventory_attachment_evidence:
        structuredClone(value.candidate_inventory_attachment_evidence),
    }),
  });
}

function matureCheckpointSeedChunkPath(index) {
  return `s-c${String(index).padStart(4, "0")}.bin`;
}

function buildMatureCheckpointSourceSeedBundle({
  repository,
  ledgerRef,
  rawSource,
}) {
  const recordManifestDigest = digestCanonical(
    "codex-review-gate-v2-fully-reachable-record-manifest",
    checkpointRecordManifest(rawSource.records),
  );
  const withoutSeedDigest = {
    schema: V2_GIT_LEDGER_MATURE_CHECKPOINT_SOURCE_SEED_SCHEMA,
    schema_version: 1,
    profile: MATURE_CHECKPOINT_PROFILE,
    repository: structuredClone(repository),
    ledger_ref: ledgerRef,
    source_tip_commit_sha: rawSource.tip_commit_sha,
    source_genesis_commit_sha: rawSource.genesis_commit_sha,
    source_commit_count: rawSource.records.length,
    source_logical_record_count: rawSource.records.length,
    source_observed_at: rawSource.observed_at,
    record_manifest_digest: recordManifestDigest,
    rolling_audit_root: checkpointRollingAuditRoot(rawSource.records),
    records: rawSource.records.map(matureCheckpointSourceRecord),
  };
  const seed = deepFreeze({
    ...withoutSeedDigest,
    source_seed_digest: digestCanonical(
      "codex-review-gate-v2-mature-checkpoint-source-seed",
      withoutSeedDigest,
    ),
  });
  const decoded = Buffer.from(`${canonicalJson(seed)}\n`, "utf8");
  if (
    decoded.byteLength === 0 ||
    decoded.byteLength >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_DECODED_BYTES
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_CAP",
      "mature checkpoint source seed exceeds its decoded cap",
    );
  }
  const encoded = deflateRawSync(decoded, { level: 9 });
  if (
    encoded.byteLength === 0 ||
    encoded.byteLength >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ENCODED_BYTES
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_CAP",
      "mature checkpoint source seed exceeds its encoded cap",
    );
  }
  const chunks = [];
  for (
    let offset = 0, chunkIndex = 0;
    offset < encoded.byteLength;
    offset += MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES, chunkIndex += 1
  ) {
    const bytes = encoded.subarray(
      offset,
      Math.min(
        encoded.byteLength,
        offset + MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES,
      ),
    );
    chunks.push({
      path: matureCheckpointSeedChunkPath(chunkIndex),
      chunk_index: chunkIndex,
      byte_length: bytes.byteLength,
      blob_sha: gitObjectSha("blob", bytes),
      sha256: rawDigest(bytes),
      bytes: Buffer.from(bytes),
    });
  }
  if (
    chunks.length === 0 ||
    chunks.length > MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_CHUNKS
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_CAP",
      "mature checkpoint source seed exceeds its chunk cap",
    );
  }
  const chunkTreeEntries = chunks.map(({ path, blob_sha: blobSha }) => ({
    path,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }));
  const chunkTreeBytes = canonicalGitTreeBytes(chunkTreeEntries);
  const withoutManifestDigest = {
    schema: V2_GIT_LEDGER_MATURE_CHECKPOINT_SOURCE_MANIFEST_SCHEMA,
    schema_version: 1,
    profile: MATURE_CHECKPOINT_PROFILE,
    repository: structuredClone(repository),
    ledger_ref: ledgerRef,
    source_tip_commit_sha: rawSource.tip_commit_sha,
    source_commit_count: rawSource.records.length,
    source_logical_record_count: rawSource.records.length,
    record_manifest_digest: recordManifestDigest,
    rolling_audit_root: checkpointRollingAuditRoot(rawSource.records),
    source_seed_digest: seed.source_seed_digest,
    decoded_byte_length: decoded.byteLength,
    decoded_sha256: rawDigest(decoded),
    encoding: "deflate-raw",
    encoded_byte_length: encoded.byteLength,
    encoded_sha256: rawDigest(encoded),
    chunk_count: chunks.length,
    chunks: chunks.map(({ bytes: _bytes, ...chunk }) => chunk),
    chunk_tree_sha: gitObjectSha("tree", chunkTreeBytes),
    chunk_tree_sha256: rawDigest(chunkTreeBytes),
  };
  const manifest = validateMatureCheckpointSourceManifest({
    ...withoutManifestDigest,
    manifest_digest: digestCanonical(
      "codex-review-gate-v2-mature-checkpoint-source-manifest",
      withoutManifestDigest,
    ),
  });
  const manifestBytes = Buffer.from(`${canonicalJson(manifest)}\n`, "utf8");
  if (manifestBytes.byteLength > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_CAP",
      "mature checkpoint source manifest exceeds its Git blob cap",
    );
  }
  const manifestBlobSha = gitObjectSha("blob", manifestBytes);
  const sourceTreeEntries = [{
    path: V2_GIT_LEDGER_CHECKPOINT_SOURCE_SEED_CHUNKS_PATH,
    mode: "040000",
    type: "tree",
    sha: manifest.chunk_tree_sha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_SOURCE_SEED_MANIFEST_PATH,
    mode: "100644",
    type: "blob",
    sha: manifestBlobSha,
  }];
  return {
    seed,
    decoded,
    encoded,
    chunks,
    chunk_tree_entries: chunkTreeEntries,
    manifest,
    manifest_bytes: manifestBytes,
    manifest_blob_sha: manifestBlobSha,
    source_tree_entries: sourceTreeEntries,
    source_tree_sha: canonicalGitTreeSha(sourceTreeEntries),
  };
}

function validateMatureCheckpointSourceManifest(value) {
  assertObject(value, "mature checkpoint source manifest");
  exactKeys(value, [
    "schema", "schema_version", "profile", "repository", "ledger_ref",
    "source_tip_commit_sha", "source_commit_count",
    "source_logical_record_count", "record_manifest_digest",
    "rolling_audit_root", "source_seed_digest", "decoded_byte_length",
    "decoded_sha256", "encoding", "encoded_byte_length",
    "encoded_sha256", "chunk_count", "chunks", "chunk_tree_sha",
    "chunk_tree_sha256", "manifest_digest",
  ], "mature checkpoint source manifest");
  if (
    value.schema !== V2_GIT_LEDGER_MATURE_CHECKPOINT_SOURCE_MANIFEST_SCHEMA ||
    value.schema_version !== 1 || value.profile !== MATURE_CHECKPOINT_PROFILE ||
    value.encoding !== "deflate-raw"
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_SCHEMA",
      "mature checkpoint source manifest schema is unsupported",
    );
  }
  normalizeRepository(value.repository);
  normalizeLedgerRef(value.ledger_ref);
  sha(value.source_tip_commit_sha, "mature checkpoint source tip");
  const sourceCommitCount = integerBetween(
    value.source_commit_count,
    4,
    MAX_V2_GIT_LEDGER_COMMITS,
    "mature checkpoint source commit count",
  );
  if (value.source_logical_record_count !== sourceCommitCount) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_COUNT",
      "first mature checkpoint source must be one ordinary physical epoch",
    );
  }
  for (const field of [
    "record_manifest_digest", "rolling_audit_root", "source_seed_digest",
    "decoded_sha256", "encoded_sha256", "chunk_tree_sha256",
    "manifest_digest",
  ]) digest(value[field], `mature checkpoint source manifest ${field}`);
  sha(value.chunk_tree_sha, "mature checkpoint source chunk tree");
  const decodedBytes = positiveInteger(
    value.decoded_byte_length,
    "mature checkpoint source decoded bytes",
  );
  const encodedBytes = positiveInteger(
    value.encoded_byte_length,
    "mature checkpoint source encoded bytes",
  );
  if (
    decodedBytes >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_DECODED_BYTES ||
    encodedBytes >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_ENCODED_BYTES ||
    !Array.isArray(value.chunks) || value.chunks.length === 0 ||
    value.chunks.length >
      MAX_V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_CHUNKS ||
    value.chunk_count !== value.chunks.length
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_CAP",
      "mature checkpoint source manifest exceeds its closed bounds",
    );
  }
  let totalBytes = 0;
  const paths = new Set();
  const treeEntries = value.chunks.map((chunk, index) => {
    assertObject(chunk, `mature checkpoint source chunk ${index}`);
    exactKeys(chunk, [
      "path", "chunk_index", "byte_length", "blob_sha", "sha256",
    ], `mature checkpoint source chunk ${index}`);
    const byteLength = positiveInteger(
      chunk.byte_length,
      `mature checkpoint source chunk ${index}.byte_length`,
    );
    if (
      chunk.path !== matureCheckpointSeedChunkPath(index) ||
      chunk.chunk_index !== index || paths.has(chunk.path) ||
      byteLength > MAX_V2_GIT_LEDGER_ATTACHMENT_CHUNK_BYTES
    ) {
      throw ledgerError(
        "CHECKPOINT_SOURCE_CHUNK_ORDER",
        "mature checkpoint source chunks are not one canonical sequence",
      );
    }
    paths.add(chunk.path);
    sha(chunk.blob_sha, `mature checkpoint source chunk ${index}.blob_sha`);
    digest(chunk.sha256, `mature checkpoint source chunk ${index}.sha256`);
    totalBytes += byteLength;
    return {
      path: chunk.path,
      mode: "100644",
      type: "blob",
      sha: chunk.blob_sha,
    };
  });
  const treeBytes = canonicalGitTreeBytes(treeEntries);
  if (
    totalBytes !== encodedBytes ||
    gitObjectSha("tree", treeBytes) !== value.chunk_tree_sha ||
    rawDigest(treeBytes) !== value.chunk_tree_sha256
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_CHUNK_TREE",
      "mature checkpoint source chunk closure changed identity",
    );
  }
  const { manifest_digest: _manifestDigest, ...withoutDigest } = value;
  if (value.manifest_digest !== digestCanonical(
    "codex-review-gate-v2-mature-checkpoint-source-manifest",
    withoutDigest,
  )) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_DIGEST",
      "mature checkpoint source manifest digest is invalid",
    );
  }
  return deepFreeze(structuredClone(value));
}

function validateMatureCheckpointSourceSeed(value, manifest, repository,
  ledgerRef) {
  assertObject(value, "mature checkpoint source seed");
  exactKeys(value, [
    "schema", "schema_version", "profile", "repository", "ledger_ref",
    "source_tip_commit_sha", "source_genesis_commit_sha",
    "source_commit_count", "source_logical_record_count",
    "source_observed_at", "record_manifest_digest", "rolling_audit_root",
    "records", "source_seed_digest",
  ], "mature checkpoint source seed");
  if (
    value.schema !== V2_GIT_LEDGER_MATURE_CHECKPOINT_SOURCE_SEED_SCHEMA ||
    value.schema_version !== 1 || value.profile !== MATURE_CHECKPOINT_PROFILE ||
    canonicalJson(value.repository) !== canonicalJson(repository) ||
    value.ledger_ref !== ledgerRef ||
    value.source_tip_commit_sha !== manifest.source_tip_commit_sha ||
    value.source_commit_count !== manifest.source_commit_count ||
    value.source_logical_record_count !==
      manifest.source_logical_record_count ||
    value.record_manifest_digest !== manifest.record_manifest_digest ||
    value.rolling_audit_root !== manifest.rolling_audit_root ||
    value.source_seed_digest !== manifest.source_seed_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_BINDING",
      "mature checkpoint source seed differs from its manifest",
    );
  }
  sha(value.source_genesis_commit_sha, "mature checkpoint source genesis");
  const observedAt = timestamp(
    value.source_observed_at,
    "mature checkpoint source observed_at",
  );
  if (observedAt !== value.source_observed_at) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_TIME",
      "mature checkpoint source observation time is not canonical",
    );
  }
  if (
    !Array.isArray(value.records) ||
    value.records.length !== value.source_commit_count
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_COUNT",
      "mature checkpoint source seed record count is inconsistent",
    );
  }
  const records = value.records.map((entry, index) =>
    validateMatureCheckpointSourceRecord(
      entry,
      repository,
      ledgerRef,
      index,
    ));
  validateReachableChain(records, observedAt);
  if (
    records[0].commit_sha !== value.source_genesis_commit_sha ||
    records.at(-1).commit_sha !== value.source_tip_commit_sha ||
    digestCanonical(
      "codex-review-gate-v2-fully-reachable-record-manifest",
      checkpointRecordManifest(records),
    ) !== value.record_manifest_digest ||
    checkpointRollingAuditRoot(records) !== value.rolling_audit_root
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_REPLAY",
      "mature checkpoint source seed cannot reconstruct its physical source",
    );
  }
  const { source_seed_digest: _sourceSeedDigest, ...withoutDigest } = value;
  if (value.source_seed_digest !== digestCanonical(
    "codex-review-gate-v2-mature-checkpoint-source-seed",
    withoutDigest,
  )) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_DIGEST",
      "mature checkpoint source seed digest is invalid",
    );
  }
  return deepFreeze({
    ...structuredClone(value),
    records,
  });
}

function buildMatureCheckpointState({
  repository,
  ledgerRef,
  epochId,
  rawSource,
  sourceLoadHandle,
  admissionHandle,
  admissionPrivate,
  capability,
  sourceSeedBundle,
}) {
  const sourceManifest = checkpointRecordManifest(rawSource.records);
  const capabilityActivation = matureCheckpointCapabilityActivation(rawSource);
  const currentOpenNextUnit = admissionPrivate.next_unit_profile ===
    MATURE_CURRENT_OPEN_NEXT_UNIT_PROFILE;
  const nextUnit = currentOpenNextUnit
    ? {
        profile: admissionHandle.profile,
        kind: admissionHandle.next_unit_kind,
        admission_digest: admissionHandle.next_unit_admission_digest,
        generation_id: admissionHandle.generation_id,
        current_open_receipt_digest:
          admissionHandle.current_open_receipt_digest,
        current_open_projection_digest:
          admissionHandle.current_open_projection_digest,
        production_candidate_authority_digest:
          admissionHandle.production_candidate_authority_digest,
        candidate_count: admissionHandle.candidate_count,
        candidate_set_digest: admissionHandle.candidate_set_digest,
        source_current_open_semantic_digest:
          admissionHandle.source_current_open_semantic_digest,
        lifecycle_candidate_set_digest:
          admissionHandle.lifecycle_candidate_set_digest,
        attachment_manifest_digest:
          admissionHandle.attachment_manifest_digest,
        stable_command_authority_digest:
          admissionHandle.stable_command_authority_digest,
        trigger_identity_digest: admissionHandle.trigger_identity_digest,
        repository_endpoint_receipt_digest:
          admissionHandle.repository_endpoint_receipt_digest,
        semantic_record_count: 2,
        total_commit_budget_required:
          admissionHandle.total_commit_budget_required,
        current_epoch_remaining_commit_capacity:
          admissionHandle.current_epoch_remaining_commit_capacity,
        fresh_epoch_remaining_commit_capacity:
          admissionHandle.fresh_epoch_remaining_commit_capacity,
      }
    : {
        kind: admissionHandle.next_unit_kind,
        admission_digest: admissionHandle.next_unit_admission_digest,
        cycle_id: admissionHandle.cycle_id,
        stable_cycle_receipt_digest:
          admissionHandle.stable_cycle_receipt_digest,
        stable_command_authority_digest:
          admissionHandle.stable_command_authority_digest,
        trigger_identity_digest: admissionHandle.trigger_identity_digest,
        projection_digest: admissionHandle.projection_digest,
        classification_projection:
          structuredClone(admissionPrivate.projection),
        semantic_record_count: admissionPrivate.drift_attempts.length + 4,
        total_commit_budget_required:
          admissionHandle.total_commit_budget_required,
        current_epoch_remaining_commit_capacity:
          admissionHandle.current_epoch_remaining_commit_capacity,
        fresh_epoch_remaining_commit_capacity:
          admissionHandle.fresh_epoch_remaining_commit_capacity,
      };
  const withoutDigest = {
    schema: V2_GIT_LEDGER_CHECKPOINT_STATE_SCHEMA,
    schema_version: currentOpenNextUnit ? 3 : 2,
    profile: MATURE_CHECKPOINT_PROFILE,
    repository: structuredClone(repository),
    ledger_ref: ledgerRef,
    epoch_id: epochId,
    epoch_sequence: 0,
    source: {
      tip_commit_sha: rawSource.tip_commit_sha,
      genesis_commit_sha: rawSource.genesis_commit_sha,
      commit_count: rawSource.records.length,
      logical_record_count: rawSource.records.length,
      source_load_digest: sourceLoadHandle.source_load_digest,
      record_manifest_digest: digestCanonical(
        "codex-review-gate-v2-fully-reachable-record-manifest",
        sourceManifest,
      ),
      rolling_audit_root: checkpointRollingAuditRoot(rawSource.records),
      provenance_reverification_digest:
        matureCheckpointProvenanceReverificationDigest(
          rawSource.provenance_reverification,
        ),
      capability_attestation_commit_sha:
        sourceLoadHandle.capability_attestation_commit_sha,
      stable_capability_digest:
        digestV2GitLedgerStableCapabilityAuthorization(capability),
      capability_activation: capabilityActivation,
      query_seed_tree_sha: sourceSeedBundle.source_tree_sha,
      query_seed_manifest: structuredClone(sourceSeedBundle.manifest),
      source_projection_digest: rawSource.projection.projection_digest,
      authority_projection_digest:
        bootstrapCheckpointAuthorityDigest(rawSource.authority_projection),
      candidate_inventory_authority_digest:
        rawSource.authority_projection.candidate_inventory.authority_digest,
      candidate_dispatch_authority_digest:
        rawSource.authority_projection.candidate_dispatch.authority_digest,
      observed_at: rawSource.observed_at,
    },
    next_unit: nextUnit,
  };
  return deepFreeze({
    ...withoutDigest,
    checkpoint_state_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-state",
      withoutDigest,
    ),
  });
}

function validateMatureCheckpointState(value) {
  assertObject(value, "mature checkpoint state");
  exactKeys(value, [
    "schema", "schema_version", "profile", "repository", "ledger_ref",
    "epoch_id", "epoch_sequence", "source", "next_unit",
    "checkpoint_state_digest",
  ], "mature checkpoint state");
  const currentOpenNextUnit = value.schema_version === 3;
  if (
    value.schema !== V2_GIT_LEDGER_CHECKPOINT_STATE_SCHEMA ||
    !new Set([2, 3]).has(value.schema_version) ||
    value.profile !== MATURE_CHECKPOINT_PROFILE ||
    value.epoch_sequence !== 0
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_SCHEMA",
      "mature checkpoint state schema or profile is unsupported",
    );
  }
  const repository = normalizeRepository(value.repository);
  const ledgerRef = normalizeLedgerRef(value.ledger_ref);
  digest(value.epoch_id, "mature checkpoint state epoch_id");
  assertObject(value.source, "mature checkpoint state source");
  exactKeys(value.source, [
    "tip_commit_sha", "genesis_commit_sha", "commit_count",
    "logical_record_count", "source_load_digest", "record_manifest_digest",
    "rolling_audit_root", "provenance_reverification_digest",
    "capability_attestation_commit_sha", "stable_capability_digest",
    "capability_activation", "query_seed_tree_sha", "query_seed_manifest",
    "source_projection_digest", "authority_projection_digest",
    "candidate_inventory_authority_digest",
    "candidate_dispatch_authority_digest", "observed_at",
  ], "mature checkpoint state source");
  sha(value.source.tip_commit_sha, "mature checkpoint source tip");
  sha(value.source.genesis_commit_sha, "mature checkpoint source genesis");
  const sourceCount = integerBetween(
    value.source.commit_count,
    4,
    MAX_V2_GIT_LEDGER_COMMITS,
    "mature checkpoint source commit count",
  );
  if (value.source.logical_record_count !== sourceCount) {
    throw checkpointBoundaryError(
      "first mature checkpoint source must be one ordinary physical epoch",
    );
  }
  for (const field of [
    "source_load_digest", "record_manifest_digest", "rolling_audit_root",
    "provenance_reverification_digest", "stable_capability_digest",
    "source_projection_digest", "authority_projection_digest",
    "candidate_inventory_authority_digest",
    "candidate_dispatch_authority_digest",
  ]) digest(value.source[field], `mature checkpoint source ${field}`);
  sha(
    value.source.capability_attestation_commit_sha,
    "mature checkpoint source capability attestation",
  );
  sha(value.source.query_seed_tree_sha, "mature checkpoint query seed tree");
  if (timestamp(
    value.source.observed_at,
    "mature checkpoint source observed_at",
  ) !== value.source.observed_at) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_TIME",
      "mature checkpoint source observation time is not canonical",
    );
  }
  validateCheckpointCapabilityActivation({
    activation: value.source.capability_activation,
    source: value.source,
    repository,
    ledgerRef,
  });
  const manifest = validateMatureCheckpointSourceManifest(
    value.source.query_seed_manifest,
  );
  if (
    canonicalJson(manifest.repository) !== canonicalJson(repository) ||
    manifest.ledger_ref !== ledgerRef ||
    manifest.source_tip_commit_sha !== value.source.tip_commit_sha ||
    manifest.source_commit_count !== sourceCount ||
    manifest.source_logical_record_count !==
      value.source.logical_record_count ||
    manifest.record_manifest_digest !==
      value.source.record_manifest_digest ||
    manifest.rolling_audit_root !== value.source.rolling_audit_root
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_MANIFEST_BINDING",
      "mature checkpoint source manifest differs from state",
    );
  }
  assertObject(value.next_unit, "mature checkpoint next unit");
  let expectedAdmissionDigest;
  if (currentOpenNextUnit) {
    exactKeys(value.next_unit, [
      "profile", "kind", "admission_digest", "generation_id",
      "current_open_receipt_digest", "current_open_projection_digest",
      "production_candidate_authority_digest", "candidate_count",
      "candidate_set_digest", "source_current_open_semantic_digest",
      "lifecycle_candidate_set_digest", "attachment_manifest_digest",
      "stable_command_authority_digest", "trigger_identity_digest",
      "repository_endpoint_receipt_digest", "semantic_record_count",
      "total_commit_budget_required",
      "current_epoch_remaining_commit_capacity",
      "fresh_epoch_remaining_commit_capacity",
    ], "mature current-open checkpoint next unit");
    if (
      value.next_unit.profile !== MATURE_CURRENT_OPEN_NEXT_UNIT_PROFILE ||
      value.next_unit.kind !== "current-open-generation" ||
      value.next_unit.semantic_record_count !== 2 ||
      !CANDIDATE_SOURCE_GENERATION_ID.test(value.next_unit.generation_id)
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_SCHEMA",
        "mature current-open checkpoint next unit is outside its closed profile",
      );
    }
    integerBetween(
      value.next_unit.candidate_count,
      0,
      MAX_V2_CANDIDATE_DISPATCH_CYCLE_ITEMS,
      "mature current-open checkpoint candidate count",
    );
    for (const field of [
      "admission_digest", "current_open_receipt_digest",
      "current_open_projection_digest",
      "production_candidate_authority_digest", "candidate_set_digest",
      "source_current_open_semantic_digest",
      "lifecycle_candidate_set_digest", "attachment_manifest_digest",
      "stable_command_authority_digest", "trigger_identity_digest",
      "repository_endpoint_receipt_digest",
    ]) digest(value.next_unit[field],
      `mature current-open checkpoint next unit ${field}`);
    positiveInteger(
      value.next_unit.total_commit_budget_required,
      "mature current-open checkpoint total commit budget",
    );
    integerBetween(
      value.next_unit.current_epoch_remaining_commit_capacity,
      -MAX_V2_GIT_LEDGER_COMMITS,
      -1,
      "mature current-open checkpoint current epoch remaining capacity",
    );
    integerBetween(
      value.next_unit.fresh_epoch_remaining_commit_capacity,
      0,
      MAX_V2_GIT_LEDGER_COMMITS,
      "mature current-open checkpoint fresh epoch remaining capacity",
    );
    const admissionFacts = {
      schema: V2_GIT_LEDGER_CURRENT_OPEN_CHECKPOINT_ADMISSION_SCHEMA,
      schema_version: 1,
      profile: value.next_unit.profile,
      repository: structuredClone(repository),
      ledger_ref: ledgerRef,
      source_load_digest: value.source.source_load_digest,
      next_unit_kind: value.next_unit.kind,
      generation_id: value.next_unit.generation_id,
      current_open_receipt_digest:
        value.next_unit.current_open_receipt_digest,
      current_open_projection_digest:
        value.next_unit.current_open_projection_digest,
      production_candidate_authority_digest:
        value.next_unit.production_candidate_authority_digest,
      candidate_count: value.next_unit.candidate_count,
      candidate_set_digest: value.next_unit.candidate_set_digest,
      source_current_open_semantic_digest:
        value.next_unit.source_current_open_semantic_digest,
      lifecycle_candidate_set_digest:
        value.next_unit.lifecycle_candidate_set_digest,
      attachment_manifest_digest:
        value.next_unit.attachment_manifest_digest,
      stable_command_authority_digest:
        value.next_unit.stable_command_authority_digest,
      trigger_identity_digest: value.next_unit.trigger_identity_digest,
      repository_endpoint_receipt_digest:
        value.next_unit.repository_endpoint_receipt_digest,
      total_commit_budget_required:
        value.next_unit.total_commit_budget_required,
      current_epoch_remaining_commit_capacity:
        value.next_unit.current_epoch_remaining_commit_capacity,
      fresh_epoch_remaining_commit_capacity:
        value.next_unit.fresh_epoch_remaining_commit_capacity,
    };
    expectedAdmissionDigest = digestCanonical(
      "codex-review-gate-v2-current-open-checkpoint-admission",
      admissionFacts,
    );
  } else {
    exactKeys(value.next_unit, [
      "kind", "admission_digest", "cycle_id",
      "stable_cycle_receipt_digest", "stable_command_authority_digest",
      "trigger_identity_digest", "projection_digest",
      "classification_projection", "semantic_record_count",
      "total_commit_budget_required",
      "current_epoch_remaining_commit_capacity",
      "fresh_epoch_remaining_commit_capacity",
    ], "mature checkpoint next unit");
    if (
      value.next_unit.kind !== "candidate-inventory-cycle" ||
      value.next_unit.semantic_record_count < 4 ||
      value.next_unit.semantic_record_count > MAX_V2_CANDIDATE_SCAN_PASSES + 3
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_SCHEMA",
        "mature checkpoint next unit is outside its closed profile",
      );
    }
    boundedString(value.next_unit.cycle_id, "mature checkpoint cycle_id", 128);
    for (const field of [
      "admission_digest", "stable_cycle_receipt_digest",
      "stable_command_authority_digest", "trigger_identity_digest",
      "projection_digest",
    ]) digest(value.next_unit[field], `mature checkpoint next unit ${field}`);
    positiveInteger(
      value.next_unit.total_commit_budget_required,
      "mature checkpoint next unit total commit budget",
    );
    integerBetween(
      value.next_unit.current_epoch_remaining_commit_capacity,
      -MAX_V2_GIT_LEDGER_COMMITS,
      MAX_V2_GIT_LEDGER_COMMITS,
      "mature checkpoint current epoch remaining capacity",
    );
    integerBetween(
      value.next_unit.fresh_epoch_remaining_commit_capacity,
      -MAX_V2_GIT_LEDGER_COMMITS,
      MAX_V2_GIT_LEDGER_COMMITS,
      "mature checkpoint fresh epoch remaining capacity",
    );
    const classification =
      validateCandidateInventoryCycleClassificationProjection(
        value.next_unit.classification_projection,
      );
    const classificationDigest = classification.projection_digest;
    if (
      digest(classificationDigest,
        "mature checkpoint classification digest") !==
        value.next_unit.projection_digest ||
      classification.state !== "checkpoint-required" ||
      classification.source_tip_commit_sha !== value.source.tip_commit_sha ||
      classification.source_commit_count !== value.source.commit_count ||
      classification.total_commit_budget_required !==
        value.next_unit.total_commit_budget_required ||
      classification.remaining_ledger_commit_capacity_after_dispatch !==
        value.next_unit.current_epoch_remaining_commit_capacity
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_PROJECTION",
        "mature checkpoint classification differs from admission",
      );
    }
    const admissionFacts = {
      schema: V2_GIT_LEDGER_CHECKPOINT_NEXT_UNIT_ADMISSION_HANDLE_SCHEMA,
      schema_version: 1,
      repository: structuredClone(repository),
      ledger_ref: ledgerRef,
      source_load_digest: value.source.source_load_digest,
      next_unit_kind: value.next_unit.kind,
      cycle_id: value.next_unit.cycle_id,
      stable_cycle_receipt_digest:
        value.next_unit.stable_cycle_receipt_digest,
      stable_command_authority_digest:
        value.next_unit.stable_command_authority_digest,
      trigger_identity_digest: value.next_unit.trigger_identity_digest,
      projection_digest: value.next_unit.projection_digest,
      total_commit_budget_required:
        value.next_unit.total_commit_budget_required,
      current_epoch_remaining_commit_capacity:
        value.next_unit.current_epoch_remaining_commit_capacity,
      fresh_epoch_remaining_commit_capacity:
        value.next_unit.fresh_epoch_remaining_commit_capacity,
    };
    expectedAdmissionDigest = digestCanonical(
      "codex-review-gate-v2-checkpoint-next-unit-admission",
      admissionFacts,
    );
  }
  if (value.next_unit.admission_digest !== expectedAdmissionDigest) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_ADMISSION",
      "mature checkpoint next-unit admission digest is invalid",
    );
  }
  digest(value.checkpoint_state_digest, "mature checkpoint state digest");
  const { checkpoint_state_digest: _checkpointStateDigest, ...withoutDigest } =
    value;
  if (value.checkpoint_state_digest !== digestCanonical(
    "codex-review-gate-v2-checkpoint-state",
    withoutDigest,
  )) {
    throw ledgerError(
      "CHECKPOINT_STATE_DIGEST",
      "mature checkpoint state digest is invalid",
    );
  }
  return deepFreeze(structuredClone(value));
}

function matureCheckpointStateTreeLayout(checkpointState, sourceSeedBundle) {
  validateMatureCheckpointState(checkpointState);
  if (
    checkpointState.source.query_seed_tree_sha !==
      sourceSeedBundle.source_tree_sha ||
    canonicalJson(checkpointState.source.query_seed_manifest) !==
      canonicalJson(sourceSeedBundle.manifest)
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEED_BINDING",
      "mature checkpoint state differs from its source seed tree",
    );
  }
  const stateBytes = Buffer.from(`${canonicalJson(checkpointState)}\n`, "utf8");
  if (stateBytes.byteLength > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError(
      "CHECKPOINT_STATE_SIZE",
      "mature checkpoint state exceeds its Git blob cap",
    );
  }
  const stateBlobSha = gitObjectSha("blob", stateBytes);
  const entries = [{
    path: V2_GIT_LEDGER_CHECKPOINT_SOURCE_SEED_PATH,
    mode: "040000",
    type: "tree",
    sha: sourceSeedBundle.source_tree_sha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_STATE_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: stateBlobSha,
  }];
  return {
    state_bytes: stateBytes,
    state_blob_sha: stateBlobSha,
    entries,
    tree_sha: canonicalGitTreeSha(entries),
  };
}

function planMatureCheckpointObjects({
  checkpointState,
  sourceSeedBundle,
  carrier,
  sourceTipCommitSha,
}) {
  const stateLayout = matureCheckpointStateTreeLayout(
    checkpointState,
    sourceSeedBundle,
  );
  if (carrier.payload.checkpoint_state_tree_sha !== stateLayout.tree_sha) {
    throw ledgerError(
      "CHECKPOINT_STATE_TREE_BINDING",
      "mature checkpoint carrier does not bind its state tree",
    );
  }
  const carrierBytes = Buffer.from(`${canonicalJson(carrier)}\n`, "utf8");
  if (carrierBytes.byteLength > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError(
      "CHECKPOINT_CARRIER_SIZE",
      "mature checkpoint carrier exceeds its Git blob cap",
    );
  }
  const carrierBlobSha = gitObjectSha("blob", carrierBytes);
  const rootEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: carrierBlobSha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_STATE_PATH,
    mode: "040000",
    type: "tree",
    sha: stateLayout.tree_sha,
  }];
  const rootTreeSha = canonicalGitTreeSha(rootEntries);
  const message = "Codex Review Gate v2: epoch-checkpoint #0";
  const commitBody = {
    message,
    tree: rootTreeSha,
    parents: [sourceTipCommitSha],
    author: { ...COMMIT_AUTHOR, date: carrier.server_observed_at },
    committer: { ...COMMIT_AUTHOR, date: carrier.server_observed_at },
  };
  const commitSha = gitObjectSha("commit", canonicalGitCommitBytes({
    treeSha: rootTreeSha,
    parents: [sourceTipCommitSha],
    message,
    serverTime: carrier.server_observed_at,
  }));
  const requests = [
    ...sourceSeedBundle.chunks.map((chunk) => ({
      kind: "blob",
      expected_sha: chunk.blob_sha,
      body: { content: chunk.bytes.toString("base64"), encoding: "base64" },
    })),
    {
      kind: "tree",
      expected_sha: sourceSeedBundle.manifest.chunk_tree_sha,
      body: { tree: structuredClone(sourceSeedBundle.chunk_tree_entries) },
    },
    {
      kind: "blob",
      expected_sha: sourceSeedBundle.manifest_blob_sha,
      body: {
        content: sourceSeedBundle.manifest_bytes.toString("utf8"),
        encoding: "utf-8",
      },
    },
    {
      kind: "tree",
      expected_sha: sourceSeedBundle.source_tree_sha,
      body: { tree: structuredClone(sourceSeedBundle.source_tree_entries) },
    },
    {
      kind: "blob",
      expected_sha: stateLayout.state_blob_sha,
      body: { content: stateLayout.state_bytes.toString("utf8"), encoding: "utf-8" },
    },
    {
      kind: "tree",
      expected_sha: stateLayout.tree_sha,
      body: { tree: structuredClone(stateLayout.entries) },
    },
    {
      kind: "blob",
      expected_sha: carrierBlobSha,
      body: { content: carrierBytes.toString("utf8"), encoding: "utf-8" },
    },
    {
      kind: "tree",
      expected_sha: rootTreeSha,
      body: { tree: rootEntries },
    },
    { kind: "commit", expected_sha: commitSha, body: commitBody },
  ];
  return deepFreeze({
    commit_sha: commitSha,
    tree_sha: rootTreeSha,
    carrier_blob_sha: carrierBlobSha,
    state_tree_sha: stateLayout.tree_sha,
    state_blob_sha: stateLayout.state_blob_sha,
    source_seed_tree_sha: sourceSeedBundle.source_tree_sha,
    requests,
  });
}

function buildBootstrapCheckpointState({
  repository,
  ledgerRef,
  epochId,
  rawSource,
  sourceLoadHandle,
  admissionHandle,
  admissionPrivate,
  capability,
  prefixFrontier,
}) {
  const sourceManifest = checkpointRecordManifest(rawSource.records);
  const sourceAttestation = rawSource.records.find((entry) =>
    entry.commit_sha === sourceLoadHandle.capability_attestation_commit_sha);
  if (
    sourceAttestation?.envelope.record_type !== "capability-attestation" ||
    rawSource.latest_capability === null
  ) {
    throw checkpointBoundaryError(
      "checkpoint source lacks its exact bootstrap capability activation",
    );
  }
  const capabilityActivation = {
    attestation_commit_sha:
      rawSource.latest_capability.attestation_commit_sha,
    capability_input_digest:
      rawSource.latest_capability.capability_input_digest,
    capability_stable_digest:
      rawSource.latest_capability.capability_stable_digest,
    capability_receipt:
      structuredClone(rawSource.latest_capability.capability_receipt),
    protection_receipt_digest:
      rawSource.latest_capability.protection_receipt_digest,
    controller_release:
      structuredClone(rawSource.latest_capability.controller_release),
    oidc_attestation_digest:
      sourceAttestation.envelope.workflow_provenance.receipt_digest,
  };
  const withoutDigest = {
    schema: V2_GIT_LEDGER_CHECKPOINT_STATE_SCHEMA,
    schema_version: 1,
    profile: CHECKPOINT_PROFILE,
    repository: structuredClone(repository),
    ledger_ref: ledgerRef,
    epoch_id: epochId,
    epoch_sequence: 0,
    source: {
      tip_commit_sha: rawSource.tip_commit_sha,
      genesis_commit_sha: rawSource.genesis_commit_sha,
      commit_count: rawSource.records.length,
      source_load_digest: sourceLoadHandle.source_load_digest,
      record_manifest_digest: digestCanonical(
        "codex-review-gate-v2-fully-reachable-record-manifest",
        sourceManifest,
      ),
      rolling_audit_root: checkpointRollingAuditRoot(rawSource.records),
      provenance_reverification_digest: digestCanonical(
        "codex-review-gate-v2-git-ledger-provenance-reverification-inventory",
        rawSource.provenance_reverification,
      ),
      capability_attestation_commit_sha:
        sourceLoadHandle.capability_attestation_commit_sha,
      stable_capability_digest:
        digestV2GitLedgerStableCapabilityAuthorization(capability),
      capability_activation: capabilityActivation,
      query_records: rawSource.records.map(redactRecordEntry),
      provenance_reverification:
        structuredClone(rawSource.provenance_reverification),
      observed_at: rawSource.observed_at,
    },
    next_unit: {
      kind: admissionHandle.next_unit_kind,
      admission_digest: admissionHandle.next_unit_admission_digest,
      cycle_id: admissionHandle.cycle_id,
      stable_cycle_receipt_digest:
        admissionHandle.stable_cycle_receipt_digest,
      stable_command_authority_digest:
        admissionHandle.stable_command_authority_digest,
      trigger_identity_digest: admissionHandle.trigger_identity_digest,
      projection_digest: admissionHandle.projection_digest,
      classification_projection:
        structuredClone(admissionPrivate.projection),
      semantic_record_count: admissionPrivate.drift_attempts.length + 4,
      total_commit_budget_required:
        admissionHandle.total_commit_budget_required,
      current_epoch_remaining_commit_capacity:
        admissionHandle.current_epoch_remaining_commit_capacity,
      fresh_epoch_remaining_commit_capacity:
        admissionHandle.fresh_epoch_remaining_commit_capacity,
    },
    prefix_frontier: structuredClone(prefixFrontier.manifest),
    empty_frontiers: bootstrapCheckpointEmptyFrontiers(epochId),
  };
  return deepFreeze({
    ...withoutDigest,
    checkpoint_state_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-state",
      withoutDigest,
    ),
  });
}

function validateBootstrapCheckpointSourceProvenanceEvidence(
  value,
  record,
  capability,
  index,
) {
  const label = `checkpoint source provenance evidence ${index}`;
  try {
    assertObject(value, label);
    exactKeys(value, [
      "record_oid", "stored_receipt_digest", "live_receipt_digest",
      "token_sha256", "key_id", "verified_at_server_time",
      "discovery", "jwks", "evidence_digest",
    ], label);
    sha(value.record_oid, `${label}.record_oid`);
    for (const field of [
      "stored_receipt_digest", "live_receipt_digest", "token_sha256",
      "evidence_digest",
    ]) digest(value[field], `${label}.${field}`);
    boundedString(value.key_id, `${label}.key_id`, 512);
    timestamp(value.verified_at_server_time,
      `${label}.verified_at_server_time`);
    const storedReceipt = record.envelope.workflow_provenance;
    const reconstructedLiveReceipt = {
      ...structuredClone(storedReceipt),
      discovery: structuredClone(value.discovery),
      jwks: structuredClone(value.jwks),
      receipt_digest: value.live_receipt_digest,
    };
    const provenanceRequest = validateProvenanceRequest({
      schema: V2_GIT_LEDGER_PROVENANCE_REQUEST_SCHEMA,
      schema_version: 1,
      ...structuredClone(storedReceipt.operation_binding),
    });
    validateV2GitLedgerProvenanceReceipt(reconstructedLiveReceipt, {
      request: provenanceRequest,
      policy: capability.workflow_provenance_policy,
    });
    validateReverifiedProvenanceStableFields(
      storedReceipt,
      reconstructedLiveReceipt,
    );
    validateReverifiedProvenanceAgainstPolicy(
      reconstructedLiveReceipt,
      capability.workflow_provenance_policy,
    );
    const { evidence_digest: _evidenceDigest, ...withoutDigest } = value;
    if (
      value.record_oid !== record.commit_sha ||
      value.stored_receipt_digest !== storedReceipt.receipt_digest ||
      value.token_sha256 !== storedReceipt.token_sha256 ||
      value.key_id !== storedReceipt.key_id ||
      value.verified_at_server_time !==
        storedReceipt.verified_at_server_time ||
      digestCanonical(
        "codex-review-gate-v2-git-ledger-provenance-reverification",
        withoutDigest,
      ) !== value.evidence_digest
    ) {
      throw new Error(`${label} differs from its query record`);
    }
  } catch (error) {
    if (error?.code === "CHECKPOINT_SOURCE_PROVENANCE_EVIDENCE") throw error;
    throw ledgerError(
      "CHECKPOINT_SOURCE_PROVENANCE_EVIDENCE",
      `${label} is not exact stored-to-live verification evidence`,
      error,
    );
  }
}

function validateBootstrapCheckpointSourceQuery({
  records,
  provenanceReverification,
  repository,
  ledgerRef,
  observedAt,
}) {
  validateReachableChain(records, observedAt);
  for (let index = 0; index < records.length; index += 1) {
    const record = records[index];
    const envelope = record.envelope;
    const capability = envelope.record_type === "capability-attestation"
      ? validateEmbeddedCapability(envelope.payload, repository, ledgerRef)
      : validateEmbeddedBootstrapCandidate(
        envelope.payload,
        repository,
        ledgerRef,
      );
    if (
      canonicalJson(envelope.repository) !== canonicalJson(repository) ||
      envelope.ledger_ref !== ledgerRef ||
      canonicalJson(envelope.source_workflow) !==
        canonicalJson(sourceWorkflow(capability.controller_release)) ||
      !provenanceMatchesExpected(envelope.workflow_provenance, {
        repository,
        ledger_ref: ledgerRef,
        source_workflow: sourceWorkflow(capability.controller_release),
        provenance_policy: provenanceExpected(capability),
      })
    ) {
      throw ledgerError(
        "CHECKPOINT_SOURCE_PROVENANCE_BINDING",
        "checkpoint query record differs from its embedded source authority",
      );
    }
    if (
      envelope.record_type === "capability-attestation" &&
      (
        envelope.payload.protection_receipt_digest !==
          capability.protection.live_ruleset_receipt_digest ||
        canonicalJson(envelope.payload.controller_release) !==
          canonicalJson(capability.controller_release)
      )
    ) {
      throw ledgerError(
        "CHECKPOINT_SOURCE_CAPABILITY_BINDING",
        "checkpoint attestation does not activate its embedded capability",
      );
    }
    validateBootstrapCheckpointSourceProvenanceEvidence(
      provenanceReverification[index],
      record,
      capability,
      index,
    );
  }
}

function validateBootstrapCheckpointState(value) {
  assertObject(value, "checkpoint state");
  exactKeys(value, [
    "schema", "schema_version", "profile", "repository", "ledger_ref",
    "epoch_id", "epoch_sequence", "source", "next_unit",
    "prefix_frontier", "empty_frontiers", "checkpoint_state_digest",
  ], "checkpoint state");
  if (
    value.schema !== V2_GIT_LEDGER_CHECKPOINT_STATE_SCHEMA ||
    value.schema_version !== 1 || value.profile !== CHECKPOINT_PROFILE ||
    value.epoch_sequence !== 0
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_SCHEMA",
      "checkpoint state schema or profile is unsupported",
    );
  }
  normalizeRepository(value.repository);
  normalizeLedgerRef(value.ledger_ref);
  digest(value.epoch_id, "checkpoint state epoch_id");
  assertObject(value.source, "checkpoint state source");
  exactKeys(value.source, [
    "tip_commit_sha", "genesis_commit_sha", "commit_count",
    "source_load_digest", "record_manifest_digest", "rolling_audit_root",
    "provenance_reverification_digest", "capability_attestation_commit_sha",
    "stable_capability_digest", "capability_activation", "query_records",
    "provenance_reverification", "observed_at",
  ], "checkpoint state source");
  sha(value.source.tip_commit_sha, "checkpoint source tip");
  sha(value.source.genesis_commit_sha, "checkpoint source genesis");
  if (value.source.commit_count !== 3) {
    throw checkpointBoundaryError(
      "checkpoint state does not represent the exact bootstrap prefix",
    );
  }
  for (const field of [
    "source_load_digest", "record_manifest_digest", "rolling_audit_root",
    "provenance_reverification_digest", "stable_capability_digest",
  ]) digest(value.source[field], `checkpoint source ${field}`);
  sha(
    value.source.capability_attestation_commit_sha,
    "checkpoint source capability attestation",
  );
  assertObject(
    value.source.capability_activation,
    "checkpoint source capability activation",
  );
  exactKeys(value.source.capability_activation, [
    "attestation_commit_sha", "capability_input_digest",
    "capability_stable_digest", "capability_receipt",
    "protection_receipt_digest", "controller_release",
    "oidc_attestation_digest",
  ], "checkpoint source capability activation");
  const activation = value.source.capability_activation;
  sha(
    activation.attestation_commit_sha,
    "checkpoint capability activation attestation",
  );
  for (const field of [
    "capability_input_digest", "capability_stable_digest",
    "protection_receipt_digest", "oidc_attestation_digest",
  ]) {
    digest(activation[field], `checkpoint capability activation ${field}`);
  }
  const embeddedCapability = validateV2GitLedgerCapabilityReceipt(
    activation.capability_receipt,
    { repository: value.repository, ledger_ref: value.ledger_ref },
  );
  const embeddedRelease = normalizeControllerRelease(
    activation.controller_release,
  );
  if (
    activation.attestation_commit_sha !==
      value.source.capability_attestation_commit_sha ||
    activation.capability_stable_digest !==
      value.source.stable_capability_digest ||
    activation.capability_stable_digest !==
      digestV2GitLedgerStableCapabilityAuthorization(embeddedCapability) ||
    activation.capability_input_digest !==
      capabilityBindingDigest(embeddedCapability) ||
    activation.protection_receipt_digest !==
      embeddedCapability.protection.live_ruleset_receipt_digest ||
    canonicalJson(embeddedRelease) !==
      canonicalJson(embeddedCapability.controller_release)
  ) {
    throw ledgerError(
      "CHECKPOINT_CAPABILITY_ACTIVATION",
      "checkpoint capability activation differs from its authenticated source",
    );
  }
  if (
    !Array.isArray(value.source.query_records) ||
    value.source.query_records.length !== 3 ||
    !Array.isArray(value.source.provenance_reverification) ||
    value.source.provenance_reverification.length !== 3
  ) {
    throw checkpointBoundaryError(
      "checkpoint query seed is not the exact bounded bootstrap prefix",
    );
  }
  const queryRecords = value.source.query_records;
  const sourceObservedAt = timestamp(
    value.source.observed_at,
    "checkpoint source observed_at",
  );
  if (sourceObservedAt !== value.source.observed_at) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_TIME",
      "checkpoint source observation time is not canonical",
    );
  }
  const queryTypes = ["genesis", "capability-canary", "capability-attestation"];
  for (let index = 0; index < queryRecords.length; index += 1) {
    const entry = queryRecords[index];
    assertObject(entry, `checkpoint query record ${index}`);
    exactKeys(entry, [
      "commit_sha", "parents", "tree_sha", "blob_sha", "envelope",
      "evidence",
    ], `checkpoint query record ${index}`);
    sha(entry.commit_sha, `checkpoint query record ${index} commit`);
    sha(entry.tree_sha, `checkpoint query record ${index} tree`);
    sha(entry.blob_sha, `checkpoint query record ${index} blob`);
    validateV2GitLedgerPublicEnvelope(entry.envelope);
    validateCanonicalJsonValue(
      entry.evidence,
      `checkpoint query record ${index} evidence`,
    );
    if (
      entry.envelope.record_type !== queryTypes[index] ||
      entry.envelope.sequence !== index ||
      canonicalJson(entry.envelope.repository) !==
        canonicalJson(value.repository) ||
      entry.envelope.ledger_ref !== value.ledger_ref ||
      canonicalJson(entry.parents) !== canonicalJson(
        index === 0 ? [] : [queryRecords[index - 1].commit_sha],
      ) ||
      entry.envelope.predecessor_commit_sha !==
        (index === 0 ? null : queryRecords[index - 1].commit_sha)
    ) {
      throw checkpointBoundaryError(
        "checkpoint query records are not one exact bootstrap chain",
      );
    }
  }
  if (
    queryRecords[0].commit_sha !== value.source.genesis_commit_sha ||
    queryRecords[2].commit_sha !== value.source.tip_commit_sha ||
    digestCanonical(
      "codex-review-gate-v2-fully-reachable-record-manifest",
      checkpointRecordManifest(queryRecords),
    ) !== value.source.record_manifest_digest ||
    checkpointRollingAuditRoot(queryRecords) !==
      value.source.rolling_audit_root ||
    digestCanonical(
      "codex-review-gate-v2-git-ledger-provenance-reverification-inventory",
      value.source.provenance_reverification,
    ) !== value.source.provenance_reverification_digest ||
    queryRecords[2].envelope.workflow_provenance.receipt_digest !==
      activation.oidc_attestation_digest ||
    queryRecords[2].envelope.payload.capability_input_digest !==
      activation.capability_input_digest ||
    queryRecords[2].envelope.payload.capability_stable_digest !==
      activation.capability_stable_digest ||
    canonicalJson(queryRecords[2].envelope.payload.capability_receipt) !==
      canonicalJson(activation.capability_receipt)
  ) {
    throw ledgerError(
      "CHECKPOINT_QUERY_SEED",
      "checkpoint query seed differs from its authenticated source facts",
    );
  }
  validateBootstrapCheckpointSourceQuery({
    records: queryRecords,
    provenanceReverification: value.source.provenance_reverification,
    repository: value.repository,
    ledgerRef: value.ledger_ref,
    observedAt: sourceObservedAt,
  });
  assertObject(value.next_unit, "checkpoint next unit");
  exactKeys(value.next_unit, [
    "kind", "admission_digest", "cycle_id",
    "stable_cycle_receipt_digest", "stable_command_authority_digest",
    "trigger_identity_digest", "projection_digest",
    "classification_projection", "semantic_record_count",
    "total_commit_budget_required",
    "current_epoch_remaining_commit_capacity",
    "fresh_epoch_remaining_commit_capacity",
  ], "checkpoint next unit");
  if (
    value.next_unit.kind !== "candidate-inventory-cycle" ||
    value.next_unit.semantic_record_count < 4 ||
    value.next_unit.semantic_record_count > MAX_V2_CANDIDATE_SCAN_PASSES + 3
  ) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_SCHEMA",
      "checkpoint next unit is outside the closed candidate-cycle profile",
    );
  }
  boundedString(value.next_unit.cycle_id, "checkpoint next unit cycle_id", 128);
  for (const field of [
    "admission_digest", "stable_cycle_receipt_digest",
    "stable_command_authority_digest", "trigger_identity_digest",
    "projection_digest",
  ]) digest(value.next_unit[field], `checkpoint next unit ${field}`);
  positiveInteger(
    value.next_unit.total_commit_budget_required,
    "checkpoint next unit total commit budget",
  );
  integerBetween(
    value.next_unit.current_epoch_remaining_commit_capacity,
    -MAX_V2_GIT_LEDGER_COMMITS,
    MAX_V2_GIT_LEDGER_COMMITS,
    "checkpoint next unit current epoch remaining capacity",
  );
  integerBetween(
    value.next_unit.fresh_epoch_remaining_commit_capacity,
    -MAX_V2_GIT_LEDGER_COMMITS,
    MAX_V2_GIT_LEDGER_COMMITS,
    "checkpoint next unit fresh epoch remaining capacity",
  );
  assertObject(
    value.next_unit.classification_projection,
    "checkpoint next unit classification projection",
  );
  const classification =
    validateCandidateInventoryCycleClassificationProjection(
      value.next_unit.classification_projection,
    );
  const classificationDigest = classification.projection_digest;
  if (
    digest(classificationDigest, "checkpoint classification projection") !==
      value.next_unit.projection_digest ||
    classification.state !== "checkpoint-required" ||
    classification.source_tip_commit_sha !== value.source.tip_commit_sha ||
    classification.source_commit_count !== value.source.commit_count ||
    classification.total_commit_budget_required !==
      value.next_unit.total_commit_budget_required ||
    classification.remaining_ledger_commit_capacity_after_dispatch !==
      value.next_unit.current_epoch_remaining_commit_capacity
  ) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_PROJECTION",
      "checkpoint next-unit classification is not its authenticated admission",
    );
  }
  const admissionFacts = {
    schema: V2_GIT_LEDGER_CHECKPOINT_NEXT_UNIT_ADMISSION_HANDLE_SCHEMA,
    schema_version: 1,
    repository: structuredClone(value.repository),
    ledger_ref: value.ledger_ref,
    source_load_digest: value.source.source_load_digest,
    next_unit_kind: value.next_unit.kind,
    cycle_id: value.next_unit.cycle_id,
    stable_cycle_receipt_digest:
      value.next_unit.stable_cycle_receipt_digest,
    stable_command_authority_digest:
      value.next_unit.stable_command_authority_digest,
    trigger_identity_digest: value.next_unit.trigger_identity_digest,
    projection_digest: value.next_unit.projection_digest,
    total_commit_budget_required:
      value.next_unit.total_commit_budget_required,
    current_epoch_remaining_commit_capacity:
      value.next_unit.current_epoch_remaining_commit_capacity,
    fresh_epoch_remaining_commit_capacity:
      value.next_unit.fresh_epoch_remaining_commit_capacity,
  };
  if (value.next_unit.admission_digest !== digestCanonical(
    "codex-review-gate-v2-checkpoint-next-unit-admission",
    admissionFacts,
  )) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_ADMISSION",
      "checkpoint next-unit admission digest cannot be independently replayed",
    );
  }
  validateCheckpointPrefixFrontierManifest(value.prefix_frontier);
  assertObject(value.empty_frontiers, "checkpoint empty frontiers");
  exactKeys(
    value.empty_frontiers,
    Object.keys(CHECKPOINT_EMPTY_FRONTIER_DOMAINS),
    "checkpoint empty frontiers",
  );
  for (const [name, domain] of Object.entries(
    CHECKPOINT_EMPTY_FRONTIER_DOMAINS,
  )) {
    const expected = createV2PersistentMerkleMap({
      domain,
      epoch_id: value.epoch_id,
      readBlob: async () => null,
      writeBlob: async () => null,
    }).emptyRoot();
    if (canonicalJson(value.empty_frontiers[name]) !== canonicalJson(expected)) {
      throw ledgerError(
        "CHECKPOINT_EMPTY_FRONTIER_MISMATCH",
        "checkpoint empty frontier root is not canonical",
      );
    }
  }
  digest(value.checkpoint_state_digest, "checkpoint state digest");
  const { checkpoint_state_digest: _digest, ...withoutDigest } = value;
  if (value.checkpoint_state_digest !== digestCanonical(
    "codex-review-gate-v2-checkpoint-state",
    withoutDigest,
  )) {
    throw ledgerError(
      "CHECKPOINT_STATE_DIGEST",
      "checkpoint state digest is invalid",
    );
  }
  return deepFreeze(structuredClone(value));
}

function bootstrapCheckpointQuerySeedDigest(checkpointState) {
  return digestCanonical(
    "codex-review-gate-v2-bootstrap-checkpoint-query-seed",
    {
      profile: checkpointState.profile,
      repository: checkpointState.repository,
      ledger_ref: checkpointState.ledger_ref,
      epoch_id: checkpointState.epoch_id,
      source: checkpointState.source,
      prefix_frontier: checkpointState.prefix_frontier,
      empty_frontiers: checkpointState.empty_frontiers,
    },
  );
}

function checkpointLatestCapabilitySeed(checkpointState) {
  const activation = checkpointState.source.capability_activation;
  return deepFreeze({
    attestation_commit_sha: activation.attestation_commit_sha,
    capability_input_digest: activation.capability_input_digest,
    capability_stable_digest: activation.capability_stable_digest,
    capability_receipt: structuredClone(activation.capability_receipt),
    protection_receipt_digest: activation.protection_receipt_digest,
    controller_release: structuredClone(activation.controller_release),
    payload: null,
  });
}

function validateCheckpointCapabilityAgainstFactory(
  checkpointState,
  capability,
) {
  const activation = checkpointState.source.capability_activation;
  if (
    checkpointState.source.stable_capability_digest !==
      digestV2GitLedgerStableCapabilityAuthorization(capability) ||
    activation.capability_stable_digest !==
      digestV2GitLedgerStableCapabilityAuthorization(capability) ||
    activation.protection_receipt_digest !==
      capability.protection.live_ruleset_receipt_digest ||
    canonicalJson(activation.controller_release) !==
      canonicalJson(capability.controller_release)
  ) {
    throw ledgerError(
      "CHECKPOINT_CAPABILITY_MISMATCH",
      "checkpoint capability seed differs from this factory authority",
    );
  }
  return checkpointLatestCapabilitySeed(checkpointState);
}

function bootstrapCheckpointAuthorityDigest(authority) {
  const stableOrderedRecords = authority.ordered_records.map((entry) => {
    const { evidence: _readEvidence, ...stableEntry } = entry;
    return stableEntry;
  });
  return digestCanonical(
    "codex-review-gate-v2-bootstrap-checkpoint-future-authority",
    {
      schema: authority.schema,
      schema_version: authority.schema_version,
      scope: authority.scope,
      ordered_records: stableOrderedRecords,
      authority_facts: authority.authority_facts,
      scope_counters: authority.scope_counters,
      control_comment_binding: authority.control_comment_binding,
      candidate_inventory: authority.candidate_inventory,
      candidate_dispatch: authority.candidate_dispatch,
      runner_state: authority.runner_state,
      source_projection_digest: authority.source_projection_digest,
    },
  );
}

function bootstrapCheckpointFutureState({
  checkpointCommitSha,
  checkpointState,
  suffixRecords,
  projectedState,
  firstDispatchPlan,
}) {
  const epochRecordOffset = 1;
  const epochCommitCount = epochRecordOffset + suffixRecords.length;
  const nextSequence = suffixRecords.at(-1).envelope.sequence + 1;
  if (nextSequence !== epochCommitCount) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_SEQUENCE",
      "checkpoint future state sequence differs from its epoch commit count",
    );
  }
  const querySeedDigest = bootstrapCheckpointQuerySeedDigest(checkpointState);
  const withoutDigest = {
    profile: CHECKPOINT_PROFILE,
    epoch_id: checkpointState.epoch_id,
    epoch_root_commit_sha: checkpointCommitSha,
    epoch_record_offset: epochRecordOffset,
    epoch_commit_count: epochCommitCount,
    next_sequence: nextSequence,
    logical_record_count:
      checkpointState.source.commit_count + epochCommitCount,
    checkpoint_state_digest: checkpointState.checkpoint_state_digest,
    query_seed_digest: querySeedDigest,
    suffix_tip_commit_sha: suffixRecords.at(-1).commit_sha,
    source_projection_digest: projectedState.projection.projection_digest,
    authority_projection_digest:
      bootstrapCheckpointAuthorityDigest(
        projectedState.authority_projection,
      ),
    candidate_inventory_authority_digest:
      projectedState.authority_projection.candidate_inventory.authority_digest,
    candidate_dispatch_authority_digest:
      projectedState.authority_projection.candidate_dispatch.authority_digest,
    first_dispatch_plan_digest: firstDispatchPlan?.plan_digest ?? null,
    active_lease: projectedState.active_lease,
    control_comment_binding: projectedState.control_comment_binding,
    effect_intent_count: projectedState.effect_intent_count,
    effect_response_count: projectedState.effect_response_count,
  };
  return deepFreeze({
    ...withoutDigest,
    future_state_digest: digestCanonical(
      "codex-review-gate-v2-bootstrap-checkpoint-future-state",
      withoutDigest,
    ),
  });
}

function matureCheckpointFutureState({
  checkpointCommitSha,
  checkpointState,
  suffixRecords,
  projectedState,
  firstDispatchPlan,
}) {
  const epochRecordOffset = 1;
  const epochCommitCount = epochRecordOffset + suffixRecords.length;
  const nextSequence = suffixRecords.at(-1).envelope.sequence + 1;
  if (
    nextSequence !== epochCommitCount ||
    checkpointState.source.logical_record_count + suffixRecords.length >
      MAX_V2_GIT_LEDGER_SEMANTIC_RECORDS
  ) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_SEQUENCE",
      "mature checkpoint future state exceeds its physical or semantic cap",
    );
  }
  const querySeedDigest = digestCanonical(
    "codex-review-gate-v2-mature-checkpoint-query-seed",
    {
      profile: checkpointState.profile,
      repository: checkpointState.repository,
      ledger_ref: checkpointState.ledger_ref,
      epoch_id: checkpointState.epoch_id,
      source_tip_commit_sha: checkpointState.source.tip_commit_sha,
      source_seed_tree_sha: checkpointState.source.query_seed_tree_sha,
      source_seed_manifest_digest:
        checkpointState.source.query_seed_manifest.manifest_digest,
      source_seed_digest:
        checkpointState.source.query_seed_manifest.source_seed_digest,
    },
  );
  const withoutDigest = {
    profile: MATURE_CHECKPOINT_PROFILE,
    epoch_id: checkpointState.epoch_id,
    epoch_root_commit_sha: checkpointCommitSha,
    epoch_record_offset: epochRecordOffset,
    epoch_commit_count: epochCommitCount,
    next_sequence: nextSequence,
    logical_record_count:
      checkpointState.source.logical_record_count + epochCommitCount,
    checkpoint_state_digest: checkpointState.checkpoint_state_digest,
    query_seed_digest: querySeedDigest,
    suffix_tip_commit_sha: suffixRecords.at(-1).commit_sha,
    source_projection_digest: projectedState.projection.projection_digest,
    authority_projection_digest:
      bootstrapCheckpointAuthorityDigest(
        projectedState.authority_projection,
      ),
    candidate_inventory_authority_digest:
      projectedState.authority_projection.candidate_inventory.authority_digest,
    candidate_dispatch_authority_digest:
      projectedState.authority_projection.candidate_dispatch.authority_digest,
    first_dispatch_plan_digest: firstDispatchPlan?.plan_digest ?? null,
    active_lease: projectedState.active_lease,
    control_comment_binding: projectedState.control_comment_binding,
    effect_intent_count: projectedState.effect_intent_count,
    effect_response_count: projectedState.effect_response_count,
  };
  return deepFreeze({
    ...withoutDigest,
    future_state_digest: digestCanonical(
      "codex-review-gate-v2-mature-checkpoint-future-state",
      withoutDigest,
    ),
  });
}

function validateCheckpointPrefixFrontierManifest(value) {
  assertObject(value, "checkpoint prefix frontier manifest");
  exactKeys(value, [
    "domain", "root", "tree_sha", "tree_entry_count", "node_count",
    "raw_node_bytes", "oid_set_digest",
  ], "checkpoint prefix frontier manifest");
  if (value.domain !== CHECKPOINT_PREFIX_FRONTIER_DOMAIN) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_DOMAIN",
      "checkpoint prefix frontier domain is invalid",
    );
  }
  sha(value.tree_sha, "checkpoint prefix frontier tree SHA");
  const entryCount = positiveInteger(
    value.tree_entry_count,
    "checkpoint prefix frontier tree entry count",
  );
  const nodeCount = positiveInteger(
    value.node_count,
    "checkpoint prefix frontier node count",
  );
  const rawBytes = positiveInteger(
    value.raw_node_bytes,
    "checkpoint prefix frontier raw bytes",
  );
  digest(value.oid_set_digest, "checkpoint prefix frontier OID set digest");
  if (
    entryCount !== nodeCount ||
    nodeCount > MAX_V2_PERSISTENT_FRONTIER_OPERATION_OBJECTS ||
    rawBytes > MAX_V2_PERSISTENT_FRONTIER_OPERATION_BYTES ||
    value.root?.count !== 9 || nodeCount !== 2 * value.root.count - 1
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_CAP",
      "checkpoint prefix frontier manifest exceeds its closed profile",
    );
  }
  return value;
}

function checkpointCarrierPayload({
  repository,
  ledgerRef,
  epochId,
  sourceTipCommitSha,
  checkpointState,
  stateTreeSha,
}) {
  if (checkpointState.profile === MATURE_CHECKPOINT_PROFILE) {
    const withoutDigest = {
      profile: MATURE_CHECKPOINT_PROFILE,
      repository: structuredClone(repository),
      ledger_ref: ledgerRef,
      epoch_id: epochId,
      epoch_sequence: 0,
      source_parent_commit_sha: sourceTipCommitSha,
      source_commit_count: checkpointState.source.commit_count,
      source_logical_record_count:
        checkpointState.source.logical_record_count,
      checkpoint_state_tree_sha: stateTreeSha,
      checkpoint_state_digest: checkpointState.checkpoint_state_digest,
      source_query_seed_tree_sha:
        checkpointState.source.query_seed_tree_sha,
      source_query_seed_manifest_digest:
        checkpointState.source.query_seed_manifest.manifest_digest,
      next_unit_admission_digest:
        checkpointState.next_unit.admission_digest,
      semantic_record_count: checkpointState.next_unit.semantic_record_count,
    };
    return deepFreeze({
      ...withoutDigest,
      payload_digest: digestCanonical(
        "codex-review-gate-v2-checkpoint-carrier-payload",
        withoutDigest,
      ),
    });
  }
  const withoutDigest = {
    profile: CHECKPOINT_PROFILE,
    repository: structuredClone(repository),
    ledger_ref: ledgerRef,
    epoch_id: epochId,
    epoch_sequence: 0,
    source_parent_commit_sha: sourceTipCommitSha,
    source_commit_count: 3,
    checkpoint_state_tree_sha: stateTreeSha,
    checkpoint_state_digest: checkpointState.checkpoint_state_digest,
    prefix_frontier_tree_sha: checkpointState.prefix_frontier.tree_sha,
    next_unit_admission_digest:
      checkpointState.next_unit.admission_digest,
    semantic_record_count: checkpointState.next_unit.semantic_record_count,
  };
  return deepFreeze({
    ...withoutDigest,
    payload_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-carrier-payload",
      withoutDigest,
    ),
  });
}

function sealCheckpointCarrier({
  payload,
  serverTime,
  sourceWorkflowValue,
  workflowProvenance,
  workflowProvenanceJwt,
}) {
  const base = {
    schema: V2_GIT_LEDGER_CHECKPOINT_CARRIER_SCHEMA,
    schema_version: 1,
    record_type: "epoch-checkpoint",
    server_observed_at: serverTime,
    payload: structuredClone(payload),
    payload_digest: payload.payload_digest,
    source_workflow: structuredClone(sourceWorkflowValue),
    workflow_provenance: structuredClone(workflowProvenance),
    workflow_provenance_jwt: workflowProvenanceJwt,
  };
  return deepFreeze({
    ...base,
    carrier_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-carrier",
      base,
    ),
  });
}

function validateCheckpointCarrier(value, {
  repository,
  ledgerRef,
  sourceTipCommitSha,
  checkpointState,
  stateTreeSha,
  capability,
}) {
  assertObject(value, "checkpoint carrier");
  exactKeys(value, [
    "schema", "schema_version", "record_type", "server_observed_at",
    "payload", "payload_digest", "source_workflow",
    "workflow_provenance", "workflow_provenance_jwt", "carrier_digest",
  ], "checkpoint carrier");
  if (
    value.schema !== V2_GIT_LEDGER_CHECKPOINT_CARRIER_SCHEMA ||
    value.schema_version !== 1 || value.record_type !== "epoch-checkpoint"
  ) {
    throw ledgerError(
      "CHECKPOINT_CARRIER_SCHEMA",
      "checkpoint carrier schema is unsupported",
    );
  }
  const expectedPayload = checkpointCarrierPayload({
    repository,
    ledgerRef,
    epochId: checkpointState.epoch_id,
    sourceTipCommitSha,
    checkpointState,
    stateTreeSha,
  });
  if (
    canonicalJson(value.payload) !== canonicalJson(expectedPayload) ||
    value.payload_digest !== expectedPayload.payload_digest ||
    canonicalJson(value.source_workflow) !== canonicalJson(
      sourceWorkflow(capability.controller_release),
    )
  ) {
    throw ledgerError(
      "CHECKPOINT_CARRIER_BINDING",
      "checkpoint carrier differs from its source and state binding",
    );
  }
  if (timestamp(
    value.server_observed_at,
    "checkpoint carrier server time",
  ) !== value.server_observed_at) {
    throw ledgerError(
      "CHECKPOINT_CARRIER_TIME",
      "checkpoint carrier server time is not canonical",
    );
  }
  compactOidcJwt(value.workflow_provenance_jwt);
  const identity = {
    record_type: "epoch-checkpoint",
    kind: null,
    effect_id: null,
    idempotency_key: null,
    payload_digest: value.payload_digest,
  };
  const binding = value.workflow_provenance?.operation_binding;
  if (
    binding?.operation !== "checkpoint-rotate" ||
    canonicalJson(binding.repository) !== canonicalJson(repository) ||
    binding.ledger_ref !== ledgerRef ||
    binding.predecessor_commit_sha !== sourceTipCommitSha ||
    binding.protection_receipt_digest !==
      capability.protection.live_ruleset_receipt_digest ||
    binding.github_server_time !== value.server_observed_at ||
    canonicalJson(binding.source_workflow) !== canonicalJson(
      sourceWorkflow(capability.controller_release),
    ) ||
    binding.effect_scope !== null ||
    binding.evaluated_scope_receipt !== null ||
    canonicalJson(binding.record_identity) !== canonicalJson(identity)
  ) {
    throw ledgerError(
      "CHECKPOINT_PROVENANCE_BINDING",
      "checkpoint provenance does not bind its exact carrier payload",
    );
  }
  digest(value.carrier_digest, "checkpoint carrier digest");
  const { carrier_digest: _digest, ...withoutDigest } = value;
  if (value.carrier_digest !== digestCanonical(
    "codex-review-gate-v2-checkpoint-carrier",
    withoutDigest,
  )) {
    throw ledgerError(
      "CHECKPOINT_CARRIER_DIGEST",
      "checkpoint carrier digest is invalid",
    );
  }
  return deepFreeze(structuredClone(value));
}

function checkpointStateTreeLayout(checkpointState) {
  const stateBytes = Buffer.from(`${canonicalJson(checkpointState)}\n`, "utf8");
  if (stateBytes.byteLength > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError(
      "CHECKPOINT_STATE_SIZE",
      "checkpoint state exceeds its Git blob cap",
    );
  }
  const stateBlobSha = gitObjectSha("blob", stateBytes);
  const entries = [{
    path: V2_GIT_LEDGER_CHECKPOINT_STATE_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: stateBlobSha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_FRONTIER_NODES_PATH,
    mode: "040000",
    type: "tree",
    sha: checkpointState.prefix_frontier.tree_sha,
  }];
  return {
    state_bytes: stateBytes,
    state_blob_sha: stateBlobSha,
    entries,
    tree_sha: canonicalGitTreeSha(entries),
  };
}

function planBootstrapCheckpointObjects({
  checkpointState,
  prefixFrontier,
  carrier,
  sourceTipCommitSha,
}) {
  validateBootstrapCheckpointState(checkpointState);
  const frontierRequests = prefixFrontier.tree_entries.map((entry) => {
    const bytes = prefixFrontier.node_bytes.get(entry.sha);
    return {
      kind: "blob",
      expected_sha: entry.sha,
      body: { content: bytes.toString("base64"), encoding: "base64" },
    };
  });
  const frontierTreeRequest = {
    kind: "tree",
    expected_sha: checkpointState.prefix_frontier.tree_sha,
    body: { tree: structuredClone(prefixFrontier.tree_entries) },
  };
  const stateLayout = checkpointStateTreeLayout(checkpointState);
  const stateBytes = stateLayout.state_bytes;
  const stateBlobSha = stateLayout.state_blob_sha;
  const stateTreeEntries = stateLayout.entries;
  const stateTreeSha = stateLayout.tree_sha;
  if (carrier.payload.checkpoint_state_tree_sha !== stateTreeSha) {
    throw ledgerError(
      "CHECKPOINT_STATE_TREE_BINDING",
      "checkpoint carrier does not bind its exact state tree",
    );
  }
  const carrierBytes = Buffer.from(`${canonicalJson(carrier)}\n`, "utf8");
  if (carrierBytes.byteLength > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError(
      "CHECKPOINT_CARRIER_SIZE",
      "checkpoint carrier exceeds its Git blob cap",
    );
  }
  const carrierBlobSha = gitObjectSha("blob", carrierBytes);
  const rootEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: carrierBlobSha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_STATE_PATH,
    mode: "040000",
    type: "tree",
    sha: stateTreeSha,
  }];
  const rootTreeSha = canonicalGitTreeSha(rootEntries);
  const message = "Codex Review Gate v2: epoch-checkpoint #0";
  const commitBody = {
    message,
    tree: rootTreeSha,
    parents: [sourceTipCommitSha],
    author: { ...COMMIT_AUTHOR, date: carrier.server_observed_at },
    committer: { ...COMMIT_AUTHOR, date: carrier.server_observed_at },
  };
  const commitSha = gitObjectSha("commit", canonicalGitCommitBytes({
    treeSha: rootTreeSha,
    parents: [sourceTipCommitSha],
    message,
    serverTime: carrier.server_observed_at,
  }));
  return deepFreeze({
    commit_sha: commitSha,
    tree_sha: rootTreeSha,
    carrier_blob_sha: carrierBlobSha,
    state_tree_sha: stateTreeSha,
    state_blob_sha: stateBlobSha,
    frontier_tree_sha: checkpointState.prefix_frontier.tree_sha,
    requests: [
      ...frontierRequests,
      frontierTreeRequest,
      {
        kind: "blob",
        expected_sha: stateBlobSha,
        body: { content: stateBytes.toString("utf8"), encoding: "utf-8" },
      },
      {
        kind: "tree",
        expected_sha: stateTreeSha,
        body: { tree: stateTreeEntries },
      },
      {
        kind: "blob",
        expected_sha: carrierBlobSha,
        body: { content: carrierBytes.toString("utf8"), encoding: "utf-8" },
      },
      {
        kind: "tree",
        expected_sha: rootTreeSha,
        body: { tree: rootEntries },
      },
      { kind: "commit", expected_sha: commitSha, body: commitBody },
    ],
  });
}

async function planBootstrapCheckpointCandidateSuffix({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  repository,
  capability,
  verifyWorkflowProvenance,
  requestBudget,
  provenanceBudget,
  sourceTipCommitSha,
  checkpointCommitSha,
  checkpointServerTime,
  prefixProvenanceIdentities,
  admissionPrivate,
  assertAdmissionCurrent,
  semanticSourceRecords = [],
}) {
  assertAdmissionCurrent();
  if (
    !Array.isArray(semanticSourceRecords) ||
    semanticSourceRecords.length > MAX_V2_GIT_LEDGER_COMMITS
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_SEMANTIC_CAP",
      "checkpoint source records exceed the first mature profile",
    );
  }
  const semanticRecords = () => [
    ...semanticSourceRecords,
    ...stagedRecords,
  ];
  const commandAuthority = admissionPrivate.command_authority;
  const triggerIdentity = admissionPrivate.trigger_identity;
  const repositoryEndpointReceipt =
    admissionPrivate.repository_endpoint_receipt;
  const driftAttempts = admissionPrivate.drift_attempts;
  const cycle = admissionPrivate.cycle;
  const owner = candidateDispatchOwner(commandAuthority);
  const stagedRecords = [];
  const stagedPlans = [];
  const stagedAttachments = [];
  const consumedJtis = new Set(prefixProvenanceIdentities);
  let predecessorCommitSha = checkpointCommitSha;
  let priorServerTime = timestamp(
    checkpointServerTime,
    "checkpoint carrier server time",
  );
  const stageRecord = async ({
    record,
    evaluatedScopeReceipt,
    validateTransition,
    candidateInventoryAttachment = null,
  }) => {
    assertAdmissionCurrent();
    const recordFence = await readRef({
      fetchImpl,
      authorization,
      base,
      repoPath,
      ref,
      refSuffix,
      requestBudget,
      assertOperationCurrent: assertAdmissionCurrent,
    });
    assertAdmissionCurrent();
    assertHttpDeadlineOpen(requestBudget);
    if (recordFence.target_commit_sha !== sourceTipCommitSha) {
      throw ledgerError(
        "CHECKPOINT_SOURCE_STALE",
        "checkpoint source ref changed during off-ref transaction planning",
      );
    }
    if (
      priorServerTime !== null &&
      Date.parse(recordFence.server_time) < Date.parse(priorServerTime)
    ) {
      throw ledgerError(
        "CHECKPOINT_TIME_REGRESSION",
        "checkpoint suffix ref observation time regressed",
      );
    }
    const authoritativeRecord = authoritativeRecordTime(
      record,
      recordFence.server_time,
    );
    const transitionRecord = candidateInventoryAttachment === null
      ? authoritativeRecord
      : {
        ...authoritativeRecord,
        candidate_inventory_attachment_evidence:
          structuredClone(candidateInventoryAttachment.evidence),
      };
    validateTransition(transitionRecord);
    assertAdmissionCurrent();
    const provenance = await obtainWorkflowProvenance({
      verifyWorkflowProvenance,
      operation: authoritativeRecord.record_type,
      repository,
      ledgerRef: ref,
      predecessorCommitSha,
      protectionReceiptDigest:
        capability.protection.live_ruleset_receipt_digest,
      source: sourceWorkflow(capability.controller_release),
      effectScope: null,
      evaluatedScopeReceipt,
      recordIdentity: productionRecordIdentity(authoritativeRecord),
      serverTime: authoritativeRecord.server_observed_at,
      policy: capability.workflow_provenance_policy,
      provenanceBudget,
    });
    assertAdmissionCurrent();
    assertHttpDeadlineOpen(requestBudget);
    assertUnusedProvenanceJti(consumedJtis, provenance.receipt);
    const envelope = sealEnvelope({
      repository,
      ledger_ref: ref,
      record_type: authoritativeRecord.record_type,
      sequence: stagedRecords.length + 1,
      pull_request: authoritativeRecord.pull_request,
      head_ref_oid: authoritativeRecord.head_ref_oid,
      base_ref_oid: authoritativeRecord.base_ref_oid,
      potential_merge_commit_oid:
        authoritativeRecord.potential_merge_commit_oid,
      kind: authoritativeRecord.kind,
      effect_id: authoritativeRecord.effect_id,
      idempotency_key: authoritativeRecord.idempotency_key,
      predecessor_commit_sha: predecessorCommitSha,
      server_observed_at: authoritativeRecord.server_observed_at,
      payload: authoritativeRecord.payload,
      control_comment_binding: authoritativeRecord.control_comment_binding,
      lease: authoritativeRecord.lease,
      source_workflow: sourceWorkflow(capability.controller_release),
      workflow_provenance: provenance.receipt,
      workflow_provenance_jwt: provenance.compact_jwt,
    });
    const plan = planGitLedgerCommitObjects({
      envelope,
      parents: [predecessorCommitSha],
      candidateInventoryAttachment,
    });
    const entry = deepFreeze({
      commit_sha: plan.commit_sha,
      parents: [predecessorCommitSha],
      tree_sha: plan.tree_sha,
      blob_sha: plan.blob_sha,
      candidate_inventory_attachment_tree_sha:
        candidateInventoryAttachment?.manifest.attachment_tree_sha ?? null,
      envelope,
      ...(candidateInventoryAttachment === null ? {} : {
        candidate_inventory_attachment_evidence:
          structuredClone(candidateInventoryAttachment.evidence),
      }),
    });
    stagedRecords.push(entry);
    stagedPlans.push(plan);
    stagedAttachments.push(candidateInventoryAttachment);
    predecessorCommitSha = plan.commit_sha;
    priorServerTime = authoritativeRecord.server_observed_at;
    return entry;
  };

  if (admissionPrivate.next_unit_profile ===
      MATURE_CURRENT_OPEN_NEXT_UNIT_PROFILE) {
    const admissionHandle = admissionPrivate.next_unit_admission_handle;
    const priorCandidateAuthority =
      deriveV2GitLedgerCandidateInventoryAuthority(
        semanticSourceRecords,
        repository,
      );
    const publication = prepareCurrentOpenGenerationPublication({
      authority: admissionPrivate.normalized_production_candidate_authority,
      projection: admissionPrivate.normalized_projection,
      priorCandidateAuthority,
      commandAuthority,
    });
    const publicationBinding = {
      generation_id: publication.generation_id,
      current_open_receipt_digest: publication.current_open_receipt_digest,
      current_open_projection_digest:
        publication.current_open_projection_digest,
      production_candidate_authority_digest:
        publication.production_candidate_authority.authority_digest,
      candidate_count:
        publication.production_candidate_authority.candidate_count,
      candidate_set_digest:
        publication.production_candidate_authority.candidate_set_digest,
      source_current_open_semantic_digest:
        publication.production_candidate_authority
          .source_current_open_semantic_digest,
      lifecycle_candidate_set_digest:
        publication.lifecycle_candidate_set_digest,
      attachment_manifest_digest: publication.manifest.manifest_digest,
    };
    const admissionBinding = Object.fromEntries(
      Object.keys(publicationBinding).map((key) => [key, admissionHandle[key]]),
    );
    const candidateCount = publication.production_candidate_authority
      .candidate_count;
    const batchCount = candidateCount === 0
      ? 0
      : Math.ceil(candidateCount / MAX_V2_CANDIDATE_DISPATCH_ITEMS);
    const currentEpochBudget =
      calculateCurrentOpenCheckpointCommitBudget({
        candidate_count: candidateCount,
        batch_count: batchCount,
        source_record_count: semanticSourceRecords.length,
      });
    const freshEpochBudget =
      calculateCurrentOpenCheckpointCommitBudget({
        candidate_count: candidateCount,
        batch_count: batchCount,
        source_record_count: 1,
      });
    if (
      priorCandidateAuthority.authority_digest !==
        admissionPrivate.source_load_handle
          .candidate_inventory_authority_digest ||
      canonicalJson(publicationBinding) !== canonicalJson(admissionBinding) ||
      canonicalJson(currentEpochBudget) !==
        canonicalJson(admissionPrivate.current_epoch_budget) ||
      canonicalJson(freshEpochBudget) !==
        canonicalJson(admissionPrivate.fresh_epoch_budget) ||
      admissionHandle.total_commit_budget_required !==
        currentEpochBudget.total_commit_budget_required ||
      admissionHandle.current_epoch_remaining_commit_capacity !==
        currentEpochBudget.remaining_ledger_commit_capacity_after_dispatch ||
      admissionHandle.fresh_epoch_remaining_commit_capacity !==
        freshEpochBudget.remaining_ledger_commit_capacity_after_dispatch ||
      currentEpochBudget.remaining_ledger_commit_capacity_after_dispatch >= 0 ||
      freshEpochBudget.remaining_ledger_commit_capacity_after_dispatch < 0 ||
      admissionHandle.stable_command_authority_digest !== digestCanonical(
        "codex-review-gate-v2-checkpoint-stable-command-authority",
        candidateDispatchStableCommandAuthority(commandAuthority),
      ) ||
      admissionHandle.trigger_identity_digest !== digestCanonical(
        "codex-review-gate-v2-checkpoint-trigger-identity",
        normalizeCandidateDispatchTriggerIdentity(triggerIdentity),
      ) ||
      admissionHandle.repository_endpoint_receipt_digest !== digestCanonical(
        "codex-review-gate-v2-checkpoint-repository-endpoint-receipt",
        repositoryEndpointReceipt,
      )
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_PROJECTION",
        "current-open checkpoint admission differs from its fresh normalized authority",
      );
    }
    const owner = candidateDispatchOwner(commandAuthority);
    const generationPayload = currentOpenGenerationPayload({
      authority: priorCandidateAuthority,
      owner,
      publication,
    });
    const generationRecord = createV2GitLedgerCandidateInventoryRecord({
      predecessor_commit_sha: predecessorCommitSha,
      owner,
      server_observed_at: priorServerTime,
      payload: generationPayload,
    });
    await stageRecord({
      record: generationRecord,
      evaluatedScopeReceipt:
        createV2GitLedgerCandidateInventoryEvaluatedScopeReceipt({
          repository,
          payload: generationPayload,
          trigger_identity: triggerIdentity,
          repository_endpoint_receipt: repositoryEndpointReceipt,
        }),
      validateTransition: (authoritative) =>
        validateCandidateInventoryTransition(
          semanticRecords(),
          authoritative,
          repository,
          { currentAuthority: priorCandidateAuthority },
        ),
      candidateInventoryAttachment: publication,
    });
    const candidateAuthority =
      deriveV2GitLedgerCandidateInventoryAuthority(
        semanticRecords(),
        repository,
      );
    const dispatchAuthority = deriveV2GitLedgerCandidateDispatchAuthority(
      semanticRecords(),
      repository,
    );
    const completedSource = candidateInventoryCompletedSource(
      candidateAuthority,
    );
    if (
      completedSource === null ||
      completedSource.source_kind !== "current-open-v3" ||
      completedSource.generation_id !== admissionHandle.generation_id
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_MISMATCH",
        "current-open checkpoint suffix did not produce its admitted generation",
      );
    }
    const reachableBeforeDispatch = 2;
    const reservation = createCandidateDispatchReservation({
      repository,
      candidateAuthority,
      dispatchAuthority,
      sourceTipCommitSha: predecessorCommitSha,
      reachableRecordCount: reachableBeforeDispatch,
      commandAuthority,
      triggerIdentity,
    });
    let dispatchPayload;
    if (reservation === null) {
      const emptyCycle = newCandidateDispatchCycle({
        repository,
        candidateAuthority,
        completed: null,
        candidates: [],
        batchCount: 0,
      });
      dispatchPayload = createCandidateDispatchPayload({
        phase: "cycle-complete",
        dispatchAuthority,
        candidateAuthority,
        commandAuthority,
        triggerIdentity,
        cycleCompletion: createCandidateDispatchCycleCompletion(emptyCycle),
      });
    } else {
      dispatchPayload = createCandidateDispatchPayload({
        phase: "reserve",
        dispatchAuthority,
        candidateAuthority,
        commandAuthority,
        triggerIdentity,
        reservation,
      });
    }
    const dispatchRecord = createV2GitLedgerCandidateDispatchRecord({
      predecessor_commit_sha: predecessorCommitSha,
      server_observed_at: priorServerTime,
      payload: dispatchPayload,
    });
    await stageRecord({
      record: dispatchRecord,
      evaluatedScopeReceipt:
        createV2GitLedgerCandidateDispatchEvaluatedScopeReceipt({
          repository,
          payload: dispatchPayload,
          trigger_identity: triggerIdentity,
          repository_endpoint_receipt: repositoryEndpointReceipt,
        }),
      validateTransition: (authoritative) =>
        validateCandidateDispatchTransition(
          semanticRecords(),
          authoritative,
          repository,
          { reachableRecordCount: reachableBeforeDispatch },
        ),
    });
    const finalDispatchAuthority =
      deriveV2GitLedgerCandidateDispatchAuthority(
        semanticRecords(),
        repository,
      );
    const activeReservation = finalDispatchAuthority.active_reservation;
    const currentCycle = finalDispatchAuthority.current_cycle;
    if (
      stagedRecords.length !== 2 || currentCycle === null ||
      currentCycle.generation_id !== completedSource.dispatch_generation_id ||
      (reservation === null
        ? activeReservation !== null || currentCycle.cycle_complete !== true
        : activeReservation?.reservation.reservation_digest !==
            reservation.reservation_digest || currentCycle.cycle_complete)
    ) {
      throw ledgerError(
        "CHECKPOINT_NEXT_UNIT_MISMATCH",
        "current-open checkpoint suffix lacks its exact first dispatch boundary",
      );
    }
    const firstPlan = activeReservation === null
      ? null
      : createCandidateDispatchPlan(activeReservation, {
          candidateDispatchAuthorityDigest:
            finalDispatchAuthority.authority_digest,
        });
    const firstPlanBytes = firstPlan === null
      ? 0
      : Buffer.byteLength(canonicalJson(firstPlan), "utf8");
    if (
      firstPlan !== null &&
      (firstPlan.schema_version !== 2 ||
        firstPlanBytes > candidateDispatchPlanByteCap(firstPlan))
    ) {
      throw ledgerError(
        "CHECKPOINT_DISPATCH_PLAN_UNREPRESENTABLE",
        "current-open checkpoint cannot expose one bounded first dispatch plan",
      );
    }
    assertAdmissionCurrent();
    return {
      records: stagedRecords,
      plans: stagedPlans,
      attachments: stagedAttachments,
      transaction_tip_commit_sha: predecessorCommitSha,
      semantic_record_count: stagedRecords.length,
      first_dispatch_plan: firstPlan,
      first_dispatch_plan_bytes: firstPlanBytes,
      consumed_provenance_identities: consumedJtis,
      current_open_publication: publication,
    };
  }

  const emptyInventoryAuthority =
    deriveV2GitLedgerCandidateInventoryAuthority(
      semanticSourceRecords,
      repository,
    );
  const publication = prepareCompactCandidateInventoryPublication({
    authority: emptyInventoryAuthority,
    commandAuthority,
    driftAttempts,
    cycle,
  });
  const stageInventoryPhase = async ({
    phase,
    bundle = null,
    priorAttempt = null,
    attemptRecords = null,
  }) => {
    const authority = deriveV2GitLedgerCandidateInventoryAuthority(
      semanticRecords(),
      repository,
    );
    const payload = compactCandidateInventoryPhasePayload({
      authority,
      owner,
      publication,
      phase,
      bundle,
      priorAttempt,
      attemptRecords,
    });
    const record = createV2GitLedgerCandidateInventoryRecord({
      predecessor_commit_sha: predecessorCommitSha,
      owner,
      server_observed_at:
        priorServerTime ?? cycle.cycle_receipt.observed_at,
      payload,
    });
    await stageRecord({
      record,
      evaluatedScopeReceipt:
        createV2GitLedgerCandidateInventoryEvaluatedScopeReceipt({
          repository,
          payload,
          trigger_identity: triggerIdentity,
          repository_endpoint_receipt: repositoryEndpointReceipt,
        }),
      validateTransition: (authoritative) =>
        validateCandidateInventoryTransition(
          semanticRecords(),
          authoritative,
          repository,
        ),
      candidateInventoryAttachment: bundle,
    });
    return stagedRecords.at(-1);
  };
  await stageInventoryPhase({ phase: "cycle-start" });
  const attemptRecords = [];
  for (const bundle of publication.bundles) {
    const entry = await stageInventoryPhase({
      phase: "attempt",
      bundle,
      priorAttempt: attemptRecords.at(-1) ?? null,
    });
    attemptRecords.push({
      record_oid: entry.commit_sha,
      attempt_evidence_digest: bundle.manifest.attempt_evidence_digest,
      attachment_manifest_digest: bundle.manifest.manifest_digest,
      outcome: bundle.manifest.outcome,
    });
  }
  await stageInventoryPhase({
    phase: "cycle-complete",
    attemptRecords,
  });
  const expectedInventoryRecords = driftAttempts.length + 3;
  if (stagedRecords.length !== expectedInventoryRecords) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_MISMATCH",
      "checkpoint candidate inventory suffix has the wrong record count",
    );
  }
  const candidateAuthority = deriveV2GitLedgerCandidateInventoryAuthority(
    semanticRecords(),
    repository,
  );
  const dispatchAuthority = deriveV2GitLedgerCandidateDispatchAuthority(
    semanticRecords(),
    repository,
  );
  const completed = candidateAuthority.completed_cycle;
  if (
    completed === null || candidateAuthority.incomplete_cycle !== null ||
    completed.cycle_id !== candidateInventoryCycleId(cycle.initial_inventory) ||
    completed.cycle_receipt.receipt_digest !==
      cycle.cycle_receipt.receipt_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_MISMATCH",
      "checkpoint suffix did not produce the admitted completed inventory",
    );
  }
  const reachableBeforeDispatch = 1 + stagedRecords.length;
  const reservation = createCandidateDispatchReservation({
    repository,
    candidateAuthority,
    dispatchAuthority,
    sourceTipCommitSha: predecessorCommitSha,
    reachableRecordCount: reachableBeforeDispatch,
    commandAuthority,
    triggerIdentity,
  });
  let dispatchPayload;
  let firstPlan;
  if (reservation === null) {
    const emptyCycle = newCandidateDispatchCycle({
      repository,
      candidateAuthority,
      completed,
      candidates: [],
      batchCount: 0,
    });
    dispatchPayload = createCandidateDispatchPayload({
      phase: "cycle-complete",
      dispatchAuthority,
      candidateAuthority,
      commandAuthority,
      triggerIdentity,
      cycleCompletion: createCandidateDispatchCycleCompletion(emptyCycle),
    });
    firstPlan = null;
  } else {
    try {
      firstPlan = createCandidateDispatchPlan({
        reservation,
        acknowledgements: [],
      });
    } catch (error) {
      throw ledgerError(
        "CHECKPOINT_DISPATCH_PLAN_UNREPRESENTABLE",
        "checkpoint next unit cannot expose one bounded first dispatch plan",
        error,
      );
    }
    dispatchPayload = createCandidateDispatchPayload({
      phase: "reserve",
      dispatchAuthority,
      candidateAuthority,
      commandAuthority,
      triggerIdentity,
      reservation,
    });
  }
  const dispatchRecord = createV2GitLedgerCandidateDispatchRecord({
    predecessor_commit_sha: predecessorCommitSha,
    server_observed_at:
      priorServerTime ?? cycle.cycle_receipt.observed_at,
    payload: dispatchPayload,
  });
  await stageRecord({
    record: dispatchRecord,
    evaluatedScopeReceipt:
      createV2GitLedgerCandidateDispatchEvaluatedScopeReceipt({
        repository,
        payload: dispatchPayload,
        trigger_identity: triggerIdentity,
        repository_endpoint_receipt: repositoryEndpointReceipt,
      }),
      validateTransition: (authoritative) =>
      validateCandidateDispatchTransition(
        semanticRecords(),
        authoritative,
        repository,
        { reachableRecordCount: reachableBeforeDispatch },
      ),
  });
  const finalDispatch = deriveV2GitLedgerCandidateDispatchAuthority(
    semanticRecords(),
    repository,
  ).current_cycle;
  if (
    stagedRecords.length !== expectedInventoryRecords + 1 ||
    finalDispatch?.generation_id !== candidateDispatchGenerationId(
      repository,
      completed,
    ) ||
    (reservation === null
      ? finalDispatch.cycle_complete !== true
      : finalDispatch.active_reservation?.reservation.reservation_digest !==
        reservation.reservation_digest)
  ) {
    throw ledgerError(
      "CHECKPOINT_NEXT_UNIT_MISMATCH",
      "checkpoint suffix does not include its exact first dispatch boundary",
    );
  }
  const firstPlanBytes = firstPlan === null
    ? 0
    : Buffer.byteLength(canonicalJson(firstPlan), "utf8");
  if (
    firstPlan !== null &&
    (firstPlan.schema_version !== 2 ||
      firstPlanBytes > candidateDispatchPlanByteCap(firstPlan))
  ) {
    throw ledgerError(
      "CHECKPOINT_DISPATCH_PLAN_UNREPRESENTABLE",
      "checkpoint next unit cannot expose one bounded first dispatch plan",
    );
  }
  assertAdmissionCurrent();
  return {
    records: stagedRecords,
    plans: stagedPlans,
    attachments: stagedAttachments,
    transaction_tip_commit_sha: predecessorCommitSha,
    semantic_record_count: stagedRecords.length,
    first_dispatch_plan: firstPlan,
    first_dispatch_plan_bytes: firstPlanBytes,
    consumed_provenance_identities: consumedJtis,
  };
}

function checkpointTransactionPlannedRequests(checkpointPlan, suffix) {
  return [
    ...checkpointPlan.requests,
    ...suffix.plans.flatMap((plan) => plan.requests),
  ];
}

function assertCheckpointTransactionPlanCapacity({
  checkpointPlan,
  suffix,
  requestBudget,
}) {
  validateHttpRequestBudget(requestBudget);
  const writes = checkpointTransactionPlannedRequests(checkpointPlan, suffix);
  const attachmentReadRequests = suffix.attachments.reduce(
    (total, attachment) => total + (attachment === null
      ? 0
      : attachment.manifest.chunk_count + 1),
    0,
  );
  // Blob reads cover the carrier, state, and frontier nodes. The six fixed
  // reads are the checkpoint commit, three trees, and the protected-ref
  // pre/post stability receipts required by the autonomous production load.
  const checkpointReadRequests =
    checkpointPlan.requests.filter(({ kind }) => kind === "blob").length +
    (checkpointPlan.source_seed_tree_sha === undefined ? 6 : 7);
  const suffixReadRequests = suffix.records.length * 3 +
    attachmentReadRequests;
  const futureRequestCount = writes.length + checkpointReadRequests +
    suffixReadRequests;
  const remainingRequests = requestBudget.limits.request_count -
    requestBudget.request_count;
  if (
    writes.length > MAX_V2_PERSISTENT_FRONTIER_OPERATION_OBJECTS ||
    futureRequestCount > remainingRequests
  ) {
    throw ledgerError(
      "CHECKPOINT_TRANSACTION_REQUEST_CAP",
      "checkpoint transaction cannot fit its shared write and validation request budget",
    );
  }
  let bodyBytes = 0;
  for (const planned of writes) {
    const bytes = Buffer.byteLength(JSON.stringify(planned.body), "utf8");
    if (
      requestBudget.request_body_bytes_limit !== null &&
      bytes > requestBudget.request_body_bytes_limit
    ) {
      throw ledgerError(
        "CHECKPOINT_TRANSACTION_REQUEST_BODY_CAP",
        "checkpoint transaction contains an oversized Git object request",
      );
    }
    bodyBytes += bytes;
  }
  if (
    requestBudget.total_request_body_bytes_limit !== null &&
    bodyBytes > requestBudget.total_request_body_bytes_limit -
      requestBudget.total_request_body_bytes
  ) {
    throw ledgerError(
      "CHECKPOINT_TRANSACTION_REQUEST_BODY_CAP",
      "checkpoint transaction exceeds its aggregate Git object request bytes",
    );
  }
  const remainingResponseBytes = requestBudget.limits.total_response_bytes -
    requestBudget.total_response_bytes;
  if (
    futureRequestCount * requestBudget.limits.response_bytes >
      remainingResponseBytes
  ) {
    throw ledgerError(
      "CHECKPOINT_TRANSACTION_RESPONSE_CAP",
      "checkpoint transaction lacks a closed worst-case response byte budget",
    );
  }
  if (
    requestBudget.deadline_at_ms === null ||
    requestBudget.deadline_at_ms <= performance.now()
  ) {
    throw ledgerError(
      "checkpoint-transaction-timeout",
      "checkpoint transaction exhausted its shared absolute deadline before writes",
    );
  }
  return deepFreeze({
    write_object_count: writes.length,
    write_request_body_bytes: bodyBytes,
    planned_loader_request_count:
      checkpointReadRequests + suffixReadRequests,
    planned_total_request_count: futureRequestCount,
  });
}

async function publishCheckpointObjectPlan({
  fetchImpl,
  authorization,
  base,
  repoPath,
  checkpointPlan,
  requestBudget,
  assertAdmissionCurrent,
}) {
  for (const planned of checkpointPlan.requests) {
    assertAdmissionCurrent();
    const path = planned.kind === "blob"
      ? `${repoPath}/git/blobs`
      : planned.kind === "tree"
        ? `${repoPath}/git/trees`
        : `${repoPath}/git/commits`;
    const capture = await request({
      fetchImpl,
      authorization,
      base,
      method: "POST",
      path,
      body: planned.body,
      expectedStatus: 201,
      requestBudget,
      assertOperationCurrent: assertAdmissionCurrent,
    });
    assertAdmissionCurrent();
    const actual = responseSha(
      capture.data,
      `created checkpoint ${planned.kind}`,
    );
    if (actual !== planned.expected_sha) {
      throw ledgerError(
        "CHECKPOINT_OBJECT_IDENTITY",
        "created checkpoint Git object changed identity",
      );
    }
    if (planned.kind === "commit") {
      const commit = capture.data;
      if (
        commit.tree?.sha !== planned.body.tree ||
        canonicalJson(commit.parents?.map(({ sha: parent }) => parent)) !==
          canonicalJson(planned.body.parents) ||
        commit.message !== planned.body.message
      ) {
        throw ledgerError(
          "CHECKPOINT_COMMIT_ECHO",
          "created checkpoint commit did not echo its exact tree and parent",
        );
      }
    }
  }
}

async function publishCheckpointSuffixPlans({
  fetchImpl,
  authorization,
  base,
  repoPath,
  suffix,
  requestBudget,
  assertAdmissionCurrent,
}) {
  for (let index = 0; index < suffix.records.length; index += 1) {
    assertAdmissionCurrent();
    const entry = suffix.records[index];
    const plan = suffix.plans[index];
    const objects = await createCommitObjects({
      fetchImpl,
      authorization,
      base,
      repoPath,
      envelope: entry.envelope,
      parents: entry.parents,
      requestBudget,
      candidateInventoryAttachment: suffix.attachments[index],
      assertOperationCurrent: assertAdmissionCurrent,
    });
    assertAdmissionCurrent();
    if (
      objects.blob_sha !== plan.blob_sha ||
      objects.tree_sha !== plan.tree_sha ||
      objects.commit_sha !== plan.commit_sha
    ) {
      throw ledgerError(
        "CHECKPOINT_SUFFIX_OBJECT_IDENTITY",
        "checkpoint suffix write differs from its complete off-ref plan",
      );
    }
  }
}

function checkpointPreparationDiagnostic({
  sourceLoadHandle,
  checkpointState,
  checkpointPlan,
  suffix,
  capacity,
}) {
  const firstPlan = suffix.first_dispatch_plan;
  const withoutDigest = {
    schema: V2_GIT_LEDGER_CHECKPOINT_PREPARATION_DIAGNOSTIC_SCHEMA,
    schema_version: 1,
    state: "prepared",
    profile: CHECKPOINT_PROFILE,
    source_tip_commit_sha: sourceLoadHandle.source_tip_commit_sha,
    source_commit_count: sourceLoadHandle.source_commit_count,
    checkpoint_commit_sha: checkpointPlan.commit_sha,
    transaction_tip_commit_sha: suffix.transaction_tip_commit_sha,
    epoch_commit_count: suffix.semantic_record_count + 1,
    semantic_record_count: suffix.semantic_record_count,
    frontier_entry_count: checkpointState.prefix_frontier.root.count,
    frontier_node_count: checkpointState.prefix_frontier.node_count,
    checkpoint_state_digest: checkpointState.checkpoint_state_digest,
    next_unit_admission_digest:
      checkpointState.next_unit.admission_digest,
    first_dispatch_plan_schema_version: firstPlan?.schema_version ?? 0,
    first_dispatch_plan_bytes: suffix.first_dispatch_plan_bytes,
    first_dispatch_plan_digest: firstPlan?.plan_digest ?? null,
    planned_write_object_count: capacity.write_object_count,
    planned_write_request_body_bytes: capacity.write_request_body_bytes,
    planned_loader_request_count: capacity.planned_loader_request_count,
    planned_total_request_count: capacity.planned_total_request_count,
  };
  return deepFreeze({
    ...withoutDigest,
    preparation_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-preparation-diagnostic",
      withoutDigest,
    ),
  });
}

function checkpointValidationDiagnostic({
  prepared,
  suffix,
  frontier,
  futureState,
}) {
  const withoutDigest = {
    schema: V2_GIT_LEDGER_CHECKPOINT_VALIDATION_DIAGNOSTIC_SCHEMA,
    schema_version: 1,
    validated: true,
    ref_published: false,
    profile: CHECKPOINT_PROFILE,
    checkpoint_commit_sha: prepared.checkpoint_plan.commit_sha,
    transaction_tip_commit_sha: suffix.records.at(-1).commit_sha,
    epoch_commit_count: suffix.records.length + 1,
    semantic_record_count: suffix.records.length,
    frontier_entry_count: frontier.entry_count,
    frontier_node_count: frontier.node_count,
    checkpoint_state_digest:
      prepared.checkpoint_state.checkpoint_state_digest,
    next_unit_admission_digest:
      prepared.checkpoint_state.next_unit.admission_digest,
    first_dispatch_plan_digest:
      prepared.suffix.first_dispatch_plan?.plan_digest ?? null,
    query_seed_digest: futureState.query_seed_digest,
    source_projection_digest: futureState.source_projection_digest,
    authority_projection_digest:
      futureState.authority_projection_digest,
    candidate_inventory_authority_digest:
      futureState.candidate_inventory_authority_digest,
    candidate_dispatch_authority_digest:
      futureState.candidate_dispatch_authority_digest,
    future_state_digest: futureState.future_state_digest,
  };
  return deepFreeze({
    ...withoutDigest,
    validation_digest: digestCanonical(
      "codex-review-gate-v2-checkpoint-validation-diagnostic",
      withoutDigest,
    ),
  });
}

async function prepareBootstrapCheckpointCandidateTransaction({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  repo,
  capability,
  preflightHandle,
  verifyWorkflowProvenance,
  requestBudget,
  provenanceBudget,
  sourcePrivate,
  admissionPrivate,
  assertAdmissionCurrent,
}) {
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const rawSource = await loadStableChain({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    repo,
    verifyWorkflowProvenance,
    provenanceBudget,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  await validateStoredProviderIdentityAuthorities(
    rawSource.records,
    capability.provider_identity_policy,
    preflightHandle,
    repo,
  );
  assertAdmissionCurrent();
  requireCurrentCapability(rawSource, capability);
  validateBootstrapOnlyCheckpointBoundary(rawSource);
  assertHttpDeadlineOpen(requestBudget);
  const sourceLoadHandle = admissionPrivate.source_load_handle;
  const sourceManifestDigest = digestCanonical(
    "codex-review-gate-v2-fully-reachable-record-manifest",
    checkpointRecordManifest(rawSource.records),
  );
  if (
    rawSource.tip_commit_sha !== sourceLoadHandle.source_tip_commit_sha ||
    rawSource.records.length !== sourceLoadHandle.source_commit_count ||
    sourceManifestDigest !==
      sourcePrivate.loaded.fully_reachable_record_manifest_digest ||
    sourcePrivate.loaded.inventory_digest !==
      sourceLoadHandle.source_inventory_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_CHANGED",
      "checkpoint source handle differs from its fresh full stable replay",
    );
  }
  const epochId = digestCanonical(
    "codex-review-gate-v2-checkpoint-epoch",
    {
      repository: repo,
      ledger_ref: ref,
      source_tip_commit_sha: rawSource.tip_commit_sha,
      source_load_digest: sourceLoadHandle.source_load_digest,
      next_unit_admission_digest:
        admissionPrivate.next_unit_admission_handle
          .next_unit_admission_digest,
    },
  );
  const prefixFrontier = await buildBootstrapCheckpointPrefixFrontier({
    records: rawSource.records,
    epochId,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const checkpointState = buildBootstrapCheckpointState({
    repository: repo,
    ledgerRef: ref,
    epochId,
    rawSource,
    sourceLoadHandle,
    admissionHandle: admissionPrivate.next_unit_admission_handle,
    admissionPrivate,
    capability,
    prefixFrontier,
  });
  const stateLayout = checkpointStateTreeLayout(checkpointState);
  assertAdmissionCurrent();
  const checkpointFence = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  if (checkpointFence.target_commit_sha !== rawSource.tip_commit_sha) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_STALE",
      "checkpoint source changed before checkpoint provenance was minted",
    );
  }
  if (
    Date.parse(checkpointFence.server_time) <
      Date.parse(rawSource.observed_at)
  ) {
    throw ledgerError(
      "CHECKPOINT_TIME_REGRESSION",
      "checkpoint carrier observation time precedes its source prefix",
    );
  }
  const carrierPayload = checkpointCarrierPayload({
    repository: repo,
    ledgerRef: ref,
    epochId,
    sourceTipCommitSha: rawSource.tip_commit_sha,
    checkpointState,
    stateTreeSha: stateLayout.tree_sha,
  });
  const checkpointIdentity = {
    record_type: "epoch-checkpoint",
    kind: null,
    effect_id: null,
    idempotency_key: null,
    payload_digest: carrierPayload.payload_digest,
  };
  assertAdmissionCurrent();
  const checkpointProvenance = await obtainWorkflowProvenance({
    verifyWorkflowProvenance,
    operation: "checkpoint-rotate",
    repository: repo,
    ledgerRef: ref,
    predecessorCommitSha: rawSource.tip_commit_sha,
    protectionReceiptDigest:
      capability.protection.live_ruleset_receipt_digest,
    source: sourceWorkflow(capability.controller_release),
    effectScope: null,
    evaluatedScopeReceipt: null,
    recordIdentity: checkpointIdentity,
    serverTime: checkpointFence.server_time,
    policy: capability.workflow_provenance_policy,
    provenanceBudget,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const prefixIdentities = new Set(rawSource.records.map((entry) =>
    provenanceReplayIdentity(entry.envelope.workflow_provenance)));
  assertUnusedProvenanceJti(prefixIdentities, checkpointProvenance.receipt);
  const carrier = sealCheckpointCarrier({
    payload: carrierPayload,
    serverTime: checkpointFence.server_time,
    sourceWorkflowValue: sourceWorkflow(capability.controller_release),
    workflowProvenance: checkpointProvenance.receipt,
    workflowProvenanceJwt: checkpointProvenance.compact_jwt,
  });
  validateCheckpointCarrier(carrier, {
    repository: repo,
    ledgerRef: ref,
    sourceTipCommitSha: rawSource.tip_commit_sha,
    checkpointState,
    stateTreeSha: stateLayout.tree_sha,
    capability,
  });
  const checkpointPlan = planBootstrapCheckpointObjects({
    checkpointState,
    prefixFrontier,
    carrier,
    sourceTipCommitSha: rawSource.tip_commit_sha,
  });
  assertHttpDeadlineOpen(requestBudget);
  const suffix = await planBootstrapCheckpointCandidateSuffix({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    repository: repo,
    capability,
    verifyWorkflowProvenance,
    requestBudget,
    provenanceBudget,
    sourceTipCommitSha: rawSource.tip_commit_sha,
    checkpointCommitSha: checkpointPlan.commit_sha,
    checkpointServerTime: carrier.server_observed_at,
    prefixProvenanceIdentities: prefixIdentities,
    admissionPrivate,
    assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const finalFence = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  if (
    finalFence.target_commit_sha !== rawSource.tip_commit_sha ||
    Date.parse(finalFence.server_time) < Date.parse(
      suffix.records.at(-1).envelope.server_observed_at,
    )
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_STALE",
      "checkpoint source changed before the complete off-ref write plan",
    );
  }
  const capacity = assertCheckpointTransactionPlanCapacity({
    checkpointPlan,
    suffix,
    requestBudget,
  });
  assertAdmissionCurrent();
  await publishCheckpointObjectPlan({
    fetchImpl,
    authorization,
    base,
    repoPath,
    checkpointPlan,
    requestBudget,
    assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  await publishCheckpointSuffixPlans({
    fetchImpl,
    authorization,
    base,
    repoPath,
    suffix,
    requestBudget,
    assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const privateBinding = {
    source_load_handle: sourceLoadHandle,
    admission_private: admissionPrivate,
    raw_source_tip_commit_sha: rawSource.tip_commit_sha,
    checkpoint_state: checkpointState,
    prefix_frontier_manifest: prefixFrontier.manifest,
    carrier,
    checkpoint_plan: checkpointPlan,
    suffix,
  };
  const result = checkpointPreparationDiagnostic({
    sourceLoadHandle,
    checkpointState,
    checkpointPlan,
    suffix,
    capacity,
  });
  privateBinding.result = result;
  const validation = await loadBootstrapCheckpointCandidateTransaction({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    repo,
    capability,
    verifyWorkflowProvenance,
    requestBudget,
    provenanceBudget,
    prepared: privateBinding,
    assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  if (
    validation.transaction_tip_commit_sha !==
      result.transaction_tip_commit_sha ||
    validation.checkpoint_state_digest !== result.checkpoint_state_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_VALIDATION_MISMATCH",
      "checkpoint transaction failed its immediate seeded loader validation",
    );
  }
  return {
    result,
    private_binding: privateBinding,
  };
}

async function publishMatureCheckpointCandidateTransaction({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  repo,
  capability,
  preflightHandle,
  verifyWorkflowProvenance,
  requestBudget,
  provenanceBudget,
  sourcePrivate,
  admissionPrivate,
  assertAdmissionCurrent,
}) {
  assertAdmissionCurrent();
  let rawSource = admissionPrivate.next_unit_profile ===
      MATURE_CURRENT_OPEN_NEXT_UNIT_PROFILE
    ? sourcePrivate.stable_chain
    : await loadStableChain({
        fetchImpl,
        authorization,
        base,
        repoPath,
        ref,
        refSuffix,
        repo,
        verifyWorkflowProvenance,
        provenanceBudget,
        requestBudget,
        assertOperationCurrent: assertAdmissionCurrent,
      });
  assertAdmissionCurrent();
  await validateStoredProviderIdentityAuthorities(
    rawSource.records,
    capability.provider_identity_policy,
    preflightHandle,
    repo,
  );
  assertAdmissionCurrent();
  requireCurrentCapability(rawSource, capability);
  validateMatureQuiescentCheckpointBoundary(rawSource);
  const sourceLoadHandle = admissionPrivate.source_load_handle;
  const sourceManifestDigest = digestCanonical(
    "codex-review-gate-v2-fully-reachable-record-manifest",
    checkpointRecordManifest(rawSource.records),
  );
  if (
    rawSource.tip_commit_sha !== sourceLoadHandle.source_tip_commit_sha ||
    rawSource.records.length !== sourceLoadHandle.source_commit_count ||
    sourceManifestDigest !==
      sourcePrivate.loaded.fully_reachable_record_manifest_digest ||
    sourcePrivate.loaded.inventory_digest !==
      sourceLoadHandle.source_inventory_digest ||
    rawSource.authority_projection.candidate_inventory.authority_digest !==
      sourceLoadHandle.candidate_inventory_authority_digest ||
    rawSource.authority_projection.candidate_dispatch.authority_digest !==
      sourceLoadHandle.candidate_dispatch_authority_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_CHANGED",
      "mature checkpoint source handle differs from fresh replay",
    );
  }
  const epochId = digestCanonical(
    "codex-review-gate-v2-mature-checkpoint-epoch",
    {
      repository: repo,
      ledger_ref: ref,
      source_tip_commit_sha: rawSource.tip_commit_sha,
      source_load_digest: sourceLoadHandle.source_load_digest,
      next_unit_admission_digest:
        admissionPrivate.next_unit_admission_handle
          .next_unit_admission_digest,
    },
  );
  const sourceSeedBundle = buildMatureCheckpointSourceSeedBundle({
    repository: repo,
    ledgerRef: ref,
    rawSource,
  });
  const checkpointState = buildMatureCheckpointState({
    repository: repo,
    ledgerRef: ref,
    epochId,
    rawSource,
    sourceLoadHandle,
    admissionHandle: admissionPrivate.next_unit_admission_handle,
    admissionPrivate,
    capability,
    sourceSeedBundle,
  });
  const stateLayout = matureCheckpointStateTreeLayout(
    checkpointState,
    sourceSeedBundle,
  );
  assertAdmissionCurrent();
  const checkpointFence = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  if (
    checkpointFence.target_commit_sha !== rawSource.tip_commit_sha ||
    Date.parse(checkpointFence.server_time) < Date.parse(rawSource.observed_at)
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_STALE",
      "mature checkpoint source changed before provenance minting",
    );
  }
  const carrierPayload = checkpointCarrierPayload({
    repository: repo,
    ledgerRef: ref,
    epochId,
    sourceTipCommitSha: rawSource.tip_commit_sha,
    checkpointState,
    stateTreeSha: stateLayout.tree_sha,
  });
  const checkpointIdentity = {
    record_type: "epoch-checkpoint",
    kind: null,
    effect_id: null,
    idempotency_key: null,
    payload_digest: carrierPayload.payload_digest,
  };
  const checkpointProvenance = await obtainWorkflowProvenance({
    verifyWorkflowProvenance,
    operation: "checkpoint-rotate",
    repository: repo,
    ledgerRef: ref,
    predecessorCommitSha: rawSource.tip_commit_sha,
    protectionReceiptDigest:
      capability.protection.live_ruleset_receipt_digest,
    source: sourceWorkflow(capability.controller_release),
    effectScope: null,
    evaluatedScopeReceipt: null,
    recordIdentity: checkpointIdentity,
    serverTime: checkpointFence.server_time,
    policy: capability.workflow_provenance_policy,
    provenanceBudget,
  });
  const prefixIdentities = new Set(rawSource.records.map((entry) =>
    provenanceReplayIdentity(entry.envelope.workflow_provenance)));
  assertUnusedProvenanceJti(prefixIdentities, checkpointProvenance.receipt);
  const carrier = sealCheckpointCarrier({
    payload: carrierPayload,
    serverTime: checkpointFence.server_time,
    sourceWorkflowValue: sourceWorkflow(capability.controller_release),
    workflowProvenance: checkpointProvenance.receipt,
    workflowProvenanceJwt: checkpointProvenance.compact_jwt,
  });
  validateCheckpointCarrier(carrier, {
    repository: repo,
    ledgerRef: ref,
    sourceTipCommitSha: rawSource.tip_commit_sha,
    checkpointState,
    stateTreeSha: stateLayout.tree_sha,
    capability,
  });
  const checkpointPlan = planMatureCheckpointObjects({
    checkpointState,
    sourceSeedBundle,
    carrier,
    sourceTipCommitSha: rawSource.tip_commit_sha,
  });
  const suffix = await planBootstrapCheckpointCandidateSuffix({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    repository: repo,
    capability,
    verifyWorkflowProvenance,
    requestBudget,
    provenanceBudget,
    sourceTipCommitSha: rawSource.tip_commit_sha,
    checkpointCommitSha: checkpointPlan.commit_sha,
    checkpointServerTime: carrier.server_observed_at,
    prefixProvenanceIdentities: prefixIdentities,
    admissionPrivate,
    assertAdmissionCurrent,
    semanticSourceRecords: rawSource.records,
  });
  const queryRecords = [...rawSource.records, ...suffix.records];
  const projectedState = projectChainState(
    queryRecords,
    suffix.records.at(-1).envelope.server_observed_at,
  );
  const firstPlan = suffix.first_dispatch_plan;
  const plannedFutureState = matureCheckpointFutureState({
    checkpointCommitSha: checkpointPlan.commit_sha,
    checkpointState,
    suffixRecords: suffix.records,
    projectedState,
    firstDispatchPlan: firstPlan,
  });
  if (
    plannedFutureState.candidate_inventory_authority_digest !==
      projectedState.authority_projection.candidate_inventory.authority_digest ||
    plannedFutureState.candidate_dispatch_authority_digest !==
      projectedState.authority_projection.candidate_dispatch.authority_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_PLANNED_REPLAY_MISMATCH",
      "mature checkpoint plan does not replay to its exact authority",
    );
  }

  // This is the final callback-bearing source replay. Everything after its
  // following ref fence is a fixed Git object transport followed by one CAS.
  const finalSource = await loadStableChain({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    repo,
    verifyWorkflowProvenance,
    provenanceBudget,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  await validateStoredProviderIdentityAuthorities(
    finalSource.records,
    capability.provider_identity_policy,
    preflightHandle,
    repo,
  );
  assertAdmissionCurrent();
  requireCurrentCapability(finalSource, capability);
  validateMatureQuiescentCheckpointBoundary(finalSource);
  if (
    finalSource.tip_commit_sha !== rawSource.tip_commit_sha ||
    digestCanonical(
      "codex-review-gate-v2-fully-reachable-record-manifest",
      checkpointRecordManifest(finalSource.records),
    ) !== sourceManifestDigest ||
    finalSource.projection.projection_digest !==
      rawSource.projection.projection_digest ||
    bootstrapCheckpointAuthorityDigest(finalSource.authority_projection) !==
      bootstrapCheckpointAuthorityDigest(rawSource.authority_projection)
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_CHANGED",
      "mature checkpoint source changed during complete planning",
    );
  }
  rawSource = finalSource;
  const finalFence = await readRef({
    fetchImpl,
    authorization,
    base,
    repoPath,
    ref,
    refSuffix,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  if (
    finalFence.target_commit_sha !== rawSource.tip_commit_sha ||
    Date.parse(finalFence.server_time) <
      Date.parse(rawSource.post_ref.server_time) ||
    Date.parse(finalFence.server_time) < Date.parse(
      suffix.records.at(-1).envelope.server_observed_at,
    )
  ) {
    throw ledgerError(
      "CHECKPOINT_SOURCE_STALE",
      "mature checkpoint final source fence changed or regressed",
    );
  }
  if (admissionPrivate.next_unit_profile ===
      MATURE_CURRENT_OPEN_NEXT_UNIT_PROFILE) {
    consumeV2CurrentOpenProductionCandidateAuthorityHandle(
      admissionPrivate.production_candidate_authority_handle,
      admissionPrivate.projection_handle,
    );
  }
  const capacity = assertCheckpointTransactionPlanCapacity({
    checkpointPlan,
    suffix,
    requestBudget,
  });
  void capacity;
  await publishCheckpointObjectPlan({
    fetchImpl,
    authorization,
    base,
    repoPath,
    checkpointPlan,
    requestBudget,
    assertAdmissionCurrent,
  });
  await publishCheckpointSuffixPlans({
    fetchImpl,
    authorization,
    base,
    repoPath,
    suffix,
    requestBudget,
    assertAdmissionCurrent,
  });
  let refUpdate = null;
  let exact = null;
  let publicationError = null;
  try {
    refUpdate = await updateRefStrict({
      fetchImpl,
      authorization,
      base,
      repoPath,
      ref,
      refSuffix,
      shaValue: suffix.transaction_tip_commit_sha,
      requestBudget,
    });
    exact = await readRef({
      fetchImpl,
      authorization,
      base,
      repoPath,
      ref,
      refSuffix,
      requestBudget,
    });
    if (exact.target_commit_sha !== suffix.transaction_tip_commit_sha) {
      throw ledgerError(
        "CHECKPOINT_REF_REREAD_MISMATCH",
        "mature checkpoint ref reread differs from its transaction tip",
      );
    }
  } catch (error) {
    publicationError = error;
  }
  return {
    source_tip_commit_sha: rawSource.tip_commit_sha,
    checkpoint_state: checkpointState,
    source_seed_bundle: sourceSeedBundle,
    carrier,
    checkpoint_plan: checkpointPlan,
    suffix,
    planned_future_state: plannedFutureState,
    ref_update: refUpdate,
    exact_ref: exact,
    publication_error: publicationError,
  };
}

async function fetchExactGitBlobBytes({
  fetchImpl,
  authorization,
  base,
  repoPath,
  objectOid,
  maximumBytes,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  const capture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/blobs/${objectOid}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  const blob = capture.data;
  assertObject(blob, "checkpoint Git blob");
  if (
    sha(blob.sha, "checkpoint Git blob SHA") !== objectOid ||
    blob.encoding !== "base64" || typeof blob.content !== "string"
  ) {
    throw ledgerError(
      "CHECKPOINT_BLOB_SHAPE",
      "checkpoint Git blob response is not canonical base64",
    );
  }
  const compact = blob.content.replace(/\n/gu, "");
  const bytes = Buffer.from(compact, "base64");
  if (
    bytes.byteLength === 0 || bytes.byteLength > maximumBytes ||
    bytes.toString("base64") !== compact ||
    gitObjectSha("blob", bytes) !== objectOid
  ) {
    throw ledgerError(
      "CHECKPOINT_BLOB_IDENTITY",
      "checkpoint Git blob bytes changed identity or exceeded their cap",
    );
  }
  return bytes;
}

async function fetchExactGitTree({
  fetchImpl,
  authorization,
  base,
  repoPath,
  treeSha,
  maximumEntries,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  const capture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/trees/${treeSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  const tree = capture.data;
  assertObject(tree, "checkpoint Git tree");
  if (
    sha(tree.sha, "checkpoint Git tree SHA") !== treeSha ||
    !Array.isArray(tree.tree) || tree.tree.length === 0 ||
    tree.tree.length > maximumEntries || tree.truncated === true
  ) {
    throw ledgerError(
      "CHECKPOINT_TREE_CAP",
      "checkpoint Git tree is truncated or exceeds its entry cap",
    );
  }
  const entries = tree.tree.map((entry, index) => {
    assertObject(entry, `checkpoint Git tree entry ${index}`);
    return {
      path: boundedString(
        entry.path,
        `checkpoint Git tree entry ${index}.path`,
        256,
      ),
      mode: entry.mode,
      type: entry.type,
      sha: sha(entry.sha, `checkpoint Git tree entry ${index}.sha`),
    };
  });
  if (canonicalGitTreeSha(entries) !== treeSha) {
    throw ledgerError(
      "CHECKPOINT_TREE_IDENTITY",
      "checkpoint Git tree entries do not match their object identity",
    );
  }
  return deepFreeze(entries);
}

async function fetchExactCheckpointCommit({
  fetchImpl,
  authorization,
  base,
  repoPath,
  commitSha,
  expectedTreeSha,
  expectedParentSha,
  expectedServerTime,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  const capture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/commits/${commitSha}`,
    expectedStatus: 200,
    requestBudget,
    assertOperationCurrent,
  });
  validateExactCheckpointCommitValue(capture.data, {
    commitSha,
    expectedTreeSha,
    expectedParentSha,
    expectedServerTime,
  });
}

function validateExactCheckpointCommitValue(commit, {
  commitSha,
  expectedTreeSha,
  expectedParentSha,
  expectedServerTime,
}) {
  assertObject(commit, "checkpoint Git commit");
  const parents = Array.isArray(commit.parents)
    ? commit.parents.map((parent) => {
      assertObject(parent, "checkpoint Git commit parent");
      return sha(parent.sha, "checkpoint Git commit parent SHA");
    })
    : null;
  const message = "Codex Review Gate v2: epoch-checkpoint #0";
  if (
    sha(commit.sha, "checkpoint Git commit SHA") !== commitSha ||
    commit.tree?.sha !== expectedTreeSha ||
    canonicalJson(parents) !== canonicalJson([expectedParentSha]) ||
    commit.message !== message
  ) {
    throw ledgerError(
      "CHECKPOINT_COMMIT_BINDING",
      "checkpoint Git commit differs from its exact tree or parent",
    );
  }
  for (const [label, identity] of [
    ["author", commit.author],
    ["committer", commit.committer],
  ]) {
    assertObject(identity, `checkpoint Git commit ${label}`);
    if (
      identity.name !== COMMIT_AUTHOR.name ||
      identity.email !== COMMIT_AUTHOR.email ||
      timestamp(identity.date, `checkpoint Git commit ${label} date`) !==
        expectedServerTime
    ) {
      throw ledgerError(
        "CHECKPOINT_COMMIT_IDENTITY",
        "checkpoint Git commit identity is not canonical",
      );
    }
  }
  if (gitObjectSha("commit", canonicalGitCommitBytes({
    treeSha: expectedTreeSha,
    parents: [expectedParentSha],
    message,
    serverTime: expectedServerTime,
  })) !== commitSha) {
    throw ledgerError(
      "CHECKPOINT_COMMIT_IDENTITY",
      "checkpoint Git commit bytes changed identity",
    );
  }
}

function parseCanonicalCheckpointJson(bytes, label) {
  let text;
  try {
    text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true })
      .decode(bytes);
  } catch (error) {
    throw ledgerError(
      "CHECKPOINT_JSON_UTF8",
      `${label} is not canonical UTF-8`,
      error,
    );
  }
  if (!text.endsWith("\n")) {
    throw ledgerError(
      "CHECKPOINT_JSON_CANONICAL",
      `${label} lacks its canonical newline`,
    );
  }
  let value;
  try {
    value = JSON.parse(text.slice(0, -1));
  } catch (error) {
    throw ledgerError(
      "CHECKPOINT_JSON_INVALID",
      `${label} is not JSON`,
      error,
    );
  }
  if (`${canonicalJson(value)}\n` !== text) {
    throw ledgerError(
      "CHECKPOINT_JSON_CANONICAL",
      `${label} is not canonical JSON`,
    );
  }
  return value;
}

function validateCheckpointPrefixEntries(entries, checkpointState) {
  if (!Array.isArray(entries) || entries.length !== 9) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_MEMBERSHIP",
      "checkpoint prefix frontier does not contain exactly nine bootstrap facts",
    );
  }
  const ordinals = new Map();
  const oidFacts = new Map();
  const provenanceFacts = new Map();
  for (const entry of entries) {
    const key = entry.key;
    const value = entry.value;
    if (key?.kind === "ordinal") ordinals.set(key.ordinal, value);
    else if (key?.kind === "record-oid") oidFacts.set(key.record_oid, value);
    else if (key?.kind === "provenance-identity") {
      provenanceFacts.set(key.identity, value);
    } else {
      throw ledgerError(
        "CHECKPOINT_FRONTIER_MEMBERSHIP",
        "checkpoint prefix frontier contains an unsupported key",
      );
    }
  }
  if (
    ordinals.size !== 3 || oidFacts.size !== 3 ||
    provenanceFacts.size !== 3
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_MEMBERSHIP",
      "checkpoint prefix frontier key classes are incomplete",
    );
  }
  const types = ["genesis", "capability-canary", "capability-attestation"];
  const facts = [];
  for (let ordinal = 0; ordinal < 3; ordinal += 1) {
    const fact = ordinals.get(ordinal);
    if (
      fact === undefined || fact.ordinal !== ordinal ||
      fact.sequence !== ordinal || fact.record_type !== types[ordinal] ||
      fact.parent_oid !== (ordinal === 0
        ? null
        : facts[ordinal - 1].record_oid) ||
      canonicalJson(oidFacts.get(fact.record_oid)) !== canonicalJson(fact)
    ) {
      throw ledgerError(
        "CHECKPOINT_FRONTIER_MEMBERSHIP",
        "checkpoint prefix frontier record facts are not one bootstrap chain",
      );
    }
    const provenance = provenanceFacts.get(fact.provenance_identity);
    if (
      provenance?.ordinal !== ordinal ||
      provenance.record_oid !== fact.record_oid ||
      provenance.provenance_receipt_digest !==
        fact.provenance_receipt_digest ||
      provenance.provenance_token_sha256 !== fact.provenance_token_sha256
    ) {
      throw ledgerError(
        "CHECKPOINT_FRONTIER_MEMBERSHIP",
        "checkpoint prefix frontier provenance index is inconsistent",
      );
    }
    const queryRecord = checkpointState.source.query_records[ordinal];
    if (
      queryRecord.commit_sha !== fact.record_oid ||
      (queryRecord.parents[0] ?? null) !== fact.parent_oid ||
      queryRecord.tree_sha !== fact.tree_oid ||
      queryRecord.blob_sha !== fact.blob_oid ||
      queryRecord.envelope.sequence !== fact.sequence ||
      queryRecord.envelope.record_type !== fact.record_type ||
      queryRecord.envelope.envelope_digest !== fact.envelope_digest ||
      queryRecord.envelope.payload_digest !== fact.payload_digest ||
      queryRecord.envelope.server_observed_at !== fact.server_observed_at ||
      provenanceReplayIdentity(queryRecord.envelope.workflow_provenance) !==
        fact.provenance_identity ||
      queryRecord.envelope.workflow_provenance.receipt_digest !==
        fact.provenance_receipt_digest ||
      queryRecord.envelope.workflow_provenance.token_sha256 !==
        fact.provenance_token_sha256
    ) {
      throw ledgerError(
        "CHECKPOINT_FRONTIER_MEMBERSHIP",
        "checkpoint query seed differs from its exact frontier record fact",
      );
    }
    facts.push(fact);
  }
  if (
    facts[0].record_oid !== checkpointState.source.genesis_commit_sha ||
    facts[2].record_oid !== checkpointState.source.tip_commit_sha ||
    facts[2].record_oid !==
      checkpointState.source.capability_attestation_commit_sha ||
    facts[2].provenance_receipt_digest !==
      checkpointState.source.capability_activation.oidc_attestation_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_MEMBERSHIP",
      "checkpoint prefix frontier differs from its source boundary",
    );
  }
  const manifest = facts.map((fact) => ({
    record_oid: fact.record_oid,
    parent_oid: fact.parent_oid,
    tree_oid: fact.tree_oid,
    envelope_digest: fact.envelope_digest,
    record_type: fact.record_type,
    kind: null,
    effect_id: null,
    idempotency_key: null,
    payload_digest: fact.payload_digest,
    workflow_provenance_receipt_digest:
      fact.provenance_receipt_digest,
    workflow_provenance_jti: fact.provenance_identity,
    server_observed_at: fact.server_observed_at,
  }));
  if (digestCanonical(
    "codex-review-gate-v2-fully-reachable-record-manifest",
    manifest,
  ) !== checkpointState.source.record_manifest_digest) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_MEMBERSHIP",
      "checkpoint prefix frontier cannot reconstruct its source manifest",
    );
  }
  let rolling = digestCanonical(
    "codex-review-gate-v2-checkpoint-audit-root-empty",
    { record_count: 0 },
  );
  for (const fact of facts) {
    rolling = digestCanonical(
      "codex-review-gate-v2-checkpoint-audit-root-step",
      {
        prior_root: rolling,
        ordinal: fact.ordinal,
        record_oid: fact.record_oid,
        parent_oid: fact.parent_oid,
        envelope_digest: fact.envelope_digest,
        record_type: fact.record_type,
        server_observed_at: fact.server_observed_at,
      },
    );
  }
  if (rolling !== checkpointState.source.rolling_audit_root) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_MEMBERSHIP",
      "checkpoint prefix frontier rolling audit root is invalid",
    );
  }
  return {
    entry_count: entries.length,
    provenance_identities: new Set(provenanceFacts.keys()),
    tip_server_observed_at: facts[2].server_observed_at,
    attestation_fact: structuredClone(facts[2]),
  };
}

async function loadCheckpointPrefixFrontier({
  fetchImpl,
  authorization,
  base,
  repoPath,
  checkpointState,
  treeEntries,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const manifest = validateCheckpointPrefixFrontierManifest(
    checkpointState.prefix_frontier,
  );
  if (
    treeEntries.length !== manifest.tree_entry_count ||
    treeEntries.some((entry) =>
      entry.mode !== "100644" || entry.type !== "blob" ||
      entry.path !== `n-${entry.sha}.json`) ||
    digestCanonical(
      "codex-review-gate-v2-checkpoint-frontier-oids",
      treeEntries.map(({ sha: objectOid }) => objectOid).sort(),
    ) !== manifest.oid_set_digest
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_TREE_MISMATCH",
      "checkpoint frontier tree differs from its bounded manifest",
    );
  }
  const allowed = new Map(treeEntries.map((entry) => [entry.sha, entry]));
  const read = new Map();
  let readBytes = 0;
  const frontier = createV2PersistentMerkleMap({
    domain: CHECKPOINT_PREFIX_FRONTIER_DOMAIN,
    epoch_id: checkpointState.epoch_id,
    readBlob: async (objectOid, { max_bytes: maxBytes }) => {
      assertOperationCurrent();
      if (!allowed.has(objectOid) || read.has(objectOid)) {
        throw ledgerError(
          "CHECKPOINT_FRONTIER_OBJECT_REUSE",
          "checkpoint frontier requested a missing or repeated object",
        );
      }
      const bytes = await fetchExactGitBlobBytes({
        fetchImpl,
        authorization,
        base,
        repoPath,
        objectOid,
        maximumBytes: Math.min(
          maxBytes,
          MAX_V2_PERSISTENT_FRONTIER_NODE_BYTES,
        ),
        requestBudget,
        assertOperationCurrent,
      });
      assertOperationCurrent();
      assertHttpDeadlineOpen(requestBudget);
      read.set(objectOid, bytes);
      readBytes += bytes.byteLength;
      return new Uint8Array(bytes);
    },
    writeBlob: async () => {
      throw ledgerError(
        "CHECKPOINT_FRONTIER_READ_ONLY",
        "checkpoint frontier loader cannot write objects",
      );
    },
  });
  const page = await frontier.scan({
    root: manifest.root,
    limit: manifest.root.count,
  });
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  if (
    page.next_cursor !== null || read.size !== allowed.size ||
    readBytes !== manifest.raw_node_bytes ||
    read.size !== manifest.node_count
  ) {
    throw ledgerError(
      "CHECKPOINT_FRONTIER_CLOSURE_MISMATCH",
      "checkpoint frontier node closure differs from its complete tree",
    );
  }
  const validated = validateCheckpointPrefixEntries(
    page.entries,
    checkpointState,
  );
  assertOperationCurrent();
  assertHttpDeadlineOpen(requestBudget);
  return {
    entry_count: validated.entry_count,
    node_count: read.size,
    provenance_identities: validated.provenance_identities,
    tip_server_observed_at: validated.tip_server_observed_at,
    attestation_fact: validated.attestation_fact,
  };
}

function sameGitTreeEntries(actual, expected) {
  const byPath = (entries) => [...entries].sort((left, right) =>
    left.path.localeCompare(right.path));
  return canonicalJson(byPath(actual)) === canonicalJson(byPath(expected));
}

async function loadBootstrapCheckpointCandidateTransaction({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  repo,
  capability,
  verifyWorkflowProvenance,
  requestBudget,
  provenanceBudget,
  prepared,
  assertAdmissionCurrent,
}) {
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  if (
    prepared === null || typeof prepared !== "object" ||
    prepared.checkpoint_plan === undefined ||
    prepared.suffix === undefined || prepared.checkpoint_state === undefined
  ) {
    throw ledgerError(
      "UNTRUSTED_CHECKPOINT_PREPARATION_DIAGNOSTIC",
      "checkpoint loader requires one private prepared transaction binding",
    );
  }
  const expectedSuffixCount = prepared.suffix.semantic_record_count;
  if (
    expectedSuffixCount < 4 ||
    expectedSuffixCount > MAX_V2_CANDIDATE_SCAN_PASSES + 3
  ) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_CAP",
      "checkpoint suffix record count is outside its closed profile",
    );
  }
  const reverse = [];
  let cursor = prepared.suffix.transaction_tip_commit_sha;
  for (let index = 0; index < expectedSuffixCount; index += 1) {
    assertAdmissionCurrent();
    const entry = await fetchCommitEnvelope({
      fetchImpl,
      authorization,
      base,
      repoPath,
      commitSha: cursor,
      repo,
      ref,
      requestBudget,
      assertOperationCurrent: assertAdmissionCurrent,
    });
    assertAdmissionCurrent();
    if (entry.parents.length !== 1) {
      throw ledgerError(
        "CHECKPOINT_SUFFIX_PARENT",
        "checkpoint suffix record lacks one exact predecessor",
      );
    }
    reverse.push(entry);
    cursor = entry.parents[0];
    assertAdmissionCurrent();
    assertHttpDeadlineOpen(requestBudget);
  }
  if (cursor !== prepared.checkpoint_plan.commit_sha) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_PARENT",
      "checkpoint suffix does not terminate at its exact checkpoint root",
    );
  }
  let suffixRecords = reverse.reverse();
  for (let index = 0; index < suffixRecords.length; index += 1) {
    const expectedParent = index === 0
      ? prepared.checkpoint_plan.commit_sha
      : suffixRecords[index - 1].commit_sha;
    const entry = suffixRecords[index];
    if (
      entry.parents[0] !== expectedParent ||
      entry.envelope.predecessor_commit_sha !== expectedParent ||
      entry.envelope.sequence !== index + 1
    ) {
      throw ledgerError(
        "CHECKPOINT_SUFFIX_SEQUENCE",
        "checkpoint suffix sequence or parent binding is invalid",
      );
    }
  }

  assertAdmissionCurrent();
  const rootEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: prepared.checkpoint_plan.tree_sha,
    maximumEntries: 2,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const expectedRootEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: prepared.checkpoint_plan.carrier_blob_sha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_STATE_PATH,
    mode: "040000",
    type: "tree",
    sha: prepared.checkpoint_plan.state_tree_sha,
  }];
  if (!sameGitTreeEntries(rootEntries, expectedRootEntries)) {
    throw ledgerError(
      "CHECKPOINT_ROOT_TREE_MISMATCH",
      "checkpoint root tree differs from its carrier and state trees",
    );
  }
  assertAdmissionCurrent();
  const carrierBytes = await fetchExactGitBlobBytes({
    fetchImpl,
    authorization,
    base,
    repoPath,
    objectOid: prepared.checkpoint_plan.carrier_blob_sha,
    maximumBytes: MAX_V2_GIT_LEDGER_BLOB_BYTES,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  const carrierValue = parseCanonicalCheckpointJson(
    carrierBytes,
    "checkpoint carrier",
  );
  assertHttpDeadlineOpen(requestBudget);
  assertAdmissionCurrent();
  const stateTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: prepared.checkpoint_plan.state_tree_sha,
    maximumEntries: 2,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const expectedStateEntries = [{
    path: V2_GIT_LEDGER_CHECKPOINT_STATE_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: prepared.checkpoint_plan.state_blob_sha,
  }, {
    path: V2_GIT_LEDGER_CHECKPOINT_FRONTIER_NODES_PATH,
    mode: "040000",
    type: "tree",
    sha: prepared.checkpoint_plan.frontier_tree_sha,
  }];
  if (!sameGitTreeEntries(stateTreeEntries, expectedStateEntries)) {
    throw ledgerError(
      "CHECKPOINT_STATE_TREE_MISMATCH",
      "checkpoint state tree differs from its exact state and frontier",
    );
  }
  assertAdmissionCurrent();
  const stateBytes = await fetchExactGitBlobBytes({
    fetchImpl,
    authorization,
    base,
    repoPath,
    objectOid: prepared.checkpoint_plan.state_blob_sha,
    maximumBytes: MAX_V2_GIT_LEDGER_BLOB_BYTES,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  const checkpointState = validateBootstrapCheckpointState(
    parseCanonicalCheckpointJson(stateBytes, "checkpoint state"),
  );
  validateCheckpointCapabilityAgainstFactory(checkpointState, capability);
  assertHttpDeadlineOpen(requestBudget);
  if (
    checkpointState.checkpoint_state_digest !==
      prepared.checkpoint_state.checkpoint_state_digest ||
    canonicalJson(checkpointState.repository) !== canonicalJson(repo) ||
    checkpointState.ledger_ref !== ref ||
    checkpointState.prefix_frontier.tree_sha !==
      prepared.checkpoint_plan.frontier_tree_sha ||
    checkpointState.next_unit.admission_digest !==
      prepared.admission_private.next_unit_admission_handle
        .next_unit_admission_digest ||
    checkpointState.source.tip_commit_sha !==
      prepared.raw_source_tip_commit_sha
  ) {
    throw ledgerError(
      "CHECKPOINT_STATE_BINDING",
      "checkpoint state differs from its private source and admission facts",
    );
  }
  const carrier = validateCheckpointCarrier(carrierValue, {
    repository: repo,
    ledgerRef: ref,
    sourceTipCommitSha: prepared.raw_source_tip_commit_sha,
    checkpointState,
    stateTreeSha: prepared.checkpoint_plan.state_tree_sha,
    capability,
  });
  assertHttpDeadlineOpen(requestBudget);
  assertAdmissionCurrent();
  await fetchExactCheckpointCommit({
    fetchImpl,
    authorization,
    base,
    repoPath,
    commitSha: prepared.checkpoint_plan.commit_sha,
    expectedTreeSha: prepared.checkpoint_plan.tree_sha,
    expectedParentSha: prepared.raw_source_tip_commit_sha,
    expectedServerTime: carrier.server_observed_at,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const frontierTreeEntries = await fetchExactGitTree({
    fetchImpl,
    authorization,
    base,
    repoPath,
    treeSha: prepared.checkpoint_plan.frontier_tree_sha,
    maximumEntries: MAX_V2_PERSISTENT_FRONTIER_OPERATION_OBJECTS,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  const frontier = await loadCheckpointPrefixFrontier({
    fetchImpl,
    authorization,
    base,
    repoPath,
    checkpointState,
    treeEntries: frontierTreeEntries,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  if (
    Date.parse(checkpointState.source.observed_at) <
      Date.parse(frontier.tip_server_observed_at)
  ) {
    throw ledgerError(
      "CHECKPOINT_TIME_REGRESSION",
      "checkpoint source observation time precedes its authenticated tip",
    );
  }
  let priorServerTime = checkpointState.source.observed_at;
  if (
    Date.parse(carrier.server_observed_at) < Date.parse(priorServerTime)
  ) {
    throw ledgerError(
      "CHECKPOINT_TIME_REGRESSION",
      "checkpoint carrier observation time precedes its source prefix",
    );
  }
  priorServerTime = carrier.server_observed_at;
  for (const entry of suffixRecords) {
    if (
      Date.parse(entry.envelope.server_observed_at) <
        Date.parse(priorServerTime)
    ) {
      throw ledgerError(
        "CHECKPOINT_TIME_REGRESSION",
        "checkpoint suffix observation time regressed across its epoch root",
      );
    }
    priorServerTime = entry.envelope.server_observed_at;
  }
  assertHttpDeadlineOpen(requestBudget);
  const consumedJtis = new Set(frontier.provenance_identities);
  assertAdmissionCurrent();
  const checkpointLiveReceipt = await reverifyStoredWorkflowProvenance({
    verifyWorkflowProvenance,
    envelope: carrier,
    policy: capability.workflow_provenance_policy,
    provenanceBudget,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  assertUnusedProvenanceJti(consumedJtis, checkpointLiveReceipt);

  suffixRecords = await hydrateCurrentCandidateInventoryAttachments({
    records: suffixRecords,
    fetchImpl,
    authorization,
    base,
    repoPath,
    repository: repo,
    requestBudget,
    assertOperationCurrent: assertAdmissionCurrent,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  for (const entry of suffixRecords) {
    validateV2GitLedgerEnvelope(entry.envelope, {
      repository: repo,
      ledger_ref: ref,
      source_workflow: sourceWorkflow(capability.controller_release),
      provenance_policy: provenanceExpected(capability),
    });
    assertAdmissionCurrent();
    const liveReceipt = await reverifyStoredWorkflowProvenance({
      verifyWorkflowProvenance,
      envelope: entry.envelope,
      policy: capability.workflow_provenance_policy,
      provenanceBudget,
    });
    assertAdmissionCurrent();
    assertHttpDeadlineOpen(requestBudget);
    assertUnusedProvenanceJti(consumedJtis, liveReceipt);
  }
  const projectedState = projectChainState(
    suffixRecords,
    suffixRecords.at(-1).envelope.server_observed_at,
    {
      epochRecordOffset: 1,
      latestCapabilitySeed: checkpointLatestCapabilitySeed(checkpointState),
    },
  );
  const candidateAuthority =
    projectedState.authority_projection.candidate_inventory;
  const dispatchAuthority =
    projectedState.authority_projection.candidate_dispatch;
  const admittedCycle = prepared.admission_private.cycle;
  if (
    candidateAuthority.incomplete_cycle !== null ||
    candidateAuthority.completed_cycle?.cycle_id !==
      checkpointState.next_unit.cycle_id ||
    candidateAuthority.completed_cycle?.cycle_receipt.receipt_digest !==
      admittedCycle.cycle_receipt.receipt_digest ||
    dispatchAuthority.active_reservation === null
  ) {
    throw ledgerError(
      "CHECKPOINT_SUFFIX_AUTHORITY",
      "checkpoint suffix does not reconstruct its admitted candidate authority",
    );
  }
  const firstPlan = createCandidateDispatchPlan(
    dispatchAuthority.active_reservation,
  );
  const firstPlanBytes = Buffer.byteLength(canonicalJson(firstPlan), "utf8");
  if (
    firstPlan.schema_version !== 2 ||
    firstPlanBytes > candidateDispatchPlanByteCap(firstPlan) ||
    canonicalJson(firstPlan) !== canonicalJson(
      prepared.suffix.first_dispatch_plan,
    )
  ) {
    throw ledgerError(
      "CHECKPOINT_DISPATCH_PLAN_UNREPRESENTABLE",
      "checkpoint loader cannot reconstruct its exact bounded dispatch plan",
    );
  }
  const queryRecords = [
    ...checkpointState.source.query_records.map((entry) =>
      deepFreeze(structuredClone(entry))),
    ...suffixRecords,
  ];
  const queryState = {
    ...projectedState,
    projection: projectV2GitLedgerRecords(queryRecords),
    authority_projection: deriveV2GitLedgerAuthority(queryRecords),
  };
  const futureState = bootstrapCheckpointFutureState({
    checkpointCommitSha: prepared.checkpoint_plan.commit_sha,
    checkpointState,
    suffixRecords,
    projectedState: queryState,
    firstDispatchPlan: firstPlan,
  });
  assertAdmissionCurrent();
  assertHttpDeadlineOpen(requestBudget);
  return checkpointValidationDiagnostic({
    prepared,
    suffix: { records: suffixRecords },
    frontier,
    futureState,
  });
}

async function createCommitObjects({
  fetchImpl,
  authorization,
  base,
  repoPath,
  envelope,
  parents,
  requestBudget,
  candidateInventoryAttachment = null,
  assertOperationCurrent = () => {},
}) {
  let attachmentTreeCapture = null;
  let attachmentBlobCaptures = [];
  let attachmentTreeSha = null;
  if (candidateInventoryAttachment !== null) {
    const { manifest, expectedChunks } =
      validateCandidateInventoryAttachmentBundle(
        envelope,
        candidateInventoryAttachment,
      );
    for (const [index, chunk] of
      candidateInventoryAttachment.chunks.entries()) {
      const expected = expectedChunks[index];
      const bytes = Buffer.from(chunk.bytes);
      if (
        chunk.path !== expected.path ||
        bytes.byteLength !== expected.byte_length ||
        gitObjectSha("blob", bytes) !== expected.blob_sha ||
        rawDigest(bytes) !== expected.sha256
      ) {
        throw ledgerError(
          "candidate-inventory-attachment-binding",
          "candidate inventory attachment bytes differ from their manifest",
        );
      }
      assertOperationCurrent();
      const capture = await request({
        fetchImpl,
        authorization,
        base,
        method: "POST",
        path: `${repoPath}/git/blobs`,
        body: { content: bytes.toString("base64"), encoding: "base64" },
        expectedStatus: 201,
        requestBudget,
        assertOperationCurrent,
      });
      assertOperationCurrent();
      if (responseSha(capture.data, "created candidate attachment blob") !==
          expected.blob_sha) {
        throw ledgerError(
          "candidate-inventory-attachment-blob-identity",
          "created candidate inventory attachment blob changed identity",
        );
      }
      attachmentBlobCaptures.push(capture);
    }
    assertOperationCurrent();
    attachmentTreeCapture = await request({
      fetchImpl,
      authorization,
      base,
      method: "POST",
      path: `${repoPath}/git/trees`,
      body: { tree: structuredClone(candidateInventoryAttachment.tree_entries) },
      expectedStatus: 201,
      requestBudget,
      assertOperationCurrent,
    });
    assertOperationCurrent();
    attachmentTreeSha = responseSha(
      attachmentTreeCapture.data,
      "created candidate attachment tree",
    );
    if (attachmentTreeSha !== manifest.attachment_tree_sha ||
        canonicalGitTreeSha(candidateInventoryAttachment.tree_entries) !==
          attachmentTreeSha) {
      throw ledgerError(
        "candidate-inventory-attachment-tree-identity",
        "created candidate inventory attachment tree changed identity",
      );
    }
  }
  const bytes = `${canonicalJson(envelope)}\n`;
  if (Buffer.byteLength(bytes, "utf8") > MAX_V2_GIT_LEDGER_BLOB_BYTES) {
    throw ledgerError("blob-size", "Git ledger envelope exceeds its blob cap");
  }
  assertOperationCurrent();
  const blobCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "POST",
    path: `${repoPath}/git/blobs`,
    body: { content: bytes, encoding: "utf-8" },
    expectedStatus: 201,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const blobSha = responseSha(blobCapture.data, "created blob");
  const rootEntries = [{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }, ...(attachmentTreeSha === null ? [] : [{
    path: V2_GIT_LEDGER_CANDIDATE_INVENTORY_ATTACHMENT_PATH,
    mode: "040000",
    type: "tree",
    sha: attachmentTreeSha,
  }])];
  assertOperationCurrent();
  const treeCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "POST",
    path: `${repoPath}/git/trees`,
    body: { tree: rootEntries },
    expectedStatus: 201,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const treeSha = responseSha(treeCapture.data, "created tree");
  if (canonicalGitTreeSha(rootEntries) !== treeSha) {
    throw ledgerError(
      "tree-identity",
      "created Git ledger tree does not match its exact Git object identity",
    );
  }
  assertOperationCurrent();
  const commitCapture = await request({
    fetchImpl,
    authorization,
    base,
    method: "POST",
    path: `${repoPath}/git/commits`,
    body: {
      message: commitMessage(envelope),
      tree: treeSha,
      parents,
      author: {
        ...COMMIT_AUTHOR,
        date: envelope.server_observed_at,
      },
      committer: {
        ...COMMIT_AUTHOR,
        date: envelope.server_observed_at,
      },
    },
    expectedStatus: 201,
    requestBudget,
    assertOperationCurrent,
  });
  assertOperationCurrent();
  const commit = commitCapture.data;
  const commitSha = responseSha(commit, "created commit");
  if (
    commit.tree?.sha !== treeSha || !Array.isArray(commit.parents) ||
    canonicalJson(commit.parents.map((parent) => parent.sha)) !== canonicalJson(parents) ||
    commit.message !== commitMessage(envelope)
  ) {
    throw ledgerError("commit-create-echo", "created commit did not echo tree and parents");
  }
  validateCommitIdentity({
    commit,
    commitSha,
    treeSha,
    parents,
    envelope,
  });
  return {
    blob_sha: blobSha,
    tree_sha: treeSha,
    commit_sha: commitSha,
    object_write_receipts: {
      blob: { object_sha: blobSha, ...captureReceipt(blobCapture) },
      tree: { object_sha: treeSha, ...captureReceipt(treeCapture) },
      commit: { object_sha: commitSha, ...captureReceipt(commitCapture) },
      ...(attachmentTreeSha === null ? {} : {
        candidate_inventory_attachments: {
          tree: {
            object_sha: attachmentTreeSha,
            ...captureReceipt(attachmentTreeCapture),
          },
          blobs: attachmentBlobCaptures.map((capture, index) => ({
            object_sha: candidateInventoryAttachment.chunks[index].blob_sha,
            ...captureReceipt(capture),
          })),
        },
      }),
    },
  };
}

async function readRef({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  refSuffix,
  allowAbsent = false,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  const capture = await request({
    fetchImpl,
    authorization,
    base,
    method: "GET",
    path: `${repoPath}/git/ref/${refSuffix}`,
    expectedStatus: [200, 404],
    requestBudget,
    assertOperationCurrent,
  });
  if (capture.http_status === 404) {
    validateAbsentRefBody(capture.data);
    if (allowAbsent) {
      return deepFreeze({
        absent: true,
        ref,
        server_time: capture.server_time,
        raw_body_sha256: rawDigest(capture.raw_body_bytes),
      });
    }
    throw ledgerError("ref-absent", "protected Git ledger ref is absent");
  }
  return parseRefCapture(capture, ref);
}

async function createRef({
  fetchImpl,
  authorization,
  base,
  repoPath,
  ref,
  shaValue,
  requestBudget,
}) {
  const capture = await request({
    fetchImpl,
    authorization,
    base,
    method: "POST",
    path: `${repoPath}/git/refs`,
    body: { ref, sha: shaValue },
    expectedStatus: 201,
    requestBudget,
  });
  const parsed = parseRefCapture(capture, ref);
  if (parsed.target_commit_sha !== shaValue) {
    throw ledgerError("ref-create-echo", "created ref did not echo the genesis commit");
  }
  return capture;
}

async function updateRefStrict(options) {
  const capture = await request({
    fetchImpl: options.fetchImpl,
    authorization: options.authorization,
    base: options.base,
    method: "PATCH",
    path: `${options.repoPath}/git/refs/${options.refSuffix}`,
    body: { sha: options.shaValue, force: false },
    expectedStatus: [200, 409, 422],
    requestBudget: options.requestBudget,
  });
  if (capture.http_status !== 200) {
    validateNonFastForwardConflict(capture);
    const error = ledgerError(
      "non-fast-forward",
      "Git ledger append lost the atomic ref race; the sibling commit is unreachable",
    );
    error.http_status = capture.http_status;
    error.raw_body_sha256 = rawDigest(capture.raw_body_bytes);
    throw error;
  }
  const ref = parseRefCapture(capture, options.ref);
  if (ref.target_commit_sha !== options.shaValue) {
    throw ledgerError("ref-update-echo", "updated ref did not echo the appended commit");
  }
  return capture;
}

async function raceUpdateRef(options) {
  const capture = await request({
    fetchImpl: options.fetchImpl,
    authorization: options.authorization,
    base: options.base,
    method: "PATCH",
    path: `${options.repoPath}/git/refs/${options.refSuffix}`,
    body: { sha: options.shaValue, force: false },
    expectedStatus: [200, 409, 422],
    requestBudget: options.requestBudget,
  });
  if (capture.http_status === 200) {
    const ref = parseRefCapture(capture, options.ref);
    if (ref.target_commit_sha !== options.shaValue) {
      throw ledgerError("ref-update-echo", "race winner did not echo its commit");
    }
    return {
      outcome: "winner",
      http_status: 200,
      server_time: capture.server_time,
      raw_body_sha256: rawDigest(capture.raw_body_bytes),
    };
  }
  validateNonFastForwardConflict(capture);
  return {
    outcome: "non-fast-forward",
    http_status: capture.http_status,
    server_time: capture.server_time,
    raw_body_sha256: rawDigest(capture.raw_body_bytes),
  };
}

function parseRefCapture(capture, expectedRef) {
  assertObject(capture.data, "Git ref response");
  if (capture.data.ref !== expectedRef) {
    throw ledgerError("ref-identity", "Git ref response names another ref");
  }
  assertObject(capture.data.object, "Git ref object");
  if (capture.data.object.type !== "commit") {
    throw ledgerError("ref-target-type", "Git ledger ref must target a commit");
  }
  return deepFreeze({
    ref: expectedRef,
    node_id: boundedString(capture.data.node_id, "Git ref node_id", 256),
    target_commit_sha: sha(capture.data.object.sha, "Git ref target SHA"),
    server_time: capture.server_time,
    raw_body_sha256: rawDigest(capture.raw_body_bytes),
  });
}

function validateAbsentRefBody(value) {
  assertObject(value, "absent ref response");
  exactKeys(value, ["message", "documentation_url", "status"], "absent ref response");
  if (
    value.message !== "Not Found" || value.status !== "404" ||
    value.documentation_url !== "https://docs.github.com/rest/git/refs#get-a-reference"
  ) {
    throw ledgerError("unexpected-404", "absent ref response is not the closed GitHub profile");
  }
}

function validateNonFastForwardConflict(capture) {
  const profile = CONFLICT_PROFILES.get(capture.http_status);
  if (profile === undefined || canonicalJson(capture.data) !== canonicalJson(profile)) {
    throw ledgerError(
      "unexpected-ref-conflict",
      "ref update conflict does not match the documented non-fast-forward profile",
    );
  }
}

function assertHttpDeadlineOpen(requestBudget, requestDeadlineAt = null) {
  const now = performance.now();
  if (
    requestBudget.deadline_at_ms !== null &&
    now >= requestBudget.deadline_at_ms
  ) {
    throw ledgerError(
      "checkpoint-transaction-timeout",
      "checkpoint transaction exceeded its shared absolute deadline",
    );
  }
  if (requestDeadlineAt !== null && now >= requestDeadlineAt) {
    throw ledgerError(
      "http-timeout",
      "Git ledger GitHub request exceeded its fixed deadline",
    );
  }
}

async function request({
  fetchImpl,
  authorization,
  base,
  method,
  path,
  body = null,
  expectedStatus,
  requestBudget,
  assertOperationCurrent = () => {},
}) {
  assertOperationCurrent();
  validateHttpRequestBudget(requestBudget);
  assertHttpDeadlineOpen(requestBudget);
  const bodyText = body === null ? null : JSON.stringify(body);
  const bodyBytes = bodyText === null
    ? 0
    : Buffer.byteLength(bodyText, "utf8");
  assertHttpDeadlineOpen(requestBudget);
  if (
    requestBudget.request_body_bytes_limit !== null &&
    bodyBytes > requestBudget.request_body_bytes_limit
  ) {
    throw ledgerError(
      "http-request-body-cap",
      "Git ledger GitHub request exceeds its per-request body cap",
    );
  }
  if (
    requestBudget.total_request_body_bytes_limit !== null &&
    bodyBytes > requestBudget.total_request_body_bytes_limit -
      requestBudget.total_request_body_bytes
  ) {
    throw ledgerError(
      "http-total-request-byte-cap",
      "Git ledger exhausted its aggregate GitHub request body cap",
    );
  }
  if (requestBudget.request_count >= requestBudget.limits.request_count) {
    throw ledgerError(
      "http-request-cap",
      "Git ledger exhausted its aggregate GitHub request cap",
    );
  }
  requestBudget.request_count += 1;
  requestBudget.total_request_body_bytes += bodyBytes;

  const remainingMs = requestBudget.deadline_at_ms === null
    ? requestBudget.limits.timeout_ms
    : Math.min(
      requestBudget.limits.timeout_ms,
      Math.ceil(requestBudget.deadline_at_ms - performance.now()),
    );
  if (remainingMs < 1) {
    throw ledgerError(
      "checkpoint-transaction-timeout",
      "checkpoint transaction exceeded its shared absolute deadline",
    );
  }
  const requestDeadlineAt = performance.now() + remainingMs;

  const controller = new AbortController();
  let rejectDeadline;
  const deadline = new Promise((resolve, reject) => {
    void resolve;
    rejectDeadline = reject;
  });
  const abortRequest = createAbortBestEffort(
    controller,
    "Git ledger HTTP request cleanup",
  );
  const timer = setTimeout(() => {
    const error = ledgerError(
      "http-timeout",
      "Git ledger GitHub request exceeded its fixed deadline",
    );
    rejectDeadline(error);
    abortRequest();
  }, remainingMs);
  let responseBody = null;
  let responseBodyComplete = false;
  try {
    let response;
    try {
      response = await Promise.race([
        fetchImpl(`${base}${path}`, {
          method,
          redirect: "error",
          signal: controller.signal,
          headers: {
            accept: "application/vnd.github+json",
            authorization: `Bearer ${authorization}`,
            "x-github-api-version": "2022-11-28",
            ...(body === null ? {} : { "content-type": "application/json" }),
          },
          ...(bodyText === null ? {} : { body: bodyText }),
        }),
        deadline,
      ]);
    } catch (error) {
      if (
        error?.code === "http-timeout" ||
        error?.code === "checkpoint-transaction-timeout"
      ) throw error;
      throw ledgerError(
        "http-request-failed",
        "Git ledger GitHub request failed before a response was read",
        error,
      );
    }
    try {
      responseBody = response?.body;
    } catch (error) {
      throw ledgerError(
        "invalid-http-response",
        "Git ledger GitHub response body could not be captured",
        error,
      );
    }
    assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
    assertOperationCurrent();
    let responseStatus;
    let responseHeaders;
    try {
      responseStatus = response?.status;
      responseHeaders = response?.headers;
    } catch (error) {
      throw ledgerError(
        "invalid-http-response",
        "Git ledger GitHub response properties could not be read",
        error,
      );
    }
    if (
      response === null || typeof response !== "object" ||
      !Number.isInteger(responseStatus) ||
      typeof responseHeaders?.get !== "function" ||
      typeof responseBody?.getReader !== "function"
    ) {
      throw ledgerError(
        "invalid-http-response",
        "Git ledger GitHub response is not Response-compatible",
      );
    }
    const expected = Array.isArray(expectedStatus) ? expectedStatus : [expectedStatus];
    if (!expected.includes(responseStatus)) {
      throw ledgerError(
        "unexpected-http-status",
        `Git ledger expected HTTP ${expected.join(" or ")} and received ${responseStatus}`,
      );
    }
    const declaredLength = parseContentLength(
      responseHeaders.get("content-length"),
    );
    if (declaredLength !== null &&
        declaredLength > requestBudget.limits.response_bytes) {
      throw ledgerError(
        "http-response-cap",
        "Git ledger GitHub response exceeds its declared byte cap",
      );
    }
    const serverTime = githubServerTime(responseHeaders.get("date"));
    assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
    const rawBody = await readResponseBodyBounded({
      responseBody,
      deadline,
      abortRequest,
      requestBudget,
      requestDeadlineAt,
      assertOperationCurrent,
    });
    responseBodyComplete = true;
    assertOperationCurrent();
    assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
    let data;
    try {
      data = JSON.parse(rawBody.text);
    } catch (error) {
      throw ledgerError("invalid-api-json", "Git ledger API response is not JSON", error);
    }
    assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
    assertOperationCurrent();
    return {
      http_status: responseStatus,
      server_time: serverTime,
      raw_body: rawBody.text,
      raw_body_bytes: rawBody.bytes,
      data,
    };
  } catch (error) {
    abortRequest();
    throw error;
  } finally {
    clearTimeout(timer);
    if (!responseBodyComplete) cancelReadableBestEffort(responseBody);
  }
}

function createHttpRequestBudget(limits, {
  deadline_at_ms: deadlineAtMs = null,
  request_body_bytes: requestBodyBytes = null,
  total_request_body_bytes: totalRequestBodyBytes = null,
} = {}) {
  if (
    deadlineAtMs !== null &&
    (!Number.isFinite(deadlineAtMs) || deadlineAtMs <= performance.now())
  ) {
    throw new TypeError("Git ledger HTTP budget deadline is invalid");
  }
  for (const [label, value] of [
    ["request body bytes", requestBodyBytes],
    ["total request body bytes", totalRequestBodyBytes],
  ]) {
    if (value !== null && (!Number.isSafeInteger(value) || value < 1)) {
      throw new TypeError(`Git ledger HTTP budget ${label} is invalid`);
    }
  }
  if (
    requestBodyBytes !== null && totalRequestBodyBytes !== null &&
    requestBodyBytes > totalRequestBodyBytes
  ) {
    throw new TypeError(
      "Git ledger HTTP per-request body cap exceeds its aggregate cap",
    );
  }
  return {
    request_count: 0,
    total_response_bytes: 0,
    total_request_body_bytes: 0,
    deadline_at_ms: deadlineAtMs,
    request_body_bytes_limit: requestBodyBytes,
    total_request_body_bytes_limit: totalRequestBodyBytes,
    limits: normalizeHttpLimits(limits),
  };
}

function createProvenanceBudget(timeoutMs, deadlineAtMs = null) {
  if (
    deadlineAtMs !== null &&
    (!Number.isFinite(deadlineAtMs) || deadlineAtMs <= performance.now())
  ) {
    throw new TypeError("Git ledger provenance budget deadline is invalid");
  }
  return {
    call_count: 0,
    maximum_calls: MAX_V2_GIT_LEDGER_COMMITS * 8 + 64,
    timeout_ms: normalizeProvenanceTimeout(timeoutMs),
    deadline_at_ms: deadlineAtMs,
  };
}

function consumeProvenanceBudget(budget) {
  if (
    budget === null || typeof budget !== "object" ||
    !Number.isSafeInteger(budget.call_count) || budget.call_count < 0 ||
    !Number.isSafeInteger(budget.maximum_calls) || budget.maximum_calls < 1 ||
    !Number.isSafeInteger(budget.timeout_ms) || budget.timeout_ms < 1 ||
    budget.timeout_ms > V2_GIT_LEDGER_PROVENANCE_TIMEOUT_MS ||
    (budget.deadline_at_ms !== null &&
      (!Number.isFinite(budget.deadline_at_ms) ||
        budget.deadline_at_ms <= 0))
  ) {
    throw new TypeError("Git ledger provenance verifier budget is invalid");
  }
  if (budget.call_count >= budget.maximum_calls) {
    throw ledgerError(
      "provenance-call-cap",
      "Git ledger exhausted its bounded provenance verifier calls",
    );
  }
  budget.call_count += 1;
  const timeoutMs = budget.deadline_at_ms === null
    ? budget.timeout_ms
    : Math.min(
      budget.timeout_ms,
      Math.ceil(budget.deadline_at_ms - performance.now()),
    );
  if (timeoutMs < 1) {
    throw ledgerError(
      "checkpoint-transaction-timeout",
      "checkpoint transaction exceeded its shared absolute deadline",
    );
  }
  const deadlineAtMs = performance.now() + timeoutMs;
  const controller = new AbortController();
  let rejectDeadline;
  const deadline = new Promise((resolve, reject) => {
    void resolve;
    rejectDeadline = reject;
  });
  const abortVerifier = createAbortBestEffort(
    controller,
    "Git ledger provenance verifier cleanup",
  );
  const timer = setTimeout(() => {
    const error = ledgerError(
      "provenance-timeout",
      "Git ledger provenance verifier exceeded its fixed deadline",
    );
    rejectDeadline(error);
    abortVerifier();
  }, timeoutMs);
  return {
    signal: controller.signal,
    deadline,
    timeout_ms: timeoutMs,
    assertOpen() {
      if (
        budget.deadline_at_ms !== null &&
        performance.now() >= budget.deadline_at_ms
      ) {
        throw ledgerError(
          "checkpoint-transaction-timeout",
          "checkpoint transaction exceeded its shared absolute deadline",
        );
      }
      if (performance.now() >= deadlineAtMs) {
        throw ledgerError(
          "provenance-timeout",
          "Git ledger provenance verifier exceeded its fixed deadline",
        );
      }
    },
    finish() {
      clearTimeout(timer);
    },
  };
}

function normalizeProvenanceTimeout(value) {
  const normalized = positiveInteger(value, "Git ledger provenance timeout");
  if (normalized > V2_GIT_LEDGER_PROVENANCE_TIMEOUT_MS) {
    throw new Error("Git ledger provenance timeout may only tighten its hard maximum");
  }
  return normalized;
}

function validateHttpRequestBudget(value) {
  if (
    value === null || typeof value !== "object" || Array.isArray(value) ||
    !Number.isSafeInteger(value.request_count) || value.request_count < 0 ||
    !Number.isSafeInteger(value.total_response_bytes) ||
    value.total_response_bytes < 0 ||
    !Number.isSafeInteger(value.total_request_body_bytes) ||
    value.total_request_body_bytes < 0 ||
    (value.deadline_at_ms !== null &&
      (!Number.isFinite(value.deadline_at_ms) || value.deadline_at_ms <= 0)) ||
    (value.request_body_bytes_limit !== null &&
      (!Number.isSafeInteger(value.request_body_bytes_limit) ||
        value.request_body_bytes_limit < 1)) ||
    (value.total_request_body_bytes_limit !== null &&
      (!Number.isSafeInteger(value.total_request_body_bytes_limit) ||
        value.total_request_body_bytes_limit < 1)) ||
    value.limits === null ||
    typeof value.limits !== "object"
  ) {
    throw new TypeError("Git ledger HTTP budget is invalid");
  }
}

function normalizeHttpLimits(value) {
  assertObject(value, "Git ledger HTTP limits");
  exactKeys(value, [
    "request_count", "response_bytes", "total_response_bytes", "timeout_ms",
  ], "Git ledger HTTP limits");
  const normalized = {
    request_count: positiveInteger(value.request_count,
      "Git ledger HTTP limits.request_count"),
    response_bytes: positiveInteger(value.response_bytes,
      "Git ledger HTTP limits.response_bytes"),
    total_response_bytes: positiveInteger(value.total_response_bytes,
      "Git ledger HTTP limits.total_response_bytes"),
    timeout_ms: positiveInteger(value.timeout_ms,
      "Git ledger HTTP limits.timeout_ms"),
  };
  if (
    normalized.request_count > MAX_V2_GIT_LEDGER_HTTP_REQUESTS ||
    normalized.response_bytes > MAX_V2_GIT_LEDGER_HTTP_RESPONSE_BYTES ||
    normalized.total_response_bytes > MAX_V2_GIT_LEDGER_HTTP_TOTAL_BYTES ||
    normalized.timeout_ms > V2_GIT_LEDGER_HTTP_TIMEOUT_MS
  ) {
    throw new Error("Git ledger HTTP limits may only tighten hard maxima");
  }
  return deepFreeze(normalized);
}

async function readResponseBodyBounded({
  responseBody,
  deadline,
  abortRequest,
  requestBudget,
  requestDeadlineAt,
  assertOperationCurrent = () => {},
}) {
  assertOperationCurrent();
  const reader = responseBody.getReader();
  const chunks = [];
  let responseBytes = 0;
  let chunkCount = 0;
  const cancelReader = createBestEffortOnce(() => cancelReadable(reader));
  const releaseReader = createBestEffortOnce(() => releaseReaderLock(reader));
  try {
    while (true) {
      assertOperationCurrent();
      assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
      let read;
      try {
        read = await Promise.race([reader.read(), deadline]);
      } catch (error) {
        if (
          error?.code === "http-timeout" ||
          error?.code === "checkpoint-transaction-timeout"
        ) throw error;
        throw ledgerError(
          "http-body-failed",
          "Git ledger GitHub response body could not be read",
          error,
        );
      }
      assertOperationCurrent();
      assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
      const { done, chunk } = closedResponseReadResult(read);
      if (done) {
        break;
      }
      const chunkBytes = chunk.byte_length;
      chunkCount += 1;
      if (
        chunkBytes === 0 ||
        chunkCount > MAX_V2_GIT_LEDGER_HTTP_BODY_CHUNKS
      ) {
        throw ledgerError(
          "http-response-chunk-cap",
          "Git ledger GitHub response stream exceeds its chunk profile",
        );
      }
      const nextResponseBytes = responseBytes + chunkBytes;
      if (nextResponseBytes > requestBudget.limits.response_bytes) {
        throw ledgerError(
          "http-response-cap",
          "Git ledger GitHub response exceeds its streamed byte cap",
        );
      }
      if (
        requestBudget.total_response_bytes + chunkBytes >
        requestBudget.limits.total_response_bytes
      ) {
        throw ledgerError(
          "http-total-byte-cap",
          "Git ledger exhausted its aggregate GitHub response byte cap",
        );
      }
      assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
      const snapshot = snapshotResponseByteChunk(chunk);
      const copiedBytes = snapshot.length;
      if (copiedBytes !== chunkBytes) {
        throw ledgerError(
          "invalid-http-response",
          "Git ledger GitHub response stream chunk copy changed length",
        );
      }
      assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
      assertOperationCurrent();
      responseBytes += copiedBytes;
      requestBudget.total_response_bytes += copiedBytes;
      chunks.push(snapshot);
    }
  } catch (error) {
    abortRequest();
    cancelReader();
    throw error;
  } finally {
    releaseReader();
  }
  if (responseBytes === 0) {
    throw ledgerError(
      "http-response-cap",
      "Git ledger GitHub response body must be non-empty",
    );
  }
  assertOperationCurrent();
  const bytes = Buffer.concat(chunks, responseBytes);
  let decoded;
  try {
    decoded = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true })
      .decode(bytes);
  } catch (error) {
    if (
      error?.code === "http-timeout" ||
      error?.code === "checkpoint-transaction-timeout"
    ) throw error;
    throw ledgerError(
      "invalid-api-utf8",
      "Git ledger GitHub response is not valid UTF-8",
      error,
    );
  }
  assertHttpDeadlineOpen(requestBudget, requestDeadlineAt);
  assertOperationCurrent();
  return { bytes, text: decoded };
}

function closedResponseReadResult(read) {
  let descriptors;
  try {
    if (read === null || typeof read !== "object") {
      throw new TypeError("response stream result is not an object");
    }
    descriptors = Object.getOwnPropertyDescriptors(read);
  } catch (error) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream result could not be snapshotted",
      error,
    );
  }
  const keys = Reflect.ownKeys(descriptors);
  if (
    keys.length !== 2 ||
    !Object.hasOwn(descriptors, "done") ||
    !Object.hasOwn(descriptors, "value")
  ) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream result is not closed",
    );
  }
  const doneDescriptor = descriptors.done;
  const valueDescriptor = descriptors.value;
  if (
    !Object.hasOwn(doneDescriptor, "value") ||
    !Object.hasOwn(valueDescriptor, "value") ||
    Object.hasOwn(doneDescriptor, "get") ||
    Object.hasOwn(doneDescriptor, "set") ||
    Object.hasOwn(valueDescriptor, "get") ||
    Object.hasOwn(valueDescriptor, "set") ||
    typeof doneDescriptor.value !== "boolean"
  ) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream result uses invalid descriptors",
    );
  }
  const done = doneDescriptor.value;
  const value = valueDescriptor.value;
  if (done) {
    if (value !== undefined) {
      throw ledgerError(
        "invalid-http-response",
        "Git ledger GitHub response terminal stream result contains bytes",
      );
    }
    return { done: true, chunk: null };
  }
  return { done: false, chunk: inspectResponseByteChunk(value) };
}

function inspectResponseByteChunk(value) {
  let isBytes;
  try {
    isBytes = safeReflectApply(isUint8ArrayIntrinsic, utilTypes, [value]);
  } catch (error) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream chunk could not be inspected",
      error,
    );
  }
  if (!isBytes) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream chunk is not bytes",
    );
  }
  try {
    const backing = safeReflectApply(typedArrayBufferGetter, value, []);
    const isOrdinaryArrayBuffer = safeReflectApply(
      isArrayBufferIntrinsic,
      utilTypes,
      [backing],
    );
    if (!isOrdinaryArrayBuffer) {
      throw new TypeError(
        "response byte chunks require ordinary ArrayBuffer backing",
      );
    }
    const detached = arrayBufferDetachedGetter === null
      ? false
      : safeReflectApply(arrayBufferDetachedGetter, backing, []);
    const resizable = arrayBufferResizableGetter === null
      ? false
      : safeReflectApply(arrayBufferResizableGetter, backing, []);
    const byteOffset = safeReflectApply(
      typedArrayByteOffsetGetter,
      value,
      [],
    );
    const byteLength = safeReflectApply(
      typedArrayByteLengthGetter,
      value,
      [],
    );
    if (detached || resizable) {
      throw new TypeError(
        "response byte chunks require fixed attached backing",
      );
    }
    return { value, backing, byte_offset: byteOffset, byte_length: byteLength };
  } catch (error) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream chunk could not be inspected exactly",
      error,
    );
  }
}

function snapshotResponseByteChunk(chunk) {
  try {
    const isBytes = safeReflectApply(
      isUint8ArrayIntrinsic,
      utilTypes,
      [chunk.value],
    );
    const backing = safeReflectApply(
      typedArrayBufferGetter,
      chunk.value,
      [],
    );
    const byteOffset = safeReflectApply(
      typedArrayByteOffsetGetter,
      chunk.value,
      [],
    );
    const byteLength = safeReflectApply(
      typedArrayByteLengthGetter,
      chunk.value,
      [],
    );
    const isOrdinaryArrayBuffer = safeReflectApply(
      isArrayBufferIntrinsic,
      utilTypes,
      [backing],
    );
    const detached = !isOrdinaryArrayBuffer ||
      arrayBufferDetachedGetter === null
      ? false
      : safeReflectApply(arrayBufferDetachedGetter, backing, []);
    const resizable = !isOrdinaryArrayBuffer ||
      arrayBufferResizableGetter === null
      ? false
      : safeReflectApply(arrayBufferResizableGetter, backing, []);
    if (
      !isBytes ||
      !isOrdinaryArrayBuffer ||
      detached ||
      resizable ||
      backing !== chunk.backing ||
      byteOffset !== chunk.byte_offset ||
      byteLength !== chunk.byte_length
    ) {
      throw new TypeError("response byte chunk changed before snapshot");
    }
    const source = new Uint8Array(backing, byteOffset, byteLength);
    const snapshot = safeReflectApply(bufferAllocIntrinsic, Buffer, [byteLength]);
    safeReflectApply(uint8ArraySetIntrinsic, snapshot, [source, 0]);
    return snapshot;
  } catch (error) {
    throw ledgerError(
      "invalid-http-response",
      "Git ledger GitHub response stream chunk could not be copied exactly",
      error,
    );
  }
}

function releaseReaderLock(reader) {
  if (
    reader === null ||
    (typeof reader !== "object" && typeof reader !== "function")
  ) {
    throw new TypeError("response reader is not an object");
  }
  const releaseLock = reader.releaseLock;
  if (typeof releaseLock !== "function") {
    throw new TypeError("response reader releaseLock is not callable");
  }
  return safeReflectApply(releaseLock, reader, []);
}

function cancelReadableBestEffort(readable) {
  startBestEffort(() => cancelReadable(readable));
}

function cancelReadable(readable) {
  if (readable === null || typeof readable !== "object") return;
  const cancel = readable.cancel;
  if (typeof cancel !== "function") return;
  return safeReflectApply(cancel, readable, []);
}

function createAbortBestEffort(controller, message) {
  // AbortSignal listeners are trusted to remain non-throwing. The fresh reason
  // keeps listener mutation separate from the authoritative request failure.
  return createBestEffortOnce(() => safeReflectApply(
    abortControllerAbortIntrinsic,
    controller,
    [new Error(message)],
  ));
}

function createBestEffortOnce(action) {
  let started = false;
  return () => {
    if (started) return;
    started = true;
    startBestEffort(action);
  };
}

function startBestEffort(action) {
  if (typeof action !== "function") return;
  let invoked = false;
  try {
    safeScheduleImmediate(() => {
      if (invoked) return;
      invoked = true;
      try {
        void Promise.resolve(action()).catch(() => {});
      } catch {
        // Isolate synchronous cleanup errors and returned promise rejections.
      }
    });
  } catch {
    // Scheduling cleanup is best-effort and must not replace the primary result.
  }
}

function parseContentLength(value) {
  if (value === null) return null;
  if (!/^(?:0|[1-9][0-9]*)$/u.test(value)) {
    throw ledgerError(
      "invalid-content-length",
      "Git ledger GitHub response Content-Length is invalid",
    );
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw ledgerError(
      "invalid-content-length",
      "Git ledger GitHub response Content-Length is outside the safe range",
    );
  }
  return parsed;
}

function validateInternalEnvelopeFields(value) {
  if (value.record_type === "genesis") {
    if (
      value.sequence !== 0 || value.predecessor_commit_sha !== null ||
      value.pull_request !== null || value.head_ref_oid !== null ||
      value.base_ref_oid !== null || value.potential_merge_commit_oid !== null ||
      value.kind !== null || value.effect_id !== null || value.idempotency_key !== null ||
      value.control_comment_binding !== null || value.lease !== null
    ) {
      throw new Error("Git ledger genesis has non-genesis fields");
    }
    assertObject(value.payload, "genesis payload");
    exactKeys(value.payload, [
      "sealed", "bootstrap_candidate_digest", "bootstrap_candidate",
    ], "genesis payload");
    if (value.payload.sealed !== true) throw new Error("Git ledger genesis is not sealed");
    digest(value.payload.bootstrap_candidate_digest,
      "genesis bootstrap_candidate_digest");
    validateEmbeddedBootstrapCandidate(
      value.payload,
      value.repository,
      value.ledger_ref,
    );
    return;
  }
  if (value.record_type === "capability-canary") {
    assertNullProductionScope(value, "capability canary");
    assertObject(value.payload, "capability canary payload");
    exactKeys(value.payload, [
      "contender", "genesis_commit_sha", "race_parent_commit_sha",
      "bootstrap_candidate_digest", "bootstrap_candidate",
    ], "capability canary payload");
    if (!new Set(["alpha", "beta"]).has(value.payload.contender)) {
      throw new Error("capability contender is invalid");
    }
    sha(value.payload.genesis_commit_sha, "canary genesis_commit_sha");
    sha(value.payload.race_parent_commit_sha, "canary race_parent_commit_sha");
    digest(value.payload.bootstrap_candidate_digest,
      "canary bootstrap_candidate_digest");
    validateEmbeddedBootstrapCandidate(
      value.payload,
      value.repository,
      value.ledger_ref,
    );
    return;
  }
  if (value.record_type === "capability-attestation") {
    assertNullProductionScope(value, "capability attestation");
    validateAttestationPayload(value.payload);
    if (
      canonicalJson(value.source_workflow) !== canonicalJson(sourceWorkflow(
        normalizeControllerRelease(value.payload.controller_release),
      ))
    ) {
      throw new Error("capability attestation source workflow binding is invalid");
    }
    return;
  }
  validateRecordTypeFields(value);
}

function validateAttestationPayload(payload) {
  assertObject(payload, "capability attestation payload");
  exactKeys(payload, [
    "genesis_commit_sha",
    "race_parent_commit_sha",
    "bootstrap_candidate_digest",
    "write_observation_receipt",
    "capability_input_digest",
    "capability_stable_digest",
    "capability_receipt",
    "protection_receipt_digest",
    "controller_release",
    "contenders",
    "winner_commit_sha",
    "race_final_ref_reread",
    "recovered_unattested_canary_commits",
  ], "capability attestation payload");
  sha(payload.genesis_commit_sha, "attestation genesis_commit_sha");
  sha(payload.race_parent_commit_sha, "attestation race_parent_commit_sha");
  digest(payload.bootstrap_candidate_digest,
    "attestation bootstrap_candidate_digest");
  const writeObservation = validateWriteObservationReceipt(
    payload.write_observation_receipt,
  );
  if (
    writeObservation.bootstrap_candidate_digest !==
      payload.bootstrap_candidate_digest ||
    writeObservation.race_parent_commit_sha !== payload.race_parent_commit_sha
  ) {
    throw new Error("attestation write observation binds another bootstrap race");
  }
  digest(payload.capability_input_digest, "attestation capability_input_digest");
  digest(payload.capability_stable_digest,
    "attestation capability_stable_digest");
  const capability = validateEmbeddedCapability(payload);
  if (
    capability.bootstrap_candidate_digest !==
      payload.bootstrap_candidate_digest ||
    capability.permissions.observation_receipt_digest !==
      writeObservation.receipt_digest ||
    stableCapabilityBindingDigest(capability) !==
      payload.capability_stable_digest
  ) {
    throw new Error("attestation capability does not bind its write observation");
  }
  digest(payload.protection_receipt_digest, "attestation protection_receipt_digest");
  normalizeControllerRelease(payload.controller_release);
  if (!Array.isArray(payload.contenders) || payload.contenders.length !== 2) {
    throw new Error("capability attestation requires exactly two contenders");
  }
  const labels = new Set();
  for (const contender of payload.contenders) {
    assertObject(contender, "capability contender receipt");
    exactKeys(contender, [
      "label", "commit_sha", "outcome", "http_status", "server_time",
      "raw_body_sha256",
    ], "capability contender receipt");
    if (!new Set(["alpha", "beta"]).has(contender.label) || labels.has(contender.label)) {
      throw new Error("capability contender labels are invalid or repeated");
    }
    labels.add(contender.label);
    sha(contender.commit_sha, "capability contender commit_sha");
    if (contender.outcome === "winner") {
      if (contender.http_status !== 200) throw new Error("winner status must be 200");
    } else if (contender.outcome === "non-fast-forward") {
      if (!CONFLICT_PROFILES.has(contender.http_status)) {
        throw new Error("loser status is not a documented non-fast-forward conflict");
      }
    } else {
      throw new Error("capability contender outcome is invalid");
    }
    timestamp(contender.server_time, "capability contender server_time");
    digest(contender.raw_body_sha256, "capability contender raw_body_sha256");
  }
  sha(payload.winner_commit_sha, "attestation winner_commit_sha");
  validateRefReceipt(payload.race_final_ref_reread);
  if (
    !Array.isArray(payload.recovered_unattested_canary_commits) ||
    payload.recovered_unattested_canary_commits.length > 32
  ) {
    throw new Error("capability recovery canary list is invalid");
  }
  const recovered = new Set();
  for (const commitSha of payload.recovered_unattested_canary_commits) {
    const current = sha(commitSha, "recovered capability canary commit");
    if (recovered.has(current)) {
      throw new Error("capability recovery repeats a canary commit");
    }
    recovered.add(current);
  }
}

function validateEmbeddedCapability(payload, repository = null, ledgerRef = null) {
  const capability = validateV2GitLedgerCapabilityReceipt(
    payload.capability_receipt,
    repository === null ? null : {
      repository,
      ledger_ref: ledgerRef,
    },
  );
  if (capabilityBindingDigest(capability) !== payload.capability_input_digest) {
    throw new Error("embedded capability receipt binding digest is invalid");
  }
  return capability;
}

function validateEmbeddedBootstrapCandidate(
  payload,
  repository = null,
  ledgerRef = null,
) {
  const candidate = validateV2GitLedgerBootstrapInput(
    payload.bootstrap_candidate,
    repository === null ? null : {
      repository,
      ledger_ref: ledgerRef,
    },
  );
  if (candidate.input_digest !== payload.bootstrap_candidate_digest) {
    throw new Error("embedded bootstrap candidate digest is invalid");
  }
  return candidate;
}

function assertNullProductionScope(value, label) {
  if (
    value.pull_request !== null || value.head_ref_oid !== null ||
    value.base_ref_oid !== null || value.potential_merge_commit_oid !== null ||
    value.kind !== null || value.effect_id !== null || value.idempotency_key !== null ||
    value.control_comment_binding !== null || value.lease !== null
  ) {
    throw new Error(`${label} has production-only fields`);
  }
}

function validateRecordTypeFields(value) {
  if (value.record_type === "candidate-inventory-observation") {
    if (
      value.pull_request !== null || value.head_ref_oid !== null ||
      value.base_ref_oid !== null ||
      value.potential_merge_commit_oid !== null || value.kind !== null ||
      value.effect_id !== null || value.idempotency_key !== null ||
      value.control_comment_binding !== null || value.lease !== null
    ) {
      throw new Error("candidate inventory record has PR-effect fields");
    }
    validateV2GitLedgerCandidateInventoryPayload(value.payload);
    return;
  }
  if (value.record_type === "candidate-dispatch-observation") {
    if (
      value.pull_request !== null || value.head_ref_oid !== null ||
      value.base_ref_oid !== null ||
      value.potential_merge_commit_oid !== null || value.kind !== null ||
      value.effect_id !== null || value.idempotency_key !== null ||
      value.control_comment_binding !== null || value.lease !== null
    ) {
      throw new Error("candidate dispatch record has PR-effect fields");
    }
    validateV2GitLedgerCandidateDispatchPayload(value.payload);
    return;
  }
  normalizePullRequest(value.pull_request);
  sha(value.head_ref_oid, "production head_ref_oid");
  sha(value.base_ref_oid, "production base_ref_oid");
  nullableSha(value.potential_merge_commit_oid, "production potential_merge_commit_oid");
  if (value.record_type === "lease-acquire") {
    requireNullEffectFields(value, "lease acquire");
    if (value.lease !== null) throw new Error("lease acquire cannot bind itself");
    validateLeaseAcquirePayload(value.payload);
  } else if (value.record_type === "lease-release") {
    requireNullEffectFields(value, "lease release");
    normalizeLeaseBinding(value.lease, { required: true });
    validateLeaseReleasePayload(value.payload);
  } else {
    const kind = boundedString(value.kind, "effect kind", 128);
    if (!EFFECT_KINDS.has(kind)) {
      throw new Error("effect kind is outside the closed Git ledger kind set");
    }
    boundedString(value.effect_id, "effect_id", 256);
    boundedString(value.idempotency_key, "idempotency_key", 256);
    const control = normalizeControlCommentBinding(value.control_comment_binding);
    const lease = normalizeLeaseBinding(value.lease, { required: true });
    if (kind === "control-comment-create") {
      if (value.record_type === "effect-intent" && control !== null) {
        throw new Error("control-comment-create intent must precede its comment binding");
      }
      if (value.record_type === "effect-response" && control === null) {
        throw new Error("control-comment-create response requires the exact new comment binding");
      }
    }
    if (kind === "control-comment-update" && control === null) {
      throw new Error("control-comment-update requires an exact comment binding");
    }
    if (
      new Set([
        "automatic-request-reservation", "scheduler-observation",
        "effect-attempt",
      ]).has(kind) && value.record_type !== "effect-intent"
    ) {
      throw new Error(`${kind} is one authoritative intent record`);
    }
    validateV2GitLedgerEffectPayload(value.payload, {
      record_type: value.record_type,
      kind,
      scope: recordScope(value),
      predecessor_commit_sha: value.predecessor_commit_sha,
      control_comment_binding: control,
      server_observed_at: value.server_observed_at,
      repository: value.repository,
      lease,
    });
  }
}

export function validateV2GitLedgerRunnerReservation(value, expected = null) {
  assertObject(value, "runner reservation");
  exactKeys(value, [
    "schema", "schema_version", "repository", "pull_request",
    "epoch_head_sha", "ordinal", "generation_id", "generation_kind",
    "generation_index", "recovery_authority", "scheduler_intent_id",
    "intent_id", "intent_digest", "attempt_id", "body", "created_at",
    "automatic", "consumed", "pre_scope_digest", "status_ledger_binding",
    "reservation_digest",
  ], "runner reservation");
  if (
    value.schema !== V2_GIT_LEDGER_REQUEST_RESERVATION_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new TypeError("runner reservation has an unsupported schema");
  }
  assertObject(value.repository, "runner reservation.repository");
  exactKeys(value.repository, ["owner", "name", "node_id"],
    "runner reservation.repository");
  boundedString(value.repository.owner, "runner reservation repository.owner", 256);
  boundedString(value.repository.name, "runner reservation repository.name", 256);
  boundedString(value.repository.node_id,
    "runner reservation repository.node_id", 256);
  const pullRequest = normalizePullRequest(value.pull_request);
  const head = sha(value.epoch_head_sha, "runner reservation epoch_head_sha");
  const ordinal = positiveInteger(value.ordinal, "runner reservation ordinal");
  if (ordinal > 3 || value.generation_id !== `automatic:${ordinal}` ||
      value.generation_kind !== "automatic" ||
      value.generation_index !== ordinal) {
    throw new Error("runner reservation generation is not one automatic budget slot");
  }
  validateRunnerRecoveryAuthority(
    value.recovery_authority,
    ordinal,
    value.created_at,
  );
  boundedString(value.scheduler_intent_id,
    "runner reservation scheduler_intent_id", 512);
  if (!RUNNER_INTENT_ID.test(value.intent_id)) {
    throw new TypeError("runner reservation intent_id is invalid");
  }
  digest(value.intent_digest, "runner reservation intent_digest");
  if (!RUNNER_ATTEMPT_ID.test(value.attempt_id)) {
    throw new TypeError("runner reservation attempt_id is invalid");
  }
  if (value.body !== "@codex review" ||
      value.automatic !== true || value.consumed !== true) {
    throw new Error("runner reservation is not one consumed automatic request");
  }
  const createdAt = timestamp(value.created_at, "runner reservation created_at");
  digest(value.pre_scope_digest, "runner reservation pre_scope_digest");
  const binding = validateRunnerHeadLedgerBinding(
    value.status_ledger_binding,
    {
      repository_node_id: value.repository.node_id,
      pull_request_node_id: pullRequest.node_id,
      head_ref_oid: head,
      observed_not_after: createdAt,
    },
  );
  if (binding.automatic_request_count !== ordinal - 1) {
    throw new Error("runner reservation ordinal does not follow its head ledger");
  }
  const expectedIntentDigest = runnerDigestCanonical(
    "codex-review-gate-v2-request-intent",
    {
      repository_node_id: value.repository.node_id,
      pull_request_node_id: pullRequest.node_id,
      head_ref_oid: head,
      ordinal,
      generation_id: value.generation_id,
      scheduler_intent_id: value.scheduler_intent_id,
      body: value.body,
      created_at: createdAt,
      pre_scope_digest: value.pre_scope_digest,
      ledger_digest: binding.ledger_digest,
      recovery_authority: value.recovery_authority,
    },
  );
  if (
    value.intent_digest !== expectedIntentDigest ||
    value.intent_id !==
      `v2-request:${expectedIntentDigest.slice("sha256:".length)}`
  ) {
    throw new Error("runner reservation intent identity is invalid");
  }
  const expectedAttemptId = `v2-attempt:${runnerDigestCanonical(
    "codex-review-gate-v2-request-attempt-id",
    { intent_id: value.intent_id, intent_digest: value.intent_digest },
  ).slice("sha256:".length)}`;
  if (value.attempt_id !== expectedAttemptId) {
    throw new Error("runner reservation attempt identity is invalid");
  }
  digest(value.reservation_digest, "runner reservation reservation_digest");
  const { reservation_digest: _digest, ...withoutDigest } = value;
  if (
    value.reservation_digest !== runnerDigestCanonical(
      "codex-review-gate-v2-request-reservation",
      withoutDigest,
    )
  ) {
    throw new Error("runner reservation digest is invalid");
  }
  if (expected !== null) {
    if (expected.repository !== undefined && (
      value.repository.owner !== expected.repository.owner ||
      value.repository.name !== expected.repository.name ||
      value.repository.node_id !== expected.repository.node_id
    )) {
      throw new Error("runner reservation belongs to another repository");
    }
    if (expected.scope !== undefined && (
      canonicalJson(pullRequest) !==
        canonicalJson(expected.scope.pull_request) ||
      head !== expected.scope.head_ref_oid
    )) {
      throw new Error("runner reservation belongs to another review epoch");
    }
    if (expected.generation !== undefined &&
        value.generation_id !== expected.generation.generation_id) {
      throw new Error("runner reservation generation differs from its effect");
    }
  }
  return value;
}

export function validateV2GitLedgerRequestAttempt(value, expected = null) {
  assertObject(value, "runner request attempt");
  exactKeys(value, [
    "schema", "schema_version", "attempt_id", "reservation_digest",
    "scheduler_intent_id", "recorded_at", "recorded_before_effect",
    "retry_limit", "attempt_digest",
  ], "runner request attempt");
  if (
    value.schema !== V2_GIT_LEDGER_REQUEST_ATTEMPT_SCHEMA ||
    value.schema_version !== 1 ||
    !RUNNER_ATTEMPT_ID.test(value.attempt_id) ||
    value.recorded_before_effect !== true || value.retry_limit !== 0
  ) {
    throw new Error("runner request attempt is not closed retry-zero authority");
  }
  digest(value.reservation_digest, "runner request attempt reservation_digest");
  boundedString(value.scheduler_intent_id,
    "runner request attempt scheduler_intent_id", 512);
  timestamp(value.recorded_at, "runner request attempt recorded_at");
  digest(value.attempt_digest, "runner request attempt attempt_digest");
  const { attempt_digest: _digest, ...withoutDigest } = value;
  if (
    value.attempt_digest !== runnerDigestCanonical(
      "codex-review-gate-v2-request-attempt",
      withoutDigest,
    )
  ) {
    throw new Error("runner request attempt digest is invalid");
  }
  if (expected !== null) {
    const reservation = validateV2GitLedgerRunnerReservation(
      expected.reservation,
    );
    if (
      value.attempt_id !== reservation.attempt_id ||
      value.reservation_digest !== reservation.reservation_digest ||
      value.scheduler_intent_id !== reservation.scheduler_intent_id ||
      Date.parse(value.recorded_at) < Date.parse(reservation.created_at)
    ) {
      throw new Error("runner request attempt differs from its reservation");
    }
  }
  return value;
}

export function validateV2GitLedgerSchedulerObservation(
  value,
  expected = null,
) {
  assertObject(value, "scheduler observation");
  exactKeys(value, [
    "schema", "schema_version", "prior_authority_digest",
    "prior_scheduling", "prior_head_ledger", "scheduler_evaluation",
    "scheduler_plan", "scheduler_plan_digest", "status_plan",
    "status_plan_digest", "evaluated_scope_receipt_digest",
    "snapshot_server_time",
    "initial_runner_state_authority",
  ], "scheduler observation");
  if (
    value.schema !== V2_GIT_LEDGER_SCHEDULER_OBSERVATION_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error("scheduler observation has an unsupported schema");
  }
  digest(value.prior_authority_digest,
    "scheduler observation prior_authority_digest");
  digest(
    value.evaluated_scope_receipt_digest,
    "scheduler observation evaluated_scope_receipt_digest",
  );
  const boundary = timestamp(
    value.snapshot_server_time,
    "scheduler observation snapshot_server_time",
  );
  const scheduling = validateRunnerScheduling(
    value.prior_scheduling,
    boundary,
    expected,
  );
  validateRunnerHeadLedger(value.prior_head_ledger, {
    ...(expected ?? {}),
    observed_not_after: boundary,
  });
  if (value.initial_runner_state_authority !== null) {
    const initial = validateV2GitLedgerInitialRunnerStateAuthority(
      value.initial_runner_state_authority,
    );
    if (
      value.prior_authority_digest !== initial.prior_authority_digest ||
      canonicalJson(value.prior_scheduling) !==
        canonicalJson(initial.scheduling) ||
      canonicalJson(value.prior_head_ledger) !==
        canonicalJson(initial.head_ledger)
    ) {
      throw new Error(
        "scheduler observation differs from its initial runner authority",
      );
    }
  }
  const evaluation = validateRunnerSchedulerSnapshot(
    value.scheduler_evaluation,
    {
      epoch_id: scheduling.epoch.id,
      epoch_started_at: scheduling.epoch.started_at,
      observed_not_after: boundary,
      require_complete: true,
    },
    "scheduler observation evaluation",
  );
  if (
    evaluation.observed_at !== boundary ||
    canonicalJson(evaluation.no_start_candidate) !==
      canonicalJson(scheduling.no_start_candidate)
  ) {
    throw new Error(
      "scheduler observation evaluation differs from its exact snapshot input",
    );
  }
  const schedulerPlan = validateRunnerSchedulerPlan(value.scheduler_plan);
  const expectedPlan = planV2Actions({
    schema: V2_SCHEDULER_SCHEMA,
    schema_version: V2_SCHEDULER_SCHEMA_VERSION,
    trigger: scheduling.trigger,
    now: boundary,
    public_wait_supported: scheduling.public_wait_supported,
    status_target_mode: scheduling.status_target_mode,
    epoch: scheduling.epoch,
    evaluation,
    complete_snapshots: scheduling.complete_snapshots,
    status: {
      exact_sha_context_count: scheduling.status.exact_sha_context_count,
      latest_idempotency_key: scheduling.status.latest_idempotency_key,
    },
    applied_action_keys: scheduling.applied_action_keys,
    wait_completions: scheduling.wait_completions,
  });
  if (canonicalJson(schedulerPlan) !== canonicalJson(expectedPlan)) {
    throw new Error("scheduler observation plan is not the closed scheduler result");
  }
  digest(value.scheduler_plan_digest,
    "scheduler observation scheduler_plan_digest");
  if (
    value.scheduler_plan_digest !== digestCanonical(
      "codex-review-gate-v2-scheduler-plan",
      schedulerPlan,
    )
  ) {
    throw new Error("scheduler observation plan digest is invalid");
  }
  const statusPlan = validateRunnerStatusPlan(
    value.status_plan,
    evaluation,
    schedulerPlan,
  );
  if (statusPlan.mode !== scheduling.status_target_mode) {
    throw new Error(
      "scheduler observation status plan changes its persisted target mode",
    );
  }
  digest(value.status_plan_digest, "scheduler observation status_plan_digest");
  if (
    value.status_plan_digest !== digestCanonical(
      "codex-review-gate-v2-status-plan",
      statusPlan,
    )
  ) {
    throw new Error("scheduler observation status plan digest is invalid");
  }
  return value;
}

function validateRunnerRecoveryAuthority(value, ordinal, createdAtValue) {
  if (ordinal === 1) {
    if (value !== null) {
      throw new Error("first automatic reservation cannot carry recovery authority");
    }
    return null;
  }
  assertObject(value, "runner reservation recovery_authority");
  exactKeys(value, [
    "prior_generation_id", "finding_ids", "closure_ids",
    "closure_observed_at",
  ], "runner reservation recovery_authority");
  if (value.prior_generation_id !== `automatic:${ordinal - 1}`) {
    throw new Error("runner recovery authority skips a generation");
  }
  const findings = validateUniqueBoundedStrings(
    value.finding_ids,
    "runner recovery authority finding_ids",
    256,
  );
  const closures = validateUniqueBoundedStrings(
    value.closure_ids,
    "runner recovery authority closure_ids",
    256,
  );
  if (findings.length === 0 || findings.length !== closures.length) {
    throw new Error("runner recovery authority lacks exact finding closures");
  }
  if (
    Date.parse(timestamp(value.closure_observed_at,
      "runner recovery authority closure_observed_at")) >=
      Date.parse(timestamp(createdAtValue,
        "runner recovery authority reservation time"))
  ) {
    throw new Error("runner recovery closure does not precede its reservation");
  }
  return value;
}

function validateRunnerHeadLedgerBinding(value, expected) {
  assertObject(value, "runner head-ledger binding");
  exactKeys(value, [
    "head_ref_oid", "automatic_request_count", "exact_sha_context_count",
    "latest_status_idempotency_key", "bound_attempt_ids", "observed_at",
    "ledger_digest",
  ], "runner head-ledger binding");
  const headLedger = {
    schema: V2_GIT_LEDGER_HEAD_LEDGER_SCHEMA,
    schema_version: 1,
    repository_node_id: expected.repository_node_id,
    pull_request_node_id: expected.pull_request_node_id,
    head_ref_oid: value.head_ref_oid,
    automatic_request_count: value.automatic_request_count,
    exact_sha_context_count: value.exact_sha_context_count,
    latest_status_idempotency_key: value.latest_status_idempotency_key,
    bound_attempt_ids: value.bound_attempt_ids,
    observed_at: value.observed_at,
  };
  validateRunnerHeadLedger(headLedger, expected);
  digest(value.ledger_digest, "runner head-ledger binding ledger_digest");
  if (
    value.ledger_digest !== runnerDigestCanonical(
      "codex-review-gate-v2-head-ledger",
      headLedger,
    )
  ) {
    throw new Error("runner head-ledger binding digest is invalid");
  }
  return value;
}

function validateRunnerHeadLedger(value, expected = null) {
  assertObject(value, "runner head ledger");
  exactKeys(value, [
    "schema", "schema_version", "repository_node_id",
    "pull_request_node_id", "head_ref_oid", "automatic_request_count",
    "exact_sha_context_count", "latest_status_idempotency_key",
    "bound_attempt_ids", "observed_at",
  ], "runner head ledger");
  if (
    value.schema !== V2_GIT_LEDGER_HEAD_LEDGER_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error("runner head ledger has an unsupported schema");
  }
  boundedString(value.repository_node_id, "runner head ledger repository_node_id", 256);
  boundedString(value.pull_request_node_id,
    "runner head ledger pull_request_node_id", 256);
  sha(value.head_ref_oid, "runner head ledger head_ref_oid");
  integerBetween(value.automatic_request_count, 0, 3,
    "runner head ledger automatic_request_count");
  integerBetween(value.exact_sha_context_count, 0, 1000,
    "runner head ledger exact_sha_context_count");
  if (value.latest_status_idempotency_key !== null) {
    boundedString(value.latest_status_idempotency_key,
      "runner head ledger latest_status_idempotency_key", 1024);
  }
  validateRunnerAttemptIds(value.bound_attempt_ids,
    "runner head ledger bound_attempt_ids");
  const observedAt = timestamp(value.observed_at,
    "runner head ledger observed_at");
  if (expected !== null) {
    if (
      expected.repository_node_id !== undefined &&
      value.repository_node_id !== expected.repository_node_id ||
      expected.pull_request_node_id !== undefined &&
      value.pull_request_node_id !== expected.pull_request_node_id ||
      expected.head_ref_oid !== undefined &&
      value.head_ref_oid !== expected.head_ref_oid
    ) {
      throw new Error("runner head ledger belongs to another scope");
    }
    if (
      expected.observed_not_after !== undefined &&
      Date.parse(observedAt) > Date.parse(expected.observed_not_after)
    ) {
      throw new Error("runner head ledger is newer than its authority boundary");
    }
  }
  return value;
}

function validateRunnerScheduling(value, boundaryValue, expected = null) {
  assertObject(value, "runner scheduling");
  exactKeys(value, [
    "trigger", "public_wait_supported", "status_target_mode", "run_identity", "epoch",
    "complete_snapshots", "status", "applied_action_keys",
    "no_start_candidate", "wait_completions",
  ], "runner scheduling");
  if (!new Set(["initial", "timer", "schedule", "provider-event", "manual"])
    .has(value.trigger) || typeof value.public_wait_supported !== "boolean" ||
    !new Set(["head", "test-merge-with-head-sentinel"])
      .has(value.status_target_mode)) {
    throw new Error("runner scheduling trigger or wait policy is invalid");
  }
  const boundary = timestamp(boundaryValue, "runner scheduling boundary");
  const runIdentity = validateRunnerRunIdentity(
    value.run_identity,
    "runner scheduling run_identity",
  );
  assertObject(value.epoch, "runner scheduling epoch");
  exactKeys(value.epoch, [
    "id", "started_at", "controlled_request", "automatic_request",
  ], "runner scheduling epoch");
  if (!RUNNER_EPOCH_ID.test(value.epoch.id)) {
    throw new Error("runner scheduling epoch id is invalid");
  }
  const startedAt = timestamp(value.epoch.started_at,
    "runner scheduling epoch.started_at");
  if (Date.parse(startedAt) > Date.parse(boundary)) {
    throw new Error("runner scheduling epoch starts after its boundary");
  }
  if (expected?.repository_node_id !== undefined) {
    const derived = runnerEpochId(
      expected.repository_node_id,
      expected.pull_request_node_id,
      expected.head_ref_oid,
    );
    if (value.epoch.id !== derived) {
      throw new Error("runner scheduling epoch does not bind the exact scope");
    }
  }
  if (value.epoch.controlled_request !== null) {
    const requestObserved = validateRunnerControlledRequest(
      value.epoch.controlled_request,
      boundary,
    ).bound_at;
    if (
      Date.parse(requestObserved) < Date.parse(startedAt) ||
      Date.parse(requestObserved) > Date.parse(boundary)
    ) {
      throw new Error("runner scheduling request observation is out of bounds");
    }
  }
  validateRunnerAutomaticRequest(
    value.epoch.automatic_request,
    startedAt,
    boundary,
  );
  void runIdentity;
  if (!Array.isArray(value.complete_snapshots) ||
      value.complete_snapshots.length > MAX_V2_GIT_LEDGER_SEMANTIC_RECORDS) {
    throw new TypeError("runner scheduling complete snapshots are unbounded");
  }
  const snapshotIds = new Set();
  let priorObserved = null;
  for (const [index, snapshotValue] of value.complete_snapshots.entries()) {
    const snapshot = validateRunnerSchedulerSnapshot(snapshotValue, {
      epoch_id: value.epoch.id,
      epoch_started_at: startedAt,
      observed_not_after: boundary,
      require_complete: true,
    }, `runner scheduling complete_snapshots[${index}]`);
    if (snapshotIds.has(snapshot.snapshot_id) ||
        (priorObserved !== null &&
          Date.parse(snapshot.observed_at) < Date.parse(priorObserved))) {
      throw new Error("runner scheduling snapshot history is duplicate or reordered");
    }
    snapshotIds.add(snapshot.snapshot_id);
    priorObserved = snapshot.observed_at;
  }
  assertObject(value.status, "runner scheduling status");
  exactKeys(value.status, [
    "exact_sha_context_count", "latest_idempotency_key",
    "head_sentinel_receipt",
  ], "runner scheduling status");
  integerBetween(value.status.exact_sha_context_count, 0, 1000,
    "runner scheduling status exact_sha_context_count");
  if (value.status.latest_idempotency_key !== null) {
    boundedString(value.status.latest_idempotency_key,
      "runner scheduling status latest_idempotency_key", 1024);
  }
  if (value.status.head_sentinel_receipt !== null) {
    validateRunnerHeadSentinel(value.status.head_sentinel_receipt, boundary);
  }
  validateUniqueBoundedStrings(
    value.applied_action_keys,
    "runner scheduling applied_action_keys",
    MAX_V2_GIT_LEDGER_SEMANTIC_RECORDS,
  );
  if (value.no_start_candidate !== null) {
    validateRunnerNoStartCandidate(value.no_start_candidate, boundary,
      "runner scheduling no_start_candidate");
  }
  validateV2PublicWaitCompletions(value.wait_completions, {
    epoch_id: value.epoch.id,
    maximum_generation_index: value.epoch.automatic_request.generation_index,
    observed_not_after: boundary,
  });
  return value;
}

function validateRunnerAutomaticRequest(value, startedAt, boundary) {
  assertObject(value, "runner automatic request");
  exactKeys(value, [
    "state", "generation_index", "recovery_authority", "intent_id",
    "intent_persisted_at", "effect_attempted_at",
  ], "runner automatic request");
  if (!new Set(["available", "intent-persisted", "effect-attempted"])
    .has(value.state)) {
    throw new Error("runner automatic request state is invalid");
  }
  const generationIndex = integerBetween(
    value.generation_index,
    1,
    3,
    "runner automatic request generation_index",
  );
  validateRunnerRecoveryAuthority(
    value.recovery_authority,
    generationIndex,
    boundary,
  );
  if (value.state === "available") {
    if (
      value.intent_id !== null || value.intent_persisted_at !== null ||
      value.effect_attempted_at !== null
    ) {
      throw new Error("available runner request already carries consumption authority");
    }
    return;
  }
  boundedString(value.intent_id, "runner automatic request intent_id", 512);
  const persisted = timestamp(value.intent_persisted_at,
    "runner automatic request intent_persisted_at");
  if (Date.parse(persisted) < Date.parse(startedAt) ||
      Date.parse(persisted) > Date.parse(boundary)) {
    throw new Error("runner automatic request persistence time is out of bounds");
  }
  if (value.state === "intent-persisted") {
    if (value.effect_attempted_at !== null) {
      throw new Error("intent-persisted runner request already has an attempt");
    }
    return;
  }
  const attempted = timestamp(value.effect_attempted_at,
    "runner automatic request effect_attempted_at");
  if (Date.parse(attempted) < Date.parse(persisted) ||
      Date.parse(attempted) > Date.parse(boundary)) {
    throw new Error("runner automatic request attempt time is out of bounds");
  }
}

function validateRunnerRunIdentity(value, label) {
  assertObject(value, label);
  exactKeys(value, ["run_id", "run_attempt"], label);
  return {
    run_id: decimal(value.run_id, `${label}.run_id`),
    run_attempt: positiveInteger(value.run_attempt, `${label}.run_attempt`),
  };
}

function validateRunnerControlledRequest(value, boundaryValue) {
  assertObject(value, "runner controlled request");
  exactKeys(value, [
    "request_id", "bound_at", "binding_record_oid",
    "binding_receipt_digest",
  ], "runner controlled request");
  decimal(value.request_id, "runner controlled request request_id");
  const boundAt = timestamp(value.bound_at, "runner controlled request bound_at");
  if (Date.parse(boundAt) > Date.parse(boundaryValue)) {
    throw new Error("runner controlled request follows its scheduler boundary");
  }
  sha(value.binding_record_oid,
    "runner controlled request binding_record_oid");
  digest(value.binding_receipt_digest,
    "runner controlled request binding_receipt_digest");
  return value;
}

function validateRunnerSchedulerSnapshot(value, expected, label) {
  assertObject(value, label);
  exactKeys(value, [
    "epoch_id", "decision", "complete", "snapshot_id",
    "snapshot_fingerprint", "observed_at", "provider_activity_fingerprint",
    "no_start_candidate", "run_id", "run_attempt",
  ], label);
  if (value.epoch_id !== expected.epoch_id ||
      !new Set([
        "not-selected", "pending", "clean", "findings", "inconclusive",
        "skipped-unavailable", "blocked-configuration", "blocked-input",
      ]).has(value.decision) || typeof value.complete !== "boolean" ||
      (expected.require_complete === true && value.complete !== true)) {
    throw new Error(`${label} is not one closed evaluation`);
  }
  boundedString(value.snapshot_id, `${label}.snapshot_id`, 512);
  boundedString(value.snapshot_fingerprint,
    `${label}.snapshot_fingerprint`, 512);
  boundedString(value.provider_activity_fingerprint,
    `${label}.provider_activity_fingerprint`, 512);
  decimal(value.run_id, `${label}.run_id`);
  positiveInteger(value.run_attempt, `${label}.run_attempt`);
  const observed = timestamp(value.observed_at, `${label}.observed_at`);
  if (
    Date.parse(observed) < Date.parse(expected.epoch_started_at) ||
    Date.parse(observed) > Date.parse(expected.observed_not_after)
  ) {
    throw new Error(`${label} time is outside its review epoch`);
  }
  if (value.no_start_candidate !== null) {
    validateRunnerNoStartCandidate(
      value.no_start_candidate,
      observed,
      `${label}.no_start_candidate`,
    );
  }
  if (value.decision === "skipped-unavailable" &&
      value.no_start_candidate === null) {
    throw new Error(`${label} skipped-unavailable lacks a no-start candidate`);
  }
  return value;
}

function validateRunnerNoStartCandidate(value, boundary, label) {
  assertObject(value, label);
  exactKeys(value, [
    "artifact_id", "artifact_digest", "scope_fingerprint",
    "lifecycle_fingerprint", "first_seen_at",
  ], label);
  boundedString(value.artifact_id, `${label}.artifact_id`, 512);
  digest(value.artifact_digest, `${label}.artifact_digest`);
  boundedString(value.scope_fingerprint, `${label}.scope_fingerprint`, 512);
  boundedString(value.lifecycle_fingerprint,
    `${label}.lifecycle_fingerprint`, 512);
  if (Date.parse(timestamp(value.first_seen_at, `${label}.first_seen_at`)) >
      Date.parse(boundary)) {
    throw new Error(`${label}.first_seen_at follows its observation`);
  }
}

function validateRunnerHeadSentinel(value, boundary) {
  assertObject(value, "runner head sentinel");
  exactKeys(value, ["sha", "context", "state", "status_id", "observed_at"],
    "runner head sentinel");
  sha(value.sha, "runner head sentinel sha");
  if (value.context !== "codex/github-review-gate" ||
      !new Set(["pending", "failure", "error"]).has(value.state)) {
    throw new Error("runner head sentinel is outside the closed status profile");
  }
  decimal(value.status_id, "runner head sentinel status_id");
  if (Date.parse(timestamp(value.observed_at,
    "runner head sentinel observed_at")) > Date.parse(boundary)) {
    throw new Error("runner head sentinel follows its authority boundary");
  }
}

function validateRunnerSchedulerPlan(value) {
  assertObject(value, "runner scheduler plan");
  exactKeys(value, [
    "schema", "schema_version", "actions", "due_at", "required_wait",
    "automatic_retry_stopped", "event_wakeup_hints_are_advisory",
    "freshness_assurance",
  ], "runner scheduler plan");
  if (
    value.schema !== V2_SCHEDULER_SCHEMA ||
    value.schema_version !== V2_SCHEDULER_SCHEMA_VERSION ||
    !Array.isArray(value.actions) ||
    typeof value.automatic_retry_stopped !== "boolean" ||
    value.event_wakeup_hints_are_advisory !== true ||
    value.freshness_assurance !== "point-in-time"
  ) {
    throw new Error("runner scheduler plan is not closed v2 output");
  }
  if (value.due_at !== null) timestamp(value.due_at, "runner scheduler plan due_at");
  if (value.required_wait !== null) {
    assertObject(value.required_wait, "runner scheduler plan required_wait");
    exactKeys(value.required_wait, ["stage", "deadline"],
      "runner scheduler plan required_wait");
    if (
      !new Set([
        "public-initial",
        "public-post-request",
        "public-no-start",
      ]).has(value.required_wait.stage) ||
      timestamp(
        value.required_wait.deadline,
        "runner scheduler plan required_wait deadline",
      ) !== value.due_at
    ) {
      throw new Error("runner scheduler plan required_wait differs from due_at");
    }
  }
  const keys = new Set();
  for (const [index, action] of value.actions.entries()) {
    validateRunnerSchedulerAction(action, `runner scheduler plan action[${index}]`);
    if (keys.has(action.idempotency_key)) {
      throw new Error("runner scheduler plan repeats an action key");
    }
    keys.add(action.idempotency_key);
  }
  return value;
}

function validateRunnerSchedulerAction(value, label) {
  assertObject(value, label);
  if (value.kind === "evaluate_snapshot") {
    exactKeys(value, ["kind", "idempotency_key", "mode", "reason"], label);
    if (!new Set(["ordinary", "evaluate-only"]).has(value.mode)) {
      throw new Error(`${label} mode is invalid`);
    }
    boundedString(value.reason, `${label}.reason`, 256);
  } else if (value.kind === "persist_auto_request_intent") {
    exactKeys(value, [
      "kind", "idempotency_key", "intent_id", "generation_id",
      "generation_index", "recovery_authority",
      "consumes_automatic_reservation",
    ], label);
    boundedString(value.intent_id, `${label}.intent_id`, 512);
    const generationIndex = integerBetween(
      value.generation_index,
      1,
      3,
      `${label}.generation_index`,
    );
    if (
      value.generation_id !== `automatic:${generationIndex}` ||
      !value.intent_id.includes(value.generation_id) ||
      !value.idempotency_key.includes(value.generation_id) ||
      value.consumes_automatic_reservation !== true
    ) {
      throw new Error(`${label} does not consume its reservation`);
    }
    validateRunnerRecoveryAuthority(
      value.recovery_authority,
      generationIndex,
      "9999-12-31T23:59:59.999Z",
    );
  } else if (value.kind === "post_review_request") {
    exactKeys(value, [
      "kind", "idempotency_key", "intent_id", "generation_id",
      "generation_index", "recovery_authority",
      "depends_on_idempotency_key", "retry_limit",
      "record_attempt_before_effect",
    ], label);
    boundedString(value.intent_id, `${label}.intent_id`, 512);
    boundedString(value.depends_on_idempotency_key,
      `${label}.depends_on_idempotency_key`, 1024);
    const generationIndex = integerBetween(
      value.generation_index,
      1,
      3,
      `${label}.generation_index`,
    );
    if (
      value.generation_id !== `automatic:${generationIndex}` ||
      !value.intent_id.includes(value.generation_id) ||
      !value.idempotency_key.includes(value.generation_id) ||
      !value.depends_on_idempotency_key.includes(value.generation_id) ||
      value.retry_limit !== 0 || value.record_attempt_before_effect !== true
    ) {
      throw new Error(`${label} is not retry-zero with a durable pre-attempt`);
    }
    validateRunnerRecoveryAuthority(
      value.recovery_authority,
      generationIndex,
      "9999-12-31T23:59:59.999Z",
    );
  } else if (value.kind === "publish_status") {
    exactKeys(value, [
      "kind", "idempotency_key", "decision", "snapshot_id",
      "required_write_slots", "reason",
    ], label);
    boundedString(value.snapshot_id, `${label}.snapshot_id`, 512);
    if (!new Set([
      "pending", "clean", "findings", "inconclusive",
      "skipped-unavailable", "blocked-configuration", "blocked-input",
    ]).has(value.decision)) {
      throw new Error(`${label} decision is invalid`);
    }
    integerBetween(value.required_write_slots, 1, 2,
      `${label}.required_write_slots`);
    if (!new Set(["evaluation-decision", "inconclusive-timeout"])
      .has(value.reason)) {
      throw new Error(`${label} reason is outside the closed status authority`);
    }
    if (
      value.reason === "inconclusive-timeout" &&
      value.decision !== "inconclusive"
    ) {
      throw new Error(`${label} timeout reason requires inconclusive authority`);
    }
  } else if (value.kind === "record_head_ledger") {
    exactKeys(value, [
      "kind", "idempotency_key", "decision", "reason",
      "exact_sha_context_count", "required_write_slots",
    ], label);
    if (value.decision !== "blocked-input" ||
        value.reason !== "status-cap-exhausted") {
      throw new Error(`${label} is not the closed status-cap record`);
    }
    integerBetween(value.exact_sha_context_count, 0, 1000,
      `${label}.exact_sha_context_count`);
    integerBetween(value.required_write_slots, 1, 2,
      `${label}.required_write_slots`);
  } else {
    throw new Error(`${label} kind is outside the closed scheduler action set`);
  }
  boundedString(value.idempotency_key, `${label}.idempotency_key`, 1024);
}

function validateRunnerStatusPlan(value, evaluation, schedulerPlan) {
  assertObject(value, "runner status plan");
  const suppressed = Object.hasOwn(value, "suppressed_writes");
  exactKeys(value, suppressed
    ? [
        "mode", "decision", "writes", "terminal_cutover",
        "freshness_assurance", "suppressed_writes", "suppression_reason",
      ]
    : [
        "mode", "decision", "writes", "terminal_cutover",
        "freshness_assurance",
      ], "runner status plan");
  if (
    !new Set(["head", "test-merge-with-head-sentinel"]).has(value.mode) ||
    value.decision !== evaluation.decision ||
    !Array.isArray(value.writes) ||
    typeof value.terminal_cutover !== "boolean" ||
    value.freshness_assurance !== "point-in-time"
  ) {
    throw new Error("runner status plan is not exact closed output");
  }
  for (const [index, write] of value.writes.entries()) {
    validateRunnerStatusWrite(write, `runner status plan writes[${index}]`);
  }
  if (value.mode === "head" && (
    value.terminal_cutover !== false ||
    value.writes.some((write) =>
      write.role !== "head-sentinel" || write.state === "success")
  )) {
    throw new Error("head-mode status plan is limited to non-success sentinels");
  }
  const publish = schedulerPlan.actions.find((action) =>
    action.kind === "publish_status");
  if (suppressed) {
    if (value.writes.length !== 0 || value.terminal_cutover !== false ||
        !Array.isArray(value.suppressed_writes)) {
      throw new Error("runner suppressed status plan has public write authority");
    }
    for (const [index, write] of value.suppressed_writes.entries()) {
      validateRunnerStatusWrite(write,
        `runner status plan suppressed_writes[${index}]`);
    }
    boundedString(value.suppression_reason,
      "runner status plan suppression_reason", 256);
    if (
      value.mode === "head" &&
      new Set(["clean", "skipped-unavailable"]).has(value.decision) &&
      value.suppression_reason !== "suppressed-unsupported-terminal-target"
    ) {
      throw new Error("runner head-mode suppression reason is not authoritative");
    }
    if (publish !== undefined &&
        (value.mode !== "head" ||
          !new Set(["clean", "skipped-unavailable"]).has(value.decision) ||
          value.suppression_reason !== "suppressed-unsupported-terminal-target")) {
      throw new Error("runner status suppression conflicts with scheduler authority");
    }
  } else if (value.writes.length > 0 && (
    publish === undefined || publish.decision !== value.decision ||
    publish.snapshot_id !== evaluation.snapshot_id ||
    publish.required_write_slots < value.writes.length
  )) {
    throw new Error("runner status plan lacks its scheduler publication authority");
  }
  return value;
}

function validateRunnerStatusWrite(value, label) {
  assertObject(value, label);
  exactKeys(value, [
    "role", "sha", "context", "state", "reason", "idempotency_key",
  ], label);
  if (!new Set(["head-sentinel", "primary-terminal"]).has(value.role) ||
      value.context !== "codex/github-review-gate" ||
      !new Set(["pending", "success", "failure", "error"]).has(value.state) ||
      (value.role === "head-sentinel" && value.state === "success")) {
    throw new Error(`${label} is outside the closed status profile`);
  }
  sha(value.sha, `${label}.sha`);
  boundedString(value.reason, `${label}.reason`, 256);
  boundedString(value.idempotency_key, `${label}.idempotency_key`, 1024);
}

function validateRunnerAttemptIds(value, label) {
  if (!Array.isArray(value) || value.length > 1000) {
    throw new TypeError(`${label} is not a bounded array`);
  }
  const seen = new Set();
  for (const attemptId of value) {
    if (!RUNNER_ATTEMPT_ID.test(attemptId) || seen.has(attemptId)) {
      throw new Error(`${label} contains an invalid or duplicate attempt`);
    }
    seen.add(attemptId);
  }
}

function runnerEpochId(repositoryNodeId, pullRequestNodeId, headRefOid) {
  return `v2-head:${runnerDigestCanonical("codex-review-gate-v2-head-epoch", {
    repository_node_id: repositoryNodeId,
    pull_request_node_id: pullRequestNodeId,
    head_ref_oid: headRefOid,
  }).slice("sha256:".length)}`;
}

export function validateV2GitLedgerEffectPayload(payload, expected) {
  assertObject(payload, "effect payload");
  exactKeys(payload, [
    "schema", "schema_version", "phase", "kind", "scope", "generation",
    "ordinal", "predecessor_commit_sha", "action", "intent_commit_sha",
    "receipt",
  ], "effect payload");
  if (
    payload.schema !== V2_GIT_LEDGER_EFFECT_PAYLOAD_SCHEMA ||
    payload.schema_version !== 1
  ) {
    throw new Error("effect payload has an unsupported schema");
  }
  const phase = payload.phase;
  if (!new Set(["intent", "response"]).has(phase) ||
      phase !== expected.record_type.slice("effect-".length)) {
    throw new Error("effect payload phase differs from its record type");
  }
  if (payload.kind !== expected.kind) {
    throw new Error("effect payload kind differs from its envelope");
  }
  const scope = normalizeEffectScope(payload.scope);
  if (canonicalJson(scope) !== canonicalJson(expected.scope)) {
    throw new Error("effect payload scope differs from its envelope");
  }
  const generation = normalizeEffectGeneration(payload.generation, scope);
  const ordinal = positiveInteger(payload.ordinal, "effect payload ordinal");
  const predecessor = sha(
    payload.predecessor_commit_sha,
    "effect payload predecessor_commit_sha",
  );
  if (predecessor !== expected.predecessor_commit_sha) {
    throw new Error("effect payload predecessor differs from its envelope");
  }
  validateEffectGenerationUse(payload.kind, generation, ordinal);
  validateEffectAction(
    payload.kind,
    payload.action,
    generation,
    scope,
    expected.server_observed_at,
  );
  if (phase === "intent") {
    if (payload.intent_commit_sha !== null || payload.receipt !== null) {
      throw new Error("effect intent cannot contain response authority");
    }
  } else {
    sha(payload.intent_commit_sha, "effect response intent_commit_sha");
    validateEffectReceipt(
      payload.kind,
      payload.receipt,
      payload.action,
      generation,
      expected.control_comment_binding,
      scope,
      expected.repository,
      expected.lease,
      expected.server_observed_at,
    );
    validateEffectReceiptTemporalBoundary(
      payload.kind,
      payload.receipt,
      expected.server_observed_at,
    );
  }
  return payload;
}

function normalizeEffectGeneration(value, scope) {
  if (value === null) return null;
  assertObject(value, "effect payload generation");
  exactKeys(value, [
    "generation_id", "kind", "index", "review_epoch_digest",
  ], "effect payload generation");
  const match = GENERATION_ID.exec(value.generation_id);
  if (match === null) throw new TypeError("effect generation_id is invalid");
  if (!new Set(["automatic", "manual"]).has(value.kind)) {
    throw new TypeError("effect generation kind is invalid");
  }
  const index = positiveInteger(value.index, "effect generation index");
  if (match[1] !== value.kind || Number(match[2]) !== index) {
    throw new Error("effect generation identity, kind, and index differ");
  }
  if (value.kind === "automatic" && index > 3) {
    throw new Error("automatic generation exceeds the closed budget cap");
  }
  digest(value.review_epoch_digest, "effect generation review_epoch_digest");
  if (value.review_epoch_digest !== reviewEpochDigest(scope)) {
    throw new Error("effect generation does not bind the exact review epoch");
  }
  return value;
}

function validateEffectGenerationUse(kind, generation, ordinal) {
  const required = new Set([
    "automatic-request-reservation", "reservation-status-write",
    "review-request", "request-binding",
    "artifact-binding", "artifact-binding-ready", "no-start-observation",
    "effect-attempt", "scheduler-state",
  ]);
  if ((required.has(kind) && generation === null) ||
      (!required.has(kind) && generation !== null)) {
    throw new Error("effect generation presence does not match its kind");
  }
  if (generation !== null && generation.index !== ordinal) {
    throw new Error("effect ordinal differs from its generation index");
  }
  if (generation === null && ordinal !== 1) {
    throw new Error("non-generation effect ordinal must be one");
  }
  if (kind === "automatic-request-reservation" &&
      generation.kind !== "automatic") {
    throw new Error("automatic reservation requires an automatic generation");
  }
  if (new Set([
    "review-request", "artifact-binding", "artifact-binding-ready",
  ]).has(kind) &&
      generation.kind !== "automatic") {
    throw new Error(`${kind} requires an automatic generation`);
  }
}

function validateEffectAction(kind, action, generation, scope, boundaryValue) {
  assertObject(action, `${kind} action`);
  if (kind === "control-comment-create") {
    exactKeys(action, [
      "method", "body_digest", "pre_comment_inventory_digest",
    ], `${kind} action`);
    if (action.method !== "POST") throw new Error("control comment create must POST");
    digest(action.body_digest, `${kind} body_digest`);
    digest(action.pre_comment_inventory_digest,
      `${kind} pre_comment_inventory_digest`);
  } else if (kind === "control-comment-update") {
    exactKeys(action, [
      "method", "comment_id", "prior_raw_body_sha256", "body_digest",
      "pre_comment_inventory_digest",
    ], `${kind} action`);
    if (action.method !== "PATCH") throw new Error("control comment update must PATCH");
    decimal(action.comment_id, `${kind} comment_id`);
    digest(action.prior_raw_body_sha256, `${kind} prior_raw_body_sha256`);
    digest(action.body_digest, `${kind} body_digest`);
    digest(action.pre_comment_inventory_digest,
      `${kind} pre_comment_inventory_digest`);
  } else if (kind === "automatic-request-reservation") {
    exactKeys(action, [
      "scheduler_observation_record_oid", "scheduler_action_key",
      "post_scheduler_action_key", "reservation", "reservation_digest",
      "budget_limit",
    ], `${kind} action`);
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    boundedString(action.scheduler_action_key,
      `${kind} scheduler_action_key`, 1024);
    boundedString(action.post_scheduler_action_key,
      `${kind} post_scheduler_action_key`, 1024);
    const reservation = validateV2GitLedgerRunnerReservation(
      action.reservation,
      { scope, generation },
    );
    digest(action.reservation_digest, `${kind} reservation_digest`);
    if (
      action.reservation_digest !== reservation.reservation_digest ||
      Date.parse(reservation.created_at) > Date.parse(boundaryValue) ||
      action.budget_limit !== 3
    ) {
      throw new Error("automatic reservation budget limit must be three");
    }
  } else if (kind === "scheduler-observation") {
    const observation = validateV2GitLedgerSchedulerObservation(action);
    if (Date.parse(observation.snapshot_server_time) > Date.parse(boundaryValue)) {
      throw new Error("scheduler observation follows its GitHub record boundary");
    }
  } else if (kind === "effect-attempt") {
    exactKeys(action, [
      "scheduler_observation_record_oid", "reservation_record_oid",
      "scheduler_action_key", "attempt",
    ], `${kind} action`);
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    sha(action.reservation_record_oid, `${kind} reservation_record_oid`);
    boundedString(action.scheduler_action_key,
      `${kind} scheduler_action_key`, 1024);
    const attempt = validateV2GitLedgerRequestAttempt(action.attempt);
    if (Date.parse(attempt.recorded_at) > Date.parse(boundaryValue)) {
      throw new Error("effect attempt follows its GitHub record boundary");
    }
  } else if (kind === "reservation-status-write") {
    exactKeys(action, [
      "reservation_record_oid", "generation_id", "ordinal", "target_sha",
      "context", "state", "description_digest",
    ], `${kind} action`);
    sha(action.reservation_record_oid, `${kind} reservation_record_oid`);
    if (
      action.generation_id !== generation.generation_id ||
      action.ordinal !== generation.index ||
      sha(action.target_sha, `${kind} target_sha`) !== scope.head_ref_oid ||
      action.context !==
        `codex/github-review-gate-reservation/${generation.index}` ||
      action.context === "codex/github-review-gate" ||
      action.state !== "pending"
    ) {
      throw new Error("reservation status intent is outside its non-required profile");
    }
    digest(action.description_digest, `${kind} description_digest`);
  } else if (kind === "review-request") {
    exactKeys(action, [
      "method", "request_body_sha256", "scheduler_observation_record_oid",
      "reservation_record_oid", "attempt_record_oid", "scheduler_action_key",
    ], `${kind} action`);
    if (action.method !== "POST") throw new Error("review request must POST");
    digest(action.request_body_sha256, `${kind} request_body_sha256`);
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    sha(action.reservation_record_oid, `${kind} reservation_record_oid`);
    sha(action.attempt_record_oid, `${kind} attempt_record_oid`);
    boundedString(action.scheduler_action_key,
      `${kind} scheduler_action_key`, 1024);
  } else if (kind === "request-binding") {
    exactKeys(action, [
      "generation_id", "request_id", "reservation_record_oid",
      "attempt_record_oid",
    ], `${kind} action`);
    if (action.generation_id !== generation.generation_id) {
      throw new Error("request binding action generation differs from its authority");
    }
    decimal(action.request_id, `${kind} request_id`);
    sha(action.reservation_record_oid, `${kind} reservation_record_oid`);
    sha(action.attempt_record_oid, `${kind} attempt_record_oid`);
  } else if (kind === "artifact-binding") {
    exactKeys(action, [
      "method", "expected_status", "retry_policy",
      "generation_id", "request_binding_record_oid", "request_id",
      "request_node_id",
      "queued_after_artifact_binding_intent_record_oid",
      "scheduler_observation_record_oid",
      "full_scope_receipt_digest", "candidate_set_digest",
      "candidate_authority",
    ], `${kind} action`);
    if (
      action.method !== "GET" || action.expected_status !== 200 ||
      action.retry_policy !== "safe-idempotent" ||
      action.generation_id !== generation.generation_id
    ) {
      throw new Error("artifact binding action generation differs from its authority");
    }
    sha(action.request_binding_record_oid,
      `${kind} request_binding_record_oid`);
    decimal(action.request_id, `${kind} request_id`);
    boundedString(action.request_node_id, `${kind} request_node_id`, 256);
    if (action.queued_after_artifact_binding_intent_record_oid !== null) {
      sha(
        action.queued_after_artifact_binding_intent_record_oid,
        `${kind} queued_after_artifact_binding_intent_record_oid`,
      );
    }
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    digest(action.full_scope_receipt_digest,
      `${kind} full_scope_receipt_digest`);
    digest(action.candidate_set_digest, `${kind} candidate_set_digest`);
    const candidateAuthority =
      validateAutomaticRecoveryArtifactBindingCandidateAuthority(
        action.candidate_authority,
      );
    if (
      candidateAuthority.generation_id !== action.generation_id ||
      candidateAuthority.request_binding_record_oid !==
        action.request_binding_record_oid ||
      candidateAuthority.request_id !== action.request_id ||
      candidateAuthority.request_node_id !== action.request_node_id ||
      action.candidate_set_digest !==
        automaticRecoveryArtifactBindingCandidateSetDigest(candidateAuthority)
    ) {
      throw new Error("artifact binding action differs from its candidate authority");
    }
    validateCodexProvider(
      candidateAuthority.expected_actor,
      candidateAuthority.expected_app,
      `${kind} expected provider`,
    );
    if (Buffer.byteLength(canonicalJson(action), "utf8") >
        MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_ACTION_BYTES) {
      throw ledgerError(
        "automatic-artifact-binding-action-size",
        "aggregate artifact binding action exceeds its hard byte cap",
      );
    }
  } else if (kind === "artifact-binding-ready") {
    exactKeys(action, [
      "artifact_binding_intent_record_oid",
      "artifact_binding_intent_payload_digest",
      "scheduler_observation_record_oid", "full_scope_receipt_digest",
      "generation_id", "candidate_set_digest", "candidate_authority_digest",
      "queued_after_artifact_binding_intent_record_oid",
      "intent_reachability_boundary",
    ], `${kind} action`);
    sha(action.artifact_binding_intent_record_oid,
      `${kind} artifact_binding_intent_record_oid`);
    digest(action.artifact_binding_intent_payload_digest,
      `${kind} artifact_binding_intent_payload_digest`);
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    digest(action.full_scope_receipt_digest,
      `${kind} full_scope_receipt_digest`);
    if (
      action.generation_id !== generation.generation_id ||
      !GENERATION_ID.test(action.generation_id)
    ) {
      throw new Error("artifact binding ready generation is invalid");
    }
    digest(action.candidate_set_digest,
      `${kind} candidate_set_digest`);
    digest(action.candidate_authority_digest,
      `${kind} candidate_authority_digest`);
    if (action.queued_after_artifact_binding_intent_record_oid !== null) {
      sha(
        action.queued_after_artifact_binding_intent_record_oid,
        `${kind} queued_after_artifact_binding_intent_record_oid`,
      );
    }
    const reachabilityBoundary =
      validateAutomaticRecoveryArtifactReachabilityBoundary(
        action.intent_reachability_boundary,
      );
    if (
      reachabilityBoundary.intent_record_oid !==
        action.artifact_binding_intent_record_oid ||
      reachabilityBoundary.scheduler_observation_record_oid !==
        action.scheduler_observation_record_oid ||
      Date.parse(reachabilityBoundary.ref_receipt.server_time) >
        Date.parse(timestamp(boundaryValue, `${kind} record boundary`))
    ) {
      throw new Error(
        "artifact binding ready action differs from its reachability boundary",
      );
    }
  } else if (kind === "no-start-observation") {
    exactKeys(action, [
      "generation_id", "request_id", "request_run_id", "request_created_at",
      "carrier_selector",
    ], `${kind} action`);
    if (action.generation_id !== generation.generation_id) {
      throw new Error("no-start action generation differs from its authority");
    }
    decimal(action.request_id, `${kind} request_id`);
    decimal(action.request_run_id, `${kind} request_run_id`);
    timestamp(action.request_created_at, `${kind} request_created_at`);
    normalizeCarrierSelector(action.carrier_selector, `${kind} carrier_selector`);
  } else if (kind === "thread-resolution-observation") {
    exactKeys(action, ["thread_id", "head_oid"], `${kind} action`);
    boundedString(action.thread_id, `${kind} thread_id`, 256);
    if (sha(action.head_oid, `${kind} head_oid`) !== scope.head_ref_oid) {
      throw new Error("thread resolution action binds another head");
    }
  } else if (kind === "status-write") {
    exactKeys(action, [
      "mode", "target_sha", "role", "context", "state",
      "description_digest",
      "scheduler_observation_record_oid", "scheduler_action_key",
      "scheduler_plan_digest", "status_plan_digest", "status_write_index",
      "status_write_count",
    ], `${kind} action`);
    const targetSha = sha(action.target_sha, `${kind} target_sha`);
    if (!new Set(["head", "test-merge-with-head-sentinel"])
      .has(action.mode)) {
      throw new Error("status-write mode is outside the closed target profile");
    }
    if (!new Set(["head-sentinel", "primary-terminal"]).has(action.role)) {
      throw new Error("status-write role is outside the closed target profile");
    }
    if (
      (action.mode === "head" &&
        (action.role !== "head-sentinel" || targetSha !== scope.head_ref_oid ||
          action.state === "success")) ||
      (action.mode === "test-merge-with-head-sentinel" &&
        action.role === "head-sentinel" &&
        (targetSha !== scope.head_ref_oid || action.state === "success")) ||
      (action.mode === "test-merge-with-head-sentinel" &&
        action.role === "primary-terminal" &&
        (scope.potential_merge_commit_oid === null ||
          targetSha !== scope.potential_merge_commit_oid))
    ) {
      throw new Error("status-write target does not match its closed role");
    }
    if (action.context !== "codex/github-review-gate" ||
        !new Set(["pending", "success", "failure", "error"])
          .has(action.state)) {
      throw new Error("status-write action is outside the closed status profile");
    }
    digest(action.description_digest, `${kind} description_digest`);
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    boundedString(action.scheduler_action_key,
      `${kind} scheduler_action_key`, 1024);
    digest(action.scheduler_plan_digest, `${kind} scheduler_plan_digest`);
    digest(action.status_plan_digest, `${kind} status_plan_digest`);
    const writeCount = integerBetween(action.status_write_count, 1, 2,
      `${kind} status_write_count`);
    const writeIndex = nonnegativeInteger(action.status_write_index,
      `${kind} status_write_index`);
    if (writeIndex >= writeCount) {
      throw new Error("status-write index is outside its authorized plan");
    }
  } else if (kind === "sticky-comment") {
    exactKeys(action, [
      "method", "comment_id", "body_digest", "pre_comment_inventory_digest",
    ], `${kind} action`);
    if (!new Set(["POST", "PATCH"]).has(action.method) ||
        (action.method === "POST" && action.comment_id !== null) ||
        (action.method === "PATCH" && action.comment_id === null)) {
      throw new Error("sticky-comment method/comment identity is invalid");
    }
    if (action.comment_id !== null) decimal(action.comment_id, `${kind} comment_id`);
    digest(action.body_digest, `${kind} body_digest`);
    digest(action.pre_comment_inventory_digest,
      `${kind} pre_comment_inventory_digest`);
  } else if (kind === "scheduler-state") {
    exactKeys(action, [
      "scheduler_observation_record_oid", "full_scope_receipt_digest",
      "prior_request_binding_record_oid", "recovery_transition_digest",
      "recovery_authority",
    ], `${kind} action`);
    sha(action.scheduler_observation_record_oid,
      `${kind} scheduler_observation_record_oid`);
    digest(action.full_scope_receipt_digest,
      `${kind} full_scope_receipt_digest`);
    sha(action.prior_request_binding_record_oid,
      `${kind} prior_request_binding_record_oid`);
    digest(action.recovery_transition_digest,
      `${kind} recovery_transition_digest`);
    const recovery = validateAutomaticRequestRecoveryAuthority(
      action.recovery_authority,
      { boundary: boundaryValue },
    );
    if (
      generation.kind !== "automatic" ||
      generation.generation_id !== recovery.prior_generation_id ||
      generation.index !== recovery.prior_generation_index ||
      action.prior_request_binding_record_oid !==
        recovery.prior_request_binding_record_oid ||
      action.recovery_transition_digest !==
        automaticRequestRecoveryTransitionDigest(recovery)
    ) {
      throw new Error("scheduler-state generation transition is invalid");
    }
  }
}

function validateEffectReceipt(
  kind,
  receipt,
  action,
  generation,
  control,
  scope,
  repository,
  lease,
  recordBoundary,
) {
  assertObject(receipt, `${kind} receipt`);
  if (new Set(["control-comment-create", "control-comment-update"])
    .has(kind)) {
    exactKeys(receipt, [
      "http_status", "server_time", "raw_body_sha256", "comment", "actor",
      "app", "pre_comment_inventory_digest", "post_comment_inventory_digest",
    ], `${kind} receipt`);
    const expectedStatus = kind === "control-comment-create" ? 201 : 200;
    if (receipt.http_status !== expectedStatus ||
        canonicalJson(normalizeControlCommentBinding(receipt.comment, {
          required: true,
        })) !== canonicalJson(control) ||
        (kind === "control-comment-update" &&
          receipt.comment.comment_id !== action.comment_id)) {
      throw new Error("control comment response receipt is not exact");
    }
    validateExternalActor(receipt.actor, `${kind} receipt.actor`);
    validateExternalApp(receipt.app, `${kind} receipt.app`);
    validateControllerCommentIdentity(receipt.actor, receipt.app, kind);
    timestamp(receipt.server_time, `${kind} receipt.server_time`);
    digest(receipt.raw_body_sha256, `${kind} receipt.raw_body_sha256`);
    if (receipt.pre_comment_inventory_digest !==
        action.pre_comment_inventory_digest) {
      throw new Error("control comment inventory preimage differs from its intent");
    }
    digest(receipt.pre_comment_inventory_digest,
      `${kind} receipt.pre_comment_inventory_digest`);
    digest(receipt.post_comment_inventory_digest,
      `${kind} receipt.post_comment_inventory_digest`);
  } else if (kind === "automatic-request-reservation") {
    exactKeys(receipt, ["committed", "server_time"], `${kind} receipt`);
    if (receipt.committed !== true) throw new Error("reservation receipt is not committed");
    timestamp(receipt.server_time, `${kind} receipt.server_time`);
  } else if (kind === "reservation-status-write") {
    exactKeys(receipt, [
      "http_status", "status_id", "target_sha", "context", "state",
      "description_digest", "created_at", "updated_at", "creator",
      "post_server_time", "post_raw_body_sha256", "refetch_server_time",
      "refetch_page_count", "refetch_item_count", "refetch_match_count",
      "refetch_inventory_digest", "refetch_pages",
    ], `${kind} receipt`);
    validateV2GitLedgerReservationStatusResponseReceipt(receipt, { action });
  } else if (kind === "review-request") {
    validateV2GitLedgerAutomaticReviewRequestBindingReceipt(receipt, {
      repository,
      scope,
      action,
      controller_actor_id: lease.owner.actor_id,
      controller_app: null,
      not_before: receipt.request_scope_receipt.pre_scope.observed_at,
      record_boundary: recordBoundary,
      rest_base_url: new URL(receipt.api_url).origin,
    });
  } else if (kind === "request-binding") {
    exactKeys(receipt, [
      "request_id", "request_node_id", "request_url", "body_sha256",
      "created_at", "updated_at", "raw_body_sha256", "actor", "controlled",
    ], `${kind} receipt`);
    if (decimal(receipt.request_id, `${kind} receipt.request_id`) !==
        action.request_id) {
      throw new Error("request binding receipt identifies another request");
    }
    boundedString(receipt.request_node_id, `${kind} receipt.request_node_id`, 256);
    githubUrl(receipt.request_url, `${kind} receipt.request_url`);
    digest(receipt.body_sha256, `${kind} receipt.body_sha256`);
    const created = timestamp(receipt.created_at, `${kind} receipt.created_at`);
    if (timestamp(receipt.updated_at, `${kind} receipt.updated_at`) !== created) {
      throw new Error("request binding receipt authorizes an edited request");
    }
    digest(receipt.raw_body_sha256, `${kind} receipt.raw_body_sha256`);
    validateExternalActor(receipt.actor, `${kind} receipt.actor`);
    if (
      receipt.controlled !== true ||
      receipt.actor.id !== lease.owner.actor_id ||
      receipt.actor.login !== "github-actions[bot]" ||
      receipt.actor.type !== "Bot"
    ) {
      throw new Error(
        "request binding must be controlled by the authenticated controller principal",
      );
    }
  } else if (kind === "artifact-binding-ready") {
    exactKeys(receipt, [
      "ready_record_oid", "ready_record_payload_digest",
      "ready_reachability_boundary",
    ], `${kind} receipt`);
    sha(receipt.ready_record_oid, `${kind} receipt.ready_record_oid`);
    digest(receipt.ready_record_payload_digest,
      `${kind} receipt.ready_record_payload_digest`);
    const readyBoundary =
      validateAutomaticRecoveryArtifactReadyReachabilityBoundary(
        receipt.ready_reachability_boundary,
      );
    if (
      readyBoundary.ready_record_oid !== receipt.ready_record_oid ||
      readyBoundary.ready_record_payload_digest !==
        receipt.ready_record_payload_digest ||
      readyBoundary.artifact_binding_intent_record_oid !==
        action.artifact_binding_intent_record_oid
    ) {
      throw new Error(
        "artifact binding ready receipt differs from its exact marker",
      );
    }
  } else if (kind === "artifact-binding") {
    exactKeys(receipt, [
      "http_status", "candidate_set_digest",
      "artifact_binding_ready_confirmation_record_oid",
      "artifact_binding_ready_confirmation_payload_digest",
      "continuation_scheduler_observation_record_oid",
      "continuation_full_scope_receipt_digest",
      "continuation_lease_acquire_commit_sha",
      "binding_count", "bindings", "bindings_digest",
    ], `${kind} receipt`);
    const authority =
      validateAutomaticRecoveryArtifactBindingCandidateAuthority(
        action.candidate_authority,
      );
    sha(receipt.artifact_binding_ready_confirmation_record_oid,
      `${kind} receipt.artifact_binding_ready_confirmation_record_oid`);
    digest(receipt.artifact_binding_ready_confirmation_payload_digest,
      `${kind} receipt.artifact_binding_ready_confirmation_payload_digest`);
    sha(receipt.continuation_scheduler_observation_record_oid,
      `${kind} receipt.continuation_scheduler_observation_record_oid`);
    digest(receipt.continuation_full_scope_receipt_digest,
      `${kind} receipt.continuation_full_scope_receipt_digest`);
    sha(receipt.continuation_lease_acquire_commit_sha,
      `${kind} receipt.continuation_lease_acquire_commit_sha`);
    const count = integerBetween(
      receipt.binding_count,
      1,
      MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_CANDIDATES,
      `${kind} receipt.binding_count`);
    if (
      receipt.http_status !== 200 ||
      receipt.candidate_set_digest !== action.candidate_set_digest ||
      generation.generation_id !== action.generation_id ||
      !Array.isArray(receipt.bindings) || receipt.bindings.length !== count ||
      count !== authority.candidates.length
    ) {
      throw new Error("artifact binding receipt differs from its aggregate intent");
    }
    receipt.bindings.forEach((binding, index) =>
      validateAutomaticRecoveryArtifactBindingReceiptItem(binding, {
        action,
        authority,
        index,
      }));
    digest(receipt.bindings_digest, `${kind} receipt.bindings_digest`);
    if (receipt.bindings_digest !== digestCanonical(
      "codex-review-gate-v2-aggregate-artifact-binding-receipts",
      receipt.bindings,
    )) {
      throw new Error("aggregate artifact binding receipts digest is invalid");
    }
    if (Buffer.byteLength(canonicalJson(receipt), "utf8") >
        MAX_V2_AUTOMATIC_RECOVERY_ARTIFACT_BINDING_RECEIPT_BYTES) {
      throw ledgerError(
        "automatic-artifact-binding-receipt-size",
        "aggregate artifact binding receipt exceeds its hard byte cap",
      );
    }
  } else if (kind === "no-start-observation") {
    exactKeys(receipt, [
      "carrier_created_at", "carrier_raw_body_sha256", "first_run_id",
      "first_observed_at", "confirmation_run_id", "confirmed_at",
    ], `${kind} receipt`);
    const carrier = timestamp(receipt.carrier_created_at,
      `${kind} receipt.carrier_created_at`);
    digest(receipt.carrier_raw_body_sha256,
      `${kind} receipt.carrier_raw_body_sha256`);
    const firstRun = decimal(receipt.first_run_id, `${kind} receipt.first_run_id`);
    const first = timestamp(receipt.first_observed_at,
      `${kind} receipt.first_observed_at`);
    const confirmationRun = decimal(receipt.confirmation_run_id,
      `${kind} receipt.confirmation_run_id`);
    const confirmed = timestamp(receipt.confirmed_at, `${kind} receipt.confirmed_at`);
    if (new Set([action.request_run_id, firstRun, confirmationRun]).size !== 3 ||
        !(Date.parse(action.request_created_at) < Date.parse(carrier) &&
          Date.parse(carrier) <= Date.parse(first) &&
          Date.parse(confirmed) - Date.parse(first) >= 900_000)) {
      throw new Error("no-start receipt lacks independent ordered observations");
    }
  } else if (kind === "thread-resolution-observation") {
    exactKeys(receipt, [
      "is_resolved", "response_server_time", "run_id", "raw_body_sha256",
    ], `${kind} receipt`);
    if (receipt.is_resolved !== true) throw new Error("thread is not resolved");
    timestamp(receipt.response_server_time, `${kind} receipt.response_server_time`);
    decimal(receipt.run_id, `${kind} receipt.run_id`);
    digest(receipt.raw_body_sha256, `${kind} receipt.raw_body_sha256`);
  } else if (kind === "status-write") {
    exactKeys(receipt, [
      "http_status", "status_id", "target_sha", "role", "context", "state",
      "description_digest", "created_at", "updated_at", "creator",
      "post_server_time", "post_raw_body_sha256", "refetch_server_time",
      "refetch_page_count", "refetch_item_count", "refetch_match_count",
      "refetch_inventory_digest", "refetch_pages",
    ], `${kind} receipt`);
    validateV2GitLedgerStatusWriteResponseReceipt(receipt, { action });
  } else if (kind === "sticky-comment") {
    exactKeys(receipt, [
      "http_status", "server_time", "raw_body_sha256", "comment", "actor",
      "app", "pre_comment_inventory_digest", "post_comment_inventory_digest",
    ], `${kind} receipt`);
    const expectedStatus = action.method === "POST" ? 201 : 200;
    if (receipt.http_status !== expectedStatus) {
      throw new Error("sticky comment response status is invalid");
    }
    normalizeControlCommentBinding(receipt.comment, { required: true });
    validateExternalActor(receipt.actor, `${kind} receipt.actor`);
    validateExternalApp(receipt.app, `${kind} receipt.app`);
    validateControllerCommentIdentity(receipt.actor, receipt.app, kind);
    timestamp(receipt.server_time, `${kind} receipt.server_time`);
    digest(receipt.raw_body_sha256, `${kind} receipt.raw_body_sha256`);
    if (receipt.pre_comment_inventory_digest !==
        action.pre_comment_inventory_digest) {
      throw new Error("sticky comment inventory preimage differs from its intent");
    }
    digest(receipt.post_comment_inventory_digest,
      `${kind} receipt.post_comment_inventory_digest`);
  } else if (kind === "scheduler-state") {
    exactKeys(receipt, [
      "committed", "recovery_transition_digest",
      "intent_recovery_authority_digest", "completion_recovery_authority",
      "completion_recovery_authority_digest",
      "completion_scheduler_observation_record_oid",
      "completion_full_scope_receipt_digest", "prior_generation_id",
      "next_generation_id", "server_time",
    ], `${kind} receipt`);
    const completion = validateAutomaticRequestRecoveryAuthority(
      receipt.completion_recovery_authority,
      { boundary: recordBoundary },
    );
    if (
      receipt.committed !== true ||
      receipt.recovery_transition_digest !==
        action.recovery_transition_digest ||
      receipt.intent_recovery_authority_digest !==
        action.recovery_authority.authority_digest ||
      receipt.completion_recovery_authority_digest !==
        completion.authority_digest ||
      receipt.recovery_transition_digest !==
        automaticRequestRecoveryTransitionDigest(completion) ||
      receipt.prior_generation_id !== completion.prior_generation_id ||
      receipt.next_generation_id !== completion.next_generation_id
    ) {
      throw new Error("scheduler-state recovery receipt is invalid");
    }
    digest(receipt.recovery_transition_digest,
      `${kind} receipt.recovery_transition_digest`);
    digest(receipt.intent_recovery_authority_digest,
      `${kind} receipt.intent_recovery_authority_digest`);
    digest(receipt.completion_recovery_authority_digest,
      `${kind} receipt.completion_recovery_authority_digest`);
    sha(receipt.completion_scheduler_observation_record_oid,
      `${kind} receipt.completion_scheduler_observation_record_oid`);
    digest(receipt.completion_full_scope_receipt_digest,
      `${kind} receipt.completion_full_scope_receipt_digest`);
    timestamp(receipt.server_time, `${kind} receipt.server_time`);
  }
}

function validateEffectReceiptTemporalBoundary(kind, receipt, boundaryValue) {
  const boundary = Date.parse(timestamp(
    boundaryValue,
    `${kind} authoritative record boundary`,
  ));
  const fields = [
    "server_time", "created_at", "updated_at", "carrier_created_at",
    "artifact_created_at",
    "first_observed_at", "confirmed_at", "response_server_time",
    "finding_observed_at", "closure_observed_at",
    "post_server_time", "refetch_server_time",
  ];
  for (const field of fields) {
    if (receipt[field] !== undefined && Date.parse(receipt[field]) > boundary) {
      throw new Error(`${kind} receipt ${field} is after its GitHub ref boundary`);
    }
  }
  if (
    kind === "artifact-binding-ready" &&
    Date.parse(receipt.ready_reachability_boundary.ref_receipt.server_time) >
      boundary
  ) {
    throw new Error(
      "artifact binding ready ref receipt is after its GitHub record boundary",
    );
  }
  if (kind === "artifact-binding") {
    for (const [index, binding] of receipt.bindings.entries()) {
      for (const field of ["artifact_created_at", "server_time"]) {
        if (Date.parse(binding[field]) > boundary) {
          throw new Error(
            `${kind} receipt bindings[${index}].${field} is after its GitHub ref boundary`,
          );
        }
      }
    }
  }
}

function validateControllerCommentIdentity(actor, app, kind) {
  if (
    actor.login !== "github-actions[bot]" || actor.type !== "Bot" ||
    app.id !== "15368" || app.slug !== "github-actions"
  ) {
    throw new Error(`${kind} receipt is not owned by the trusted GitHub Actions app`);
  }
}

function requireNullEffectFields(value, label) {
  if (value.kind !== null || value.effect_id !== null || value.idempotency_key !== null) {
    throw new Error(`${label} cannot carry effect identity fields`);
  }
}

function validateLeaseAcquirePayload(payload) {
  assertObject(payload, "lease acquire payload");
  exactKeys(payload, [
    "lease_id", "owner", "acquired_at", "expires_at", "lease_ttl_seconds",
  ],
    "lease acquire payload");
  boundedString(payload.lease_id, "lease_id", 256);
  normalizeLeaseOwner(payload.owner);
  const acquired = timestamp(payload.acquired_at, "lease acquired_at");
  const expires = timestamp(payload.expires_at, "lease expires_at");
  if (Date.parse(expires) <= Date.parse(acquired)) {
    throw new Error("lease expiry must be after acquisition");
  }
  const ttl = positiveInteger(payload.lease_ttl_seconds, "lease_ttl_seconds");
  if (ttl > 900 || Date.parse(expires) - Date.parse(acquired) !== ttl * 1000) {
    throw new Error("lease expiry does not match its bounded TTL");
  }
}

function validateLeaseReleasePayload(payload) {
  assertObject(payload, "lease release payload");
  exactKeys(payload, ["lease_id", "owner", "acquire_commit_sha", "released_at"],
    "lease release payload");
  boundedString(payload.lease_id, "lease release lease_id", 256);
  normalizeLeaseOwner(payload.owner);
  sha(payload.acquire_commit_sha, "lease release acquire_commit_sha");
  timestamp(payload.released_at, "lease release released_at");
}

function normalizeLeaseAcquireInput(value) {
  assertObject(value, "lease acquire input");
  exactKeys(value, [
    "predecessor_commit_sha", "pull_request", "head_ref_oid", "base_ref_oid",
    "potential_merge_commit_oid", "lease_id", "owner", "observed_at",
    "lease_ttl_seconds", "control_comment_binding",
  ], "lease acquire input");
  const normalized = {
    predecessor_commit_sha: sha(value.predecessor_commit_sha, "predecessor_commit_sha"),
    pull_request: normalizePullRequest(value.pull_request),
    head_ref_oid: sha(value.head_ref_oid, "head_ref_oid"),
    base_ref_oid: sha(value.base_ref_oid, "base_ref_oid"),
    potential_merge_commit_oid: nullableSha(
      value.potential_merge_commit_oid,
      "potential_merge_commit_oid",
    ),
    lease_id: boundedString(value.lease_id, "lease_id", 256),
    owner: normalizeLeaseOwner(value.owner),
    observed_at: timestamp(value.observed_at, "observed_at"),
    lease_ttl_seconds: positiveInteger(
      value.lease_ttl_seconds,
      "lease_ttl_seconds",
    ),
    control_comment_binding:
      normalizeControlCommentBinding(value.control_comment_binding),
  };
  if (normalized.lease_ttl_seconds > 900) {
    throw new Error("lease TTL exceeds the 900-second safety cap");
  }
  return normalized;
}

function validateLeaseReceipt(value, repo, ref) {
  assertObject(value, "lease receipt");
  exactKeys(value, [
    "schema", "schema_version", "repository", "ledger_ref", "lease_id", "owner",
    "acquire_commit_sha", "acquired_at", "expires_at", "scope",
    "append_receipt_digest", "receipt_digest",
  ], "lease receipt");
  if (value.schema !== V2_GIT_LEDGER_LEASE_RECEIPT_SCHEMA || value.schema_version !== 1) {
    throw new Error("lease receipt has an unsupported schema");
  }
  if (
    canonicalJson(normalizeRepository(value.repository)) !== canonicalJson(repo) ||
    normalizeLedgerRef(value.ledger_ref) !== ref
  ) {
    throw new Error("lease receipt belongs to another repository or ref");
  }
  boundedString(value.lease_id, "lease receipt lease_id", 256);
  normalizeLeaseOwner(value.owner);
  sha(value.acquire_commit_sha, "lease receipt acquire_commit_sha");
  timestamp(value.acquired_at, "lease receipt acquired_at");
  timestamp(value.expires_at, "lease receipt expires_at");
  assertObject(value.scope, "lease receipt scope");
  exactKeys(value.scope, [
    "pull_request", "head_ref_oid", "base_ref_oid", "potential_merge_commit_oid",
  ], "lease receipt scope");
  normalizePullRequest(value.scope.pull_request);
  sha(value.scope.head_ref_oid, "lease receipt scope.head_ref_oid");
  sha(value.scope.base_ref_oid, "lease receipt scope.base_ref_oid");
  nullableSha(value.scope.potential_merge_commit_oid,
    "lease receipt scope.potential_merge_commit_oid");
  digest(value.append_receipt_digest, "lease receipt append_receipt_digest");
  digest(value.receipt_digest, "lease receipt receipt_digest");
  const { receipt_digest: _digest, ...withoutDigest } = value;
  if (digestCanonical("codex-review-gate-v2-git-ledger-lease-receipt", withoutDigest) !==
      value.receipt_digest) {
    throw new Error("lease receipt digest is invalid");
  }
  return value;
}

function normalizeEnvelopeScopeFields(value) {
  if (
    INTERNAL_RECORD_TYPES.has(value.record_type) ||
    REPOSITORY_RECORD_TYPES.has(value.record_type)
  ) {
    if (value.pull_request !== null) normalizePullRequest(value.pull_request);
    if (value.head_ref_oid !== null) sha(value.head_ref_oid, "envelope.head_ref_oid");
    if (value.base_ref_oid !== null) sha(value.base_ref_oid, "envelope.base_ref_oid");
  } else {
    normalizePullRequest(value.pull_request);
    sha(value.head_ref_oid, "envelope.head_ref_oid");
    sha(value.base_ref_oid, "envelope.base_ref_oid");
  }
  nullableSha(value.potential_merge_commit_oid, "envelope.potential_merge_commit_oid");
  nullableBoundedString(value.kind, "envelope.kind", 128);
  nullableBoundedString(value.effect_id, "envelope.effect_id", 256);
  nullableBoundedString(value.idempotency_key, "envelope.idempotency_key", 256);
  normalizeControlCommentBinding(value.control_comment_binding);
  normalizeLeaseBinding(value.lease);
}

async function obtainWorkflowProvenance({
  verifyWorkflowProvenance,
  operation,
  repository,
  ledgerRef,
  predecessorCommitSha,
  protectionReceiptDigest,
  source,
  effectScope,
  evaluatedScopeReceipt = null,
  recordIdentity,
  serverTime,
  policy,
  provenanceBudget,
}) {
  const request = sealProvenanceRequest({
    operation,
    repository,
    ledger_ref: ledgerRef,
    predecessor_commit_sha: predecessorCommitSha,
    protection_receipt_digest: protectionReceiptDigest,
    source_workflow: source,
    effect_scope: effectScope,
    evaluated_scope_receipt: evaluatedScopeReceipt,
    record_identity: recordIdentity,
    github_server_time: serverTime,
  });
  return callWorkflowProvenanceVerifier({
    verifyWorkflowProvenance,
    mode: "mint-and-verify",
    request,
    compactJwt: null,
    storedReceipt: null,
    policy,
    provenanceBudget,
  });
}

async function reverifyStoredWorkflowProvenance({
  verifyWorkflowProvenance,
  envelope,
  policy,
  provenanceBudget,
}) {
  const binding = envelope.workflow_provenance.operation_binding;
  const request = validateProvenanceRequest({
    schema: V2_GIT_LEDGER_PROVENANCE_REQUEST_SCHEMA,
    schema_version: 1,
    ...structuredClone(binding),
  });
  const result = await callWorkflowProvenanceVerifier({
    verifyWorkflowProvenance,
    mode: "reverify-stored",
    request,
    compactJwt: envelope.workflow_provenance_jwt,
    storedReceipt: envelope.workflow_provenance,
    policy,
    provenanceBudget,
  });
  validateReverifiedProvenanceStableFields(
    envelope.workflow_provenance,
    result.receipt,
  );
  return result.receipt;
}

async function reverifyReachableWorkflowProvenance({
  records,
  repository,
  ledgerRef,
  verifyWorkflowProvenance,
  provenanceBudget,
  assertOperationCurrent = () => {},
}) {
  let activeCapability = null;
  const evidence = [];
  for (const entry of records) {
    const envelope = entry.envelope;
    let recordCapability;
    if (new Set(["genesis", "capability-canary"])
      .has(envelope.record_type)) {
      recordCapability = validateEmbeddedBootstrapCandidate(
        envelope.payload,
        repository,
        ledgerRef,
      );
    } else if (envelope.record_type === "capability-attestation") {
      recordCapability = validateEmbeddedCapability(
        envelope.payload,
        repository,
        ledgerRef,
      );
    } else {
      if (activeCapability === null) {
        throw ledgerError(
          "capability-attestation-required",
          "production Git ledger record precedes any reachable capability attestation",
        );
      }
      recordCapability = activeCapability;
    }
    validateV2GitLedgerEnvelope(envelope, {
      repository,
      ledger_ref: ledgerRef,
      source_workflow: sourceWorkflow(recordCapability.controller_release),
      provenance_policy: provenanceExpected(recordCapability),
    });
    assertOperationCurrent();
    const liveReceipt = await reverifyStoredWorkflowProvenance({
      verifyWorkflowProvenance,
      envelope,
      policy: recordCapability.workflow_provenance_policy,
      provenanceBudget,
    });
    assertOperationCurrent();
    const withoutDigest = {
      record_oid: entry.commit_sha,
      stored_receipt_digest: envelope.workflow_provenance.receipt_digest,
      live_receipt_digest: liveReceipt.receipt_digest,
      token_sha256: liveReceipt.token_sha256,
      key_id: liveReceipt.key_id,
      verified_at_server_time: liveReceipt.verified_at_server_time,
      discovery: structuredClone(liveReceipt.discovery),
      jwks: structuredClone(liveReceipt.jwks),
    };
    evidence.push({
      ...withoutDigest,
      evidence_digest: digestCanonical(
        "codex-review-gate-v2-git-ledger-provenance-reverification",
        withoutDigest,
      ),
    });
    if (envelope.record_type === "capability-attestation") {
      if (
        envelope.payload.protection_receipt_digest !==
          recordCapability.protection.live_ruleset_receipt_digest ||
        canonicalJson(envelope.payload.controller_release) !==
          canonicalJson(recordCapability.controller_release)
      ) {
        throw ledgerError(
          "attestation-capability-mismatch",
          "capability attestation does not activate its embedded capability receipt",
        );
      }
      activeCapability = recordCapability;
    }
  }
  return deepFreeze(evidence);
}

async function callWorkflowProvenanceVerifier({
  verifyWorkflowProvenance,
  mode,
  request,
  compactJwt,
  storedReceipt,
  policy,
  provenanceBudget,
}) {
  const verifierRequest = deepFreeze({
    schema: V2_GIT_LEDGER_PROVENANCE_VERIFIER_REQUEST_SCHEMA,
    schema_version: 1,
    mode,
    provenance_request: structuredClone(request),
    compact_jwt: compactJwt,
    stored_receipt:
      storedReceipt === null ? null : structuredClone(storedReceipt),
  });
  let rawResult;
  const verifierSignal = consumeProvenanceBudget(provenanceBudget);
  try {
    rawResult = await Promise.race([
      verifyWorkflowProvenance(structuredClone(verifierRequest), {
        signal: verifierSignal.signal,
        deadline_ms: verifierSignal.timeout_ms,
      }),
      verifierSignal.deadline,
    ]);
    verifierSignal.assertOpen();
  } catch (error) {
    if (
      error?.code === "provenance-timeout" ||
      error?.code === "checkpoint-transaction-timeout"
    ) throw error;
    if (new Set(["oidc-kid-unavailable", "OIDC_KID_UNAVAILABLE"])
      .has(error?.code)) {
      throw ledgerError(
        "oidc-kid-unavailable",
        "stored OIDC JWT key id is unavailable in the current GitHub JWKS",
      );
    }
    throw ledgerError(
      "workflow-provenance-verification-failed",
      "GitHub OIDC workflow provenance verification failed closed",
    );
  } finally {
    verifierSignal.finish();
  }
  assertObject(rawResult, "workflow provenance verifier result");
  exactKeys(rawResult, [
    "schema", "schema_version", "mode", "compact_jwt", "receipt",
  ], "workflow provenance verifier result");
  if (
    rawResult.schema !== V2_GIT_LEDGER_PROVENANCE_VERIFIER_RESULT_SCHEMA ||
    rawResult.schema_version !== 1 || rawResult.mode !== mode
  ) {
    throw new Error("workflow provenance verifier result schema is invalid");
  }
  const jwt = mode === "mint-and-verify"
    ? compactOidcJwt(rawResult.compact_jwt)
    : compactOidcJwt(compactJwt);
  if (
    (mode === "reverify-stored" && rawResult.compact_jwt !== null) ||
    (mode === "mint-and-verify" && rawResult.compact_jwt !== jwt)
  ) {
    throw new Error("workflow provenance verifier returned unexpected JWT bytes");
  }
  const receipt = validateV2GitLedgerProvenanceReceipt(
    rawResult.receipt,
    mode === "mint-and-verify" ? { request, policy } : { request },
  );
  if (mode === "reverify-stored") {
    validateReverifiedProvenanceAgainstPolicy(receipt, policy);
  }
  if (rawDigest(jwt) !== receipt.token_sha256) {
    throw new Error("workflow provenance verifier JWT digest is invalid");
  }
  verifierSignal.assertOpen();
  return deepFreeze({ receipt, compact_jwt: jwt });
}

function validateReverifiedProvenanceStableFields(stored, live) {
  const stableFields = [
    "verified",
    "signature_verified",
    "jwks_verified",
    "live_supported",
    "issuer",
    "audience",
    "algorithm",
    "key_id",
    "claims",
    "token_sha256",
    "verified_at_server_time",
    "replay_prevention_receipt_digest",
    "operation_binding",
  ];
  for (const field of stableFields) {
    if (canonicalJson(stored[field]) !== canonicalJson(live[field])) {
      throw ledgerError(
        "stored-provenance-mismatch",
        "stored workflow provenance stable fields differ from live JWT reverification",
      );
    }
  }
}

function validateReverifiedProvenanceAgainstPolicy(receipt, policyValue) {
  const policy = normalizeProvenancePolicy(policyValue);
  const claims = normalizeOidcClaims(receipt.claims);
  const discovery = normalizeOidcDiscoveryReceipt(receipt.discovery);
  const jwks = normalizeOidcJwksReceipt(receipt.jwks);
  if (
    receipt.issuer !== policy.issuer ||
    !receipt.audience.startsWith(`${policy.audience}:`) ||
    receipt.algorithm !== policy.algorithm ||
    discovery.url !== policy.discovery_url ||
    jwks.url !== policy.jwks_uri ||
    policy.required_claims.some((claim) =>
      !discovery.claims_supported.includes(claim)) ||
    claims.repository_owner_id !== String(policy.repository_owner_id) ||
    claims.sub !== policy.subject_pattern ||
    digestCanonical("codex-review-gate-v2-oidc-subject-pattern", claims.sub) !==
      policy.subject_pattern_digest ||
    !policy.allowed_event_names.includes(claims.event_name) ||
    !policy.allowed_refs.includes(claims.ref)
  ) {
    throw ledgerError(
      "live-provenance-policy-mismatch",
      "live JWT reverification differs from the sealed stable OIDC policy",
    );
  }
}

function sealProvenanceRequest(value) {
  const nonceInput = {
    schema: V2_GIT_LEDGER_PROVENANCE_REQUEST_SCHEMA,
    schema_version: 1,
    ...structuredClone(value),
  };
  const nonce = digestCanonical(
    "codex-review-gate-v2-git-ledger-provenance-nonce",
    nonceInput,
  );
  const withoutDigest = {
    ...nonceInput,
    nonce,
    audience: `${V2_GIT_LEDGER_OIDC_AUDIENCE}:${nonce.slice("sha256:".length)}`,
  };
  const sealed = {
    ...withoutDigest,
    request_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-provenance-request",
      withoutDigest,
    ),
  };
  validateProvenanceRequest(sealed);
  return deepFreeze(sealed);
}

function validateProvenanceRequest(value) {
  assertObject(value, "workflow provenance request");
  exactKeys(value, [
    "schema", "schema_version", "operation", "repository", "ledger_ref",
    "predecessor_commit_sha", "protection_receipt_digest", "source_workflow",
    "effect_scope", "evaluated_scope_receipt", "record_identity",
    "github_server_time", "nonce",
    "audience", "request_digest",
  ], "workflow provenance request");
  if (
    value.schema !== V2_GIT_LEDGER_PROVENANCE_REQUEST_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error("workflow provenance request has an unsupported schema");
  }
  const operation = boundedString(
    value.operation,
    "workflow provenance operation",
    128,
  );
  if (!PROVENANCE_OPERATIONS.has(operation)) {
    throw new Error("workflow provenance operation is not closed");
  }
  const repository = normalizeRepository(value.repository);
  const ledgerRef = normalizeLedgerRef(value.ledger_ref);
  const predecessor = value.predecessor_commit_sha === null
    ? null
    : sha(value.predecessor_commit_sha,
      "workflow provenance predecessor_commit_sha");
  digest(value.protection_receipt_digest,
    "workflow provenance protection_receipt_digest");
  const source = normalizeSourceWorkflow(
    value.source_workflow,
    "workflow provenance source_workflow",
  );
  const effectScope = normalizeEffectScope(value.effect_scope);
  const evaluatedScopeReceipt = value.evaluated_scope_receipt === null
    ? null
    : validateV2GitLedgerEvaluatedScopeReceipt(
      value.evaluated_scope_receipt,
      { repository, scope: effectScope },
    );
  const recordIdentity = normalizeProvenanceRecordIdentity(value.record_identity);
  const productionOperation = RECORD_TYPES.has(operation);
  const repositoryOperation = REPOSITORY_RECORD_TYPES.has(operation);
  const checkpointOperation = operation === "checkpoint-rotate";
  if ((productionOperation &&
        ((repositoryOperation ? effectScope !== null : effectScope === null) ||
          evaluatedScopeReceipt === null ||
          recordIdentity === null)) ||
      (checkpointOperation &&
        (effectScope !== null || evaluatedScopeReceipt !== null ||
          recordIdentity?.record_type !== "epoch-checkpoint")) ||
      (!productionOperation &&
        !checkpointOperation &&
        (effectScope !== null || evaluatedScopeReceipt !== null ||
          recordIdentity !== null))) {
    throw new Error(
      "workflow provenance effect scope does not match its operation",
    );
  }
  const serverTime = timestamp(
    value.github_server_time,
    "workflow provenance github_server_time",
  );
  const nonce = digest(value.nonce, "workflow provenance nonce");
  boundedString(value.audience, "workflow provenance audience", 512);
  const {
    request_digest: _requestDigest,
    audience: _audience,
    nonce: _nonce,
    ...nonceInput
  } = value;
  const expectedNonce = digestCanonical(
    "codex-review-gate-v2-git-ledger-provenance-nonce",
    nonceInput,
  );
  if (
    nonce !== expectedNonce ||
    value.audience !==
      `${V2_GIT_LEDGER_OIDC_AUDIENCE}:${nonce.slice("sha256:".length)}`
  ) {
    throw new Error("workflow provenance nonce or effect-bound audience is invalid");
  }
  digest(value.request_digest, "workflow provenance request_digest");
  const { request_digest: _digest, ...withoutDigest } = value;
  if (digestCanonical("codex-review-gate-v2-git-ledger-provenance-request",
    withoutDigest) !== value.request_digest) {
    throw new Error("workflow provenance request digest is invalid");
  }
  return {
    ...value,
    repository,
    ledger_ref: ledgerRef,
    predecessor_commit_sha: predecessor,
    source_workflow: source,
    effect_scope: effectScope,
    evaluated_scope_receipt: evaluatedScopeReceipt,
    record_identity: recordIdentity,
    github_server_time: serverTime,
  };
}

function operationBinding(request) {
  return {
    operation: request.operation,
    repository: request.repository,
    ledger_ref: request.ledger_ref,
    predecessor_commit_sha: request.predecessor_commit_sha,
    protection_receipt_digest: request.protection_receipt_digest,
    source_workflow: request.source_workflow,
    effect_scope: request.effect_scope,
    evaluated_scope_receipt: request.evaluated_scope_receipt,
    record_identity: request.record_identity,
    github_server_time: request.github_server_time,
    nonce: request.nonce,
    audience: request.audience,
    request_digest: request.request_digest,
  };
}

function normalizeProvenanceOperationBinding(value) {
  assertObject(value, "workflow provenance operation_binding");
  exactKeys(value, [
    "operation", "repository", "ledger_ref", "predecessor_commit_sha",
    "protection_receipt_digest", "source_workflow", "effect_scope",
    "evaluated_scope_receipt",
    "record_identity", "github_server_time", "nonce", "audience",
    "request_digest",
  ], "workflow provenance operation_binding");
  const operation = boundedString(
    value.operation,
    "workflow provenance binding.operation",
    128,
  );
  if (!PROVENANCE_OPERATIONS.has(operation)) {
    throw new Error("workflow provenance binding operation is not closed");
  }
  normalizeRepository(value.repository);
  normalizeLedgerRef(value.ledger_ref);
  if (value.predecessor_commit_sha !== null) {
    sha(value.predecessor_commit_sha,
      "workflow provenance binding.predecessor_commit_sha");
  }
  digest(value.protection_receipt_digest,
    "workflow provenance binding.protection_receipt_digest");
  normalizeSourceWorkflow(value.source_workflow,
    "workflow provenance binding.source_workflow");
  const effectScope = normalizeEffectScope(value.effect_scope);
  const evaluatedScopeReceipt = value.evaluated_scope_receipt === null
    ? null
    : validateV2GitLedgerEvaluatedScopeReceipt(
      value.evaluated_scope_receipt,
      { repository: value.repository, scope: effectScope },
    );
  const recordIdentity = normalizeProvenanceRecordIdentity(value.record_identity);
  const repositoryOperation = REPOSITORY_RECORD_TYPES.has(operation);
  const checkpointOperation = operation === "checkpoint-rotate";
  if ((RECORD_TYPES.has(operation) &&
        ((repositoryOperation ? effectScope !== null : effectScope === null) ||
          evaluatedScopeReceipt === null ||
          recordIdentity === null)) ||
      (checkpointOperation &&
        (effectScope !== null || evaluatedScopeReceipt !== null ||
          recordIdentity?.record_type !== "epoch-checkpoint")) ||
      (!RECORD_TYPES.has(operation) &&
        !checkpointOperation &&
        (effectScope !== null || evaluatedScopeReceipt !== null ||
          recordIdentity !== null))) {
    throw new Error(
      "workflow provenance binding effect scope does not match its operation",
    );
  }
  timestamp(value.github_server_time,
    "workflow provenance binding.github_server_time");
  digest(value.nonce, "workflow provenance binding.nonce");
  boundedString(value.audience, "workflow provenance binding.audience", 512);
  digest(value.request_digest, "workflow provenance binding.request_digest");
  const { request_digest: _digest, ...requestFields } = value;
  const request = {
    schema: V2_GIT_LEDGER_PROVENANCE_REQUEST_SCHEMA,
    schema_version: 1,
    ...structuredClone(requestFields),
  };
  if (digestCanonical("codex-review-gate-v2-git-ledger-provenance-request",
    request) !== value.request_digest) {
    throw new Error("workflow provenance binding request digest is invalid");
  }
  return value;
}

function normalizeOidcClaims(value) {
  assertObject(value, "workflow provenance claims");
  const keys = Object.keys(value).sort();
  const withoutJti = [...V2_GIT_LEDGER_OIDC_CLAIMS].sort();
  const withJti = [...V2_GIT_LEDGER_OIDC_CLAIMS, "jti"].sort();
  if (
    canonicalJson(keys) !== canonicalJson(withoutJti) &&
    canonicalJson(keys) !== canonicalJson(withJti)
  ) {
    throw new TypeError(
      "workflow provenance claims must use the closed required set with only optional jti",
    );
  }
  const strings = {};
  for (const key of V2_GIT_LEDGER_OIDC_CLAIMS) {
    if (new Set(["iat", "nbf", "exp"]).has(key)) continue;
    strings[key] = boundedString(value[key], `workflow provenance claims.${key}`, 1024);
  }
  const jti = value.jti === undefined
    ? null
    : boundedString(value.jti, "workflow provenance claims.jti", 1024);
  if (!SHA.test(strings.sha) || !SHA.test(strings.workflow_sha) ||
      !SHA.test(strings.job_workflow_sha)) {
    throw new Error("workflow provenance SHA claims must be lowercase full SHAs");
  }
  if (!strings.ref.startsWith("refs/")) {
    throw new Error("workflow provenance ref claim is not canonical");
  }
  return {
    ...strings,
    jti,
    iat: nonnegativeInteger(value.iat, "workflow provenance claims.iat"),
    nbf: nonnegativeInteger(value.nbf, "workflow provenance claims.nbf"),
    exp: positiveInteger(value.exp, "workflow provenance claims.exp"),
  };
}

function normalizeOidcDiscoveryReceipt(value) {
  assertObject(value, "workflow provenance discovery receipt");
  exactKeys(value, [
    "url", "server_time", "raw_body_sha256", "claims_supported",
  ], "workflow provenance discovery receipt");
  if (value.url !==
      "https://token.actions.githubusercontent.com/.well-known/openid-configuration") {
    throw new Error("workflow provenance discovery URL is unsupported");
  }
  timestamp(value.server_time, "workflow provenance discovery server_time");
  digest(value.raw_body_sha256,
    "workflow provenance discovery raw_body_sha256");
  normalizeUniqueStringArray(value.claims_supported,
    "workflow provenance discovery claims_supported");
  return value;
}

function normalizeOidcJwksReceipt(value) {
  assertObject(value, "workflow provenance JWKS receipt");
  exactKeys(value, [
    "url", "server_time", "raw_body_sha256",
  ], "workflow provenance JWKS receipt");
  if (value.url !== "https://token.actions.githubusercontent.com/.well-known/jwks") {
    throw new Error("workflow provenance JWKS URL is unsupported");
  }
  timestamp(value.server_time, "workflow provenance JWKS server_time");
  digest(value.raw_body_sha256, "workflow provenance JWKS raw_body_sha256");
  return value;
}

function validateProvenanceAgainstPolicy({ value, discovery, jwks, policy }) {
  if (
    value.issuer !== policy.issuer ||
    !value.audience.startsWith(`${policy.audience}:`) ||
    value.algorithm !== policy.algorithm || discovery.url !== policy.discovery_url ||
    jwks.url !== policy.jwks_uri ||
    canonicalJson([...discovery.claims_supported].sort()) !==
      canonicalJson([...policy.claims_supported].sort())
  ) {
    throw new Error("workflow provenance differs from the live capability policy");
  }
  const claims = normalizeOidcClaims(value.claims);
  if (
    claims.repository_owner_id !== String(policy.repository_owner_id) ||
    claims.sub !== policy.subject_pattern ||
    digestCanonical("codex-review-gate-v2-oidc-subject-pattern", claims.sub) !==
      policy.subject_pattern_digest ||
    !policy.allowed_event_names.includes(claims.event_name) ||
    !policy.allowed_refs.includes(claims.ref)
  ) {
    throw new Error("workflow provenance claims violate the closed subject/event/ref policy");
  }
}

function validateOidcEffectScopeRelation(claims, effectScope) {
  if (effectScope === null) return;
  if (claims.event_name === "pull_request") {
    const expectedRef = `refs/pull/${effectScope.pull_request.number}/merge`;
    if (
      effectScope.potential_merge_commit_oid === null ||
      claims.ref !== expectedRef ||
      claims.sha !== effectScope.potential_merge_commit_oid
    ) {
      throw new Error(
        "pull_request OIDC ref/SHA does not bind the exact effect scope",
      );
    }
    return;
  }
  if (claims.event_name === "pull_request_target") {
    if (claims.sha !== effectScope.base_ref_oid) {
      throw new Error(
        "pull_request_target OIDC SHA does not bind the exact base scope",
      );
    }
    return;
  }
  if (new Set([
    "issue_comment", "pull_request_review", "pull_request_review_comment",
    "schedule", "workflow_dispatch",
  ]).has(claims.event_name)) return;
  throw new Error("OIDC trigger event cannot authorize production effects");
}

function validateTriggerIdentityAgainstClaims(receipt, claimsValue) {
  if (receipt === null) return;
  const claims = normalizeOidcClaims(claimsValue);
  if (
    receipt.trigger_event_name !== claims.event_name ||
    receipt.trigger_ref !== claims.ref ||
    receipt.trigger_sha !== claims.sha
  ) {
    throw new Error(
      "evaluated scope receipt trigger identity differs from signed OIDC claims",
    );
  }
}

export function validateV2GitLedgerEvaluatedScopeReceipt(
  value,
  { repository: repositoryValue = null, scope: scopeValue = null } = {},
) {
  assertObject(value, "evaluated_scope_receipt");
  exactKeys(value, [
    "schema", "schema_version", "relation", "phase", "repository", "scope",
    "trigger_event_name", "trigger_ref", "trigger_sha", "selector",
    "inventory_receipt", "provider_artifact_receipt",
    "provider_identity_authority",
    "discovery_continuity_receipt",
    "scope_endpoint_receipt", "receipt_digest",
  ], "evaluated_scope_receipt");
  if (
    value.schema !== V2_GIT_LEDGER_EVALUATED_SCOPE_RECEIPT_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error("evaluated scope receipt schema is unsupported");
  }
  const repository = normalizeRepository(value.repository);
  const relations = new Set([
    "pull-request-event", "provider-selector", "scheduled-pull-request",
    "scheduled-repository-inventory", "scheduled-repository-dispatch",
    "manual-pull-request",
  ]);
  if (!relations.has(value.relation)) {
    throw new Error("evaluated scope receipt relation is unsupported");
  }
  const repositoryRelation = new Set([
    "scheduled-repository-inventory",
    "scheduled-repository-dispatch",
  ]).has(value.relation);
  const expectedPhases = value.relation === "scheduled-repository-inventory"
    ? new Set(["repository-inventory"])
    : value.relation === "scheduled-repository-dispatch"
      ? new Set(["repository-dispatch"])
    : new Set(["pre-scope", "full-discovery"]);
  if (!expectedPhases.has(value.phase)) {
    throw new Error("evaluated scope receipt phase is unsupported");
  }
  const scope = normalizeEffectScope(value.scope);
  if (
    repositoryRelation !== (scope === null)
  ) {
    throw new Error(
      "evaluated scope receipt PR scope differs from its repository relation",
    );
  }
  const eventName = boundedString(
    value.trigger_event_name,
    "evaluated scope trigger_event_name",
    128,
  );
  const triggerRef = boundedString(
    value.trigger_ref,
    "evaluated scope trigger_ref",
    1024,
  );
  if (!triggerRef.startsWith("refs/")) {
    throw new Error("evaluated scope trigger_ref is not canonical");
  }
  const triggerSha = sha(value.trigger_sha, "evaluated scope trigger_sha");
  const allowedByRelation = {
    "pull-request-event": new Set(["pull_request", "pull_request_target"]),
    "provider-selector": new Set([
      "issue_comment", "pull_request_review", "pull_request_review_comment",
    ]),
    "scheduled-pull-request": new Set(["schedule"]),
    "scheduled-repository-inventory": new Set(["schedule"]),
    "scheduled-repository-dispatch": new Set(["schedule"]),
    "manual-pull-request": new Set(["workflow_dispatch"]),
  };
  if (!allowedByRelation[value.relation].has(eventName)) {
    throw new Error("evaluated scope relation differs from its trigger event");
  }
  const selector = normalizeEvaluatedScopeSelector(
    value.selector,
    value.relation,
    repository,
    scope,
  );
  const inventoryReceipt = normalizeEvaluatedScopeInventoryReceipt(
    value.inventory_receipt,
    value.relation,
    scope,
  );
  const providerArtifactReceipt = normalizeProviderArtifactReceipt(
    value.provider_artifact_receipt,
    value.relation,
    selector,
  );
  const providerIdentityAuthority = normalizeEvaluatedProviderIdentityAuthority(
    value.provider_identity_authority,
    value.relation,
  );
  const discoveryContinuityReceipt =
    normalizeEvaluatedDiscoveryContinuityReceipt(
      value.discovery_continuity_receipt,
      value.relation,
      repository,
      scope,
    );
  if (
    (value.phase === "full-discovery") !==
      (discoveryContinuityReceipt !== null)
  ) {
    throw new Error(
      "evaluated scope receipt phase differs from discovery continuity",
    );
  }
  const scopeEndpointReceipt = normalizeEvaluatedScopeEndpointReceipt(
    value.scope_endpoint_receipt,
    value.relation,
    repository,
    scope,
  );
  if (
    repositoryValue !== null &&
    canonicalJson(repository) !==
      canonicalJson(normalizeRepository(repositoryValue))
  ) {
    throw new Error("evaluated scope receipt binds another repository");
  }
  if (
    scopeValue !== null &&
    canonicalJson(scope) !== canonicalJson(normalizeEffectScope(scopeValue))
  ) {
    throw new Error("evaluated scope receipt binds another PR scope");
  }
  digest(value.receipt_digest, "evaluated scope receipt_digest");
  const { receipt_digest: _receiptDigest, ...withoutDigest } = value;
  if (digestCanonical("codex-review-gate-v2-evaluated-scope-receipt",
    withoutDigest) !== value.receipt_digest) {
    throw new Error("evaluated scope receipt digest is invalid");
  }
  return deepFreeze({
    ...structuredClone(value),
    repository,
    scope,
    trigger_event_name: eventName,
    trigger_ref: triggerRef,
    trigger_sha: triggerSha,
    selector,
    inventory_receipt: inventoryReceipt,
    provider_artifact_receipt: providerArtifactReceipt,
    provider_identity_authority: providerIdentityAuthority,
    discovery_continuity_receipt: discoveryContinuityReceipt,
    scope_endpoint_receipt: scopeEndpointReceipt,
  });
}

function normalizeEvaluatedDiscoveryContinuityReceipt(
  value,
  relation,
  repository,
  scope,
) {
  if (value === null) return null;
  if (new Set([
    "scheduled-repository-inventory",
    "scheduled-repository-dispatch",
  ]).has(relation) || scope === null) {
    throw new Error("repository inventory cannot carry PR discovery continuity");
  }
  return validateV2GitLedgerDiscoveryContinuityReceipt(value, {
    repository,
    scope,
  });
}

function normalizeEvaluatedScopeSelector(value, relation, repository, scope) {
  if (relation === "manual-pull-request") {
    assertObject(value, "manual evaluated scope selector");
    exactKeys(value, [
      "source", "input_name", "input_value", "pull_request_number",
      "pull_request_node_id", "command_receipt_digest",
      "selection_receipt_digest",
    ], "manual evaluated scope selector");
    if (
      value.source !== "trusted-reusable-workflow-input" ||
      value.input_name !== "pull-request" ||
      value.input_value !== String(scope.pull_request.number) ||
      positiveInteger(
        value.pull_request_number,
        "manual evaluated scope selector.pull_request_number",
      ) !== scope.pull_request.number ||
      value.pull_request_node_id !== scope.pull_request.node_id
    ) {
      throw new Error(
        "manual evaluated scope is not one trusted explicit PR selection",
      );
    }
    boundedString(
      value.pull_request_node_id,
      "manual evaluated scope selector.pull_request_node_id",
      256,
    );
    digest(
      value.command_receipt_digest,
      "manual evaluated scope selector.command_receipt_digest",
    );
    digest(
      value.selection_receipt_digest,
      "manual evaluated scope selector.selection_receipt_digest",
    );
    const { selection_receipt_digest: _digest, ...withoutDigest } = value;
    if (
      value.selection_receipt_digest !== digestCanonical(
        "codex-review-gate-v2-manual-pull-request-selection",
        withoutDigest,
      )
    ) {
      throw new Error("manual evaluated scope selection digest is invalid");
    }
    return value;
  }
  if (relation !== "provider-selector") {
    if (value !== null) throw new Error("scope relation cannot carry a selector");
    return null;
  }
  assertObject(value, "evaluated scope selector");
  exactKeys(value, [
    "kind", "id", "node_id", "url", "pull_request_number",
    "pull_request_node_id", "actor", "app", "server_time",
    "raw_body_sha256",
  ], "evaluated scope selector");
  const selector = normalizeCarrierSelector(
    { kind: value.kind, id: value.id },
    "evaluated scope selector",
  );
  boundedString(value.node_id, "evaluated scope selector.node_id", 256);
  if (
    value.url !== exactProviderArtifactUrl(
      repository,
      scope.pull_request,
      selector,
    ) ||
    positiveInteger(value.pull_request_number,
      "evaluated scope selector.pull_request_number") !==
      scope.pull_request.number ||
    value.pull_request_node_id !== scope.pull_request.node_id
  ) {
    throw new Error("provider selector does not exact-bind the evaluated PR");
  }
  boundedString(value.pull_request_node_id,
    "evaluated scope selector.pull_request_node_id", 256);
  validateExternalActor(value.actor, "evaluated scope selector.actor");
  validateExternalApp(value.app, "evaluated scope selector.app");
  validateCodexProvider(value.actor, value.app, "evaluated scope selector provider");
  timestamp(value.server_time, "evaluated scope selector.server_time");
  digest(value.raw_body_sha256, "evaluated scope selector.raw_body_sha256");
  return value;
}

function normalizeProviderArtifactReceipt(value, relation, selector) {
  if (relation !== "provider-selector") {
    if (value !== null) {
      throw new Error("non-provider scope cannot carry provider artifact evidence");
    }
    return null;
  }
  assertObject(value, "provider artifact receipt");
  exactKeys(value, [
    "phase", "pre_scope_receipt_digest", "carrier_digest",
    "snapshot_digest", "observed_at",
  ], "provider artifact receipt");
  if (!new Set(["pre-scope", "full-discovery"]).has(value.phase)) {
    throw new Error("provider artifact receipt phase is unsupported");
  }
  if (value.phase === "pre-scope") {
    if (
      value.pre_scope_receipt_digest !== null ||
      value.snapshot_digest !== null
    ) {
      throw new Error("provider pre-scope receipt cannot cite full discovery");
    }
  } else {
    digest(
      value.pre_scope_receipt_digest,
      "provider artifact pre_scope_receipt_digest",
    );
    digest(value.snapshot_digest, "provider artifact snapshot_digest");
  }
  digest(value.carrier_digest, "provider artifact carrier_digest");
  const observedAt = timestamp(value.observed_at,
    "provider artifact observed_at");
  if (observedAt !== selector.server_time) {
    throw new Error("provider artifact receipt time differs from its exact selector");
  }
  return value;
}

function normalizeEvaluatedScopeInventoryReceipt(value, relation, scope) {
  if (relation === "scheduled-repository-inventory") {
    assertObject(value, "evaluated repository inventory receipt");
    if (value.phase === "current-open-generation") {
      exactKeys(value, [
        "phase", "source_profile", "generation_id",
        "production_candidate_authority_digest", "candidate_set_digest",
        "source_current_open_semantic_digest",
        "lifecycle_candidate_set_digest", "evidence_receipt_digest",
        "observed_at",
      ], "evaluated current-open generation receipt");
      if (
        value.source_profile !== CURRENT_OPEN_GENERATION_SOURCE_PROFILE ||
        !CANDIDATE_SOURCE_GENERATION_ID.test(value.generation_id)
      ) {
        throw new Error("evaluated current-open generation is unsupported");
      }
      for (const field of [
        "production_candidate_authority_digest", "candidate_set_digest",
        "source_current_open_semantic_digest",
        "lifecycle_candidate_set_digest", "evidence_receipt_digest",
      ]) digest(value[field], `evaluated current-open generation ${field}`);
      timestamp(value.observed_at,
        "evaluated current-open generation observed_at");
      return value;
    }
    exactKeys(value, [
      "phase", "cycle_id", "initial_inventory_receipt_digest",
      "shard_index", "evidence_receipt_digest", "observed_at",
    ], "evaluated repository inventory receipt");
    if (
      !new Set(["cycle-start", "shard", "attempt", "cycle-complete"])
        .has(value.phase) ||
      !CANDIDATE_CYCLE_ID.test(value.cycle_id)
    ) {
      throw new Error("evaluated repository inventory phase is unsupported");
    }
    digest(value.initial_inventory_receipt_digest,
      "evaluated repository inventory initial digest");
    if (new Set(["shard", "attempt"]).has(value.phase)) {
      nonnegativeInteger(value.shard_index,
        "evaluated repository inventory shard_index");
    } else if (value.shard_index !== null) {
      throw new Error("non-shard repository inventory cannot carry a shard index");
    }
    digest(value.evidence_receipt_digest,
      "evaluated repository inventory evidence digest");
    timestamp(value.observed_at,
      "evaluated repository inventory observed_at");
    return value;
  }
  if (relation === "scheduled-repository-dispatch") {
    assertObject(value, "evaluated repository dispatch receipt");
    exactKeys(value, [
      "phase", "generation_id", "cycle_id", "inventory_digest",
      "reservation_digest", "dispatch_digest", "batch_index",
      "candidate_number", "result_digest", "evidence_digest",
    ], "evaluated repository dispatch receipt");
    if (
      !new Set([
        "reserve", "candidate-ack", "batch-complete", "cycle-complete",
      ]).has(value.phase) ||
      !CANDIDATE_DISPATCH_GENERATION_ID.test(value.generation_id) ||
      !CANDIDATE_CYCLE_ID.test(value.cycle_id)
    ) {
      throw new Error("evaluated repository dispatch phase is unsupported");
    }
    digest(value.inventory_digest,
      "evaluated repository dispatch inventory digest");
    if (value.reservation_digest !== null) {
      digest(value.reservation_digest,
        "evaluated repository dispatch reservation digest");
    }
    if (value.dispatch_digest !== null) {
      digest(value.dispatch_digest,
        "evaluated repository dispatch dispatch digest");
    }
    if (value.batch_index !== null) {
      nonnegativeInteger(value.batch_index,
        "evaluated repository dispatch batch index");
    }
    if (value.candidate_number !== null) {
      positiveInteger(value.candidate_number,
        "evaluated repository dispatch candidate number");
    }
    if (value.result_digest !== null) {
      digest(value.result_digest,
        "evaluated repository dispatch result digest");
    }
    digest(value.evidence_digest,
      "evaluated repository dispatch evidence digest");
    return value;
  }
  if (relation !== "scheduled-pull-request") {
    if (value !== null) throw new Error("non-scheduled scope cannot carry inventory");
    return null;
  }
  assertObject(value, "evaluated scope inventory receipt");
  if (value.schema_version === 2) {
    exactKeys(value, [
      "schema_version", "candidate_authority_digest",
      "candidate_dispatch_authority_digest", "candidate_source",
      "dispatch_generation_id", "dispatch_cycle_id",
      "dispatch_reservation_record_oid", "dispatch_reservation_digest",
      "dispatch_digest", "dispatch_batch_index", "dispatch_batch_count",
      "dispatch_candidate_index", "selected_candidate",
      "selected_pull_request_number", "selected_pull_request_node_id",
      "inventory_digest",
    ], "evaluated current-open scope inventory receipt");
    digest(value.candidate_authority_digest,
      "evaluated scope inventory candidate_authority_digest");
    digest(value.candidate_dispatch_authority_digest,
      "evaluated scope inventory candidate_dispatch_authority_digest");
    const candidateSource = normalizeCandidateDispatchSourceBinding(
      value.candidate_source,
    );
    if (!CANDIDATE_DISPATCH_GENERATION_ID.test(value.dispatch_generation_id) ||
        !CANDIDATE_CYCLE_ID.test(value.dispatch_cycle_id)) {
      throw new Error("scheduled inventory dispatch generation is invalid");
    }
    sha(value.dispatch_reservation_record_oid,
      "evaluated scope inventory dispatch_reservation_record_oid");
    digest(value.dispatch_reservation_digest,
      "evaluated scope inventory dispatch_reservation_digest");
    digest(value.dispatch_digest,
      "evaluated scope inventory dispatch_digest");
    nonnegativeInteger(value.dispatch_batch_index,
      "evaluated scope inventory dispatch_batch_index");
    positiveInteger(value.dispatch_batch_count,
      "evaluated scope inventory dispatch_batch_count");
    nonnegativeInteger(value.dispatch_candidate_index,
      "evaluated scope inventory dispatch_candidate_index");
    const candidate = normalizeCandidateDispatchSelection(
      value.selected_candidate,
      "evaluated scope inventory selected_candidate",
    );
    if (
      candidate.schema_version !== 2 ||
      candidate.source_generation_record_oid !==
        candidateSource.source_generation_record_oid ||
      positiveInteger(value.selected_pull_request_number,
        "evaluated scope inventory selected_pull_request_number") !==
        scope.pull_request.number ||
      value.selected_pull_request_node_id !== scope.pull_request.node_id ||
      candidateDispatchNumber(candidate) !== scope.pull_request.number ||
      candidateDispatchNodeId(candidate) !== scope.pull_request.node_id ||
      candidateDispatchHeadOid(candidate) !== scope.head_ref_oid ||
      candidateDispatchBaseOid(candidate) !== scope.base_ref_oid
    ) {
      throw new Error("scheduled inventory selected another pull request");
    }
    boundedString(value.selected_pull_request_node_id,
      "evaluated scope inventory selected_pull_request_node_id", 256);
    digest(value.inventory_digest,
      "evaluated scope inventory inventory_digest");
    return {
      ...value,
      candidate_source: candidateSource,
      selected_candidate: candidate,
    };
  }
  exactKeys(value, [
    "candidate_authority_digest", "candidate_dispatch_authority_digest",
    "completed_cycle_record_oid", "cycle_receipt_digest",
    "dispatch_generation_id", "dispatch_cycle_id",
    "dispatch_reservation_record_oid", "dispatch_reservation_digest",
    "dispatch_digest", "dispatch_batch_index", "dispatch_batch_count",
    "dispatch_candidate_index", "selected_candidate",
    "selected_pull_request_number", "selected_pull_request_node_id",
    "selected_observation_raw_body_sha256", "server_time", "inventory_digest",
  ], "evaluated scope inventory receipt");
  digest(value.candidate_authority_digest,
    "evaluated scope inventory candidate_authority_digest");
  digest(value.candidate_dispatch_authority_digest,
    "evaluated scope inventory candidate_dispatch_authority_digest");
  sha(value.completed_cycle_record_oid,
    "evaluated scope inventory completed_cycle_record_oid");
  digest(value.cycle_receipt_digest,
    "evaluated scope inventory cycle_receipt_digest");
  if (!CANDIDATE_DISPATCH_GENERATION_ID.test(value.dispatch_generation_id) ||
      !CANDIDATE_CYCLE_ID.test(value.dispatch_cycle_id)) {
    throw new Error("scheduled inventory dispatch generation is invalid");
  }
  sha(value.dispatch_reservation_record_oid,
    "evaluated scope inventory dispatch_reservation_record_oid");
  digest(value.dispatch_reservation_digest,
    "evaluated scope inventory dispatch_reservation_digest");
  digest(value.dispatch_digest,
    "evaluated scope inventory dispatch_digest");
  nonnegativeInteger(value.dispatch_batch_index,
    "evaluated scope inventory dispatch_batch_index");
  positiveInteger(value.dispatch_batch_count,
    "evaluated scope inventory dispatch_batch_count");
  nonnegativeInteger(value.dispatch_candidate_index,
    "evaluated scope inventory dispatch_candidate_index");
  const candidate = normalizeCandidateInventoryIdentity(
    value.selected_candidate,
  );
  if (
    positiveInteger(value.selected_pull_request_number,
      "evaluated scope inventory selected_pull_request_number") !==
      scope.pull_request.number ||
    value.selected_pull_request_node_id !== scope.pull_request.node_id ||
    candidate.number !== scope.pull_request.number ||
    candidate.node_id !== scope.pull_request.node_id
  ) {
    throw new Error("scheduled inventory selected another pull request");
  }
  boundedString(value.selected_pull_request_node_id,
    "evaluated scope inventory selected_pull_request_node_id", 256);
  digest(value.selected_observation_raw_body_sha256,
    "evaluated scope inventory selected observation raw digest");
  timestamp(value.server_time, "evaluated scope inventory server_time");
  digest(value.inventory_digest, "evaluated scope inventory inventory_digest");
  return value;
}

function normalizeEvaluatedScopeEndpointReceipt(
  value,
  relation,
  repository,
  scope,
) {
  if (new Set([
    "scheduled-repository-inventory",
    "scheduled-repository-dispatch",
  ]).has(relation)) {
    return normalizeRepositoryEndpointReceipt(value, repository);
  }
  assertObject(value, "evaluated scope endpoint receipt");
  exactKeys(value, [
    "method", "path", "status", "server_time", "raw_body_sha256",
    "pull_request", "head_ref_oid", "base_ref_oid",
    "potential_merge_commit_oid",
  ], "evaluated scope endpoint receipt");
  if (
    value.method !== "GET" || value.status !== 200 ||
    value.path !== `/repos/${repository.owner}/${repository.name}/pulls/` +
      scope.pull_request.number ||
    canonicalJson(normalizePullRequest(value.pull_request)) !==
      canonicalJson(scope.pull_request) ||
    sha(value.head_ref_oid, "evaluated scope endpoint head_ref_oid") !==
      scope.head_ref_oid ||
    sha(value.base_ref_oid, "evaluated scope endpoint base_ref_oid") !==
      scope.base_ref_oid ||
    nullableSha(value.potential_merge_commit_oid,
      "evaluated scope endpoint potential_merge_commit_oid") !==
      scope.potential_merge_commit_oid
  ) {
    throw new Error("live PR endpoint receipt differs from evaluated scope");
  }
  timestamp(value.server_time, "evaluated scope endpoint server_time");
  digest(value.raw_body_sha256, "evaluated scope endpoint raw_body_sha256");
  return value;
}

function provenanceMatchesExpected(provenance, expected) {
  if (expected.provenance_policy === undefined) return true;
  try {
    const {
      protection_receipt_digest: protectionDigest,
      ...policy
    } = expected.provenance_policy;
    validateV2GitLedgerProvenanceReceipt(provenance, {
      policy,
    });
    return canonicalJson(provenance.operation_binding.repository) ===
      canonicalJson(expected.repository) &&
      provenance.operation_binding.ledger_ref === expected.ledger_ref &&
      canonicalJson(provenance.operation_binding.source_workflow) ===
        canonicalJson(expected.source_workflow) &&
      provenance.operation_binding.protection_receipt_digest ===
        protectionDigest;
  } catch {
    return false;
  }
}

function normalizeUniqueStringArray(value, label) {
  if (!Array.isArray(value) || value.length === 0 || value.length > 256) {
    throw new TypeError(`${label} must be a non-empty bounded array`);
  }
  const strings = value.map((item, index) =>
    boundedString(item, `${label}[${index}]`, 128));
  if (new Set(strings).size !== strings.length ||
      canonicalJson(strings) !== canonicalJson([...strings].sort())) {
    throw new Error(`${label} must be unique and lexically sorted`);
  }
  return strings;
}

function normalizeUniqueDecimalArray(value, label) {
  if (!Array.isArray(value) || value.length === 0 || value.length > 256) {
    throw new TypeError(`${label} must be a non-empty bounded array`);
  }
  const decimals = value.map((item, index) =>
    decimal(item, `${label}[${index}]`));
  const sorted = [...decimals].sort((left, right) =>
    BigInt(left) < BigInt(right) ? -1 : BigInt(left) > BigInt(right) ? 1 : 0);
  if (new Set(decimals).size !== decimals.length ||
      canonicalJson(decimals) !== canonicalJson(sorted)) {
    throw new Error(`${label} must be unique and numerically sorted`);
  }
  return decimals;
}

function normalizeRepository(value) {
  assertObject(value, "repository");
  exactKeys(value, ["owner", "name", "id", "node_id", "owner_id"], "repository");
  const part = /^[A-Za-z0-9_.-]{1,100}$/u;
  if (!part.test(value.owner) || !part.test(value.name)) {
    throw new TypeError("repository owner and name are not canonical GitHub parts");
  }
  return {
    owner: value.owner,
    name: value.name,
    id: decimal(value.id, "repository.id"),
    node_id: boundedString(value.node_id, "repository.node_id", 256),
    owner_id: decimal(value.owner_id, "repository.owner_id"),
  };
}

function normalizeAutomaticReviewRequestRepository(value) {
  assertObject(value, "automatic review request repository");
  exactKeys(value, ["owner", "name", "node_id"],
    "automatic review request repository");
  const part = /^[A-Za-z0-9_.-]{1,100}$/u;
  if (!part.test(value.owner) || !part.test(value.name)) {
    throw new TypeError("automatic review request repository is not canonical");
  }
  return {
    owner: value.owner,
    name: value.name,
    node_id: boundedString(
      value.node_id,
      "automatic review request repository.node_id",
      256,
    ),
  };
}

function candidateRepository(value) {
  const repository = normalizeRepository(value);
  return normalizeCandidateRepository({
    owner: repository.owner,
    name: repository.name,
    id: repository.id,
    node_id: repository.node_id,
  });
}

function normalizeCandidateRepository(value) {
  assertObject(value, "candidate inventory repository");
  exactKeys(value, ["owner", "name", "id", "node_id"],
    "candidate inventory repository");
  const part = /^[A-Za-z0-9_.-]{1,100}$/u;
  if (!part.test(value.owner) || !part.test(value.name)) {
    throw new TypeError("candidate inventory repository is invalid");
  }
  return {
    owner: value.owner,
    name: value.name,
    id: decimal(value.id, "candidate inventory repository.id"),
    node_id: boundedString(
      value.node_id,
      "candidate inventory repository.node_id",
      256,
    ),
  };
}

function normalizeCandidateInventoryIdentity(value) {
  assertObject(value, "candidate inventory identity");
  exactKeys(value, ["id", "node_id", "number", "created_at"],
    "candidate inventory identity");
  return {
    id: decimal(value.id, "candidate inventory identity.id"),
    node_id: boundedString(
      value.node_id,
      "candidate inventory identity.node_id",
      256,
    ),
    number: positiveInteger(
      value.number,
      "candidate inventory identity.number",
    ),
    created_at: timestamp(
      value.created_at,
      "candidate inventory identity.created_at",
    ),
  };
}

function normalizeRepositoryEndpointReceipt(value, repository) {
  assertObject(value, "repository_endpoint_receipt");
  exactKeys(value, [
    "method", "path", "status", "server_time", "raw_body_sha256",
  ], "repository_endpoint_receipt");
  const expectedPath = `/repos/${repository.owner}/${repository.name}`;
  if (
    value.method !== "GET" || value.path !== expectedPath ||
    value.status !== 200
  ) {
    throw new Error(
      "repository endpoint receipt does not bind the exact repository GET",
    );
  }
  timestamp(value.server_time, "repository_endpoint_receipt.server_time");
  digest(value.raw_body_sha256,
    "repository_endpoint_receipt.raw_body_sha256");
  return deepFreeze(structuredClone(value));
}

function normalizeLedgerRulesetReceipt(value, repository, ledgerRef) {
  assertObject(value, "capabilityReceipt.ruleset_receipt");
  exactKeys(value, [
    "receipt_digest", "configuration_digest", "protection_digest",
    "repository_id", "ledger_ref", "ruleset_ids",
    "target_includes_exact_ref", "deletion_blocked",
    "non_fast_forward_blocked", "force_pushes_blocked",
    "bypass_actors_empty",
  ], "capabilityReceipt.ruleset_receipt");
  digest(value.receipt_digest, "ruleset_receipt.receipt_digest");
  digest(value.configuration_digest, "ruleset_receipt.configuration_digest");
  digest(value.protection_digest, "ruleset_receipt.protection_digest");
  const rulesetIds = normalizeUniqueDecimalArray(
    value.ruleset_ids,
    "ruleset_receipt.ruleset_ids",
  );
  if (
    decimal(value.repository_id, "ruleset_receipt.repository_id") !==
      repository.id ||
    value.ledger_ref !== ledgerRef ||
    value.target_includes_exact_ref !== true ||
    value.deletion_blocked !== true ||
    value.non_fast_forward_blocked !== true ||
    value.force_pushes_blocked !== true ||
    value.bypass_actors_empty !== true
  ) {
    throw new Error(
      "Git ledger ruleset receipt does not exact-protect the dedicated ledger ref",
    );
  }
  return deepFreeze({
    ...structuredClone(value),
    ruleset_ids: rulesetIds,
  });
}

function normalizeLedgerProtectionReceipt(value, ruleset) {
  assertObject(value, "capabilityReceipt.protection_receipt");
  exactKeys(value, [
    "receipt_digest",
    "protection_digest",
    "ruleset_receipt_digest",
    "deletion_blocked",
    "non_fast_forward_blocked",
    "source_workflow_pinned",
  ], "capabilityReceipt.protection_receipt");
  digest(value.receipt_digest, "protection_receipt.receipt_digest");
  digest(value.protection_digest, "protection_receipt.protection_digest");
  if (
    value.ruleset_receipt_digest !== ruleset.receipt_digest ||
    value.protection_digest !== ruleset.protection_digest ||
    value.deletion_blocked !== true ||
    value.non_fast_forward_blocked !== true ||
    value.source_workflow_pinned !== true
  ) {
    throw new Error("Git ledger protection receipt is incomplete or mismatched");
  }
  return deepFreeze(structuredClone(value));
}

function normalizeControllerRelease(value) {
  assertObject(value, "controller_release");
  exactKeys(value, [
    "repository", "release_sha", "workflow_path", "workflow_ref",
    "workflow_sha", "job_workflow_ref", "job_workflow_sha",
    "caller_workflow_file_receipt_digest",
    "job_workflow_file_receipt_digest", "release_receipt_digest", "current",
  ], "controller_release");
  assertObject(value.repository, "controller_release.repository");
  exactKeys(value.repository, ["owner", "name", "id"], "controller_release.repository");
  const part = /^[A-Za-z0-9_.-]{1,100}$/u;
  if (!part.test(value.repository.owner) || !part.test(value.repository.name)) {
    throw new TypeError("controller release repository is invalid");
  }
  if (value.current !== true) throw new Error("controller release is not current");
  const normalized = {
    repository: {
      owner: value.repository.owner,
      name: value.repository.name,
      id: decimal(value.repository.id, "controller_release.repository.id"),
    },
    release_sha: sha(value.release_sha, "controller_release.release_sha"),
    workflow_path: boundedString(value.workflow_path, "controller_release.workflow_path", 512),
    workflow_ref: callerWorkflowRef(
      value.workflow_ref,
      "controller_release.workflow_ref",
    ),
    workflow_sha: sha(value.workflow_sha, "controller_release.workflow_sha"),
    job_workflow_ref: jobWorkflowRef(
      value.job_workflow_ref,
      "controller_release.job_workflow_ref",
    ),
    job_workflow_sha: sha(
      value.job_workflow_sha,
      "controller_release.job_workflow_sha",
    ),
    caller_workflow_file_receipt_digest: digest(
      value.caller_workflow_file_receipt_digest,
      "controller_release.caller_workflow_file_receipt_digest",
    ),
    job_workflow_file_receipt_digest: digest(
      value.job_workflow_file_receipt_digest,
      "controller_release.job_workflow_file_receipt_digest",
    ),
    release_receipt_digest: digest(
      value.release_receipt_digest,
      "controller_release.release_receipt_digest",
    ),
    current: true,
  };
  validateCalledWorkflowIdentity(normalized, "controller_release");
  if (normalized.release_sha !== normalized.job_workflow_sha) {
    throw new Error(
      "controller release SHA does not equal the reusable workflow SHA",
    );
  }
  return normalized;
}

function sourceWorkflow(release) {
  return {
    repository: structuredClone(release.repository),
    workflow_path: release.workflow_path,
    workflow_ref: release.workflow_ref,
    workflow_sha: release.workflow_sha,
    job_workflow_ref: release.job_workflow_ref,
    job_workflow_sha: release.job_workflow_sha,
    caller_workflow_file_receipt_digest:
      release.caller_workflow_file_receipt_digest,
    job_workflow_file_receipt_digest:
      release.job_workflow_file_receipt_digest,
    release_receipt_digest: release.release_receipt_digest,
  };
}

function normalizeSourceWorkflow(value, label) {
  assertObject(value, label);
  exactKeys(value, [
    "repository", "workflow_path", "workflow_ref", "workflow_sha",
    "job_workflow_ref", "job_workflow_sha",
    "caller_workflow_file_receipt_digest",
    "job_workflow_file_receipt_digest", "release_receipt_digest",
  ], label);
  assertObject(value.repository, `${label}.repository`);
  exactKeys(value.repository, ["owner", "name", "id"], `${label}.repository`);
  const part = /^[A-Za-z0-9_.-]{1,100}$/u;
  if (!part.test(value.repository.owner) || !part.test(value.repository.name)) {
    throw new TypeError(`${label}.repository is invalid`);
  }
  const normalized = {
    repository: {
      owner: value.repository.owner,
      name: value.repository.name,
      id: decimal(value.repository.id, `${label}.repository.id`),
    },
    workflow_path: boundedString(value.workflow_path, `${label}.workflow_path`, 512),
    workflow_ref: callerWorkflowRef(value.workflow_ref, `${label}.workflow_ref`),
    workflow_sha: sha(value.workflow_sha, `${label}.workflow_sha`),
    job_workflow_ref: jobWorkflowRef(
      value.job_workflow_ref,
      `${label}.job_workflow_ref`,
    ),
    job_workflow_sha: sha(value.job_workflow_sha, `${label}.job_workflow_sha`),
    caller_workflow_file_receipt_digest: digest(
      value.caller_workflow_file_receipt_digest,
      `${label}.caller_workflow_file_receipt_digest`,
    ),
    job_workflow_file_receipt_digest: digest(
      value.job_workflow_file_receipt_digest,
      `${label}.job_workflow_file_receipt_digest`,
    ),
    release_receipt_digest: digest(
      value.release_receipt_digest,
      `${label}.release_receipt_digest`,
    ),
  };
  validateCalledWorkflowIdentity(normalized, label);
  return normalized;
}

function callerWorkflowRef(value, label) {
  const ref = boundedString(value, label, 1024);
  if (!ref.includes("/.github/workflows/") || !ref.includes("@refs/")) {
    throw new TypeError(`${label} must be a GitHub workflow @refs/ shape`);
  }
  return ref;
}

function jobWorkflowRef(value, label) {
  const ref = boundedString(value, label, 1024);
  if (!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/\.github\/workflows\/[A-Za-z0-9_.\/-]+@[0-9a-f]{40}$/u
    .test(ref)) {
    throw new TypeError(`${label} must be a reusable workflow exact-SHA ref`);
  }
  return ref;
}

function validateCalledWorkflowIdentity(value, label) {
  if (!value.workflow_path.startsWith(".github/workflows/") ||
      value.workflow_path.includes("..")) {
    throw new TypeError(`${label}.workflow_path is not canonical`);
  }
  const expected = `${value.repository.owner}/${value.repository.name}/` +
    `${value.workflow_path}@${value.job_workflow_sha}`;
  if (value.job_workflow_ref !== expected) {
    throw new Error(`${label} does not bind the reusable workflow repository/path`);
  }
}

function normalizePullRequest(value) {
  assertObject(value, "pull_request");
  exactKeys(value, ["number", "node_id"], "pull_request");
  return {
    number: positiveInteger(value.number, "pull_request.number"),
    node_id: boundedString(value.node_id, "pull_request.node_id", 256),
  };
}

function normalizeLeaseOwner(value) {
  assertObject(value, "lease owner");
  exactKeys(value, ["run_id", "run_attempt", "actor_id"], "lease owner");
  return {
    run_id: decimal(value.run_id, "lease owner.run_id"),
    run_attempt: positiveInteger(value.run_attempt, "lease owner.run_attempt"),
    actor_id: decimal(value.actor_id, "lease owner.actor_id"),
  };
}

function normalizeLeaseBinding(value, { required = false } = {}) {
  if (value === null) {
    if (required) throw new Error("active lease binding is required");
    return null;
  }
  assertObject(value, "lease binding");
  exactKeys(value, [
    "lease_id", "owner", "acquire_commit_sha", "expires_at",
  ], "lease binding");
  return {
    lease_id: boundedString(value.lease_id, "lease binding.lease_id", 256),
    owner: normalizeLeaseOwner(value.owner),
    acquire_commit_sha: sha(value.acquire_commit_sha,
      "lease binding.acquire_commit_sha"),
    expires_at: timestamp(value.expires_at, "lease binding.expires_at"),
  };
}

function normalizeControlCommentBinding(value, { required = false } = {}) {
  if (value === null) {
    if (required) throw new Error("effect record requires a control comment binding");
    return null;
  }
  assertObject(value, "control_comment_binding");
  exactKeys(value, [
    "comment_id", "comment_node_id", "raw_body_sha256",
  ], "control_comment_binding");
  return {
    comment_id: decimal(value.comment_id, "control_comment_binding.comment_id"),
    comment_node_id: boundedString(
      value.comment_node_id,
      "control_comment_binding.comment_node_id",
      256,
    ),
    raw_body_sha256: digest(
      value.raw_body_sha256,
      "control_comment_binding.raw_body_sha256",
    ),
  };
}

function normalizeCarrierSelector(value, label) {
  assertObject(value, label);
  exactKeys(value, ["kind", "id"], label);
  if (!new Set(["issue_comment", "pull_request_review", "inline_comment"])
    .has(value.kind)) {
    throw new TypeError(`${label}.kind is unsupported`);
  }
  decimal(value.id, `${label}.id`);
  return value;
}

function validateExternalActor(value, label) {
  assertObject(value, label);
  exactKeys(value, ["id", "node_id", "login", "type"], label);
  decimal(value.id, `${label}.id`);
  boundedString(value.node_id, `${label}.node_id`, 256);
  boundedString(value.login, `${label}.login`, 128);
  boundedString(value.type, `${label}.type`, 64);
}

function validateExternalApp(value, label) {
  assertObject(value, label);
  exactKeys(value, ["id", "node_id", "slug"], label);
  decimal(value.id, `${label}.id`);
  boundedString(value.node_id, `${label}.node_id`, 256);
  boundedString(value.slug, `${label}.slug`, 128);
}

function validateCodexProvider(actor, app, label) {
  if (
    actor.login !== "chatgpt-codex-connector[bot]" ||
    actor.type !== "Bot" || app.slug !== "chatgpt-codex-connector"
  ) {
    throw new Error(`${label} is not the exact GitHub Codex provider`);
  }
}

function githubUrl(value, label) {
  const text = boundedString(value, label, 2048);
  let parsed;
  try {
    parsed = new URL(text);
  } catch {
    throw new TypeError(`${label} must be an exact github.com URL`);
  }
  if (
    parsed.protocol !== "https:" || parsed.hostname !== "github.com" ||
    parsed.username !== "" || parsed.password !== ""
  ) {
    throw new TypeError(`${label} must be an exact github.com URL`);
  }
  return text;
}

function normalizeLedgerRef(value) {
  if (value !== V2_GIT_LEDGER_REF) {
    throw new Error(`Git ledger ref must be exactly ${V2_GIT_LEDGER_REF}`);
  }
  return value;
}

function normalizeRestBase(value) {
  let url;
  try {
    url = new URL(value);
  } catch (error) {
    throw new TypeError("restBaseUrl must be an absolute HTTPS URL", { cause: error });
  }
  if (
    url.protocol !== "https:" || url.username !== "" || url.password !== "" ||
    url.search !== "" || url.hash !== ""
  ) {
    throw new TypeError("restBaseUrl must be a credential-free HTTPS URL");
  }
  return url.href.replace(/\/$/u, "");
}

function normalizeRaceAttestationResult(value) {
  return {
    label: value.label,
    commit_sha: value.commit_sha,
    outcome: value.outcome,
    http_status: value.http_status,
    server_time: value.server_time,
    raw_body_sha256: value.raw_body_sha256,
  };
}

function validateRecordLease(record, active) {
  const lease = normalizeLeaseBinding(record.lease, { required: true });
  if (
    lease.lease_id !== active.lease_id ||
    lease.acquire_commit_sha !== active.acquire_commit_sha ||
    lease.expires_at !== active.expires_at ||
    canonicalJson(lease.owner) !== canonicalJson(active.owner)
  ) {
    throw ledgerError("lease-binding", "record does not bind the active controller lease");
  }
}

function validateEnvelopeLease(envelope, active) {
  validateRecordLease(envelope, active);
}

function leaseBindingFromReceipt(receipt) {
  return {
    lease_id: receipt.lease_id,
    owner: structuredClone(receipt.owner),
    acquire_commit_sha: receipt.acquire_commit_sha,
    expires_at: receipt.expires_at,
  };
}

function leaseBindingFromValue(value) {
  assertObject(value, "effect builder lease receipt");
  const candidate = {
    lease_id: value.lease_id,
    owner: value.owner,
    acquire_commit_sha: value.acquire_commit_sha,
    expires_at: value.expires_at,
  };
  return normalizeLeaseBinding(candidate, { required: true });
}

function envelopeScope(envelope) {
  if (REPOSITORY_RECORD_TYPES.has(envelope.record_type)) return null;
  return {
    pull_request: envelope.pull_request,
    head_ref_oid: envelope.head_ref_oid,
    base_ref_oid: envelope.base_ref_oid,
    potential_merge_commit_oid: envelope.potential_merge_commit_oid,
  };
}

function recordScope(record) {
  if (REPOSITORY_RECORD_TYPES.has(record.record_type)) return null;
  return {
    pull_request: record.pull_request,
    head_ref_oid: record.head_ref_oid,
    base_ref_oid: record.base_ref_oid,
    potential_merge_commit_oid: record.potential_merge_commit_oid,
  };
}

function productionRecordIdentity(record) {
  return {
    record_type: record.record_type,
    kind: record.kind,
    effect_id: record.effect_id,
    idempotency_key: record.idempotency_key,
    // Authoritative GitHub Date normalization may rewrite timestamp-bearing
    // payload fields after the caller record was sealed. Bind the OIDC request
    // to the bytes that will actually be committed, never to the caller's
    // superseded payload digest.
    payload_digest: digestV2GitLedgerPayload(record.payload),
  };
}

function normalizeProvenanceRecordIdentity(value) {
  if (value === null) return null;
  assertObject(value, "workflow provenance record_identity");
  exactKeys(value, [
    "record_type", "kind", "effect_id", "idempotency_key", "payload_digest",
  ], "workflow provenance record_identity");
  if (
    !RECORD_TYPES.has(value.record_type) &&
    value.record_type !== "epoch-checkpoint"
  ) {
    throw new TypeError("workflow provenance record type is not production");
  }
  const effect = new Set(["effect-intent", "effect-response"])
    .has(value.record_type);
  if (effect) {
    if (!EFFECT_KINDS.has(value.kind)) {
      throw new TypeError("workflow provenance effect kind is unsupported");
    }
    boundedString(value.effect_id, "workflow provenance effect_id", 256);
    boundedString(
      value.idempotency_key,
      "workflow provenance idempotency_key",
      256,
    );
  } else if (
    value.kind !== null || value.effect_id !== null ||
    value.idempotency_key !== null
  ) {
    throw new TypeError("workflow provenance lease identity has effect fields");
  }
  digest(value.payload_digest, "workflow provenance payload_digest");
  return value;
}

function reviewEpochDigest(scope) {
  return digestCanonical("codex-review-gate-v2-review-epoch", {
    pull_request: scope.pull_request,
    base_ref_oid: scope.base_ref_oid,
    head_ref_oid: scope.head_ref_oid,
    potential_merge_commit_oid: scope.potential_merge_commit_oid,
  });
}

function normalizeEffectScope(value) {
  if (value === null) return null;
  assertObject(value, "workflow provenance effect_scope");
  exactKeys(value, [
    "pull_request",
    "head_ref_oid",
    "base_ref_oid",
    "potential_merge_commit_oid",
  ], "workflow provenance effect_scope");
  return {
    pull_request: normalizePullRequest(value.pull_request),
    head_ref_oid: sha(
      value.head_ref_oid,
      "workflow provenance effect_scope.head_ref_oid",
    ),
    base_ref_oid: sha(
      value.base_ref_oid,
      "workflow provenance effect_scope.base_ref_oid",
    ),
    potential_merge_commit_oid: nullableSha(
      value.potential_merge_commit_oid,
      "workflow provenance effect_scope.potential_merge_commit_oid",
    ),
  };
}

function requireSameScope(actual, expected, label) {
  if (canonicalJson(actual) !== canonicalJson(expected)) {
    throw ledgerError("scope-mismatch", `${label} does not bind the active lease scope`);
  }
}

function sealAppendReceipt(value) {
  const withoutDigest = {
    schema: V2_GIT_LEDGER_APPEND_RECEIPT_SCHEMA,
    schema_version: 1,
    ...value,
  };
  return deepFreeze({
    ...withoutDigest,
    receipt_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-append-receipt",
      withoutDigest,
    ),
  });
}

function sealBootstrapReceipt(value) {
  const withoutDigest = {
    schema: V2_GIT_LEDGER_BOOTSTRAP_RECEIPT_SCHEMA,
    schema_version: 1,
    ...value,
  };
  return deepFreeze({
    ...withoutDigest,
    receipt_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-bootstrap-receipt",
      withoutDigest,
    ),
  });
}

function sealWriteObservationReceipt(value) {
  const withoutDigest = {
    schema: V2_GIT_LEDGER_WRITE_OBSERVATION_SCHEMA,
    schema_version: 1,
    ...structuredClone(value),
  };
  return validateWriteObservationReceipt({
    ...withoutDigest,
    receipt_digest: digestCanonical(
      "codex-review-gate-v2-git-ledger-write-observation",
      withoutDigest,
    ),
  });
}

function validateWriteObservationReceipt(value) {
  assertObject(value, "write observation receipt");
  exactKeys(value, [
    "schema", "schema_version", "bootstrap_candidate_digest", "genesis",
    "race_parent_commit_sha", "contenders", "race_results",
    "winner_commit_sha", "race_final_ref_reread", "receipt_digest",
  ], "write observation receipt");
  if (
    value.schema !== V2_GIT_LEDGER_WRITE_OBSERVATION_SCHEMA ||
    value.schema_version !== 1
  ) {
    throw new Error("write observation receipt schema is unsupported");
  }
  digest(value.bootstrap_candidate_digest,
    "write observation bootstrap_candidate_digest");
  if (value.genesis !== null) validateGenesisWriteObservation(value.genesis);
  sha(value.race_parent_commit_sha,
    "write observation race_parent_commit_sha");
  if (!Array.isArray(value.contenders) || value.contenders.length !== 2) {
    throw new Error("write observation requires two contender object writes");
  }
  const contenderByLabel = new Map();
  for (const contender of value.contenders) {
    assertObject(contender, "write observation contender");
    exactKeys(contender, [
      "label", "commit_sha", "tree_sha", "blob_sha",
      "object_write_receipts",
    ], "write observation contender");
    if (!new Set(["alpha", "beta"]).has(contender.label) ||
        contenderByLabel.has(contender.label)) {
      throw new Error("write observation contender labels are invalid");
    }
    validateObjectWriteReceipts(contender);
    contenderByLabel.set(contender.label, contender);
  }
  if (!Array.isArray(value.race_results) || value.race_results.length !== 2) {
    throw new Error("write observation requires two race results");
  }
  const winners = [];
  const losers = [];
  for (const result of value.race_results) {
    validateRaceResultReceipt(result);
    const contender = contenderByLabel.get(result.label);
    if (contender?.commit_sha !== result.commit_sha) {
      throw new Error("write observation race result differs from object write");
    }
    (result.outcome === "winner" ? winners : losers).push(result);
  }
  if (
    winners.length !== 1 || losers.length !== 1 ||
    sha(value.winner_commit_sha, "write observation winner_commit_sha") !==
      winners[0].commit_sha
  ) {
    throw new Error("write observation lacks one winner and one loser");
  }
  validateRefReceipt(value.race_final_ref_reread);
  if (value.race_final_ref_reread.target_commit_sha !== value.winner_commit_sha) {
    throw new Error("write observation ref reread differs from its winner");
  }
  digest(value.receipt_digest, "write observation receipt_digest");
  const { receipt_digest: _receiptDigest, ...withoutDigest } = value;
  if (digestCanonical("codex-review-gate-v2-git-ledger-write-observation",
    withoutDigest) !== value.receipt_digest) {
    throw new Error("write observation receipt digest is invalid");
  }
  return deepFreeze(structuredClone(value));
}

function validateRaceResultReceipt(value) {
  assertObject(value, "write observation race result");
  exactKeys(value, [
    "label", "commit_sha", "outcome", "http_status", "server_time",
    "raw_body_sha256",
  ], "write observation race result");
  if (!new Set(["alpha", "beta"]).has(value.label)) {
    throw new Error("write observation race label is invalid");
  }
  sha(value.commit_sha, "write observation race commit_sha");
  if (
    (value.outcome === "winner" && value.http_status !== 200) ||
    (value.outcome === "non-fast-forward" &&
      !CONFLICT_PROFILES.has(value.http_status)) ||
    !new Set(["winner", "non-fast-forward"]).has(value.outcome)
  ) {
    throw new Error("write observation race outcome is invalid");
  }
  timestamp(value.server_time, "write observation race server_time");
  digest(value.raw_body_sha256, "write observation race raw_body_sha256");
}

function validateGenesisWriteObservation(value) {
  assertObject(value, "genesis write observation");
  exactKeys(value, [
    "commit_sha", "tree_sha", "blob_sha", "object_write_receipts",
    "ref_create", "ref_reread",
  ], "genesis write observation");
  validateObjectWriteReceipts(value);
  validateCaptureReceipt(value.ref_create, "genesis ref create");
  if (value.ref_create.http_status !== 201) {
    throw new Error("genesis ref create was not successful");
  }
  validateRefReceipt(value.ref_reread);
  if (value.ref_reread.target_commit_sha !== value.commit_sha) {
    throw new Error("genesis ref reread differs from its commit");
  }
}

function validateObjectWriteReceipts(value) {
  const objectShas = {
    blob: sha(value.blob_sha, "object write blob_sha"),
    tree: sha(value.tree_sha, "object write tree_sha"),
    commit: sha(value.commit_sha, "object write commit_sha"),
  };
  assertObject(value.object_write_receipts, "object write receipts");
  exactKeys(value.object_write_receipts, ["blob", "tree", "commit"],
    "object write receipts");
  for (const [kind, receipt] of Object.entries(value.object_write_receipts)) {
    assertObject(receipt, `${kind} object write receipt`);
    exactKeys(receipt, [
      "object_sha", "http_status", "server_time", "raw_body_sha256",
    ], `${kind} object write receipt`);
    if (
      receipt.object_sha !== objectShas[kind] ||
      receipt.http_status !== 201
    ) {
      throw new Error(`${kind} object write receipt is not exact and successful`);
    }
    timestamp(receipt.server_time, `${kind} object write server_time`);
    digest(receipt.raw_body_sha256, `${kind} object write raw_body_sha256`);
  }
}

function validateCaptureReceipt(value, label) {
  assertObject(value, label);
  exactKeys(value, ["http_status", "server_time", "raw_body_sha256"], label);
  positiveInteger(value.http_status, `${label}.http_status`);
  timestamp(value.server_time, `${label}.server_time`);
  digest(value.raw_body_sha256, `${label}.raw_body_sha256`);
}

function captureReceipt(capture) {
  return {
    http_status: capture.http_status,
    server_time: capture.server_time,
    raw_body_sha256: rawDigest(capture.raw_body_bytes),
  };
}

function refReceipt(value) {
  return {
    ref: value.ref,
    node_id: value.node_id,
    target_commit_sha: value.target_commit_sha,
    server_time: value.server_time,
    raw_body_sha256: value.raw_body_sha256,
  };
}

function validateRefReceipt(value) {
  assertObject(value, "ref receipt");
  exactKeys(value, [
    "ref", "node_id", "target_commit_sha", "server_time", "raw_body_sha256",
  ], "ref receipt");
  normalizeLedgerRef(value.ref);
  boundedString(value.node_id, "ref receipt.node_id", 256);
  sha(value.target_commit_sha, "ref receipt.target_commit_sha");
  timestamp(value.server_time, "ref receipt.server_time");
  digest(value.raw_body_sha256, "ref receipt.raw_body_sha256");
}

function responseSha(value, label) {
  assertObject(value, label);
  return sha(value.sha, `${label}.sha`);
}

function validateCommitIdentity({ commit, commitSha, treeSha, parents, envelope }) {
  assertObject(commit.author, "Git ledger commit.author");
  assertObject(commit.committer, "Git ledger commit.committer");
  const identity = {
    name: COMMIT_AUTHOR.name,
    email: COMMIT_AUTHOR.email,
    date: envelope.server_observed_at,
  };
  for (const [label, value] of [
    ["author", commit.author],
    ["committer", commit.committer],
  ]) {
    if (
      value.name !== identity.name || value.email !== identity.email ||
      timestamp(value.date, `Git ledger commit.${label}.date`) !== identity.date
    ) {
      throw ledgerError(
        "commit-identity",
        `Git ledger commit ${label} differs from the canonical identity`,
      );
    }
  }
  const bytes = canonicalGitCommitBytes({
    treeSha,
    parents,
    message: commitMessage(envelope),
    serverTime: envelope.server_observed_at,
  });
  if (gitObjectSha("commit", bytes) !== commitSha) {
    throw ledgerError(
      "commit-object-identity",
      "Git ledger commit response fields do not hash to its exact object identity",
    );
  }
}

function gitTimestamp(value) {
  const date = new Date(timestamp(value, "Git commit timestamp"));
  return `${Math.floor(date.getTime() / 1000)} +0000`;
}

function gitObjectSha(type, bytes) {
  const header = Buffer.from(`${type} ${bytes.byteLength}\0`, "utf8");
  return createHash("sha1").update(header).update(bytes).digest("hex");
}

function canonicalGitTreeBytes(entriesValue) {
  if (!Array.isArray(entriesValue) || entriesValue.length === 0) {
    throw new TypeError("Git ledger tree requires one or more entries");
  }
  const seen = new Set();
  const entries = entriesValue.map((entry, index) => {
    assertObject(entry, `Git ledger tree entry ${index}`);
    exactKeys(entry, ["path", "mode", "type", "sha"],
      `Git ledger tree entry ${index}`);
    const path = boundedString(entry.path, `Git ledger tree entry ${index}.path`, 256);
    if (!/^[0-9A-Za-z][0-9A-Za-z._-]*$/u.test(path) || seen.has(path)) {
      throw ledgerError("tree-shape", "Git ledger tree paths are not closed and unique");
    }
    seen.add(path);
    const type = entry.type;
    const mode = entry.mode;
    if (!(
      type === "blob" && mode === "100644" ||
      type === "tree" && mode === "040000"
    )) {
      throw ledgerError("tree-shape", "Git ledger tree entry mode/type is unsupported");
    }
    return {
      path,
      mode,
      type,
      sha: sha(entry.sha, `Git ledger tree entry ${index}.sha`),
    };
  }).sort((left, right) => Buffer.compare(
    Buffer.from(`${left.path}${left.type === "tree" ? "/" : ""}`, "utf8"),
    Buffer.from(`${right.path}${right.type === "tree" ? "/" : ""}`, "utf8"),
  ));
  return Buffer.concat(entries.map((entry) => Buffer.concat([
    Buffer.from(`${entry.mode} ${entry.path}\0`, "utf8"),
    Buffer.from(entry.sha, "hex"),
  ])));
}

function canonicalTreeSha(blobSha) {
  return canonicalGitTreeSha([{
    path: V2_GIT_LEDGER_BLOB_PATH,
    mode: "100644",
    type: "blob",
    sha: blobSha,
  }]);
}

function canonicalGitTreeSha(entries) {
  return gitObjectSha("tree", canonicalGitTreeBytes(entries));
}

function commitMessage(envelope) {
  return `Codex Review Gate v2: ${envelope.record_type} #${envelope.sequence}`;
}

function githubServerTime(value) {
  const text = boundedString(value, "GitHub Date header", 128);
  const parsed = Date.parse(text);
  if (!Number.isFinite(parsed)) {
    throw ledgerError("server-time", "GitHub response lacks a valid Date header");
  }
  return new Date(parsed).toISOString();
}

function timestamp(value, label) {
  if (typeof value !== "string" || !TIMESTAMP.test(value)) {
    throw new TypeError(`${label} must be a canonical UTC timestamp`);
  }
  const parsed = Date.parse(value);
  if (!Number.isFinite(parsed)) throw new TypeError(`${label} is invalid`);
  return new Date(parsed).toISOString();
}

function addSeconds(value, seconds) {
  const at = timestamp(value, "time arithmetic input");
  const duration = positiveInteger(seconds, "time arithmetic seconds");
  return new Date(Date.parse(at) + duration * 1000).toISOString();
}

function sha(value, label) {
  if (typeof value !== "string" || !SHA.test(value)) {
    throw new TypeError(`${label} must be a lowercase full SHA`);
  }
  return value;
}

function nullableSha(value, label) {
  return value === null ? null : sha(value, label);
}

function requireNull(value, label) {
  if (value !== null) throw new TypeError(`${label} must be null`);
  return null;
}

function digest(value, label) {
  if (typeof value !== "string" || !DIGEST.test(value)) {
    throw new TypeError(`${label} must be sha256:<64 lowercase hex>`);
  }
  return value;
}

function decimal(value, label) {
  if (typeof value !== "string" || !DECIMAL.test(value)) {
    throw new TypeError(`${label} must be a canonical decimal string`);
  }
  return value;
}

function positiveInteger(value, label) {
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new TypeError(`${label} must be a positive safe integer`);
  }
  return value;
}

function nonnegativeInteger(value, label) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${label} must be a nonnegative safe integer`);
  }
  return value;
}

function integerBetween(value, minimum, maximum, label) {
  if (!Number.isSafeInteger(value) || value < minimum || value > maximum) {
    throw new TypeError(
      `${label} must be an integer from ${minimum} through ${maximum}`,
    );
  }
  return value;
}

function validateUniqueBoundedStrings(value, label, maximumItems) {
  if (!Array.isArray(value) || value.length > maximumItems) {
    throw new TypeError(`${label} must be a bounded array`);
  }
  const seen = new Set();
  for (const [index, item] of value.entries()) {
    const normalized = boundedString(item, `${label}[${index}]`, 1024);
    if (seen.has(normalized)) {
      throw new Error(`${label} must not contain duplicates`);
    }
    seen.add(normalized);
  }
  return value;
}

function boundedString(value, label, maximum) {
  if (
    typeof value !== "string" || value.length === 0 ||
    Buffer.byteLength(value, "utf8") > maximum
  ) {
    throw new TypeError(`${label} must be a non-empty bounded string`);
  }
  return value;
}

function compactOidcJwt(value) {
  const jwt = boundedString(value, "workflow provenance compact JWT", 32 * 1024);
  if (!/^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/u.test(jwt)) {
    throw new TypeError("workflow provenance compact JWT is not canonical");
  }
  return jwt;
}

function nullableBoundedString(value, label, maximum) {
  return value === null ? null : boundedString(value, label, maximum);
}

function assertObject(value, label) {
  if (
    value === null || typeof value !== "object" || Array.isArray(value) ||
    Object.getPrototypeOf(value) !== Object.prototype
  ) {
    throw new TypeError(`${label} must be a plain object`);
  }
}

function exactKeys(value, expected, label) {
  const actual = Object.keys(value).sort();
  const keys = [...expected].sort();
  if (canonicalJson(actual) !== canonicalJson(keys)) {
    throw new TypeError(`${label} must use the closed key set ${keys.join(", ")}`);
  }
}

function validateCanonicalJsonValue(value, label, depth = 0) {
  if (depth > 32) throw new TypeError(`${label} exceeds canonical JSON depth`);
  if (value === null || typeof value === "boolean" || typeof value === "string") return;
  if (typeof value === "number") {
    if (!Number.isSafeInteger(value)) {
      throw new TypeError(`${label} numbers must be safe integers`);
    }
    return;
  }
  if (Array.isArray(value)) {
    if (value.length > 10_000) throw new TypeError(`${label} array exceeds its cap`);
    for (const [index, item] of value.entries()) {
      validateCanonicalJsonValue(item, `${label}[${index}]`, depth + 1);
    }
    return;
  }
  assertObject(value, label);
  if (Object.keys(value).length > 10_000) {
    throw new TypeError(`${label} object exceeds its key cap`);
  }
  for (const [key, item] of Object.entries(value)) {
    if (key.length === 0) throw new TypeError(`${label} contains an empty key`);
    validateCanonicalJsonValue(item, `${label}.${key}`, depth + 1);
  }
}

function rawDigest(value) {
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;
}

function digestCanonical(domain, value) {
  return rawDigest(`${domain}\0${canonicalJson(value)}`);
}

// Runner reservation and head-ledger receipts predate the Git ledger and use
// their own length-prefixed domain separation. Keep this distinct from the
// Git-ledger envelope digest so real runner receipts interoperate byte-for-byte.
function runnerDigestCanonical(domain, value) {
  const domainBytes = Buffer.from(domain, "utf8");
  const valueBytes = Buffer.from(canonicalJson(value), "utf8");
  const hash = createHash("sha256");
  hash.update(`${domainBytes.length}:`);
  hash.update(domainBytes);
  hash.update("\0");
  hash.update(`${valueBytes.length}:`);
  hash.update(valueBytes);
  return `sha256:${hash.digest("hex")}`;
}

function canonicalJson(value) {
  if (Array.isArray(value)) {
    return `[${value.map((item) => canonicalJson(item)).join(",")}]`;
  }
  if (value !== null && typeof value === "object") {
    return `{${Object.keys(value).sort().map((key) =>
      `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

function deepFreeze(value) {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const child of Object.values(value)) deepFreeze(child);
  }
  return value;
}

function ledgerError(code, message, cause = undefined) {
  const error = cause === undefined ? new Error(message) : new Error(message, { cause });
  error.code = code;
  return error;
}
